  {
    id = "Q0I2";
    name_text = "[QUEST_Q0I2_NAME]";
    desc_text = "[QUEST_Q0I2_DESC]";
    group = "[QG_SELE_NAME]";
    text_file = "English\\Quests\\Q0I2_Text.xml";
    texts = [("[QUEST_Q0I2_ACTION1]", "Approach the Palace"); ("[QUEST_Q0I2_ACTION2]", "Sneak into the Palace"); ("[QUEST_Q0I2_DONE]", "The message has finally been delivered to the Emperor of Selentia."); ("[QUEST_Q0I2_ENMOUTH]", "You have arrived in Emouth, largest Trade Port in the eastern lands, and home to the Selentine Emperor."); ("[QUEST_Q0I2_FAIL]", "The Giant Rat has blocked your progress, but you may try again..."); ("[QUEST_Q0I2_GUARDIAN]", "You sneak into the Palace through the sewers, but you find a Giant Rat blocking the way..."); ("[QUEST_Q0I2_PROGRESS1]", "You must carry your message to the Imperial Palace in Enmouth."); ("[QUEST_Q0I2_PROGRESS2]", "You must find another way to enter the Imperial Palace."); ("[QUEST_Q0I2_QMHELP0]", "This Rat is larger than most, and also very fast - it knows the Haste spell.")];
    lua_file = "Assets\\Quests\\Q0I2.lua";
    lua_object = "Q0I2";
    lua_source = "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--             Imperial Message	\n" ^
      "--	\n" ^
      "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--		STATES	\n" ^
      "--\n" ^
      "-- 0 => Inactive\n" ^
      "-- 1 => Nothing done yet\n" ^
      "-- 2 => Tried to get into palace, failed\n" ^
      "-- 3 => complete (snuck into palace)\n" ^
      "-- \n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Variables\n" ^
      "--\n" ^
      "local questState = 0;\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Constants\n" ^
      "--\n" ^
      "local myCode     = \"Q0I2\";\n" ^
      "local myOrigin   = \"CBAR\";\n" ^
      "local myDestination   = \"CENM\";\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnInit				\n" ^
      "--		(called for every quest when they are loading\n" ^
      "--		 to set the initial state of all variables)\n" ^
      "--\n" ^
      "local function OnInit()\n" ^
      "	questState = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnBegin				\n" ^
      "--		(called when a quest is first obtained)\n" ^
      "--\n" ^
      "local function OnBegin()\n" ^
      "	questState = 1;\n" ^
      "	QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q0I2a.xml\",myOrigin);\n" ^
      "	QUEST_SET_VISIBILITY(\"CENM\",1);	\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnd				\n" ^
      "--		(called when a quest has ended)\n" ^
      "--\n" ^
      "local function OnEnd()\n" ^
      "	questState = 3;\n" ^
      "	\n" ^
      "	-- Reward\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q0I2_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[QUEST_Q0I2_DONE]\");\n" ^
      "	QUEST_REWARD_MENU(myTitle,myMessage);\n" ^
      "	QUEST_REWARD_XP(20);\n" ^
      "	QUEST_REWARD_GOLD(100);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnAbandon				\n" ^
      "--		(called when a quest has been abandoned by the player)\n" ^
      "--\n" ^
      "local function OnAbandon()\n" ^
      "	questState = 0;  -- it can be restarted\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnterLocation		\n" ^
      "--		(a hero has arrived at a new location)\n" ^
      "--\n" ^
      "local function OnEnterLocation(idLocation)\n" ^
      "	if (idLocation == myDestination and questState == 1) then\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_Q0I2_NAME]\");\n" ^
      "		local myMessage = GET_TEXT(\"[QUEST_Q0I2_ENMOUTH]\");\n" ^
      "		QUEST_MESSAGE(myTitle,myMessage,idLocation);\n" ^
      "		QUEST_STOP_MOVEMENT();\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryAction\n" ^
      "--		(should anything appear on the popup menu)\n" ^
      "--\n" ^
      "local function OnQueryAction(idLocation)\n" ^
      "	if (idLocation == myDestination) then\n" ^
      "		if (questState == 1) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q0I2_ACTION1]\");\n" ^
      "		elseif (questState == 2) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q0I2_ACTION2]\");\n" ^
      "		end\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnExecuteAction				\n" ^
      "--		(do this whenever the player executes the next action)\n" ^
      "--\n" ^
      "local function OnExecuteAction(idLocation)\n" ^
      "	if (questState == 1) then\n" ^
      "		-- Approach the Palace\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q0I2b.xml\",idLocation);\n" ^
      "\n" ^
      "	elseif (questState == 2) then\n" ^
      "		-- Sneak into the Palace\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_Q0I2_NAME]\");\n" ^
      "		local myMessage = GET_TEXT(\"[QUEST_Q0I2_GUARDIAN]\");\n" ^
      "		QUEST_MESSAGE_CALLBACK(myTitle,myMessage,idLocation, \"Q0I2\",\"CallbackGuardian\");\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnCompleteAction				\n" ^
      "--		(do this whenever the player completes his action)\n" ^
      "--		It is called after the game has returned to the map screen\n" ^
      "--\n" ^
      "local function OnCompleteAction(idLocation, success)\n" ^
      "	if (success == 1 and questState == 2) then\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q0I2c.xml\",idLocation);\n" ^
      "	elseif (success == 0 and questState == 2) then\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_Q0I2_NAME]\");\n" ^
      "		local myMessage = GET_TEXT(\"[QUEST_Q0I2_FAIL]\");\n" ^
      "		QUEST_MESSAGE(myTitle,myMessage,idLocation);\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnLoad				\n" ^
      "--		(a save game is being loaded)\n" ^
      "--\n" ^
      "local function OnLoad()\n" ^
      "	questState = QUEST_LOAD_INT();\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnSave				\n" ^
      "--		(a save game is being saved)\n" ^
      "--\n" ^
      "local function OnSave()\n" ^
      "	QUEST_SAVE_INT(questState);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryProgress		\n" ^
      "--		(returns text describing the next step required)\n" ^
      "--\n" ^
      "local function OnQueryProgress()\n" ^
      "	if (questState == 1) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q0I2_PROGRESS1]\");\n" ^
      "	elseif (questState == 2) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q0I2_PROGRESS2]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryPercentage	\n" ^
      "--		(returns a percentage of completion)\n" ^
      "--\n" ^
      "local function OnQueryPercentage()\n" ^
      "	return (questState - 1)*50;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryDifficulty	\n" ^
      "--		(returns 0-4 for difficulty - v.easy to v.difficult )\n" ^
      "--\n" ^
      "local function OnQueryDifficulty()\n" ^
      "	-- average\n" ^
      "	return 2; \n" ^
      "end\n" ^
      "\n" ^
      "-- CallbackAmbush				\n" ^
      "--		(Callback fn - for after the ambush message)\n" ^
      "--\n" ^
      "local function CallbackGuardian()\n" ^
      "	  	QUEST_BATTLE(myCode,0,1);\n" ^
      "end\n" ^
      "\n" ^
      "-- CallbackConvB 				\n" ^
      "--		(Callback fn - for talked to guard)\n" ^
      "--\n" ^
      "local function CallbackConvB () \n" ^
      "	questState = 2;\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "\n" ^
      "-- CallbackConvC 				\n" ^
      "--		(Callback fn - for end of quest)\n" ^
      "--\n" ^
      "local function CallbackConvC ()\n" ^
      "	QUEST_COMPLETE(myCode);\n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "--	\n" ^
      "--		DECLARE TABLE	\n" ^
      "--\n" ^
      "\n" ^
      "Q0I2 = {\n" ^
      "	OnInit				= OnInit,\n" ^
      "	OnBegin				= OnBegin,\n" ^
      "	OnEnd				= OnEnd,\n" ^
      "	OnAbandon			= OnAbandon,\n" ^
