  {
    id = "Q0I4";
    name_text = "[QUEST_Q0I4_NAME]";
    desc_text = "[QUEST_Q0I4_DESC]";
    group = "[QG_SELE_NAME]";
    text_file = "English\\Quests\\Q0I4_Text.xml";
    texts = [("[Q0I4_ACTIONFREE]", "Free Serephine"); ("[Q0I4_ACTIONGIVE]", "Deliver Serephine"); ("[Q0I4_GETSEREPHINE]", "Meet Serephine"); ("[Q0I4_PROGRESS0]", "You must travel to Barthel and collect the Emperor's daughter, Princess Serephine."); ("[Q0I4_PROGRESS1]", "You must decide whether to give Serephine to Utrarg of Trarg, or whether to free her in Bartonia."); ("[Q0I4_REWARD0]", "Utrarg of Trarg is pleased with his new bride.  He gives you a small payment of gold as a token of his gratitude."); ("[Q0I4_REWARD1]", "Serephine has been freed and she gives you the reward as promised. She also joins you as a Companion.")];
    lua_file = "Assets\\Quests\\Q0I4.lua";
    lua_object = "Q0I4";
    lua_source = "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--             The Marriage	\n" ^
      "--	\n" ^
      "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--		STATES	\n" ^
      "--\n" ^
      "-- 0 => Inactive\n" ^
      "-- 1 => Nothing done yet\n" ^
      "-- 2 => Got Serephine... traveling\n" ^
      "-- 3 => Serephine has begged in Trarg\n" ^
      "-- 4 => Ended\n" ^
      "-- \n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Variables\n" ^
      "--\n" ^
      "local questState = 0;\n" ^
      "local serephineFreed = 0;\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Constants\n" ^
      "--\n" ^
      "local myCode     = \"Q0I4\";\n" ^
      "local myOrigin   = \"CENM\";\n" ^
      "local myLocation1     = \"WBTH\";\n" ^
      "local myLocation2     = \"WELE\";\n" ^
      "local myDestination   = \"CTRA\";\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnInit				\n" ^
      "--		(called for every quest when they are loading\n" ^
      "--		 to set the initial state of all variables)\n" ^
      "--\n" ^
      "local function OnInit()\n" ^
      "	questState = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnBegin				\n" ^
      "--		(called when a quest is first obtained)\n" ^
      "--\n" ^
      "local function OnBegin()\n" ^
      "\n" ^
      "	questState = 1;\n" ^
      "\n" ^
      "	QUEST_SET_VISIBILITY(myDestination,1);	\n" ^
      "\n" ^
      "	-- Add the Wolf encounters \n" ^
      "	local encounterId1 = QUEST_ENCOUNTER_GET_AT(myLocation1,myDestination);\n" ^
      "	local encounterId2 = QUEST_ENCOUNTER_GET_AT(myLocation2,myDestination);	\n" ^
      "	\n" ^
      "	-- Add the encounter  (but remove anything else there first)\n" ^
      "	if (encounterId1 ~= \"ETWF\") then\n" ^
      "		if (encounterId ~= \"\") then\n" ^
      "			QUEST_ENCOUNTER_REMOVE_AT(myLocation1,myDestination);\n" ^
      "		end\n" ^
      "		QUEST_ENCOUNTER_ADD(\"ETWF\");\n" ^
      "	end\n" ^
      "	if (encounterId2 ~= \"EEWF\") then\n" ^
      "		if (encounterId ~= \"\") then\n" ^
      "			QUEST_ENCOUNTER_REMOVE_AT(myLocation2,myDestination);\n" ^
      "		end\n" ^
      "		QUEST_ENCOUNTER_ADD(\"EEWF\");\n" ^
      "	end\n" ^
      "\n" ^
      "	QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q0I4a.xml\",myOrigin);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnd				\n" ^
      "--		(called when a quest has ended)\n" ^
      "--\n" ^
      "local function OnEnd()\n" ^
      "	questState = 4;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnAbandon				\n" ^
      "--		(called when a quest has been abandoned by the player)\n" ^
      "--\n" ^
      "local function OnAbandon()\n" ^
      "	questState = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnterLocation		\n" ^
      "--		(a hero has arrived at a new location)\n" ^
      "--\n" ^
      "local function OnEnterLocation(idLocation)\n" ^
      "	if (idLocation==myDestination and questState==2) then\n" ^
      "		QUEST_STOP_MOVEMENT();\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q0I4c.xml\",idLocation);\n" ^
      "		questState = 3;\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryAction\n" ^
      "--		(should anything appear on the popup menu)\n" ^
      "--\n" ^
      "local function OnQueryAction(idLocation)\n" ^
      "	if (questState == 2 or questState == 3) then\n" ^
      "		if (idLocation == \"CBAR\") then\n" ^
      "			-- Free Serephine\n" ^
      "			return GET_TEXT(\"[Q0I4_ACTIONFREE]\");\n" ^
      "		elseif (idLocation == myDestination) then\n" ^
      "			-- Give Serephine\n" ^
      "			return GET_TEXT(\"[Q0I4_ACTIONGIVE]\");\n" ^
      "		end\n" ^
      "	elseif (questState == 1 and idLocation == myLocation1) then\n" ^
      "		return GET_TEXT(\"[Q0I4_GETSEREPHINE]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnExecuteAction				\n" ^
      "--		(do this whenever the player executes the next action)\n" ^
      "--\n" ^
      "local function OnExecuteAction(idLocation)\n" ^
      "	if (questState == 2 or questState == 3) then\n" ^
      "		if (idLocation == \"CBAR\") then\n" ^
      "			-- Free Serephine\n" ^
      "			QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q0I4d.xml\",idLocation);\n" ^
      "			serephineFreed = 1;\n" ^
      "		elseif (idLocation == myDestination) then\n" ^
      "			-- Give Serephine\n" ^
      "			QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q0I4e.xml\",idLocation);\n" ^
      "			serephineFreed = 0;\n" ^
      "		end\n" ^
      "	elseif (questState == 1 and idLocation == myLocation1) then\n" ^
      "		questState = 2;\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q0I4b.xml\",idLocation);\n" ^
      "		QUEST_UPDATE_MAP();\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnCompleteAction				\n" ^
      "--		(do this whenever the player completes his action)\n" ^
      "--		It is called after the game has returned to the map screen\n" ^
      "--\n" ^
      "local function OnCompleteAction(idLocation, success)\n" ^
      "\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnLoad				\n" ^
      "--		(a save game is being loaded)\n" ^
      "--\n" ^
      "local function OnLoad()\n" ^
      "	questState = QUEST_LOAD_INT();\n" ^
      "	serephineFreed= QUEST_LOAD_INT();\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnSave				\n" ^
      "--		(a save game is being saved)\n" ^
      "--\n" ^
      "local function OnSave()\n" ^
      "	QUEST_SAVE_INT(questState);\n" ^
      "	QUEST_SAVE_INT(serephineFreed);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryProgress		\n" ^
      "--		(returns text describing the next step required)\n" ^
      "--\n" ^
      "local function OnQueryProgress()\n" ^
      "	if (questState == 1) then\n" ^
      "		return GET_TEXT(\"[Q0I4_PROGRESS0]\");\n" ^
      "	end\n" ^
      "	return GET_TEXT(\"[Q0I4_PROGRESS1]\");\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryPercentage	\n" ^
      "--		(returns a percentage of completion)\n" ^
      "--\n" ^
      "local function OnQueryPercentage()\n" ^
      "	if (questState == 1) then\n" ^
      "		return 0;\n" ^
      "	end\n" ^
      "	return 50;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryDifficulty	\n" ^
      "--		(returns 0-4 for difficulty - v.easy to v.difficult )\n" ^
      "--\n" ^
      "local function OnQueryDifficulty()\n" ^
      "	-- average\n" ^
      "	return 1; \n" ^
      "end\n" ^
      "\n" ^
      "-- CallbackConvDE 				\n" ^
      "--		(Callback fn - for end of quest)\n" ^
      "--\n" ^
      "local function CallbackConvDE ()\n" ^
      "	-- Reward\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q0I4_NAME]\");\n" ^
      "	if (serephineFreed == 1) then\n" ^
      "		local myMessage = GET_TEXT(\"[Q0I4_REWARD1]\");\n" ^
      "		QUEST_REWARD_MENU_CALLBACK(myTitle,myMessage, myCode,\"CallbackCompanion\");\n" ^
      "		QUEST_REWARD_GOLD(2000);\n" ^
      "		QUEST_REWARD_ITEM(\"ISRI\"); -- Serephines Ring\n" ^
      "	else\n" ^
      "		local myMessage = GET_TEXT(\"[Q0I4_REWARD0]\");\n" ^
      "		QUEST_REWARD_MENU(myTitle,myMessage);\n" ^
      "		QUEST_REWARD_GOLD(50);\n" ^
      "		QUEST_REWARD_XP(50);\n" ^
      "		QUEST_COMPLETE(myCode);\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "local function CallbackCompanion ()\n" ^
      "	QUEST_ADD_COMPANION(\"NSER\");\n" ^
      "	QUEST_COMPANION_MESSAGE(\"NSER\");	\n" ^
      "	QUEST_COMPLETE(myCode);\n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "--	\n" ^
      "--		DECLARE TABLE	\n" ^
      "--\n" ^
      "\n" ^
      "Q0I4 = {\n" ^
