    texts = [("[Q0I6_ACTION0]", "Train in Bartonia"); ("[Q0I6_ACTION1]", "Train in Siria"); ("[Q0I6_ACTION2]", "Train in Elenia"); ("[Q0I6_ACTION3]", "Train in Theira"); ("[Q0I6_ACTION4]", "Train in Gildor"); ("[Q0I6_AWARD_MESG0]", "You have received a new Award. You are now a Bartonian Knight, and you gain +2 Battle Skill."); ("[Q0I6_AWARD_MESG1]", "You have received a new Award. You are now a Sirian Knight, and you gain +3 Morale Skill."); ("[Q0I6_AWARD_MESG2]", "You have received a new Award. You are now an Elenian Knight, and you gain +2 Earth Skill."); ("[Q0I6_AWARD_MESG3]", "You have received a new Award. You are now a Theiran Knight, and you gain +2 Fire Skill."); ("[Q0I6_AWARD_MESG4]", "You have received a new Award. You are now a Gildine Knight, and you gain +2 Cunning Skill."); ("[Q0I6_DONE]", "You have completed your training with excellent results. All of the Knightly Orders of Agaria offered you membership, and you have now chosen between them."); ("[Q0I6_FAIL]", "You have failed this training exercise, but do not fear - you may try it again as often as you wish."); ("[Q0I6_JOIN0]", "Join the Bartonians (+2 Battle)"); ("[Q0I6_JOIN1]", "Join the Sirians (+3 Morale)"); ("[Q0I6_JOIN2]", "Join the Elenians (+2 Earth)"); ("[Q0I6_JOIN3]", "Join the Theirans (+2 Fire)"); ("[Q0I6_JOIN4]", "Join the Gildines (+2 Cunning)"); ("[Q0I6_PROGRESS0]", "You have not yet completed any of the 5 training missions."); ("[Q0I6_PROGRESS1]", "You have completed 1 of 5 training missions."); ("[Q0I6_PROGRESS2]", "You have completed 2 of 5 training missions."); ("[Q0I6_PROGRESS3]", "You have completed 3 of 5 training missions."); ("[Q0I6_PROGRESS4]", "You have completed 4 of 5 training missions."); ("[Q0I6_PROGRESS5]", "You have completed all 5 training missions. You may now travel to one of the 5 Agarian cities and join a Knightly Order."); ("[Q0I6_SUCCESS]", "Congratulations, you have passed this phase of your training! You must now seek out the remaining Knights to train you."); ("[QUEST_Q0I6_QMNAME0]", "Brian of Bartonia"); ("[QUEST_Q0I6_QMHELP0]", "Bartonian Knights are very well-trained. This Knight has Battle and Life Points higher than an average Knight."); ("[QUEST_Q0I6_QMNAME1]", "Styvren of Siria"); ("[QUEST_Q0I6_QMHELP1]", "This Knight carries a Holy Lance.  The higher his Yellow Mana, the more damage he inflicts."); ("[QUEST_Q0I6_QMNAME2]", "Edmund of Elenia"); ("[QUEST_Q0I6_QMHELP2]", "This Knight carries a Longbow that adds to his Yellow Mana when he hits.  He can also use your own Yellow Mana against you with his Archery skill."); ("[QUEST_Q0I6_QMNAME3]", "Tharl of Theira"); ("[QUEST_Q0I6_QMHELP3]", "This Knight carries a Theiran Hammer that not only adds to damage, but turns Yellow Gems to Blue."); ("[QUEST_Q0I6_QMNAME4]", "Godwin of Gildor"); ("[QUEST_Q0I6_QMHELP4]", "Although weaker than the other Knights, this Gildine Knight has expensive armor that protects against much damage.")];
    lua_file = "Assets\\Quests\\Q0I6.lua";
    lua_object = "Q0I6";
    lua_source = "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--             Knightly Orders	\n" ^
      "--	\n" ^
      "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--		STATES	\n" ^
      "--\n" ^
      "-- 0 => Inactive\n" ^
      "-- 1 => Quest underway \n" ^
      "-- 2 => Done training - joining an order\n" ^
      "-- 3 => Complete\n" ^
      "-- \n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Variables\n" ^
      "--\n" ^
      "local questState = 0;\n" ^
      "local beatBartonia = 0;\n" ^
      "local beatSiria = 0;\n" ^
      "local beatElenia = 0;\n" ^
      "local beatTheira = 0;\n" ^
      "local beatGildor = 0;\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Constants\n" ^
      "--\n" ^
      "local myCode     = \"Q0I6\";\n" ^
      "local myOrigin   = \"CBAR\";\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnInit				\n" ^
      "--		(called for every quest when they are loading\n" ^
      "--		 to set the initial state of all variables)\n" ^
      "--\n" ^
      "local function OnInit()\n" ^
      "	questState = 0;\n" ^
      "	beatBartonia = 0;\n" ^
      "	beatTheira = 0;\n" ^
      "	beatSiria = 0;\n" ^
      "	beatGildor = 0;\n" ^
      "	beatElenia = 0;	\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnBegin				\n" ^
      "--		(called when a quest is first obtained)\n" ^
      "--\n" ^
      "local function OnBegin()\n" ^
      "	questState = 1;\n" ^
      "	beatBartonia = 0;\n" ^
      "	beatTheira = 0;\n" ^
      "	beatSiria = 0;\n" ^
      "	beatGildor = 0;\n" ^
      "	beatElenia = 0;	\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnd				\n" ^
      "--		(called when a quest has ended)\n" ^
      "--\n" ^
      "local function OnEnd()\n" ^
      "	questState = 3;\n" ^
      "	\n" ^
      "	-- Reward\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q0I6_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[Q0I6_DONE]\");\n" ^
      "	QUEST_REWARD_MENU(myTitle,myMessage);\n" ^
      "	QUEST_REWARD_XP(50);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnAbandon				\n" ^
      "--		(called when a quest has been abandoned by the player)\n" ^
      "--\n" ^
      "local function OnAbandon()\n" ^
      "	questState = 0;  -- it can be restarted\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnterLocation		\n" ^
      "--		(a hero has arrived at a new location)\n" ^
      "--\n" ^
      "local function OnEnterLocation(idLocation)\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryAction\n" ^
      "--		(should anything appear on the popup menu)\n" ^
      "--\n" ^
      "local function OnQueryAction(idLocation)\n" ^
      "\n" ^
      "	if (questState==1) then\n" ^
      "	\n" ^
      "		if (idLocation==\"CBAR\" and beatBartonia==0) then\n" ^
      "				return GET_TEXT(\"[Q0I6_ACTION0]\");				\n" ^
      "		elseif (idLocation==\"WSIR\" and beatSiria==0) then\n" ^
      "				return GET_TEXT(\"[Q0I6_ACTION1]\");\n" ^
      "		elseif (idLocation==\"WELE\" and beatElenia==0) then\n" ^
      "				return GET_TEXT(\"[Q0I6_ACTION2]\");\n" ^
      "		elseif (idLocation==\"WTHR\" and beatTheira==0) then\n" ^
      "				return GET_TEXT(\"[Q0I6_ACTION3]\");\n" ^
      "		elseif (idLocation==\"WGIL\" and beatGildor==0) then\n" ^
      "				return GET_TEXT(\"[Q0I6_ACTION4]\");\n" ^
      "		end\n" ^
      "	elseif (questState==2) then\n" ^
      "	\n" ^
      "		if (idLocation==\"CBAR\") then\n" ^
      "				return GET_TEXT(\"[Q0I6_JOIN0]\");				\n" ^
      "		elseif (idLocation==\"WSIR\") then\n" ^
      "				return GET_TEXT(\"[Q0I6_JOIN1]\");\n" ^
      "		elseif (idLocation==\"WELE\") then\n" ^
      "				return GET_TEXT(\"[Q0I6_JOIN2]\");\n" ^
      "		elseif (idLocation==\"WTHR\") then\n" ^
      "				return GET_TEXT(\"[Q0I6_JOIN3]\");\n" ^
      "		elseif (idLocation==\"WGIL\") then\n" ^
      "				return GET_TEXT(\"[Q0I6_JOIN4]\");\n" ^
      "		end\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnExecuteAction				\n" ^
      "--		(do this whenever the player executes the next action)\n" ^
      "--\n" ^
      "local function OnExecuteAction(idLocation)\n" ^
      "	if (questState==1) then\n" ^
      "	\n" ^
      "		if (idLocation==\"CBAR\") then\n" ^
      "				QUEST_BATTLE_NOCAPTURE(myCode,0,1);		\n" ^
      "		elseif (idLocation==\"WSIR\") then\n" ^
      "				QUEST_BATTLE_NOCAPTURE(myCode,1,1);\n" ^
      "		elseif (idLocation==\"WELE\") then\n" ^
      "				QUEST_BATTLE_NOCAPTURE(myCode,2,1);\n" ^
      "		elseif (idLocation==\"WTHR\") then\n" ^
      "				QUEST_BATTLE_NOCAPTURE(myCode,3,1);\n" ^
      "		elseif (idLocation==\"WGIL\") then\n" ^
      "				QUEST_BATTLE_NOCAPTURE(myCode,4,1);\n" ^
      "		end\n" ^
      "		\n" ^
      "	elseif (questState==2) then\n" ^
      "	\n" ^
      "		if (idLocation==\"CBAR\") then\n" ^
      "				QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q0I6aa.xml\",idLocation);	\n" ^
      "		elseif (idLocation==\"WSIR\") then\n" ^
      "				QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q0I6bb.xml\",idLocation);	\n" ^
      "		elseif (idLocation==\"WELE\") then\n" ^
      "				QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q0I6cc.xml\",idLocation);	\n" ^
      "		elseif (idLocation==\"WTHR\") then\n" ^
      "				QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q0I6dd.xml\",idLocation);	\n" ^
      "		elseif (idLocation==\"WGIL\") then\n" ^
      "				QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q0I6ee.xml\",idLocation);	\n" ^
      "		end\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnCompleteAction				\n" ^
      "--		(do this whenever the player completes his action)\n" ^
      "--		It is called after the game has returned to the map screen\n" ^
      "--\n" ^
      "local function OnCompleteAction(idLocation, success)\n" ^
      "\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q0I6_NAME]\");\n" ^
      "	\n" ^
      "	if (success == 0) then\n" ^
      "	\n" ^
      "		QUEST_MESSAGE(myTitle, GET_TEXT(\"[Q0I6_FAIL]\"), idLocation);\n" ^
      "		\n" ^
      "	elseif (questState == 1) then\n" ^
      "	\n" ^
      "		-- Result\n" ^
      "		if (idLocation==\"CBAR\") then\n" ^
      "				beatBartonia = 1;	\n" ^
      "				QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q0I6a.xml\",idLocation);	\n" ^
      "		elseif (idLocation==\"WSIR\") then\n" ^
      "				beatSiria = 1;		\n" ^
      "				QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q0I6b.xml\",idLocation);	\n" ^
      "		elseif (idLocation==\"WELE\") then\n" ^
      "				beatElenia = 1;		\n" ^
      "				QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q0I6c.xml\",idLocation);	\n" ^
      "		elseif (idLocation==\"WTHR\") then\n" ^
      "				beatTheira = 1;		\n" ^
      "				QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q0I6d.xml\",idLocation);	\n" ^
      "		elseif (idLocation==\"WGIL\") then\n" ^
      "				beatGildor = 1;		\n" ^
      "				QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q0I6e.xml\",idLocation);	\n" ^
      "		end\n" ^
      "		\n" ^
      "		-- Check for completion\n" ^
      "		if (beatBartonia == 1 and beatSiria == 1 and beatElenia == 1 and beatTheira == 1 and beatGildor == 1) then\n" ^
      "				questState = 2;\n" ^
      "				QUEST_MESSAGE(myTitle, GET_TEXT(\"[Q0I6_PROGRESS5]\"), idLocation);\n" ^
      "		else\n" ^
      "				QUEST_MESSAGE(myTitle, GET_TEXT(\"[Q0I6_SUCCESS]\"), idLocation);\n" ^
      "		end\n" ^
      "		\n" ^
      "		QUEST_UPDATE_MAP();\n" ^
      "		\n" ^
      "	end\n" ^
      "\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnLoad				\n" ^
      "--		(a save game is being loaded)\n" ^
      "--\n" ^
      "local function OnLoad()\n" ^
      "	questState	 = QUEST_LOAD_INT();\n" ^
      "	beatBartonia = QUEST_LOAD_INT();\n" ^
      "	beatSiria	 = QUEST_LOAD_INT();\n" ^
      "	beatElenia	 = QUEST_LOAD_INT();\n" ^
      "	beatTheira	 = QUEST_LOAD_INT();\n" ^
      "	beatGildor	 = QUEST_LOAD_INT();\n" ^
      "	\n" ^
      "	if (beatBartonia == 1 and beatSiria == 1 and beatElenia == 1 and \n" ^
      "	    beatTheira == 1 and beatGildor == 1 and questState == 1) then\n" ^
      "			questState = 2;\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnSave				\n" ^
      "--		(a save game is being saved)\n" ^
      "--\n" ^
      "local function OnSave()\n" ^
      "	QUEST_SAVE_INT(questState);\n" ^
      "	QUEST_SAVE_INT(beatBartonia);\n" ^
      "	QUEST_SAVE_INT(beatSiria);\n" ^
      "	QUEST_SAVE_INT(beatElenia);\n" ^
      "	QUEST_SAVE_INT(beatTheira);\n" ^
      "	QUEST_SAVE_INT(beatGildor);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryProgress		\n" ^
      "--		(returns text describing the next step required)\n" ^
      "--\n" ^
      "local function OnQueryProgress()\n" ^
      "	local myText=\"\";\n" ^
      "	if (questState == 1) then\n" ^
      "		local myTotal = beatBartonia + beatTheira + beatSiria + beatGildor + beatElenia;\n" ^
      "		if (myTotal == 0) then\n" ^
      "			myText = GET_TEXT(\"[Q0I6_PROGRESS0]\");\n" ^
      "		elseif (myTotal == 1) then\n" ^
      "			myText = GET_TEXT(\"[Q0I6_PROGRESS1]\");\n" ^
      "		elseif (myTotal == 2) then\n" ^
      "			myText = GET_TEXT(\"[Q0I6_PROGRESS2]\");\n" ^
      "		elseif (myTotal == 3) then\n" ^
      "			myText = GET_TEXT(\"[Q0I6_PROGRESS3]\");\n" ^
      "		elseif (myTotal == 4) then\n" ^
      "			myText = GET_TEXT(\"[Q0I6_PROGRESS4]\");\n" ^
      "		elseif (myTotal == 5) then\n" ^
      "			myText = GET_TEXT(\"[Q0I6_PROGRESS5]\");\n" ^
      "		end\n" ^
      "	elseif (questState == 2) then\n" ^
      "		myText = GET_TEXT(\"[Q0I6_PROGRESS5]\");\n" ^
      "	end\n" ^
      "	return myText;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryPercentage	\n" ^
      "--		(returns a percentage of completion)\n" ^
      "--\n" ^
      "local function OnQueryPercentage()\n" ^
      "\n" ^
      "	local amt = 0;\n" ^
      "	\n" ^
      "	if (questState == 1) then\n" ^
      "		if (beatBartonia ==1) then\n" ^
      "			amt = amt + 19;\n" ^
      "		end\n" ^
      "		if (beatTheira ==1) then\n" ^
      "			amt = amt + 19;\n" ^
      "		end\n" ^
      "		if (beatSiria ==1) then\n" ^
      "			amt = amt + 19;\n" ^
      "		end\n" ^
      "		if (beatGildor ==1) then\n" ^
      "			amt = amt + 19;\n" ^
      "		end\n" ^
      "		if (beatElenia ==1) then\n" ^
      "			amt = amt + 19;\n" ^
      "		end\n" ^
      "	elseif (questState == 2) then\n" ^
      "		amt = 95;\n" ^
      "	elseif (questState == 3) then\n" ^
      "		amt = 100;\n" ^
      "	end\n" ^
      "	return amt;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryDifficulty	\n" ^
      "--		(returns 0-4 for difficulty - v.easy to v.difficult )\n" ^
      "--\n" ^
      "local function OnQueryDifficulty()\n" ^
      "	-- average\n" ^
      "	return 3; \n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- CALLBACKS\n" ^
      "--\n" ^
      "local function CallbackJoinedBartonia()\n" ^
      "	QUEST_ADD_AWARD(\"AKBA\");\n" ^
      "	QUEST_MESSAGE_CALLBACK(GET_TEXT(\"[QUEST_Q0I6_NAME]\"),GET_TEXT(\"[Q0I6_AWARD_MESG0]\"),myOrigin, myCode,\"CallbackComplete\");\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackJoinedSiria()\n" ^
      "	QUEST_ADD_AWARD(\"AKSI\");\n" ^
      "	QUEST_MESSAGE_CALLBACK(GET_TEXT(\"[QUEST_Q0I6_NAME]\"),GET_TEXT(\"[Q0I6_AWARD_MESG1]\"),myOrigin, myCode,\"CallbackComplete\");\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackJoinedElenia()\n" ^
      "	QUEST_ADD_AWARD(\"AKEL\");\n" ^
      "	QUEST_MESSAGE_CALLBACK(GET_TEXT(\"[QUEST_Q0I6_NAME]\"),GET_TEXT(\"[Q0I6_AWARD_MESG2]\"),myOrigin, myCode,\"CallbackComplete\");\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackJoinedTheira()\n" ^
      "	QUEST_ADD_AWARD(\"AKTH\");\n" ^
      "	QUEST_MESSAGE_CALLBACK(GET_TEXT(\"[QUEST_Q0I6_NAME]\"),GET_TEXT(\"[Q0I6_AWARD_MESG3]\"),myOrigin, myCode,\"CallbackComplete\");\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackJoinedGildor()\n" ^
      "	QUEST_ADD_AWARD(\"AKGI\");\n" ^
      "	QUEST_MESSAGE_CALLBACK(GET_TEXT(\"[QUEST_Q0I6_NAME]\"),GET_TEXT(\"[Q0I6_AWARD_MESG4]\"),myOrigin, myCode,\"CallbackComplete\");\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackComplete()\n" ^
      "	QUEST_COMPLETE(myCode);\n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "--	\n" ^
      "--		DECLARE TABLE	\n" ^
      "--\n" ^
      "\n" ^
      "Q0I6 = {\n" ^
      "	OnInit				= OnInit,\n" ^
      "	OnBegin				= OnBegin,\n" ^
      "	OnEnd				= OnEnd,\n" ^
      "	OnAbandon			= OnAbandon,\n" ^
      "	OnEnterLocation		= OnEnterLocation,\n" ^
      "	OnExecuteAction		= OnExecuteAction,\n" ^
      "	OnCompleteAction	= OnCompleteAction,\n" ^
      "	OnQueryAction		= OnQueryAction,\n" ^
      "	OnLoad				= OnLoad,\n" ^
      "	OnSave				= OnSave,\n" ^
      "	OnQueryProgress		= OnQueryProgress,\n" ^
      "	OnQueryPercentage	= OnQueryPercentage,\n" ^
      "	OnQueryDifficulty	= OnQueryDifficulty,\n" ^
      "\n" ^
      "	CallbackJoinedBartonia	= CallbackJoinedBartonia,\n" ^
      "	CallbackJoinedSiria		= CallbackJoinedSiria,\n" ^
      "	CallbackJoinedElenia	= CallbackJoinedElenia,\n" ^
      "	CallbackJoinedTheira	= CallbackJoinedTheira,\n" ^
      "	CallbackJoinedGildor	= CallbackJoinedGildor,\n" ^
      "	CallbackComplete		= CallbackComplete,\n" ^
      "\n" ^
      "};\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
