    battles = [("MKNI", []); ("MKNI", []); ("MKNI", ["SARC"]); ("MKNI", []); ("MKNI", [])];
    battle_actions = [(1, 0, false); (1, 1, false); (1, 2, false); (1, 3, false); (1, 4, false)];
    battle_stage_advances = [];
