  {
    id = "Q0Q0";
    name_text = "[QUEST_Q0Q0_NAME]";
    desc_text = "[QUEST_Q0Q0_DESC]";
    group = "[QG_PRIM_NAME]";
    text_file = "English\\Quests\\Q0Q0_Text.xml";
    texts = [("[QUEST_Q0Q0_ACTION0]", "You must first travel to Siria."); ("[QUEST_Q0Q0_ACTION1]", "You have survived an attack at the gates of Siria.  You must now deliver the message."); ("[QUEST_Q0Q0_ACTION2]", "The message has been stolen! You must visit your father, Sir Albion, to explain."); ("[QUEST_Q0Q0_AMBUSH]", "As you approach the city of Siria, a thief leaps out at you and demands you hand over the message!"); ("[QUEST_Q0Q0_DONE]", "Your father is grateful for your dedication to the task.  He gives you a fine Longsword with which to protect yourself."); ("[QUEST_Q0Q0_POPUP0]", "Enter the City"); ("[QUEST_Q0Q0_POPUP1]", "Deliver the Message"); ("[QUEST_Q0Q0_POPUP2]", "Visit Your Father")];
    lua_file = "Assets\\Quests\\Q0Q0.lua";
    lua_object = "Q0Q0";
    lua_source = "--	\n" ^
      "--		STATES	\n" ^
      "--\n" ^
      "-- 0 => Inactive\n" ^
      "-- 1 => Quest obtained, nothing done yet (not arrived in Elenia)\n" ^
      "-- 2 => Fought the thief in Elenia\n" ^
      "-- 3 => Finished\n" ^
      "-- \n" ^
      "\n" ^
      "-- Local Variables\n" ^
      "--\n" ^
      "local questState = 0;\n" ^
      "local lostToThief = 0;\n" ^
      "\n" ^
      "\n" ^
      "-- Local Constants\n" ^
      "--\n" ^
      "local myCode = \"Q0Q0\";\n" ^
      "local myLocation = \"WSIR\";\n" ^
      "local myOrigin = \"CBAR\";\n" ^
      "\n" ^
      "--	\n" ^
      "--		FUNCTIONS	\n" ^
      "--\n" ^
      "\n" ^
      "-- OnInit				\n" ^
      "--		(called for every quest when they are loading\n" ^
      "--		 to set the initial state of all variables)\n" ^
      "--\n" ^
      "local function OnInit()\n" ^
      "	questState = 0;\n" ^
      "	lostToThief = 0;\n" ^
      "end\n" ^
      "\n" ^
      "-- OnBegin				\n" ^
      "--		(called when a quest is first obtained)\n" ^
      "--\n" ^
      "local function OnBegin()\n" ^
      "	questState = 1;\n" ^
      "	lostToThief = 0;\n" ^
      "	QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q0Q0.xml\",myOrigin);\n" ^
      "end\n" ^
      "\n" ^
      "-- OnEnd				\n" ^
      "--		(called when a quest has ended)\n" ^
      "--\n" ^
      "local function OnEnd()\n" ^
      "	questState = 3;\n" ^
      "	\n" ^
      "	-- Reward\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q0Q0_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[QUEST_Q0Q0_DONE]\");\n" ^
      "	QUEST_REWARD_MENU(myTitle,myMessage);\n" ^
      "	QUEST_REWARD_XP(20);\n" ^
      "	QUEST_REWARD_ITEM(\"ILSW\"); -- Longsword\n" ^
      "end\n" ^
      "\n" ^
      "-- OnAbandon				\n" ^
      "--		(called when a quest has been abandoned by the player)\n" ^
      "--\n" ^
      "local function OnAbandon()\n" ^
      "	questState = 0;  -- it can be restarted\n" ^
      "end\n" ^
      "\n" ^
      "-- OnEnterLocation		\n" ^
      "--		(a hero has arrived at a new location)\n" ^
      "--\n" ^
      "local function OnEnterLocation(idLocation)\n" ^
      "	if (idLocation == myLocation and questState == 1) then\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_Q0Q0_NAME]\");\n" ^
      "		local myMessage = GET_TEXT(\"[QUEST_Q0Q0_AMBUSH]\");\n" ^
      "		QUEST_MESSAGE_CALLBACK(myTitle,myMessage,myLocation, \"Q0Q0\",\"CallbackAmbush\");\n" ^
      "		QUEST_STOP_MOVEMENT();\n" ^
      "	end\n" ^
      "	\n" ^
      "end\n" ^
      "\n" ^
      "-- OnQueryAction\n" ^
      "--		(should anything appear on the popup menu)\n" ^
      "--\n" ^
      "local function OnQueryAction(idLocation)\n" ^
      "	if (idLocation==myLocation and questState==2 and lostToThief==0) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q0Q0_POPUP1]\");\n" ^
      "			\n" ^
      "	elseif (idLocation==myLocation and questState==2 and lostToThief==1) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q0Q0_POPUP2]\");\n" ^
      "\n" ^
      "	elseif (idLocation==myLocation and questState==1) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q0Q0_POPUP0]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "-- OnExecuteAction				\n" ^
      "--		(do this whenever the player executes the next action)\n" ^
      "--\n" ^
      "local function OnExecuteAction(idLocation)\n" ^
      "	if (questState==2 and lostToThief==0) then\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q0Q0a.xml\",idLocation);\n" ^
      "	elseif (questState==2 and lostToThief==1) then\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q0Q0b.xml\",idLocation);\n" ^
      "	elseif (questState==1) then\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_Q0Q0_NAME]\");\n" ^
      "		local myMessage = GET_TEXT(\"[QUEST_Q0Q0_AMBUSH]\");\n" ^
      "		QUEST_MESSAGE_CALLBACK(myTitle,myMessage,idLocation, \"Q0Q0\",\"CallbackAmbush\");\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "-- OnCompleteAction				\n" ^
      "--		(do this whenever the player completes his action)\n" ^
      "--		It is called after the game has returned to the map screen\n" ^
      "--\n" ^
      "local function OnCompleteAction(idLocation, success)\n" ^
      "	if (questState==1) then\n" ^
      "	\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_Q0Q0_NAME]\");\n" ^
      "		local myMessage;\n" ^
      "		if (success == 1) then\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_Q0Q0_ACTION1]\");\n" ^
      "			lostToThief = 0;\n" ^
      "		else\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_Q0Q0_ACTION2]\");\n" ^
      "			lostToThief = 1;\n" ^
      "		end\n" ^
      "		questState = 2;\n" ^
      "		QUEST_MESSAGE(myTitle,myMessage,myLocation);\n" ^
      "		\n" ^
      "	elseif (questState==2) then\n" ^
      "	\n" ^
      "		QUEST_COMPLETE(myCode);\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "-- OnLoad				\n" ^
      "--		(a save game is being loaded)\n" ^
      "--\n" ^
      "local function OnLoad()\n" ^
      "	questState	 = QUEST_LOAD_INT();\n" ^
      "	lostToThief  = QUEST_LOAD_INT();\n" ^
      "end\n" ^
      "\n" ^
      "-- OnSave				\n" ^
      "--		(a save game is being saved)\n" ^
      "--\n" ^
      "local function OnSave()\n" ^
      "	QUEST_SAVE_INT(questState);\n" ^
      "	QUEST_SAVE_INT(lostToThief);\n" ^
      "end\n" ^
      "\n" ^
      "-- OnQueryProgress		\n" ^
      "--		(returns text describing the next step required)\n" ^
      "--\n" ^
      "local function OnQueryProgress()\n" ^
      "	local myText=\"\";\n" ^
      "	if (questState == 1) then\n" ^
      "		myText = GET_TEXT(\"[QUEST_Q0Q0_ACTION0]\");\n" ^
      "	elseif (questState == 2 and lostToThief == 0) then\n" ^
      "		myText = GET_TEXT(\"[QUEST_Q0Q0_ACTION1]\");\n" ^
      "	elseif (questState == 2 and lostToThief == 0) then\n" ^
      "		myText = GET_TEXT(\"[QUEST_Q0Q0_ACTION2]\");\n" ^
      "	end\n" ^
      "	return myText;\n" ^
      "end\n" ^
      "\n" ^
      "-- OnQueryPercentage	\n" ^
      "--		(returns a percentage of completion)\n" ^
      "--\n" ^
      "local function OnQueryPercentage()\n" ^
      "	if (questState == 1) then \n" ^
      "		return 0;\n" ^
      "	elseif (questState == 2) then\n" ^
      "		return 50;\n" ^
      "	end\n" ^
      "	return 100;\n" ^
      "end\n" ^
      "\n" ^
      "-- OnQueryDifficulty	\n" ^
      "--		(returns 0-4 for difficulty - v.easy to v.difficult )\n" ^
      "--\n" ^
      "local function OnQueryDifficulty()\n" ^
      "	return 1;\n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "-- CallbackAmbush				\n" ^
      "--		(Callback fn - for after the ambush message)\n" ^
      "--\n" ^
      "local function CallbackAmbush()\n" ^
      "	  	QUEST_BATTLE(myCode,0,1);\n" ^
      "end\n" ^
      "\n" ^
      "-- CallbackGivenMessage				\n" ^
      "--		(Callback fn - for after the conversation)\n" ^
      "--\n" ^
      "local function CallbackGivenMessage()\n" ^
      "		QUEST_COMPLETE_PART(myCode,myLocation,1);\n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "--	\n" ^
      "--		DECLARE TABLE	\n" ^
      "--\n" ^
      "\n" ^
      "Q0Q0 = {\n" ^
      "	OnInit				= OnInit,\n" ^
      "	OnBegin				= OnBegin,\n" ^
      "	OnEnd				= OnEnd,\n" ^
      "	OnAbandon			= OnAbandon,\n" ^
      "	OnEnterLocation		= OnEnterLocation,\n" ^
      "	OnExecuteAction		= OnExecuteAction,\n" ^
      "	OnCompleteAction	= OnCompleteAction,\n" ^
      "	OnQueryAction		= OnQueryAction,\n" ^
      "	OnLoad				= OnLoad,\n" ^
      "	OnSave				= OnSave,\n" ^
      "	OnQueryProgress		= OnQueryProgress,\n" ^
      "	OnQueryPercentage	= OnQueryPercentage,\n" ^
      "	OnQueryDifficulty	= OnQueryDifficulty,\n" ^
      "	\n" ^
      "	CallbackAmbush		= CallbackAmbush,\n" ^
      "	CallbackGivenMessage= CallbackGivenMessage,\n" ^
      "};\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n";
