    text_file = "English\\Quests\\Q0Q2_Text.xml";
    texts = [("[QUEST_Q0Q2_FAIL]", "You have suffered a loss, but Darkhunter still needs your help."); ("[QUEST_Q0Q2_HELP]", "Help Darkhunter"); ("[QUEST_Q0Q2_MESSAGE]", "In the distance you see Darkhunter.  He is surrounded by Orcs and looks like he could use some help."); ("[QUEST_Q0Q2_PROG1]", "You must travel south to Gallia in search of Darkhunter."); ("[QUEST_Q0Q2_PROG2]", "Darkhunter was tracking some Orcs near the Ruins of Artum. Try searching there."); ("[QUEST_Q0Q2_PROG3]", "Darkhunter is surrounded by Orcs near the Ruins of Artum. He needs your help."); ("[QUEST_Q0Q2_REWARD]", "You and Darkhunter have managed to slay the Orcs. You find a small amount of treasure on them."); ("[QUEST_Q0Q2_SEARCH]", "Search for Darkhunter"); ("[QUEST_Q0Q2_QMHELP0]", "This Orc carries a Great Axe that can give him an extra turn if he does a lot of damage. He is also slightly stronger than a regular Orc.")];
    lua_file = "Assets\\Quests\\Q0Q2.lua";
    lua_object = "Q0Q2";
    lua_source = "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--             Darkhunter	\n" ^
      "--	\n" ^
      "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--		STATES	\n" ^
      "--\n" ^
      "-- 0 => Inactive\n" ^
      "-- 1 => Quest obtained, nothing done yet\n" ^
      "-- 2 => Had the conversation witha Guard in Gallia who says -> Go to Artum\n" ^
      "-- 3 => Been to Artum and received a message that Darkhunter is there\n" ^
      "-- 4 => Complete\n" ^
      "-- \n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Variables\n" ^
      "--\n" ^
      "local questState = 0;\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Constants\n" ^
      "--\n" ^
      "local myCode     = \"Q0Q2\";\n" ^
      "local myLocation0= \"CGAL\";\n" ^
      "local myLocation1= \"WRAR\";\n" ^
      "local myOrigin   = \"CBAR\";\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnInit				\n" ^
      "--		(called for every quest when they are loading\n" ^
      "--		 to set the initial state of all variables)\n" ^
      "--\n" ^
      "local function OnInit()\n" ^
      "	questState = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnBegin				\n" ^
      "--		(called when a quest is first obtained)\n" ^
      "--\n" ^
      "local function OnBegin()\n" ^
      "	questState = 1;\n" ^
      "	QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q0Q2a.xml\",myOrigin);\n" ^
      "	QUEST_SET_VISIBILITY(\"WAPS\",1);\n" ^
      "	QUEST_SET_VISIBILITY(\"CGAL\",1);\n" ^
      "	QUEST_ADD_RUIN(myLocation);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnd				\n" ^
      "--		(called when a quest has ended)\n" ^
      "--\n" ^
      "local function OnEnd()\n" ^
      "	questState = 4;\n" ^
      "	\n" ^
      "	-- Reward\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q0Q2_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[QUEST_Q0Q2_REWARD]\");\n" ^
      "	QUEST_REWARD_MENU(myTitle,myMessage);\n" ^
      "	QUEST_REWARD_GOLD(25);\n" ^
      "	QUEST_REWARD_XP(40);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnAbandon				\n" ^
      "--		(called when a quest has been abandoned by the player)\n" ^
      "--\n" ^
      "local function OnAbandon()\n" ^
      "	questState = 0;  -- it can be restarted\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnterLocation		\n" ^
      "--		(a hero has arrived at a new location)\n" ^
      "--\n" ^
      "local function OnEnterLocation(idLocation)\n" ^
      "	if (idLocation == myLocation1 and questState == 2) then\n" ^
      "		-- Message: You see darkhunter\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_Q0Q2_NAME]\");\n" ^
      "		local myMessage = GET_TEXT(\"[QUEST_Q0Q2_MESSAGE]\");\n" ^
      "		QUEST_MESSAGE_CALLBACK(myTitle,myMessage,idLocation,myCode,\"CallbackSeenDarkhunter\");\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryAction\n" ^
      "--		(should anything appear on the popup menu)\n" ^
      "--\n" ^
      "local function OnQueryAction(idLocation)\n" ^
      "	if (idLocation==myLocation0 and questState==1) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q0Q2_SEARCH]\");\n" ^
      "	elseif (idLocation==myLocation1 and questState==2) then\n" ^
      "			return GET_TEXT(\"[ON]\");\n" ^
      "	elseif (idLocation==myLocation1 and questState==3) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q0Q2_HELP]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnExecuteAction				\n" ^
      "--		(do this whenever the player executes the next action)\n" ^
      "--\n" ^
      "local function OnExecuteAction(idLocation)\n" ^
      "	if (idLocation==myLocation0 and questState==1) then\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q0Q2b.xml\",idLocation);\n" ^
      "	elseif (idLocation==myLocation1 and questState==3) then\n" ^
      "		QUEST_BATTLE_NOCAPTURE(myCode,0,1);\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnCompleteAction				\n" ^
      "--		(do this whenever the player completes his action)\n" ^
      "--		It is called after the game has returned to the map screen\n" ^
      "--\n" ^
      "local function OnCompleteAction(idLocation, success)\n" ^
      "\n" ^
      "	if (questState==3) then\n" ^
      "	\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_Q0Q2_NAME]\");\n" ^
      "		local myMessage;\n" ^
      "		if (success == 1) then\n" ^
      "	  		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q0Q2c.xml\",idLocation);\n" ^
      "		else\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_Q0Q2_FAIL]\");\n" ^
      "			QUEST_MESSAGE(myTitle,myMessage,idLocation);\n" ^
      "		end\n" ^
      "		\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnLoad				\n" ^
      "--		(a save game is being loaded)\n" ^
      "--\n" ^
      "local function OnLoad()\n" ^
      "	questState = QUEST_LOAD_INT();\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnSave				\n" ^
      "--		(a save game is being saved)\n" ^
      "--\n" ^
      "local function OnSave()\n" ^
      "	QUEST_SAVE_INT(questState);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryProgress		\n" ^
      "--		(returns text describing the next step required)\n" ^
      "--\n" ^
      "local function OnQueryProgress()\n" ^
      "	if (questState == 1) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q0Q2_PROG1]\");\n" ^
      "	elseif (questState == 2) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q0Q2_PROG2]\");\n" ^
      "	elseif (questState == 3) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q0Q2_PROG3]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryPercentage	\n" ^
      "--		(returns a percentage of completion)\n" ^
      "--\n" ^
      "local function OnQueryPercentage()\n" ^
      "	if (questState==1) then\n" ^
      "		return 0;\n" ^
      "	elseif (questState==2) then\n" ^
      "		return 33;\n" ^
      "	elseif (questState==3) then\n" ^
      "		return 50;\n" ^
      "	end\n" ^
      "	return 100;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryDifficulty	\n" ^
      "--		(returns 0-4 for difficulty - v.easy to v.difficult )\n" ^
      "--\n" ^
      "local function OnQueryDifficulty()\n" ^
      "	-- average\n" ^
      "	return 2; \n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "--	Callbacks	\n" ^
      "--\n" ^
      "local function CallbackTalkedToGuard ()\n" ^
      "	questState = 2; \n" ^
      "	QUEST_SET_VISIBILITY(\"WRAR\",1);\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackSeenDarkhunter ()\n" ^
      "	questState = 3; \n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackHelpedDarkhunter ()\n" ^
      "	QUEST_COMPLETE(myCode);\n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "--	\n" ^
      "--		DECLARE TABLE	\n" ^
      "--\n" ^
      "\n" ^
      "Q0Q2 = {\n" ^
      "	OnInit		= OnInit,\n" ^
      "	OnBegin		= OnBegin,\n" ^
      "	OnEnd			= OnEnd,\n" ^
      "	OnAbandon		= OnAbandon,\n" ^
      "	OnEnterLocation	= OnEnterLocation,\n" ^
      "	OnExecuteAction	= OnExecuteAction,\n" ^
      "	OnCompleteAction	= OnCompleteAction,\n" ^
      "	OnQueryAction	= OnQueryAction,\n" ^
      "	OnLoad		= OnLoad,\n" ^
      "	OnSave		= OnSave,\n" ^
      "	OnQueryProgress	= OnQueryProgress,\n" ^
      "	OnQueryPercentage	= OnQueryPercentage,\n" ^
      "	OnQueryDifficulty	= OnQueryDifficulty,\n" ^
      "\n" ^
      "	CallbackTalkedToGuard = CallbackTalkedToGuard ,\n" ^
      "	CallbackSeenDarkhunter = CallbackSeenDarkhunter ,\n" ^
      "	CallbackHelpedDarkhunter = CallbackHelpedDarkhunter ,\n" ^
      "};\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
