    reward_xp = 50;
    reward_items = [];
    reward_awards = [];
    reward_companions = [];
  };
  {
    id = "Q0Q4";
    name_text = "[QUEST_Q0Q4_NAME]";
    desc_text = "[QUEST_Q0Q4_DESC]";
    group = "[QG_PRIM_NAME]";
    text_file = "English\\Quests\\Q0Q4_Text.xml";
    texts = [("[QUEST_Q0Q4_ACTION0]", "Visit the Riverguard"); ("[QUEST_Q0Q4_ACTION1]", "Find Darkhunter"); ("[QUEST_Q0Q4_ACTION2]", "Release Moarg"); ("[QUEST_Q0Q4_COMPANION]", "Darkhunter joins you as a Companion.  You may view your list of Companions in your Hero's Inventory."); ("[QUEST_Q0Q4_END_DEMO]", "The story continues in the full version of Puzzle Quest."); ("[QUEST_Q0Q4_END_HDR]", "Demo"); ("[QUEST_Q0Q4_MAETHELBURG]", "Maethelburg is an imposing city on a hill overlooking the River Maethel.  At the very center of the city is an enormous Red Tower - the home of the Riverguard."); ("[QUEST_Q0Q4_PROGRESS0]", "You must first travel to Maethelburg."); ("[QUEST_Q0Q4_PROGRESS1]", "You must take Moarg to the Riverguard in Maethelburg, or set him free in Skellheim."); ("[QUEST_Q0Q4_PROGRESS2]", "You must return to Darkhunter in Gallia."); ("[QUEST_Q0Q4_REWARD]", "Darkhunter's business in the Borderlands is finally complete.  You may now travel north."); ("[QUEST_Q0Q4_SWORD]", "Before he departs, Moarg gives you the sword as promised.  You have received Sir Ector's Sword.")];
    lua_file = "Assets\\Quests\\Q0Q4.lua";
    lua_object = "Q0Q4";
    lua_source = "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--             The Prisoner	\n" ^
      "--	\n" ^
      "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--		STATES	\n" ^
      "--\n" ^
      "-- 0 => Inactive\n" ^
      "-- 1 => Got the Quest, haven't reached Maethelburg yet\n" ^
      "-- 2 => Reached Maethelburg, haven't had the conversation with Moarg\n" ^
      "-- 3 => Reached Maethelburg, HAVE had the conversation with Moarg\n" ^
      "-- 4 => Finished in Maethelburg/Skellheim (either turned him in or let him go).\n" ^
      "-- 5 => Done! Returned to Gallia\n" ^
      "-- \n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Variables\n" ^
      "--\n" ^
      "local questState = 0;\n" ^
      "local releasedMoarg = 0;\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Constants\n" ^
      "--\n" ^
      "local myCode     = \"Q0Q4\";\n" ^
      "local myOrigin   = \"CGAL\";\n" ^
      "local myDestination   = \"WMAE\";\n" ^
      "local myDestination2   = \"WSKE\";\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnInit				\n" ^
      "--		(called for every quest when they are loading\n" ^
      "--		 to set the initial state of all variables)\n" ^
      "--\n" ^
      "local function OnInit()\n" ^
      "	questState = 0;\n" ^
      "	releasedMoarg = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnBegin				\n" ^
      "--		(called when a quest is first obtained)\n" ^
      "--\n" ^
      "local function OnBegin()\n" ^
      "	questState = 1;\n" ^
      "	QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q0Q4a.xml\",myOrigin);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnd				\n" ^
      "--		(called when a quest has ended)\n" ^
      "--\n" ^
      "local function OnEnd()\n" ^
      "	questState = 4;\n" ^
      "	if (IS_DEMO()) then\n" ^
      "		myTitle = GET_TEXT(\"[QUEST_Q0Q4_END_HDR]\");\n" ^
      "		myMessage = GET_TEXT(\"[QUEST_Q0Q4_END_DEMO]\");\n" ^
      "		QUEST_MESSAGE(myTitle, myMessage, \"CBAR\");\n" ^
      "	end\n" ^
      "	\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnAbandon				\n" ^
      "--		(called when a quest has been abandoned by the player)\n" ^
      "--\n" ^
      "local function OnAbandon()\n" ^
      "	questState = 0;\n" ^
      "	releasedMoarg = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnterLocation		\n" ^
      "--		(a hero has arrived at a new location)\n" ^
      "--\n" ^
      "local function OnEnterLocation(idLocation)\n" ^
      "	if (idLocation == myDestination and questState == 1) then\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_Q0Q4_NAME]\");\n" ^
      "		local myMessage = GET_TEXT(\"[QUEST_Q0Q4_MAETHELBURG]\");\n" ^
      "		QUEST_MESSAGE_CALLBACK(myTitle, myMessage, idLocation, myCode, \"CallbackEnterMaethelburg\");\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryAction\n" ^
      "--		(should anything appear on the popup menu)\n" ^
      "--\n" ^
      "local function OnQueryAction(idLocation)\n" ^
      "	if (idLocation == myDestination and questState <= 3) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q0Q4_ACTION0]\");\n" ^
      "	elseif (idLocation == myDestination2 and questState == 3) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q0Q4_ACTION2]\");\n" ^
      "	elseif (idLocation == myOrigin and questState == 4) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q0Q4_ACTION1]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnExecuteAction				\n" ^
      "--		(do this whenever the player executes the next action)\n" ^
      "--\n" ^
      "local function OnExecuteAction(idLocation)\n" ^
      "	if (idLocation == myDestination and questState == 2) then\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q0Q4c.xml\",idLocation);\n" ^
      "	elseif (idLocation == myDestination and questState == 3) then\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q0Q4d.xml\",idLocation);\n" ^
      "	elseif (idLocation == myDestination2 and questState == 3) then\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q0Q4e.xml\",idLocation);\n" ^
      "	elseif (idLocation == myOrigin and questState == 4) then\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q0Q4f.xml\",idLocation);\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnCompleteAction				\n" ^
      "--		(do this whenever the player completes his action)\n" ^
      "--		It is called after the game has returned to the map screen\n" ^
      "--\n" ^
      "local function OnCompleteAction(idLocation, success)\n" ^
      "\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnLoad				\n" ^
      "--		(a save game is being loaded)\n" ^
      "--\n" ^
      "local function OnLoad()\n" ^
      "	questState = QUEST_LOAD_INT();\n" ^
      "	releasedMoarg = QUEST_LOAD_INT();\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnSave				\n" ^
      "--		(a save game is being saved)\n" ^
      "--\n" ^
      "local function OnSave()\n" ^
      "	QUEST_SAVE_INT(questState);\n" ^
      "	QUEST_SAVE_INT(releasedMoarg);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryProgress		\n" ^
      "--		(returns text describing the next step required)\n" ^
      "--\n" ^
      "local function OnQueryProgress()\n" ^
      "	if (questState == 2) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q0Q4_PROGRESS0]\");\n" ^
      "	elseif (questState == 3) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q0Q4_PROGRESS1]\");\n" ^
      "	elseif (questState == 4) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q0Q4_PROGRESS2]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryPercentage	\n" ^
      "--		(returns a percentage of completion)\n" ^
      "--\n" ^
      "local function OnQueryPercentage()\n" ^
      "	return (questState-1)*25;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryDifficulty	\n" ^
      "--		(returns 0-4 for difficulty - v.easy to v.difficult )\n" ^
      "--\n" ^
      "local function OnQueryDifficulty()\n" ^
      "	-- average\n" ^
      "	return 2; \n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "--	Callbacks	\n" ^
      "--\n" ^
      "local function CallbackConvA ()\n" ^
      "	questState = 1;\n" ^
      "	QUEST_SET_VISIBILITY(\"WMAE\",1);\n" ^
      "\n" ^
      "	-- Add an encounter\n" ^
      "	local encounterId = QUEST_ENCOUNTER_GET_AT(myDestination,myOrigin);		\n" ^
      "	if (encounterId == \"\") then\n" ^
      "		QUEST_ENCOUNTER_ADD(\"EMRA\");\n" ^
      "	end\n" ^
      "end\n" ^
      "local function CallbackEnterMaethelburg()\n" ^
      "	QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q0Q4b.xml\",myDestination);\n" ^
      "end\n" ^
      "local function CallbackConvB ()\n" ^
      "	questState = 2;\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "local function CallbackConvC ()\n" ^
      "	questState = 3;\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "local function CallbackConvD ()\n" ^
      "	questState = 4;\n" ^
      "	releasedMoarg = 0;\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "local function CallbackConvE ()\n" ^
      "	questState = 4;\n" ^
      "	releasedMoarg = 1;\n" ^
      "\n" ^
      "	QUEST_ADD_ITEM(\"ISES\");\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q0Q4_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[QUEST_Q0Q4_SWORD]\");\n" ^
      "	QUEST_MESSAGE(myTitle, myMessage, myDestination2);\n" ^
      "\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "local function CallbackConvF ()\n" ^
      "	-- Reward\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q0Q4_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[QUEST_Q0Q4_REWARD]\");\n" ^
      "	QUEST_REWARD_MENU(myTitle,myMessage);\n" ^
      "	QUEST_REWARD_XP(50);\n" ^
      "\n" ^
      "	myTitle = GET_TEXT(\"[QUEST_Q0Q4_NAME]\");\n" ^
      "	myMessage = GET_TEXT(\"[QUEST_Q0Q4_COMPANION]\");\n" ^
      "	QUEST_MESSAGE_CALLBACK(myTitle, myMessage, myOrigin, myCode, \"CallbackCompanion\");\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackCompanion ()\n" ^
      "	QUEST_ADD_COMPANION(\"NDKH\");\n" ^
      "	QUEST_COMPANION_MESSAGE(\"NDKH\");\n" ^
      "\n" ^
      "	QUEST_COMPLETE(myCode);\n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "--	\n" ^
      "--		DECLARE TABLE	\n" ^
      "--\n" ^
      "\n" ^
      "Q0Q4 = {\n" ^
      "	OnInit				= OnInit,\n" ^
      "	OnBegin				= OnBegin,\n" ^
      "	OnEnd				= OnEnd,\n" ^
      "	OnAbandon			= OnAbandon,\n" ^
      "	OnEnterLocation		= OnEnterLocation,\n" ^
      "	OnExecuteAction		= OnExecuteAction,\n" ^
      "	OnCompleteAction	= OnCompleteAction,\n" ^
      "	OnQueryAction		= OnQueryAction,\n" ^
      "	OnLoad				= OnLoad,\n" ^
      "	OnSave				= OnSave,\n" ^
      "	OnQueryProgress		= OnQueryProgress,\n" ^
      "	OnQueryPercentage	= OnQueryPercentage,\n" ^
      "	OnQueryDifficulty	= OnQueryDifficulty,\n" ^
      "\n" ^
      "	CallbackConvA = CallbackConvA ,\n" ^
      "	CallbackEnterMaethelburg = CallbackEnterMaethelburg,\n" ^
      "	CallbackConvB = CallbackConvB ,\n" ^
      "	CallbackConvC = CallbackConvC ,\n" ^
      "	CallbackConvD  = CallbackConvD ,\n" ^
      "	CallbackConvE  = CallbackConvE ,\n" ^
      "	CallbackConvF  = CallbackConvF ,\n" ^
      "\n" ^
      "	CallbackCompanion = CallbackCompanion,\n" ^
      "};\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n";
    abandonable = false;
    icon = 0;
    important = true;
    avail_location = "CGAL";
    avail_minlevel = 5;
    avail_maxlevel = 1000;
    avail_repeat = 1;
    avail_donequest0 = "Q0Q3";
    avail_donequest1 = "";
    avail_donequest2 = "";
    avail_notdonequest = "";
    avail_notactivequest = "";
    avail_companion0 = "";
    avail_companion1 = "";
    avail_notcompanion = "";
    avail_item = "";
    avail_notitem = "";
    avail_award = "";
    avail_notaward = "";
    battle_monster = "";
    battle_spells = [];
    battles = [];
    battle_actions = [];
    battle_stage_advances = [];
    battle_stage_fails = [];
    enter_removes = [];
    reveal_on_begin = ["WMAE"];
    reveal_on_end = [];
