  {
    id = "Q0Q6";
    name_text = "[QUEST_Q0Q6_NAME]";
    desc_text = "[QUEST_Q0Q6_DESC]";
    group = "[QG_PRIM_NAME]";
    text_file = "English\\Quests\\Q0Q6_Text.xml";
    texts = [("[Q0Q6_ACTION]", "Visit Queen Titania"); ("[Q0Q6_GIFT]", "Darkhunter gives you a Lichebane Charm to protect yourself."); ("[Q0Q6_PROGRESS0]", "You must travel to Silvermyr and defeat the guardian on your way there."); ("[Q0Q6_PROGRESS1]", "You must visit Queen Titania of Silvermyr and tell her the Liche has been defeated."); ("[Q0Q6_REWARD]", "Queen Titania of Silvermyr rewards you well for your help.")];
    lua_file = "Assets\\Quests\\Q0Q6.lua";
    lua_object = "Q0Q6";
    lua_source = "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--             None Shall Pass	\n" ^
      "--	\n" ^
      "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--		STATES	\n" ^
      "--\n" ^
      "-- 0 => Inactive\n" ^
      "-- 1 => Got Quest\n" ^
      "-- 2 => Arrived in Alfland... talked to Darkhunter\n" ^
      "-- 3 => Killed Liche\n" ^
      "-- 4 => Completed Quest\n" ^
      "-- \n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Variables\n" ^
      "--\n" ^
      "local questState = 0;\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Constants\n" ^
      "--\n" ^
      "local myCode     = \"Q0Q6\";\n" ^
      "local myOrigin   = \"CBAR\";\n" ^
      "local myLocation = \"CSIL\";\n" ^
      "local myStart    = \"WALF\";\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnInit				\n" ^
      "--		(called for every quest when they are loading\n" ^
      "--		 to set the initial state of all variables)\n" ^
      "--\n" ^
      "local function OnInit()\n" ^
      "	questState = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnBegin				\n" ^
      "--		(called when a quest is first obtained)\n" ^
      "--\n" ^
      "local function OnBegin()\n" ^
      "	questState = 1;\n" ^
      "	QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q0Q6a.xml\",myOrigin);\n" ^
      "	QUEST_SET_VISIBILITY(\"WALF\",1);	\n" ^
      "	QUEST_SET_VISIBILITY(\"CSIL\",1);\n" ^
      "	\n" ^
      "		\n" ^
      "	-- Add the Liche (but remove anything else there first)\n" ^
      "	local encounterId = QUEST_ENCOUNTER_GET_AT(myLocation ,myStart);\n" ^
      "	if (encounterId ~= \"ESLI\") then\n" ^
      "		if (encounterId ~= \"\") then\n" ^
      "			QUEST_ENCOUNTER_REMOVE_AT(myLocation,myStart);\n" ^
      "		end\n" ^
      "		QUEST_ENCOUNTER_ADD(\"ESLI\");\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnd				\n" ^
      "--		(called when a quest has ended)\n" ^
      "--\n" ^
      "local function OnEnd()\n" ^
      "	questState = 4;\n" ^
      "	\n" ^
      "	-- Reward\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q0Q6_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[Q0Q6_REWARD]\");\n" ^
      "	QUEST_REWARD_MENU(myTitle,myMessage);\n" ^
      "	QUEST_REWARD_GOLD(350);\n" ^
      "	QUEST_REWARD_XP(50);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnAbandon				\n" ^
      "--		(called when a quest has been abandoned by the player)\n" ^
      "--\n" ^
      "local function OnAbandon()\n" ^
      "	questState = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnterLocation		\n" ^
      "--		(a hero has arrived at a new location)\n" ^
      "--\n" ^
      "local function OnEnterLocation(idLocation)\n" ^
      "	if (idLocation == myStart and\n" ^
      "		QUEST_HERO_HAS_COMPANION_SELECTED(\"NDKH\")==1 and\n" ^
      "		questState == 1) then\n" ^
      "			questState = 2;\n" ^
      "			QUEST_ADD_ITEM(\"ILBC\");\n" ^
      "			QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q0Q6b.xml\",idLocation);\n" ^
      "			QUEST_STOP_MOVEMENT();\n" ^
      "			QUEST_UPDATE_MAP();\n" ^
      "	elseif (idLocation == myLocation and questState == 2) then\n" ^
      "			questState = 3;\n" ^
      "			QUEST_UPDATE_MAP();\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryAction\n" ^
      "--		(should anything appear on the popup menu)\n" ^
      "--\n" ^
      "local function OnQueryAction(idLocation)\n" ^
      "	if (idLocation == myLocation) then\n" ^
      "		return GET_TEXT(\"[Q0Q6_ACTION]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnExecuteAction				\n" ^
      "--		(do this whenever the player executes the next action)\n" ^
      "--\n" ^
      "local function OnExecuteAction(idLocation)\n" ^
      "	if (QUEST_HERO_HAS_ITEM(\"ILBC\")==1) then\n" ^
      "		QUEST_REMOVE_ITEM(\"ILBC\");\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q0Q6c.xml\",idLocation);\n" ^
      "	else\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q0Q6cc.xml\",idLocation);\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnCompleteAction				\n" ^
      "--		(do this whenever the player completes his action)\n" ^
      "--		It is called after the game has returned to the map screen\n" ^
      "--\n" ^
      "local function OnCompleteAction(idLocation, success)\n" ^
      "\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnLoad				\n" ^
      "--		(a save game is being loaded)\n" ^
      "--\n" ^
      "local function OnLoad()\n" ^
      "	questState = QUEST_LOAD_INT();\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnSave				\n" ^
      "--		(a save game is being saved)\n" ^
      "--\n" ^
      "local function OnSave()\n" ^
      "	QUEST_SAVE_INT(questState);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryProgress		\n" ^
      "--		(returns text describing the next step required)\n" ^
      "--\n" ^
      "local function OnQueryProgress()\n" ^
      "	if (questState <= 2) then\n" ^
      "		return GET_TEXT(\"[Q0Q6_PROGRESS0]\");\n" ^
      "	elseif (questState == 3) then\n" ^
      "		return GET_TEXT(\"[Q0Q6_PROGRESS1]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryPercentage	\n" ^
      "--		(returns a percentage of completion)\n" ^
      "--\n" ^
      "local function OnQueryPercentage()\n" ^
      "	if (questState <= 1) then\n" ^
      "		return 0;\n" ^
      "	elseif (questState == 2) then\n" ^
      "		return 20;\n" ^
      "	elseif (questState == 3) then\n" ^
      "		return 80;\n" ^
      "	end\n" ^
      "	return 100;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryDifficulty	\n" ^
      "--		(returns 0-4 for difficulty - v.easy to v.difficult )\n" ^
      "--\n" ^
      "local function OnQueryDifficulty()\n" ^
      "	-- average\n" ^
      "	return 3; \n" ^
      "end\n" ^
      "\n" ^
      "-- CallbackConvX				\n" ^
      "--		(Callback fn - for end of quest)\n" ^
      "--\n" ^
      "local function CallbackConvB ()\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q0Q6_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[Q0Q6_GIFT]\");\n" ^
      "	QUEST_MESSAGE(myTitle, myMessage, myStart);\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackConvC ()\n" ^
      "	QUEST_COMPLETE(myCode);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "--	\n" ^
      "--		DECLARE TABLE	\n" ^
      "--\n" ^
      "\n" ^
      "Q0Q6 = {\n" ^
      "	OnInit				= OnInit,\n" ^
      "	OnBegin				= OnBegin,\n" ^
      "	OnEnd				= OnEnd,\n" ^
      "	OnAbandon			= OnAbandon,\n" ^
      "	OnEnterLocation		= OnEnterLocation,\n" ^
      "	OnExecuteAction		= OnExecuteAction,\n" ^
      "	OnCompleteAction	= OnCompleteAction,\n" ^
      "	OnQueryAction		= OnQueryAction,\n" ^
      "	OnLoad				= OnLoad,\n" ^
      "	OnSave				= OnSave,\n" ^
      "	OnQueryProgress		= OnQueryProgress,\n" ^
      "	OnQueryPercentage	= OnQueryPercentage,\n" ^
      "	OnQueryDifficulty	= OnQueryDifficulty,\n" ^
      "\n" ^
      "	CallbackConvB = CallbackConvB ,\n" ^
      "	CallbackConvC = CallbackConvC ,\n" ^
      "};\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n";
