  {
    id = "Q0Q7";
    name_text = "[QUEST_Q0Q7_NAME]";
    desc_text = "[QUEST_Q0Q7_DESC]";
    group = "[QG_PRIM_NAME]";
    text_file = "English\\Quests\\Q0Q7_Text.xml";
    texts = [("[Q0Q7_ACTION0]", "Meet with Khalkus"); ("[Q0Q7_ACTION1]", "Protect the Caravan"); ("[Q0Q7_ACTION2]", "Battle against Dugog"); ("[Q0Q7_AMBUSH]", "As you are making your way through the Hammer Pass, a band of Ogres leap out at you!"); ("[Q0Q7_BATTLE0]", "Khalkus is impressed with the way you saved the Caravan.   He joins you as a Companion."); ("[Q0Q7_LOSE3]", "You will need to defeat these Ogres before you can progress any further."); ("[Q0Q7_LOSE4]", "Dugog is too strong - you cannot get past him.  You must try again."); ("[Q0Q7_REWARD]", "Dugog is dead, and the way into Dhun-Kor is clear. You take all of his treasure, including a huge Club that looks obviously magical."); ("[Q0Q7_STEP1]", "You must travel to the Hammer Pass and meet with Khalkus."); ("[Q0Q7_STEP2]", "You must travel to Theira and help the Caravan safely through."); ("[Q0Q7_STEP3]", "You must travel to Dhun-Kor and defeat Dugog, the two-headed Ogre."); ("[Q0Q7_WIN3]", "The Ogres have been defeated and you may travel down into the lands of Kor."); ("[Q0Q7_DUGOG]", "Dugog, the giant two-headed Ogre, stands at the gates of Dhun-Kor, blocking your way."); ("[QUEST_Q0Q7_BATTLE0_FAIL]", "The Wight has captured the Caravan. You must fight him again to capture it back."); ("[QUEST_Q0Q7_QMHELP0]", "This  Wight is better equipped and armored than most."); ("[QUEST_Q0Q7_QMHELP1]", "This Ogre is wearing Chainmail armor for better protection."); ("[QUEST_Q0Q7_QMHELP2]", "Dugog, the two-headed Ogre, is the leader of the forces that have been attacking Agaria. Beware the second head!")];
    lua_file = "Assets\\Quests\\Q0Q7.lua";
    lua_object = "Q0Q7";
    lua_source = "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--             Dwarven Caravan	\n" ^
      "--	\n" ^
      "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--		STATES	\n" ^
      "--\n" ^
      "-- 0 => Inactive\n" ^
      "-- 1 => Got Quest\n" ^
      "-- 2 => Met Khalkus and talked with him\n" ^
      "-- 3 => Saved Caravan in Theira\n" ^
      "-- 4 => Defeated the Ogre in the Hammer Pass\n" ^
      "-- 5 => Finished (defeated Dugog)\n" ^
      "-- \n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Variables\n" ^
      "--\n" ^
      "local questState = 0;\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Constants\n" ^
      "--\n" ^
      "local myCode     = \"Q0Q7\";\n" ^
      "local myOrigin   = \"CBAR\";\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnInit				\n" ^
      "--		(called for every quest when they are loading\n" ^
      "--		 to set the initial state of all variables)\n" ^
      "--\n" ^
      "local function OnInit()\n" ^
      "	questState = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnBegin				\n" ^
      "--		(called when a quest is first obtained)\n" ^
      "--\n" ^
      "local function OnBegin()\n" ^
      "	questState = 1;\n" ^
      "	QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q0Q7a.xml\",myOrigin);\n" ^
      "\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnd				\n" ^
      "--		(called when a quest has ended)\n" ^
      "--\n" ^
      "local function OnEnd()\n" ^
      "	questState = 5;\n" ^
      "	\n" ^
      "	-- Reward\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q0Q7_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[Q0Q7_REWARD]\");\n" ^
      "	QUEST_REWARD_MENU(myTitle,myMessage);\n" ^
      "	QUEST_REWARD_ITEM(\"IDCL\");\n" ^
      "	QUEST_REWARD_GOLD(1000);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnAbandon				\n" ^
      "--		(called when a quest has been abandoned by the player)\n" ^
      "--\n" ^
      "local function OnAbandon()\n" ^
      "	-- cannot be abandoned\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnterLocation		\n" ^
      "--		(a hero has arrived at a new location)\n" ^
      "--\n" ^
      "local function OnEnterLocation(idLocation)\n" ^
      "	if (questState == 3 and idLocation==\"WHPS\") then\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_Q0Q7_NAME]\");\n" ^
      "		local myMessage = GET_TEXT(\"[Q0Q7_AMBUSH]\");\n" ^
      "		QUEST_MESSAGE_CALLBACK(myTitle,myMessage,idLocation, \"Q0Q7\",\"CallbackAmbush\");\n" ^
      "		QUEST_STOP_MOVEMENT();\n" ^
      "	elseif (questState == 4 and idLocation==\"CDKO\") then\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_Q0Q7_NAME]\");\n" ^
      "		local myMessage = GET_TEXT(\"[Q0Q7_DUGOG]\");\n" ^
      "		QUEST_MESSAGE(myTitle,myMessage,idLocation);\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryAction\n" ^
      "--		(should anything appear on the popup menu)\n" ^
      "--\n" ^
      "local function OnQueryAction(idLocation)\n" ^
      "	if (idLocation==\"WHPS\" and questState==1) then\n" ^
      "		return GET_TEXT(\"[Q0Q7_ACTION0]\");\n" ^
      "\n" ^
      "	elseif (idLocation==\"WTHR\" and questState==2) then\n" ^
      "		return GET_TEXT(\"[Q0Q7_ACTION1]\");\n" ^
      "\n" ^
      "	elseif (idLocation==\"CDKO\" and (questState==3 or questState==4)) then\n" ^
      "		return GET_TEXT(\"[Q0Q7_ACTION2]\");\n" ^
      "\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnExecuteAction				\n" ^
      "--		(do this whenever the player executes the next action)\n" ^
      "--\n" ^
      "local function OnExecuteAction(idLocation)\n" ^
      "	if (idLocation==\"WHPS\" and questState==1) then\n" ^
      "		-- Talk to Khalkus\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q0Q7b.xml\",idLocation);\n" ^
      "		questState = 2;\n" ^
      "		QUEST_UPDATE_MAP();\n" ^
      "	elseif (idLocation==\"WTHR\" and questState==2) then\n" ^
      "		-- Fight some Undead\n" ^
      "		QUEST_BATTLE(myCode,0,1);	\n" ^
      "	elseif (idLocation==\"CDKO\" and (questState==3 or questState==4)) then\n" ^
      "		-- Fight some Undead\n" ^
      "		QUEST_BATTLE_NOCAPTURE(myCode,2,0);	\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnCompleteAction				\n" ^
      "--		(do this whenever the player completes his action)\n" ^
      "--		It is called after the game has returned to the map screen\n" ^
      "--\n" ^
      "local function OnCompleteAction(idLocation, success)\n" ^
      "	if (questState==2) then\n" ^
      "	\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_Q0Q7_NAME]\");\n" ^
      "\n" ^
      "		if (success == 1) then\n" ^
      "			local myMessage = GET_TEXT(\"[Q0Q7_BATTLE0]\");\n" ^
      "			QUEST_MESSAGE(myTitle,myMessage,idLocation);\n" ^
      "			questState = 3;\n" ^
      "			QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q0Q7c.xml\",idLocation);\n" ^
      "\n" ^
      "			-- Add the Ogre encounter \n" ^
      "			QUEST_SET_VISIBILITY(\"CDKO\",1);\n" ^
      "			QUEST_SET_CITY_STATUS(\"CDKO\",CITYSTATUS_CLOSED);		\n" ^
      "			local encounterId = QUEST_ENCOUNTER_GET_AT(\"WHPS\",\"CDKO\");\n" ^
      "			if (encounterId1 ~= \"EDOG\") then\n" ^
      "				if (encounterId ~= \"\") then\n" ^
      "					QUEST_ENCOUNTER_REMOVE_AT(\"WHPS\",\"CDKO\");\n" ^
      "				end\n" ^
      "				QUEST_ENCOUNTER_ADD(\"EDOG\");\n" ^
      "			end\n" ^
      "\n" ^
      "		else -- Failure\n" ^
      "			local myMessage = GET_TEXT(\"[QUEST_Q0Q7_BATTLE0_FAIL]\");\n" ^
      "			QUEST_MESSAGE(myTitle,myMessage,idLocation);\n" ^
      "		end\n" ^
      "	\n" ^
      "	elseif (questState == 3 and idLocation == \"WHPS\") then\n" ^
      "\n" ^
      "		-- Going towards Dhun-Kor\n" ^
      "		local myMessage;\n" ^
      "		if (success == 0) then\n" ^
      "			QUEST_MOVE(\"WTHR\");\n" ^
      "			myMessage = GET_TEXT(\"[Q0Q7_LOSE3]\");\n" ^
      "		else\n" ^
      "			questState = 4;\n" ^
      "			myMessage = GET_TEXT(\"[Q0Q7_WIN3]\");\n" ^
      "		end\n" ^
      "		QUEST_MESSAGE(myTitle,myMessage,idLocation);\n" ^
      "		QUEST_UPDATE_MAP();\n" ^
      "\n" ^
      "	elseif (questState >= 3 and idLocation == \"CDKO\") then\n" ^
      "		-- Defeat Dugog\n" ^
      "		if (success == 0) then\n" ^
      "			local myTitle = GET_TEXT(\"[QUEST_Q0Q7_NAME]\");\n" ^
      "			local myMessage = GET_TEXT(\"[Q0Q7_LOSE4]\");\n" ^
      "			QUEST_MESSAGE(myTitle,myMessage,idLocation);\n" ^
      "		else\n" ^
      "			QUEST_SET_CITY_STATUS(\"CDKO\",CITYSTATUS_AVAILABLE);\n" ^
      "			QUEST_COMPLETE(myCode);\n" ^
      "		end\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnLoad				\n" ^
      "--		(a save game is being loaded)\n" ^
      "--\n" ^
      "local function OnLoad()\n" ^
      "	questState = QUEST_LOAD_INT();\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnSave				\n" ^
      "--		(a save game is being saved)\n" ^
      "--\n" ^
      "local function OnSave()\n" ^
      "	QUEST_SAVE_INT(questState);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryProgress		\n" ^
      "--		(returns text describing the next step required)\n" ^
      "--\n" ^
      "local function OnQueryProgress()\n" ^
      "	if (questState == 1) then\n" ^
      "		return GET_TEXT(\"[Q0Q7_STEP1]\");\n" ^
      "	elseif (questState == 2) then\n" ^
      "		return GET_TEXT(\"[Q0Q7_STEP2]\");\n" ^
      "	elseif (questState == 3 or questState == 4) then\n" ^
      "		return GET_TEXT(\"[Q0Q7_STEP3]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryPercentage	\n" ^
      "--		(returns a percentage of completion)\n" ^
      "--\n" ^
      "local function OnQueryPercentage()\n" ^
      "	return (questState-1) * 25;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryDifficulty	\n" ^
      "--		(returns 0-4 for difficulty - v.easy to v.difficult )\n" ^
      "--\n" ^
      "local function OnQueryDifficulty()\n" ^
      "	-- average\n" ^
      "	return 2; \n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "-- CallbackAmbush				\n" ^
      "--		(Callback fn - for after the ambush message)\n" ^
      "--\n" ^
      "local function CallbackAmbush()\n" ^
      "	  	QUEST_BATTLE(myCode,1,1);\n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "local function CallbackConvC ()\n" ^
      "	QUEST_ADD_COMPANION(\"NKHA\");\n" ^
      "	QUEST_COMPANION_MESSAGE(\"NKHA\");\n" ^
      "end\n" ^
      "\n" ^
      "------------------------------------------------\n" ^
      "--\n" ^
      "-- OnCancelAction\n" ^
      "--\n" ^
      "--    Called whenever a battle is cancelled\n" ^
      "--\n" ^
      "local function OnCancelAction(idLocation)\n" ^
      "	if(idLocation == \"WHPS\") then\n" ^
      "		QUEST_MOVE(\"WTHR\");--Move Character back to Theira\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
