  {
    id = "Q0R0";
    name_text = "[QUEST_Q0R0_NAME]";
    desc_text = "[QUEST_Q0R0_DESC]";
    group = "";
    text_file = "English\\Quests\\Q0R0_Text.xml";
    texts = [("[QUEST_Q0R0_ACTION0]", "You must first patrol the road to Elenia."); ("[QUEST_Q0R0_ACTION1]", "You must now patrol the road back to Bartonia."); ("[QUEST_Q0R0_DONE]", "The patrol has ended successfully and you receive your payment."); ("[QUEST_Q0R0_MESSAGE]", "You have completed the first part of your patrol.  Now you must travel back to Bartonia, but be warned, travelers report seeing Undead lurking near the road.")];
    lua_file = "Assets\\Quests\\Q0R0.lua";
    lua_object = "Q0R0";
    lua_source = "--	\n" ^
      "--		STATES	\n" ^
      "--\n" ^
      "-- 0 => Inactive\n" ^
      "-- 1 => Quest obtained, nothing done yet (no travel)\n" ^
      "-- 2 => Arrived in Elenia\n" ^
      "-- \n" ^
      "\n" ^
      "-- Local Variables\n" ^
      "--\n" ^
      "local questState = 0;\n" ^
      "\n" ^
      "\n" ^
      "-- Local Constants\n" ^
      "--\n" ^
      "local myCode = \"Q0R0\";\n" ^
      "local myLocation = \"WELE\";\n" ^
      "local myOrigin = \"CBAR\";\n" ^
      "\n" ^
      "--	\n" ^
      "--		FUNCTIONS	\n" ^
      "--\n" ^
      "\n" ^
      "-- OnInit				\n" ^
      "--		(called for every quest when they are loading\n" ^
      "--		 to set the initial state of all variables)\n" ^
      "--\n" ^
      "local function OnInit()\n" ^
      "	questState = 0;\n" ^
      "end\n" ^
      "\n" ^
      "-- OnBegin				\n" ^
      "--		(called when a quest is first obtained)\n" ^
      "--\n" ^
      "local function OnBegin()\n" ^
      "	questState = 1;\n" ^
      "end\n" ^
      "\n" ^
      "-- OnEnd				\n" ^
      "--		(called when a quest has ended)\n" ^
      "--\n" ^
      "local function OnEnd()\n" ^
      "	questState = 0;\n" ^
      "	\n" ^
      "	-- Reward\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q0R0_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[QUEST_Q0R0_DONE]\");\n" ^
      "	QUEST_REWARD_MENU(myTitle,myMessage);\n" ^
      "	QUEST_REWARD_XP(10);\n" ^
      "	QUEST_REWARD_GOLD(20);\n" ^
      "end\n" ^
      "\n" ^
      "-- OnAbandon				\n" ^
      "--		(called when a quest has been abandoned by the player)\n" ^
      "--\n" ^
      "local function OnAbandon()\n" ^
      "	questState = 0;  -- it can be restarted\n" ^
      "end\n" ^
      "\n" ^
      "-- OnEnterLocation		\n" ^
      "--		(a hero has arrived at a new location)\n" ^
      "--\n" ^
      "local function OnEnterLocation(idLocation)\n" ^
      "	if (idLocation == myLocation and questState == 1) then\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_Q0R0_NAME]\");\n" ^
      "		local myMessage = GET_TEXT(\"[QUEST_Q0R0_MESSAGE]\");\n" ^
      "		QUEST_COMPLETE_PART(myCode,myLocation,1);\n" ^
      "		QUEST_STOP_MOVEMENT();\n" ^
      "	elseif (idLocation == myOrigin and questState == 2) then\n" ^
      "		QUEST_STOP_MOVEMENT();\n" ^
      "		QUEST_COMPLETE(myCode);\n" ^
      "	end\n" ^
      "	\n" ^
      "end\n" ^
      "\n" ^
      "-- OnQueryAction\n" ^
      "--		(should anything appear on the popup menu)\n" ^
      "--\n" ^
      "local function OnQueryAction(idLocation)\n" ^
      "	if (idLocation==myLocation and questState==1) then\n" ^
      "			return GET_TEXT(\"[ON]\");\n" ^
      "			\n" ^
      "	elseif (idLocation==myOrigin and questState==2) then\n" ^
      "			return GET_TEXT(\"[ON]\");\n" ^
      "\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "-- OnExecuteAction				\n" ^
      "--		(do this whenever the player executes the next action)\n" ^
      "--\n" ^
      "local function OnExecuteAction(idLocation)\n" ^
      "end\n" ^
      "\n" ^
      "-- OnCompleteAction				\n" ^
      "--		(do this whenever the player completes his action)\n" ^
      "--		It is called after the game has returned to the map screen\n" ^
      "--\n" ^
      "local function OnCompleteAction(idLocation, success)\n" ^
      "\n" ^
      "		\n" ^
      "	if (questState == 1) then\n" ^
      "		questState = 2;\n" ^
      "		\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_Q0R0_NAME]\");\n" ^
      "		local myMessage = GET_TEXT(\"[QUEST_Q0R0_MESSAGE]\");\n" ^
      "		QUEST_MESSAGE(myTitle, myMessage, myLocation);\n" ^
      "		\n" ^
      "		-- Add the spider (but remove anything else there first)\n" ^
      "		Std_AddEncounter(myLocation,myOrigin,\"EESK\");\n" ^
      "		\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "-- OnLoad				\n" ^
      "--		(a save game is being loaded)\n" ^
      "--\n" ^
      "local function OnLoad()\n" ^
      "	questState	 = QUEST_LOAD_INT();\n" ^
      "end\n" ^
      "\n" ^
      "-- OnSave				\n" ^
      "--		(a save game is being saved)\n" ^
      "--\n" ^
      "local function OnSave()\n" ^
      "	QUEST_SAVE_INT(questState);\n" ^
      "end\n" ^
      "\n" ^
      "-- OnQueryProgress		\n" ^
      "--		(returns text describing the next step required)\n" ^
      "--\n" ^
      "local function OnQueryProgress()\n" ^
      "	local myText=\"\";\n" ^
      "	if (questState == 1) then\n" ^
      "		myText = GET_TEXT(\"[QUEST_Q0R0_ACTION0]\");\n" ^
      "	elseif (questState == 2) then\n" ^
      "		myText = GET_TEXT(\"[QUEST_Q0R0_ACTION1]\");\n" ^
      "	end\n" ^
      "	return myText;\n" ^
      "end\n" ^
      "\n" ^
      "-- OnQueryPercentage	\n" ^
      "--		(returns a percentage of completion)\n" ^
      "--\n" ^
      "local function OnQueryPercentage()\n" ^
      "	if (questState == 1) then \n" ^
      "		return 0;\n" ^
      "	elseif (questState == 2) then\n" ^
      "		return 50;\n" ^
      "	end\n" ^
      "	return 100;\n" ^
      "end\n" ^
      "\n" ^
      "-- OnQueryDifficulty	\n" ^
      "--		(returns 0-4 for difficulty - v.easy to v.difficult )\n" ^
      "--\n" ^
      "local function OnQueryDifficulty()\n" ^
      "	return 1;\n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "--	\n" ^
      "--		DECLARE TABLE	\n" ^
      "--\n" ^
