      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryProgress		\n" ^
      "--		(returns text describing the next step required)\n" ^
      "--\n" ^
      "local function OnQueryProgress()\n" ^
      "	if (questState == 1) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q0T0_STEP1]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryPercentage	\n" ^
      "--		(returns a percentage of completion)\n" ^
      "--\n" ^
      "local function OnQueryPercentage()\n" ^
      "	if (questState <= 1) then\n" ^
      "		return 0;\n" ^
      "	end\n" ^
      "	return 100;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryDifficulty	\n" ^
      "--		(returns 0-4 for difficulty - v.easy to v.difficult )\n" ^
      "--\n" ^
      "local function OnQueryDifficulty()\n" ^
      "	-- easy\n" ^
      "	return 0; \n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "\n" ^
      "local function CallbackConvA ()\n" ^
      "	questState = 1;\n" ^
      "	QUEST_SET_VISIBILITY(\"WSIR\",1);\n" ^
      "	QUEST_SET_VISIBILITY(\"WTHR\",1);\n" ^
      "	QUEST_SET_VISIBILITY(\"WELE\",1);\n" ^
      "	QUEST_SET_VISIBILITY(\"WGIL\",1);\n" ^
      "	\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "	\n" ^
      "	if (TUTORIAL_ACTIVE()==1) then\n" ^
      "		TUTORIAL_OPEN(\"QuestMove\");\n" ^
      "	end\n" ^
      "	\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackConvB ()\n" ^
      "	\n" ^
      "	-- Reward\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q0T0_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[QUEST_Q0T0_REWARD]\");\n" ^
      "	QUEST_REWARD_MENU_CALLBACK(myTitle,myMessage,myCode,\"CallbackReward\");\n" ^
      "	QUEST_REWARD_ITEM(\"IBSH\");\n" ^
      "	QUEST_REWARD_XP(1);\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackMessage ()\n" ^
      "	if (TUTORIAL_ACTIVE()==1) then\n" ^
      "		TUTORIAL_OPEN(\"QuestAction\");\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackReward ()\n" ^
      "	if (TUTORIAL_ACTIVE()==1) then\n" ^
      "		TUTORIAL_OPEN(\"QuestMoreQuests\");\n" ^
      "	end\n" ^
      "	QUEST_COMPLETE(myCode);\n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "--	\n" ^
      "--		DECLARE TABLE	\n" ^
      "--\n" ^
      "\n" ^
      "Q0T0 = {\n" ^
      "	OnInit				= OnInit,\n" ^
      "	OnBegin				= OnBegin,\n" ^
      "	OnEnd				= OnEnd,\n" ^
      "	OnAbandon			= OnAbandon,\n" ^
      "	OnEnterLocation		= OnEnterLocation,\n" ^
      "	OnExecuteAction		= OnExecuteAction,\n" ^
      "	OnCompleteAction	= OnCompleteAction,\n" ^
      "	OnQueryAction		= OnQueryAction,\n" ^
      "	OnLoad				= OnLoad,\n" ^
      "	OnSave				= OnSave,\n" ^
      "	OnQueryProgress		= OnQueryProgress,\n" ^
      "	OnQueryPercentage	= OnQueryPercentage,\n" ^
      "	OnQueryDifficulty	= OnQueryDifficulty,\n" ^
      "	\n" ^
      "	CallbackConvA = CallbackConvA ,\n" ^
      "	CallbackConvB = CallbackConvB ,\n" ^
      "	CallbackMessage = CallbackMessage ,\n" ^
      "	CallbackReward = CallbackReward ,\n" ^
      "};\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n";
    abandonable = false;
    icon = 0;
    important = true;
    avail_location = "CBAR";
    avail_minlevel = 1;
    avail_maxlevel = 1000;
    avail_repeat = 1;
    avail_donequest0 = "";
    avail_donequest1 = "";
    avail_donequest2 = "";
    avail_notdonequest = "";
    avail_notactivequest = "";
    avail_companion0 = "";
    avail_companion1 = "";
    avail_notcompanion = "";
    avail_item = "";
    avail_notitem = "";
    avail_award = "";
    avail_notaward = "";
    battle_monster = "";
    battle_spells = [];
    battles = [];
    battle_actions = [];
    battle_stage_advances = [];
    battle_stage_fails = [];
    enter_removes = [];
    reveal_on_begin = ["WSIR"; "WTHR"; "WELE"; "WGIL"];
    reveal_on_end = [];
    ruin_reveals = [];
