    abandonable = false;
    icon = 0;
    important = true;
    avail_location = "CBAR";
    avail_minlevel = 1;
    avail_maxlevel = 1000;
    avail_repeat = 0;
    avail_donequest0 = "Q0T0";
    avail_donequest1 = "";
    avail_donequest2 = "";
    avail_notdonequest = "Q0Q0";
