  {
    id = "Q0T2";
    name_text = "[QUEST_Q0T2_NAME]";
    desc_text = "[QUEST_Q0T2_DESC]";
    group = "[QG_PRIM_NAME]";
    text_file = "English\\Quests\\Q0T2_Text.xml";
    texts = [("[QUEST_Q0T2_ACTION]", "Advanced Combat Training"); ("[QUEST_Q0T2_FAILURE]", "You have failed your combat training. You must try again."); ("[QUEST_Q0T2_REWARD]", "You have passed your combat training."); ("[QUEST_Q0T2_QMNAME0]", "Young Knight")];
    lua_file = "Assets\\Quests\\Q0T2.lua";
    lua_object = "Q0T2";
    lua_source = "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--             Advanced Combat	\n" ^
      "--	\n" ^
      "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--		STATES	\n" ^
      "--\n" ^
      "-- 0 => Inactive\n" ^
      "-- 1 => Quest obtained, nothing done yet\n" ^
      "-- 2 => Finished\n" ^
      "-- \n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Variables\n" ^
      "--\n" ^
      "local questState = 0;\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Constants\n" ^
      "--\n" ^
      "local myCode        = \"Q0T2\";\n" ^
      "local myOrigin      = \"CBAR\";\n" ^
      "local myPrevQuest   = \"Q0T1\";\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "\n" ^
      "local function CallbackConvA ()\n" ^
      "	questState = 1;\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "	QUEST_BATTLE_CUSTOM(myCode,0,0, \n" ^
      "				myCode,\"T2_StartTurn\",\"T2_StartBattle\",\"\",\"\",\"\",\"T2_Match4\",\"T2_Match5\");\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnInit				\n" ^
      "--		(called for every quest when they are loading\n" ^
      "--		 to set the initial state of all variables)\n" ^
      "--\n" ^
      "local function OnInit()\n" ^
      "	questState = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnBegin				\n" ^
      "--		(called when a quest is first obtained)\n" ^
      "--\n" ^
      "local function OnBegin()\n" ^
      "	questState = 1;\n" ^
      "	if (QUEST_COUNT_DONE(myCode)==0) then\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q0T2a.xml\",myOrigin);\n" ^
      "	else\n" ^
      "		CallbackConvA();\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnd				\n" ^
      "--		(called when a quest has ended)\n" ^
      "--\n" ^
      "local function OnEnd()\n" ^
      "	questState = 0;\n" ^
      "	\n" ^
      "	-- Reward\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q0T2_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[QUEST_Q0T2_REWARD]\");\n" ^
      "	QUEST_REWARD_MENU(myTitle,myMessage);\n" ^
      "	QUEST_REWARD_XP(1);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnAbandon				\n" ^
      "--		(called when a quest has been abandoned by the player)\n" ^
      "--\n" ^
      "local function OnAbandon()\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnterLocation		\n" ^
      "--		(a hero has arrived at a new location)\n" ^
      "--\n" ^
      "local function OnEnterLocation(idLocation)\n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryAction\n" ^
      "--		(should anything appear on the popup menu)\n" ^
      "--\n" ^
      "local function OnQueryAction(idLocation)\n" ^
      "	if (idLocation==myOrigin and questState==1) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q0T2_ACTION]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnExecuteAction				\n" ^
      "--		(do this whenever the player executes the next action)\n" ^
      "--\n" ^
      "local function OnExecuteAction(idLocation)\n" ^
      "	CallbackConvA();\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnCompleteAction				\n" ^
      "--		(do this whenever the player completes his action)\n" ^
      "--		It is called after the game has returned to the map screen\n" ^
      "--\n" ^
      "local function OnCompleteAction(idLocation, success)\n" ^
      "\n" ^
      "	if (questState==1) then\n" ^
      "	\n" ^
      "		if (success == 1) then\n" ^
      "			if (TUTORIAL_ACTIVE()==1) then\n" ^
      "				TUTORIAL_OPEN(\"Quest_T2b\");\n" ^
      "			else\n" ^
      "				QUEST_COMPLETE(myCode);\n" ^
      "			end\n" ^
      "		else\n" ^
      "			local myTitle = GET_TEXT(\"[QUEST_Q0T2_NAME]\");\n" ^
      "			local myMessage = GET_TEXT(\"[QUEST_Q0T2_FAILURE]\");\n" ^
      "			QUEST_MESSAGE(myTitle,myMessage,idLocation);\n" ^
      "		end\n" ^
      "		\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnLoad				\n" ^
      "--		(a save game is being loaded)\n" ^
      "--\n" ^
      "local function OnLoad()\n" ^
      "	questState = QUEST_LOAD_INT();\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnSave				\n" ^
      "--		(a save game is being saved)\n" ^
      "--\n" ^
      "local function OnSave()\n" ^
      "	QUEST_SAVE_INT(questState);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryProgress		\n" ^
      "--		(returns text describing the next step required)\n" ^
      "--\n" ^
      "local function OnQueryProgress()\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryPercentage	\n" ^
      "--		(returns a percentage of completion)\n" ^
      "--\n" ^
      "local function OnQueryPercentage()\n" ^
      "	if (questState <= 1) then\n" ^
      "		return 0;\n" ^
      "	end\n" ^
      "	return 100;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryDifficulty	\n" ^
      "--		(returns 0-4 for difficulty - v.easy to v.difficult )\n" ^
      "--\n" ^
      "local function OnQueryDifficulty()\n" ^
      "	-- average\n" ^
      "	return 1; \n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "\n" ^
      "--\n" ^
      "-- Local Tutorial Constants\n" ^
      "--\n" ^
      "local tuteDoneSkulls		= 0;\n" ^
      "local tuteDoneMatch4		= 0;\n" ^
      "local tuteDoneMatch5		= 0;\n" ^
      "local tuteDoneWildcard		= 0;\n" ^
      "local tuteDoneRedSkull		= 0;\n" ^
      "local tuteDoneExtra			= 0;\n" ^
      "local tuteDoneSpell			= 0;\n" ^
      "local tuteDoneGreen			= 0;\n" ^
      "local tuteDoneRed			= 0;\n" ^
      "local tuteDoneYellow		= 0;\n" ^
      "local tuteDoneBlue			= 0;\n" ^
      "\n" ^
      "\n" ^
      "local function T2_StartTurn(characterIdx, turnNo)\n" ^
      "\n" ^
      "	-- Set up gems on first turn only\n" ^
      "	if (turnNo == 1 and characterIdx == 0) then\n" ^
      "		SET_ILLEGAL_MOVE_DAMAGE_ENABLED(0);\n" ^
      "		TUTORIAL_GAME_SET_GEMS(\"ROOBO*RS\",\"GRSR*YBB\",\"*YBGRRGB\",\"GRGOSOSS\",\"YGBROBR*\",\"OOYR*BSO\",\"*BROGYYR\",\"O*YGSBRY\");\n" ^
      "	end\n" ^
      "	\n" ^
      "	-- Check gem layout for human player only\n" ^
      "	if (characterIdx == 0 and turnNo >= 1) then\n" ^
      "		\n" ^
      "		BufferLocalGemTable();\n" ^
      "		\n" ^
      "		-- Match 5\n" ^
      "		local keepSearching = true;\n" ^
      "		local x1,y1,x2,y2;\n" ^
      "		if (keepSearching and tuteDoneMatch5 <= 100) then\n" ^
      "				x1,y1,x2,y2 = CheckForSequences(5);\n" ^
      "				if (x1 >= 0) then\n" ^
      "					if (TUTORIAL_ACTIVE()==1) then\n" ^
      "						TUTORIAL_OPPTUTE_SWAP(x1,y1,x2,y2,GET_TEXT(\"[OT_MATCH_5]\"),0,1);\n" ^
      "					end\n" ^
      "					keepSearching = false;\n" ^
      "					tuteDoneMatch5 = tuteDoneMatch5 + 1;\n" ^
      "				end\n" ^
      "		end\n" ^
      "		\n" ^
      "		-- Match 4\n" ^
      "		if (keepSearching and tuteDoneMatch4 <= 100) then\n" ^
      "				x1,y1,x2,y2 = CheckForSequences(4);\n" ^
      "				if (x1 >= 0) then\n" ^
      "					if (TUTORIAL_ACTIVE()==1) then\n" ^
      "						TUTORIAL_OPPTUTE_SWAP(x1,y1,x2,y2,GET_TEXT(\"[OT_MATCH_4]\"),0,1);\n" ^
      "					end\n" ^
      "					keepSearching = false;\n" ^
      "					tuteDoneMatch4 = tuteDoneMatch4 + 1;\n" ^
      "				end\n" ^
      "		end\n" ^
      "		\n" ^
      "		-- Red Skull...\n" ^
      "		if (keepSearching and tuteDoneRedSkull <= 1) then\n" ^
      "				x1,y1 = CheckForRedSkull();\n" ^
      "				if (x1 >= 0) then\n" ^
      "					local msg;\n" ^
      "					if (tuteDoneRedSkull==0) then\n" ^
      "						msg = GET_TEXT(\"[OT_REDSKULL0]\");\n" ^
      "					else\n" ^
      "						msg = GET_TEXT(\"[OT_REDSKULL1]\");\n" ^
      "					end\n" ^
      "					if (TUTORIAL_ACTIVE()==1) then\n" ^
      "						TUTORIAL_OPPTUTE_GEM(x1,y1,msg,0,1);\n" ^
      "					end\n" ^
      "					keepSearching = false;\n" ^
      "					tuteDoneRedSkull = tuteDoneRedSkull + 1;\n" ^
      "				end\n" ^
      "		end\n" ^
      "		\n" ^
      "		-- Wildcard...\n" ^
      "		if (keepSearching and tuteDoneWildcard <= 1) then\n" ^
      "				x1,y1,wild = CheckForWildcard();\n" ^
      "				if (x1 >= 0) then\n" ^
      "					local msg;\n" ^
      "					if (tuteDoneWildcard==0) then\n" ^
      "						msg = GET_TEXT(\"[OT_WILDCARD0]\");\n" ^
      "					else\n" ^
      "						msg = GET_TEXT(\"[OT_WILDCARD1]\");\n" ^
      "					end\n" ^
      "					if (TUTORIAL_ACTIVE()==1) then\n" ^
      "						TUTORIAL_OPPTUTE_GEM(x1,y1,msg,0,1);\n" ^
      "					end\n" ^
      "					keepSearching = false;\n" ^
      "					tuteDoneWildcard = tuteDoneWildcard + 1;\n" ^
      "				end\n" ^
      "		end\n" ^
      "		\n" ^
      "		-- Skulls\n" ^
      "		if (keepSearching and tuteDoneSkulls <= 2) then\n" ^
      "			x1,y1,x2,y2 = CheckForPatterns(GEM_SKULL); \n" ^
      "			if (x1 >= 0) then\n" ^
      "				local msg;\n" ^
      "				if (tuteDoneSkulls == 0) then\n" ^
      "					msg = GET_TEXT(\"[OT_MATCH_SKULLS3]\");\n" ^
      "				elseif (tuteDoneSkulls == 1) then\n" ^
      "					msg = GET_TEXT(\"[OT_MATCH_SKULLS4]\");\n" ^
      "				else\n" ^
      "					msg = GET_TEXT(\"[OT_MATCH_SKULLS5]\");\n" ^
      "				end\n" ^
      "				if (TUTORIAL_ACTIVE()==1) then\n" ^
      "					TUTORIAL_OPPTUTE_SWAP(x1,y1,x2,y2,msg,0,1);\n" ^
      "				end\n" ^
      "				keepSearching = false;\n" ^
      "				tuteDoneSkulls = tuteDoneSkulls + 1;\n" ^
      "			end\n" ^
      "		end\n" ^
      "		\n" ^
      "		-- SPELLCASTING\n" ^
      "		if (keepSearching and tuteDoneSpell<=2) then\n" ^
      "			local spl;\n" ^
      "			local numspl = GET_NUM_SPELLS(0);\n" ^
      "			for spl=0,numspl-1 do\n" ^
      "				if (IS_SPELL_CASTABLE(0,spl)) then\n" ^
      "					local msg;\n" ^
      "					if (tuteDoneSpell == 0) then\n" ^
      "						msg = GET_TEXT(\"[OT_SPELLCASTING2]\");\n" ^
      "					elseif (tuteDoneSpell == 1) then\n" ^
      "						msg = GET_TEXT(\"[OT_SPELLCASTING3]\");\n" ^
      "					else\n" ^
      "						msg = GET_TEXT(\"[OT_SPELLCASTING4]\");\n" ^
      "					end\n" ^
      "					if (TUTORIAL_ACTIVE()==1) then\n" ^
      "						TUTORIAL_OPPTUTE_SPELL(spl,msg,0,1);\n" ^
      "					end\n" ^
      "					keepSearching = false;\n" ^
      "					tuteDoneSpell = tuteDoneSpell + 1;\n" ^
      "					break;\n" ^
      "				end\n" ^
      "			end\n" ^
      "		end\n" ^
      "		\n" ^
      "		-- GREEN MANA\n" ^
      "		if (keepSearching and tuteDoneGreen <= 0) then\n" ^
      "			x1,y1,x2,y2 = CheckForPatterns(GEM_GREEN); \n" ^
      "			if (x1 >= 0) then\n" ^
      "				if (TUTORIAL_ACTIVE()==1) then\n" ^
      "					TUTORIAL_OPPTUTE_SWAP(x1,y1,x2,y2,GET_TEXT(\"[OT_MATCH_GREEN1]\"),0,1);\n" ^
      "				end\n" ^
      "				keepSearching = false;\n" ^
      "				tuteDoneGreen = tuteDoneGreen + 1;\n" ^
      "			end\n" ^
      "		end\n" ^
      "		\n" ^
      "		-- RED MANA\n" ^
      "		if (keepSearching and tuteDoneRed <= 0) then\n" ^
      "			x1,y1,x2,y2 = CheckForPatterns(GEM_RED); \n" ^
      "			if (x1 >= 0) then\n" ^
      "				if (TUTORIAL_ACTIVE()==1) then\n" ^
      "					TUTORIAL_OPPTUTE_SWAP(x1,y1,x2,y2,GET_TEXT(\"[OT_MATCH_RED1]\"),0,1);\n" ^
      "				end\n" ^
      "				keepSearching = false;\n" ^
      "				tuteDoneRed = tuteDoneRed + 1;\n" ^
      "			end\n" ^
      "		end\n" ^
      "		\n" ^
      "		-- YELLOW MANA\n" ^
      "		if (keepSearching and tuteDoneYellow <= 0) then\n" ^
      "			x1,y1,x2,y2 = CheckForPatterns(GEM_YELLOW); \n" ^
      "			if (x1 >= 0) then\n" ^
      "				if (TUTORIAL_ACTIVE()==1) then\n" ^
      "					TUTORIAL_OPPTUTE_SWAP(x1,y1,x2,y2,GET_TEXT(\"[OT_MATCH_YELLOW1]\"),0,1);\n" ^
      "				end\n" ^
      "				keepSearching = false;\n" ^
      "				tuteDoneYellow = tuteDoneYellow + 1;\n" ^
      "			end\n" ^
      "		end\n" ^
      "		\n" ^
      "		-- BLUE MANA\n" ^
      "		if (keepSearching and tuteDoneBlue <= 0) then\n" ^
      "			x1,y1,x2,y2 = CheckForPatterns(GEM_BLUE); \n" ^
      "			if (x1 >= 0) then\n" ^
      "				if (TUTORIAL_ACTIVE()==1) then\n" ^
      "					TUTORIAL_OPPTUTE_SWAP(x1,y1,x2,y2,GET_TEXT(\"[OT_MATCH_BLUE1]\"),0,1);\n" ^
      "				end\n" ^
      "				keepSearching = false;\n" ^
      "				tuteDoneBlue = tuteDoneBlue + 1;\n" ^
      "			end\n" ^
      "		end\n" ^
      "		\n" ^
      "		-- Extra Dialog\n" ^
      "		if (keepSearching and tuteDoneExtra <= 0) then\n" ^
      "				if (TUTORIAL_ACTIVE()==1) then\n" ^
      "					TUTORIAL_OPEN(\"Quest_T2a\");\n" ^
      "				end\n" ^
      "				keepSearching = false;\n" ^
      "				tuteDoneExtra = tuteDoneExtra + 1;\n" ^
      "		end\n" ^
      "		\n" ^
      "	end\n" ^
      "	\n" ^
      "	\n" ^
      "	\n" ^
      "	-- Show tute on first turn only\n" ^
      "	if (turnNo == 1 and characterIdx == 0) then\n" ^
      "		if (TUTORIAL_ACTIVE()==1) then\n" ^
      "			TUTORIAL_OPEN(\"Quest_T2\");\n" ^
      "		end\n" ^
      "	end\n" ^
      "	\n" ^
      "end\n" ^
      "\n" ^
      "local function T2_StartBattle(characterIdx)\n" ^
      "	\n" ^
      "end\n" ^
      "\n" ^
      "local function T2_Match4(characterIdx)\n" ^
      "	if (characterIdx == 0) then\n" ^
      "		--T2_StartTurn(characterIdx, GET_TURN());\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "local function T2_Match5(characterIdx)\n" ^
      "	if (characterIdx == 0) then\n" ^
      "		--T2_StartTurn(characterIdx, GET_TURN());\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "--	\n" ^
      "--		DECLARE TABLE	\n" ^
      "--\n" ^
      "\n" ^
      "Q0T2 = {\n" ^
      "	OnInit				= OnInit,\n" ^
      "	OnBegin				= OnBegin,\n" ^
      "	OnEnd				= OnEnd,\n" ^
      "	OnAbandon			= OnAbandon,\n" ^
      "	OnEnterLocation		= OnEnterLocation,\n" ^
      "	OnExecuteAction		= OnExecuteAction,\n" ^
      "	OnCompleteAction	= OnCompleteAction,\n" ^
      "	OnQueryAction		= OnQueryAction,\n" ^
      "	OnLoad				= OnLoad,\n" ^
      "	OnSave				= OnSave,\n" ^
      "	OnQueryProgress		= OnQueryProgress,\n" ^
      "	OnQueryPercentage	= OnQueryPercentage,\n" ^
      "	OnQueryDifficulty	= OnQueryDifficulty,\n" ^
      "	\n" ^
      "	CallbackConvA = CallbackConvA ,\n" ^
      "	\n" ^
      "	T2_StartTurn = T2_StartTurn,\n" ^
      "	T2_StartBattle = T2_StartBattle,\n" ^
      "	T2_Match4 = T2_Match4,\n" ^
      "	T2_Match5 = T2_Match5,\n" ^
      "};\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n";
    abandonable = false;
    icon = 0;
    important = true;
    avail_location = "CBAR";
    avail_minlevel = 1;
    avail_maxlevel = 1000;
    avail_repeat = 0;
    avail_donequest0 = "Q0T1";
    avail_donequest1 = "";
    avail_donequest2 = "";
    avail_notdonequest = "Q0Q0";
    avail_notactivequest = "";
    avail_companion0 = "";
    avail_companion1 = "";
    avail_notcompanion = "";
    avail_item = "";
    avail_notitem = "";
