    texts = [("[QUEST_Q1E0_ACTION1]", "Re-light Skullguard beacon"); ("[QUEST_Q1E0_ACTION2]", "Re-light Iceguard beacon"); ("[QUEST_Q1E0_FAILURE1]", "You have failed to re-light the Skullguard beacon"); ("[QUEST_Q1E0_FAILURE2]", "You have failed to re-light the Iceguard beacon"); ("[QUEST_Q1E0_PROGRESS1]", "You must journey to Skullguard Keep and Iceguard Keep. There you must capture Fire Elementals to re-light the beacon fires."); ("[QUEST_Q1E0_PROGRESS2]", "You must journey to Skullguard Keep. There you must capture Fire Elementals to re-light the beacon fires."); ("[QUEST_Q1E0_PROGRESS3]", "You must journey to Iceguard Keep. There you must capture Fire Elementals to re-light the beacon fires."); ("[QUEST_Q1E0_REWARD]", "You have been rewarded for re-lighting both beacons."); ("[QUEST_Q1E0_SUCCESS1]", "You have succeeded in re-lighting the Skullguard beacon."); ("[QUEST_Q1E0_SUCCESS2]", "You have succeeded in re-lighting the Iceguard beacon.")];
    lua_file = "Assets\\Quests\\Q1E0.lua";
    lua_object = "Q1E0";
    lua_source = "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--             Beacon Fires	\n" ^
      "--	\n" ^
      "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--		STATES	\n" ^
      "--\n" ^
      "-- 0 => Inactive\n" ^
      "-- 1 => Quest obtained, nothing done yet\n" ^
      "-- 2 => Killed Monster #1 @ myLocation2\n" ^
      "-- 3 => Killed Monster #1 @ myLocation\n" ^
      "-- 3 => Finished (Killed Monster #2)\n" ^
      "-- \n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Variables\n" ^
      "--\n" ^
      "local questState = 0;\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Constants\n" ^
      "--\n" ^
      "local myCode     = \"Q1E0\";\n" ^
      "local myLocation = \"WSGK\";\n" ^
      "local myLocation2= \"WIGK\";\n" ^
      "local myOrigin   = \"CEHL\";\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnInit				\n" ^
      "--		(called for every quest when they are loading\n" ^
      "--		 to set the initial state of all variables)\n" ^
      "--\n" ^
      "local function OnInit()\n" ^
      "	questState = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnBegin				\n" ^
      "--		(called when a quest is first obtained)\n" ^
      "--\n" ^
      "local function OnBegin()\n" ^
      "	questState = 1;\n" ^
      "	QUEST_SET_VISIBILITY(myLocation,1);\n" ^
      "	QUEST_SET_VISIBILITY(myLocation2,1);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnd				\n" ^
      "--		(called when a quest has ended)\n" ^
      "--\n" ^
      "local function OnEnd()\n" ^
      "	questState = 4;\n" ^
      "	\n" ^
      "	-- Reward\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q1E0_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[QUEST_Q1E0_REWARD]\");\n" ^
      "	QUEST_REWARD_MENU(myTitle,myMessage);\n" ^
      "	QUEST_REWARD_GOLD(300);\n" ^
      "	QUEST_REWARD_XP(200);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnAbandon				\n" ^
      "--		(called when a quest has been abandoned by the player)\n" ^
      "--\n" ^
      "local function OnAbandon()\n" ^
      "	questState = 0;  -- it can be restarted\n" ^
      "\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnterLocation		\n" ^
      "--		(a hero has arrived at a new location)\n" ^
      "--\n" ^
      "local function OnEnterLocation(idLocation)\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryAction\n" ^
      "--		(should anything appear on the popup menu)\n" ^
      "--\n" ^
      "local function OnQueryAction(idLocation)\n" ^
      "	if (idLocation==myLocation and questState < 3) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q1E0_ACTION1]\");\n" ^
      "	elseif (idLocation==myLocation2 and questState ~= 2) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q1E0_ACTION2]\");\n" ^
      "	end\n" ^
      "	\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnExecuteAction				\n" ^
      "--		(do this whenever the player executes the next action)\n" ^
      "--\n" ^
      "local function OnExecuteAction(idLocation)\n" ^
      "	if (questState==1) then\n" ^
      "		QUEST_BATTLE(myCode,0,1);\n" ^
      "	elseif (questState>1) then\n" ^
      "		QUEST_BATTLE(myCode,1,1);\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnCompleteAction				\n" ^
      "--		(do this whenever the player completes his action)\n" ^
      "--		It is called after the game has returned to the map screen\n" ^
      "--\n" ^
      "local function OnCompleteAction(idLocation, success)\n" ^
      "		\n" ^
      "\n" ^
      "	if (questState==1) then\n" ^
      "	\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_Q1E0_NAME]\");\n" ^
      "		local myMessage;\n" ^
      "		if (success == 1) then			\n" ^
      "			if(idLocation==myLocation) then\n" ^
      "				questState = 3;\n" ^
      "				myMessage = GET_TEXT(\"[QUEST_Q1E0_SUCCESS1]\");\n" ^
      "			else\n" ^
      "				questState = 2;\n" ^
      "				myMessage = GET_TEXT(\"[QUEST_Q1E0_SUCCESS2]\");\n" ^
      "			end\n" ^
      "			QUEST_UPDATE_MAP();\n" ^
      "			--QUEST_COMPLETE_PART(myCode,idLocation,1);\n" ^
      "		else\n" ^
      "			if(idLocation==myLocation) then\n" ^
      "				myMessage = GET_TEXT(\"[QUEST_Q1E0_FAILURE1]\");\n" ^
      "			else\n" ^
      "				myMessage = GET_TEXT(\"[QUEST_Q1E0_FAILURE2]\");\n" ^
      "			end\n" ^
      "		end\n" ^
      "		QUEST_MESSAGE(myTitle,myMessage,idLocation);\n" ^
      "			\n" ^
      "	elseif (questState>1) then\n" ^
      "	\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_Q1E0_NAME]\");\n" ^
      "		local myMessage;\n" ^
      "		if (success == 1) then\n" ^
      "\n" ^
      "	  		QUEST_COMPLETE(myCode);\n" ^
      "		else\n" ^
      "			if(idLocation==myLocation) then\n" ^
      "				myMessage = GET_TEXT(\"[QUEST_Q1E0_FAILURE1]\");\n" ^
      "			else\n" ^
      "				myMessage = GET_TEXT(\"[QUEST_Q1E0_FAILURE2]\");\n" ^
      "			end\n" ^
      "			QUEST_MESSAGE(myTitle,myMessage,myLocation);\n" ^
      "		end\n" ^
      "		\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnLoad				\n" ^
      "--		(a save game is being loaded)\n" ^
      "--\n" ^
      "local function OnLoad()\n" ^
      "	questState = QUEST_LOAD_INT();\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnSave				\n" ^
      "--		(a save game is being saved)\n" ^
      "--\n" ^
      "local function OnSave()\n" ^
      "	QUEST_SAVE_INT(questState);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryProgress		\n" ^
      "--		(returns text describing the next step required)\n" ^
      "--\n" ^
      "local function OnQueryProgress()\n" ^
      "	if (questState==1) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q1E0_PROGRESS1]\");\n" ^
      "	elseif (questState==2) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q1E0_PROGRESS2]\");\n" ^
      "	elseif (questState==3) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q1E0_PROGRESS3]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryPercentage	\n" ^
      "--		(returns a percentage of completion)\n" ^
      "--\n" ^
      "local function OnQueryPercentage()\n" ^
      "	if (questState==1) then\n" ^
      "		return 0\n" ^
      "	elseif (questState>1) then\n" ^
      "		return 50\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryDifficulty	\n" ^
      "--		(returns 0-4 for difficulty - v.easy to v.difficult )\n" ^
      "--\n" ^
      "local function OnQueryDifficulty()\n" ^
      "	-- average\n" ^
      "	return 2; \n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "--	\n" ^
      "--		DECLARE TABLE	\n" ^
      "--\n" ^
      "\n" ^
      "Q1E0 = {\n" ^
      "	OnInit				= OnInit,\n" ^
      "	OnBegin				= OnBegin,\n" ^
      "	OnEnd				= OnEnd,\n" ^
      "	OnAbandon			= OnAbandon,\n" ^
      "	OnEnterLocation		= OnEnterLocation,\n" ^
      "	OnExecuteAction		= OnExecuteAction,\n" ^
      "	OnCompleteAction	= OnCompleteAction,\n" ^
      "	OnQueryAction		= OnQueryAction,\n" ^
      "	OnLoad				= OnLoad,\n" ^
      "	OnSave				= OnSave,\n" ^
      "	OnQueryProgress		= OnQueryProgress,\n" ^
      "	OnQueryPercentage	= OnQueryPercentage,\n" ^
      "	OnQueryDifficulty	= OnQueryDifficulty,\n" ^
      "};\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
