    lua_source = "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--             Reagent Hunt	\n" ^
      "--	\n" ^
      "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--		STATES	\n" ^
      "--\n" ^
      "-- 0 => Inactive\n" ^
      "-- 1 => Quest obtained, nothing done yet\n" ^
      "-- 2 => Monsters defeated, must return\n" ^
      "-- 3 => Finished\n" ^
      "-- \n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Variables\n" ^
      "--\n" ^
      "local questState = 0;\n" ^
      "local doneTroll = 0;\n" ^
      "local doneWasp = 0;\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Constants\n" ^
      "--\n" ^
      "local myCode     = \"Q1G1\";\n" ^
      "local myLocation  = \"RWHV\";\n" ^
      "local myLocation2 = \"RTLH\";\n" ^
      "local myOrigin   = \"CGRU\";\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnInit				\n" ^
      "--		(called for every quest when they are loading\n" ^
      "--		 to set the initial state of all variables)\n" ^
      "--\n" ^
      "local function OnInit()\n" ^
      "	questState = 0;\n" ^
      "	doneTroll = 0;\n" ^
      "	doneWasp = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnBegin				\n" ^
      "--		(called when a quest is first obtained)\n" ^
      "--\n" ^
      "local function OnBegin()\n" ^
      "	questState = 1;\n" ^
      "	doneTroll = 0;\n" ^
      "	doneWasp = 0;\n" ^
      "	QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q1G1a.xml\",myOrigin);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnd				\n" ^
      "--		(called when a quest has ended)\n" ^
      "--\n" ^
      "local function OnEnd()\n" ^
      "	questState = 3;\n" ^
      "	\n" ^
      "	-- Reward\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q1G1_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[QUEST_Q1G1_REWARD]\");\n" ^
      "	QUEST_REWARD_MENU(myTitle,myMessage);\n" ^
      "	QUEST_REWARD_GOLD(500);\n" ^
      "	QUEST_REWARD_XP(50);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnAbandon				\n" ^
      "--		(called when a quest has been abandoned by the player)\n" ^
      "--\n" ^
      "local function OnAbandon()\n" ^
      "	questState = 0;  -- it can be restarted\n" ^
      "	QUEST_SET_RUIN_DONE(myLocation);\n" ^
      "	QUEST_SET_RUIN_DONE(myLocation2);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnterLocation		\n" ^
      "--		(a hero has arrived at a new location)\n" ^
      "--\n" ^
      "local function OnEnterLocation(idLocation)\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryAction\n" ^
      "--		(should anything appear on the popup menu)\n" ^
      "--\n" ^
      "local function OnQueryAction(idLocation)\n" ^
      "	if (idLocation==myLocation and questState==1 and doneWasp==0) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q1G1_ACTION]\");\n" ^
      "	elseif (idLocation==myLocation2 and questState==1 and doneTroll==0) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q1G1_ACTION2]\");\n" ^
      "	elseif (idLocation==myOrigin and questState==2) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q1G1_RETURN]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnExecuteAction				\n" ^
      "--		(do this whenever the player executes the next action)\n" ^
      "--\n" ^
      "local function OnExecuteAction(idLocation)\n" ^
      "	if (questState==1 and idLocation==myLocation) then\n" ^
      "		QUEST_BATTLE(myCode,0,1);\n" ^
      "	elseif (questState==1 and idLocation==myLocation2) then\n" ^
      "		QUEST_BATTLE_NOCAPTURE(myCode,1,1);\n" ^
      "	elseif (questState==2) then\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q1G1b.xml\",myOrigin);\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnCompleteAction				\n" ^
      "--		(do this whenever the player completes his action)\n" ^
      "--		It is called after the game has returned to the map screen\n" ^
      "--\n" ^
      "local function OnCompleteAction(idLocation, success)\n" ^
      "\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q1G1_NAME]\");\n" ^
      "	local myMessage;\n" ^
      "\n" ^
      "	if (questState==1) then\n" ^
      "	\n" ^
      "		if (idLocation == myLocation) then\n" ^
      "			if (success == 1) then\n" ^
      "	  			doneWasp = 1;\n" ^
      "				QUEST_SET_RUIN_DONE(myLocation);\n" ^
      "				if(doneTroll ==1) then\n" ^
      "					myMessage = GET_TEXT(\"[QUEST_Q1G1_KILL3]\");\n" ^
      "				else\n" ^
      "					myMessage = GET_TEXT(\"[QUEST_Q1G1_KILL]\");\n" ^
      "				end\n" ^
      "			else\n" ^
      "				myMessage = GET_TEXT(\"[QUEST_Q1G1_FAILURE]\");\n" ^
      "			end\n" ^
      "		elseif (idLocation == myLocation2) then\n" ^
      "			if (success == 1) then\n" ^
      "	  			doneTroll = 1;\n" ^
      "				QUEST_SET_RUIN_DONE(myLocation2);\n" ^
      "				if(doneWasp ==1) then\n" ^
      "					myMessage = GET_TEXT(\"[QUEST_Q1G1_KILL3]\");\n" ^
      "				else\n" ^
      "					myMessage = GET_TEXT(\"[QUEST_Q1G1_KILL2]\");\n" ^
      "				end\n" ^
      "			else\n" ^
      "				myMessage = GET_TEXT(\"[QUEST_Q1G1_FAILURE2]\");\n" ^
      "			end\n" ^
      "		end\n" ^
      "		if (doneTroll == 1 and doneWasp == 1) then\n" ^
      "			QUEST_SET_RUIN_DONE(myLocation);\n" ^
      "			QUEST_SET_RUIN_DONE(myLocation2);\n" ^
      "			questState = 2;\n" ^
      "		end\n" ^
      "		QUEST_MESSAGE(myTitle,myMessage,idLocation);\n" ^
      "		QUEST_UPDATE_MAP();\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnLoad				\n" ^
      "--		(a save game is being loaded)\n" ^
      "--\n" ^
      "local function OnLoad()\n" ^
      "	questState = QUEST_LOAD_INT();\n" ^
      "	doneTroll = QUEST_LOAD_INT();\n" ^
      "	doneWasp = QUEST_LOAD_INT();\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnSave				\n" ^
      "--		(a save game is being saved)\n" ^
      "--\n" ^
      "local function OnSave()\n" ^
      "	QUEST_SAVE_INT(questState);\n" ^
      "	QUEST_SAVE_INT(doneTroll);\n" ^
      "	QUEST_SAVE_INT(doneWasp);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryProgress		\n" ^
      "--		(returns text describing the next step required)\n" ^
      "--\n" ^
      "local function OnQueryProgress()\n" ^
      "	if (questState == 1) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q1G1_STEP1]\");\n" ^
      "	elseif (questState == 2) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q1G1_STEP2]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryPercentage	\n" ^
      "--		(returns a percentage of completion)\n" ^
      "--\n" ^
      "local function OnQueryPercentage()\n" ^
      "	if (questState <= 1) then\n" ^
      "		return doneTroll*40 + doneWasp*40;\n" ^
      "	elseif (questState == 2) then\n" ^
      "		return 80;\n" ^
      "	end\n" ^
      "	return 100;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryDifficulty	\n" ^
      "--		(returns 0-4 for difficulty - v.easy to v.difficult )\n" ^
      "--\n" ^
      "local function OnQueryDifficulty()\n" ^
      "	-- average\n" ^
      "	return 2; \n" ^
      "end\n" ^
      "\n" ^
      "-- CallbackConvA 				\n" ^
      "--		(Callback fn - for end of conv)\n" ^
      "--\n" ^
      "local function CallbackConvA ()\n" ^
      "	QUEST_ADD_RUIN(myLocation);\n" ^
      "	QUEST_ADD_RUIN(myLocation2);\n" ^
      "end\n" ^
      "\n" ^
      "-- CallbackConvB 				\n" ^
      "--		(Callback fn - for end of conv)\n" ^
      "--\n" ^
      "local function CallbackConvB ()\n" ^
      "	-- Reward\n" ^
      "	QUEST_COMPLETE(myCode);\n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
