      "local myCode     = \"Q1G2\";\n" ^
      "local myLocation  = \"WTHR\";\n" ^
      "local myLocation2 = \"CSIL\";\n" ^
      "local myOrigin   = \"CGRU\";\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnInit				\n" ^
      "--		(called for every quest when they are loading\n" ^
      "--		 to set the initial state of all variables)\n" ^
      "--\n" ^
      "local function OnInit()\n" ^
      "	questState = 0;\n" ^
      "	doneTheira = 0;\n" ^
      "	doneSilvermyr = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnBegin				\n" ^
      "--		(called when a quest is first obtained)\n" ^
      "--\n" ^
      "local function OnBegin()\n" ^
      "	questState = 1;\n" ^
      "	doneTheira = 0;\n" ^
      "	doneSilvermyr = 0;\n" ^
      "	QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q1G2a.xml\",myOrigin);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnd				\n" ^
      "--		(called when a quest has ended)\n" ^
      "--\n" ^
      "local function OnEnd()\n" ^
      "	questState = 3;\n" ^
      "	\n" ^
      "	-- Reward\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q1G2_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[QUEST_Q1G2_REWARD]\");\n" ^
      "	QUEST_REWARD_MENU(myTitle,myMessage);\n" ^
      "	QUEST_REWARD_GOLD(500);\n" ^
      "	QUEST_REWARD_XP(50);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnAbandon				\n" ^
      "--		(called when a quest has been abandoned by the player)\n" ^
      "--\n" ^
      "local function OnAbandon()\n" ^
      "	questState = 0;  -- it can be restarted\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnterLocation		\n" ^
      "--		(a hero has arrived at a new location)\n" ^
      "--\n" ^
      "local function OnEnterLocation(idLocation)\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryAction\n" ^
      "--		(should anything appear on the popup menu)\n" ^
      "--\n" ^
      "local function OnQueryAction(idLocation)\n" ^
      "	if (idLocation==myLocation and questState==1 and doneTheira==0) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q1G2_ACTION]\");\n" ^
      "	elseif (idLocation==myLocation2 and questState==1 and doneSilvermyr==0) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q1G2_ACTION2]\");\n" ^
      "	elseif (idLocation==myOrigin and questState==2) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q1G2_RETURN]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnExecuteAction				\n" ^
      "--		(do this whenever the player executes the next action)\n" ^
      "--\n" ^
      "local function OnExecuteAction(idLocation)\n" ^
      "	if (questState==1) then\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_Q1G2_NAME]\");\n" ^
      "		local myMessage;\n" ^
      "		if (idLocation == myLocation) then\n" ^
      "			doneTheira = 1;\n" ^
      "			if( doneSilvermyr ==1) then\n" ^
      "				myMessage = GET_TEXT(\"[QUEST_Q1G2_TRADE1]\");\n" ^
      "			else\n" ^
      "				myMessage = GET_TEXT(\"[QUEST_Q1G2_TRADE]\");\n" ^
      "			end\n" ^
      "		elseif (idLocation == myLocation2) then\n" ^
      "			doneSilvermyr = 1;\n" ^
      "			if( doneTheira ==1) then\n" ^
      "				myMessage = GET_TEXT(\"[QUEST_Q1G2_TRADE3]\");\n" ^
      "			else\n" ^
      "				myMessage = GET_TEXT(\"[QUEST_Q1G2_TRADE2]\");\n" ^
      "			end\n" ^
      "		end\n" ^
      "		if (doneTheira == 1 and doneSilvermyr == 1) then\n" ^
      "			questState = 2;\n" ^
      "		end\n" ^
      "		QUEST_MESSAGE(myTitle,myMessage,idLocation);\n" ^
      "		QUEST_UPDATE_MAP();\n" ^
      "	elseif (questState==2) then\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q1G2b.xml\",idLocation);\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnCompleteAction				\n" ^
      "--		(do this whenever the player completes his action)\n" ^
      "--		It is called after the game has returned to the map screen\n" ^
      "--\n" ^
      "local function OnCompleteAction(idLocation, success)\n" ^
      "\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnLoad				\n" ^
      "--		(a save game is being loaded)\n" ^
      "--\n" ^
      "local function OnLoad()\n" ^
      "	questState = QUEST_LOAD_INT();\n" ^
      "	doneTheira = QUEST_LOAD_INT();\n" ^
      "	doneSilvermyr = QUEST_LOAD_INT();\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnSave				\n" ^
      "--		(a save game is being saved)\n" ^
      "--\n" ^
      "local function OnSave()\n" ^
      "	QUEST_SAVE_INT(questState);\n" ^
      "	QUEST_SAVE_INT(doneTheira );\n" ^
      "	QUEST_SAVE_INT(doneSilvermyr );\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryProgress		\n" ^
      "--		(returns text describing the next step required)\n" ^
      "--\n" ^
      "local function OnQueryProgress()\n" ^
      "	if (questState == 1) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q1G2_STEP1]\");\n" ^
      "	elseif (questState == 2) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q1G2_STEP2]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryPercentage	\n" ^
      "--		(returns a percentage of completion)\n" ^
      "--\n" ^
      "local function OnQueryPercentage()\n" ^
      "	if (questState <= 1) then\n" ^
      "		return doneTheira*40 + doneSilvermyr*40;\n" ^
      "	elseif (questState == 2) then\n" ^
      "		return 80;\n" ^
      "	end\n" ^
      "	return 100;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryDifficulty	\n" ^
      "--		(returns 0-4 for difficulty - v.easy to v.difficult )\n" ^
      "--\n" ^
      "local function OnQueryDifficulty()\n" ^
      "	-- average\n" ^
      "	return 1; \n" ^
      "end\n" ^
      "\n" ^
      "-- CallbackConvB 				\n" ^
      "--		(Callback fn - for end of conv)\n" ^
      "--\n" ^
      "local function CallbackConvB ()\n" ^
      "	QUEST_COMPLETE(myCode);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "--	\n" ^
      "--		DECLARE TABLE	\n" ^
      "--\n" ^
      "\n" ^
      "Q1G2 = {\n" ^
      "	OnInit				= OnInit,\n" ^
      "	OnBegin				= OnBegin,\n" ^
      "	OnEnd				= OnEnd,\n" ^
      "	OnAbandon			= OnAbandon,\n" ^
      "	OnEnterLocation		= OnEnterLocation,\n" ^
      "	OnExecuteAction		= OnExecuteAction,\n" ^
      "	OnCompleteAction	= OnCompleteAction,\n" ^
      "	OnQueryAction		= OnQueryAction,\n" ^
      "	OnLoad				= OnLoad,\n" ^
      "	OnSave				= OnSave,\n" ^
      "	OnQueryProgress		= OnQueryProgress,\n" ^
      "	OnQueryPercentage	= OnQueryPercentage,\n" ^
      "	OnQueryDifficulty	= OnQueryDifficulty,\n" ^
      "\n" ^
      "	CallbackConvB = CallbackConvB ,\n" ^
      "};\n" ^
