  {
    id = "Q1Q0";
    name_text = "[QUEST_Q1Q0_NAME]";
    desc_text = "[QUEST_Q1Q0_DESC]";
    group = "[QG_PRIM_NAME]";
    text_file = "English\\Quests\\Q1Q0_Text.xml";
    texts = [("[QUEST_Q1Q0_ACTION]", "Battle the Orc Lord"); ("[QUEST_Q1Q0_FAILURE]", "You have failed to defeat the Orc Lord - you must try again."); ("[QUEST_Q1Q0_RETURN]", "Report your Success"); ("[QUEST_Q1Q0_REWARD]", "The Elders of Dhun-Kor are grateful for your help. They reward you with much gold and a Dwarven Axe."); ("[QUEST_Q1Q0_STEP1]", "You must travel to the 4 Orc villages east of Dhun-Kor and defeat their leaders."); ("[QUEST_Q1Q0_STEP2]", "You have defeated one Orc Lord. Three more remain in the villages east of Dhun-Khor."); ("[QUEST_Q1Q0_STEP3]", "You have defeated two Orc Lords. Two more remain in the villages east of Dhun-Kor."); ("[QUEST_Q1Q0_STEP4]", "You have defeated three Orc Lords. Only one remains in a village east of Dhun-Khor."); ("[QUEST_Q1Q0_STEP5]", "You must report your success to the elders of Dhun-Kor.")];
    lua_file = "Assets\\Quests\\Q1Q0.lua";
    lua_object = "Q1Q0";
    lua_source = "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--             Tribal Chaos	\n" ^
      "--	\n" ^
      "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--		STATES	\n" ^
      "--\n" ^
      "-- 0 => Inactive\n" ^
      "-- 1 => Quest obtained, nothing done yet\n" ^
      "-- 2 => Some Orc Lords defeated\n" ^
      "-- 3 => All 4 Orc Lords defeated\n" ^
      "-- 4 => Finished\n" ^
      "-- \n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Variables\n" ^
      "--\n" ^
      "local questState = 0;\n" ^
      "local numOrcLordsDefeated = 0;\n" ^
      "local done1 = 0;\n" ^
      "local done2 = 0;\n" ^
      "local done3 = 0;\n" ^
      "local done4 = 0;\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Constants\n" ^
      "--\n" ^
      "local myCode     = \"Q1Q0\";\n" ^
      "local myLocation1 = \"WRMO\";\n" ^
      "local myLocation2 = \"WSFA\";\n" ^
      "local myLocation3 = \"WBHE\";\n" ^
      "local myLocation4 = \"WWSK\";\n" ^
      "local myOrigin   = \"CDKO\";\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnInit				\n" ^
      "--		(called for every quest when they are loading\n" ^
      "--		 to set the initial state of all variables)\n" ^
      "--\n" ^
      "local function OnInit()\n" ^
      "	questState = 0;\n" ^
      "	numOrcLordsDefeated = 0;\n" ^
      "	done1 = 0;\n" ^
      "	done2 = 0;\n" ^
      "	done3 = 0;\n" ^
      "	done4 = 0;\n" ^
      "	doneKhalkusDarkhunterConv = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnBegin				\n" ^
      "--		(called when a quest is first obtained)\n" ^
      "--\n" ^
      "local function OnBegin()\n" ^
      "	questState = 1;\n" ^
      "	numOrcLordsDefeated = 0;\n" ^
      "	done1 = 0;\n" ^
      "	done2 = 0;\n" ^
      "	done3 = 0;\n" ^
      "	done4 = 0;\n" ^
      "	doneKhalkusDarkhunterConv = 0;\n" ^
      "	QUEST_SET_VISIBILITY(myLocation1 ,1);\n" ^
      "	QUEST_SET_VISIBILITY(myLocation2 ,1);\n" ^
      "	QUEST_SET_VISIBILITY(myLocation3 ,1);\n" ^
      "	QUEST_SET_VISIBILITY(myLocation4 ,1);\n" ^
      "	QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q1Q0a.xml\",myOrigin);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnd				\n" ^
      "--		(called when a quest has ended)\n" ^
      "--\n" ^
      "local function OnEnd()\n" ^
      "	questState = 3;\n" ^
      "	\n" ^
      "	-- Reward\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q1Q0_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[QUEST_Q1Q0_REWARD]\");\n" ^
      "	QUEST_REWARD_MENU(myTitle,myMessage);\n" ^
      "	QUEST_REWARD_GOLD(450);\n" ^
      "	QUEST_REWARD_ITEM(\"IDAX\");\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnAbandon				\n" ^
      "--		(called when a quest has been abandoned by the player)\n" ^
      "--\n" ^
      "local function OnAbandon()\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnterLocation		\n" ^
      "--		(a hero has arrived at a new location)\n" ^
      "--\n" ^
      "local function OnEnterLocation(idLocation)\n" ^
      "	if (idLocation == \"WBHE\" and doneKhalkusDarkhunterConv==0 and\n" ^
      "          QUEST_HERO_HAS_COMPANION_SELECTED(\"NKHA\")==1 and \n" ^
      "	    QUEST_HERO_HAS_COMPANION_SELECTED(\"NDKH\")==1 ) then\n" ^
      "		doneKhalkusDarkhunterConv = 1;\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q1Q0b.xml\",idLocation);\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryAction\n" ^
      "--		(should anything appear on the popup menu)\n" ^
      "--\n" ^
      "local function OnQueryAction(idLocation)\n" ^
      "	if (questState==1 or questState == 2) then\n" ^
      "		if (idLocation==myLocation1 and done1==0) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q1Q0_ACTION]\");\n" ^
      "		elseif (idLocation==myLocation2 and done2==0) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q1Q0_ACTION]\");\n" ^
      "		elseif (idLocation==myLocation3 and done3==0) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q1Q0_ACTION]\");\n" ^
      "		elseif (idLocation==myLocation4 and done4==0) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q1Q0_ACTION]\");\n" ^
      "		end\n" ^
      "	elseif (questState==3) then\n" ^
      "		if (idLocation==myOrigin) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q1Q0_RETURN]\");\n" ^
      "		end\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnExecuteAction				\n" ^
      "--		(do this whenever the player executes the next action)\n" ^
      "--\n" ^
      "local function OnExecuteAction(idLocation)\n" ^
      "	if (questState==1 or questState == 2) then\n" ^
      "		QUEST_BATTLE(myCode,0,1);\n" ^
      "	elseif (questState==3) then\n" ^
      "		QUEST_COMPLETE(myCode);\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnCompleteAction				\n" ^
      "--		(do this whenever the player completes his action)\n" ^
      "--		It is called after the game has returned to the map screen\n" ^
      "--\n" ^
      "local function OnCompleteAction(idLocation, success)\n" ^
      "\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q1Q0_NAME]\");\n" ^
      "\n" ^
      "	if (success == 0) then\n" ^
      "		local myMessage = GET_TEXT(\"[QUEST_Q1Q0_FAILURE]\");\n" ^
      "		QUEST_MESSAGE(myTitle,myMessage,myLocation);\n" ^
      "	elseif (questState==1 or questState == 2) then\n" ^
      "	\n" ^
      "		if (idLocation == myLocation1) then\n" ^
      "			done1 = 1;\n" ^
      "			numOrcLordsDefeated = numOrcLordsDefeated + 1;\n" ^
      "		elseif (idLocation == myLocation2) then\n" ^
      "			done2 = 1;\n" ^
      "			numOrcLordsDefeated = numOrcLordsDefeated + 1;\n" ^
      "		elseif (idLocation == myLocation3) then\n" ^
      "			done3 = 1;\n" ^
      "			numOrcLordsDefeated = numOrcLordsDefeated + 1;\n" ^
      "		elseif (idLocation == myLocation4) then\n" ^
      "			done4 = 1;\n" ^
      "			numOrcLordsDefeated = numOrcLordsDefeated + 1;\n" ^
      "		end\n" ^
      "\n" ^
      "		local myMessage \n" ^
      "		if (numOrcLordsDefeated == 1) then\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_Q1Q0_STEP2]\");\n" ^
      "			questState = 2;\n" ^
      "		elseif (numOrcLordsDefeated == 2) then\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_Q1Q0_STEP3]\");\n" ^
      "		elseif (numOrcLordsDefeated == 3) then\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_Q1Q0_STEP4]\");\n" ^
      "		elseif (numOrcLordsDefeated >= 4) then\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_Q1Q0_STEP5]\");\n" ^
      "			questState = 3;\n" ^
      "		end\n" ^
      "		QUEST_MESSAGE(myTitle,myMessage,idLocation);\n" ^
      "		QUEST_UPDATE_MAP();\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnLoad				\n" ^
      "--		(a save game is being loaded)\n" ^
      "--\n" ^
      "local function OnLoad()\n" ^
      "	questState = QUEST_LOAD_INT();\n" ^
      "	numOrcLordsDefeated = QUEST_LOAD_INT();\n" ^
      "	done1 = QUEST_LOAD_INT();\n" ^
      "	done2 = QUEST_LOAD_INT();\n" ^
      "	done3 = QUEST_LOAD_INT();\n" ^
      "	done4 = QUEST_LOAD_INT();\n" ^
      "	doneKhalkusDarkhunterConv = QUEST_LOAD_INT();\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnSave				\n" ^
      "--		(a save game is being saved)\n" ^
      "--\n" ^
      "local function OnSave()\n" ^
      "	QUEST_SAVE_INT(questState);\n" ^
      "	QUEST_SAVE_INT(numOrcLordsDefeated);\n" ^
      "	QUEST_SAVE_INT(done1);\n" ^
      "	QUEST_SAVE_INT(done2);\n" ^
      "	QUEST_SAVE_INT(done3);\n" ^
      "	QUEST_SAVE_INT(done4);\n" ^
      "	QUEST_SAVE_INT(doneKhalkusDarkhunterConv);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryProgress		\n" ^
      "--		(returns text describing the next step required)\n" ^
      "--\n" ^
      "local function OnQueryProgress()\n" ^
      "	if (questState == 1) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q1Q0_STEP1]\");\n" ^
      "	elseif (questState == 2 and numOrcLordsDefeated == 1) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q1Q0_STEP2]\");\n" ^
      "	elseif (questState == 2 and numOrcLordsDefeated == 2) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q1Q0_STEP3]\");\n" ^
      "	elseif (questState == 2 and numOrcLordsDefeated == 3) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q1Q0_STEP4]\");\n" ^
      "	elseif (questState >= 3) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q1Q0_STEP5]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryPercentage	\n" ^
      "--		(returns a percentage of completion)\n" ^
      "--\n" ^
      "local function OnQueryPercentage()\n" ^
      "	if (questState <= 1) then\n" ^
      "		return 0;\n" ^
      "	elseif (questState == 2) then\n" ^
      "		return numOrcLordsDefeated*20;\n" ^
      "	elseif (questState == 3) then\n" ^
      "		return 80;\n" ^
      "	end\n" ^
      "	return 100;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryDifficulty	\n" ^
      "--		(returns 0-4 for difficulty - v.easy to v.difficult )\n" ^
      "--\n" ^
      "local function OnQueryDifficulty()\n" ^
      "	-- average\n" ^
      "	return 2; \n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "--	\n" ^
      "--		DECLARE TABLE	\n" ^
      "--\n" ^
      "\n" ^
      "Q1Q0 = {\n" ^
      "	OnInit			= OnInit,\n" ^
      "	OnBegin			= OnBegin,\n" ^
      "	OnEnd				= OnEnd,\n" ^
      "	OnAbandon			= OnAbandon,\n" ^
      "	OnEnterLocation		= OnEnterLocation,\n" ^
      "	OnExecuteAction		= OnExecuteAction,\n" ^
      "	OnCompleteAction		= OnCompleteAction,\n" ^
      "	OnQueryAction		= OnQueryAction,\n" ^
      "	OnLoad			= OnLoad,\n" ^
      "	OnSave			= OnSave,\n" ^
      "	OnQueryProgress		= OnQueryProgress,\n" ^
      "	OnQueryPercentage		= OnQueryPercentage,\n" ^
      "	OnQueryDifficulty		= OnQueryDifficulty,\n" ^
      "};\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n";
    abandonable = false;
    icon = 0;
    important = true;
    avail_location = "CDKO";
    avail_minlevel = 14;
    avail_maxlevel = 1000;
    avail_repeat = 1;
    avail_donequest0 = "Q0Q8";
    avail_donequest1 = "";
    avail_donequest2 = "";
    avail_notdonequest = "";
    avail_notactivequest = "";
    avail_companion0 = "";
    avail_companion1 = "";
    avail_notcompanion = "";
