  {
    id = "Q1Q1";
    name_text = "[QUEST_Q1Q1_NAME]";
    desc_text = "[QUEST_Q1Q1_DESC]";
    group = "[QG_PRIM_NAME]";
    text_file = "English\\Quests\\Q1Q1_Text.xml";
    texts = [("[QUEST_Q1Q1_ACTION0]", "Visit Gruulkar"); ("[QUEST_Q1Q1_ACTION1]", "Battle the Wargs"); ("[QUEST_Q1Q1_FAILURE]", "You could not defeat the Wargs, but you must try again."); ("[QUEST_Q1Q1_HELP0]", "You must travel to Gruuldok to meet with Gruulkar."); ("[QUEST_Q1Q1_HELP1]", "You must get Gruulkar a gift.  A Warg Pelt from the pack near the Wargstone should do the trick."); ("[QUEST_Q1Q1_HELP2]", "You must return the Warg Pelt to Gruulkar."); ("[QUEST_Q1Q1_REWARD]", "You now know that the Orcs taking prisoners are controlled by someone in the north."); ("[QUEST_Q1Q1_SUCCESS]", "You have obtained a Warg pelt to take to Gruulkar as a gift."); ("[QUEST_Q1Q1_QMNAME0]", "Warg"); ("[QUEST_Q1Q1_QMHELP0]", "This is a particularly nasty type of Wolf, called a Warg. They are huge and fast.  They can cast both Rend and Haste.")];
    lua_file = "Assets\\Quests\\Q1Q1.lua";
    lua_object = "Q1Q1";
    lua_source = "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--             Lord of Orcs	\n" ^
      "--	\n" ^
      "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--		STATES	\n" ^
      "--\n" ^
      "-- 0 => Inactive\n" ^
      "-- 1 => Nothing done yet\n" ^
      "-- 2 => Talked to Orc Guard\n" ^
      "-- 3 => Got Warg Pelt\n" ^
      "-- 4 => Complete\n" ^
      "-- \n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Variables\n" ^
      "--\n" ^
      "local questState = 0;\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Constants\n" ^
      "--\n" ^
      "local myCode     = \"Q1Q1\";\n" ^
      "local myOrigin   = \"CDKO\";\n" ^
      "local myDest0    = \"WSFA\";\n" ^
      "local myDest1    = \"CGRU\";\n" ^
      "local myDest2    = \"RWGS\";\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnInit				\n" ^
      "--		(called for every quest when they are loading\n" ^
      "--		 to set the initial state of all variables)\n" ^
      "--\n" ^
      "local function OnInit()\n" ^
      "	questState = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnBegin				\n" ^
      "--		(called when a quest is first obtained)\n" ^
      "--\n" ^
      "local function OnBegin()\n" ^
      "	questState = 1;\n" ^
      "	QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q1Q1a.xml\",myOrigin);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnd				\n" ^
      "--		(called when a quest has ended)\n" ^
      "--\n" ^
      "local function OnEnd()\n" ^
      "	questState = 4;\n" ^
      "	\n" ^
      "	-- Reward\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q1Q1_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[QUEST_Q1Q1_REWARD]\");\n" ^
      "	QUEST_REWARD_MENU(myTitle,myMessage);\n" ^
      "	QUEST_REWARD_XP(80);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnAbandon				\n" ^
      "--		(called when a quest has been abandoned by the player)\n" ^
      "--\n" ^
      "local function OnAbandon()\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnterLocation		\n" ^
      "--		(a hero has arrived at a new location)\n" ^
      "--\n" ^
      "local function OnEnterLocation(idLocation)\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryAction\n" ^
      "--		(should anything appear on the popup menu)\n" ^
      "--\n" ^
      "local function OnQueryAction(idLocation)\n" ^
      "	if (idLocation == myDest1 and questState == 1) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q1Q1_ACTION0]\");\n" ^
      "	elseif (idLocation == myDest2 and questState == 2) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q1Q1_ACTION1]\");\n" ^
      "	elseif (idLocation == myDest1 and questState == 3) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q1Q1_ACTION0]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnExecuteAction				\n" ^
      "--		(do this whenever the player executes the next action)\n" ^
      "--\n" ^
      "local function OnExecuteAction(idLocation)\n" ^
      "	if (idLocation == myDest1 and questState == 1) then\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q1Q1b.xml\",myOrigin);\n" ^
      "		questState = 2;\n" ^
      "	elseif (idLocation == myDest2 and questState == 2) then\n" ^
      "		QUEST_BATTLE_NOCAPTURE(myCode,0,1);\n" ^
      "	elseif (idLocation == myDest1 and questState == 3) then\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q1Q1c.xml\",myOrigin);\n" ^
      "		questState = 4;\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnCompleteAction				\n" ^
      "--		(do this whenever the player completes his action)\n" ^
      "--		It is called after the game has returned to the map screen\n" ^
      "--\n" ^
      "local function OnCompleteAction(idLocation, success)\n" ^
      "\n" ^
      "	if (questState==2 and idLocation==myDest2) then\n" ^
      "	\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_Q1Q1_NAME]\");\n" ^
      "		local myMessage;\n" ^
      "		if (success == 1) then\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_Q1Q1_SUCCESS]\");\n" ^
      "			questState = 3;\n" ^
      "			QUEST_SET_RUIN_DONE(myDest2);\n" ^
      "		else\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_Q1Q1_FAILURE]\");\n" ^
      "		end\n" ^
      "		QUEST_MESSAGE(myTitle,myMessage,idLocation);\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnLoad				\n" ^
      "--		(a save game is being loaded)\n" ^
      "--\n" ^
      "local function OnLoad()\n" ^
      "	questState = QUEST_LOAD_INT();\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnSave				\n" ^
      "--		(a save game is being saved)\n" ^
      "--\n" ^
      "local function OnSave()\n" ^
      "	QUEST_SAVE_INT(questState);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryProgress		\n" ^
      "--		(returns text describing the next step required)\n" ^
      "--\n" ^
      "local function OnQueryProgress()\n" ^
      "	if (questState <= 1) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q1Q1_HELP0]\");\n" ^
      "	elseif (questState == 2) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q1Q1_HELP1]\");\n" ^
      "	elseif (questState == 3) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q1Q1_HELP2]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryPercentage	\n" ^
      "--		(returns a percentage of completion)\n" ^
      "--\n" ^
      "local function OnQueryPercentage()\n" ^
      "	if (questState <= 1) then\n" ^
      "		return 0;\n" ^
      "	elseif (questState == 2) then\n" ^
      "		return 40;\n" ^
      "	elseif (questState == 3) then\n" ^
      "		return 80;\n" ^
      "	end\n" ^
      "	return 40;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryDifficulty	\n" ^
      "--		(returns 0-4 for difficulty - v.easy to v.difficult )\n" ^
      "--\n" ^
      "local function OnQueryDifficulty()\n" ^
      "	-- average\n" ^
      "	return 2; \n" ^
      "end\n" ^
      "\n" ^
      "-- CallbackConvA 				\n" ^
      "--		(Callback fn - for end of quest)\n" ^
      "--\n" ^
      "local function CallbackConvA ()\n" ^
      "	QUEST_SET_VISIBILITY(myDest1 ,1);\n" ^
      "	Std_AddEncounter(myDest0,myDest1,\"EGRO\");\n" ^
      "end\n" ^
      "\n" ^
      "-- CallbackConvB 				\n" ^
      "--		(Callback fn - for end of quest)\n" ^
      "--\n" ^
      "local function CallbackConvB ()\n" ^
      "	QUEST_ADD_RUIN(myDest2);\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "\n" ^
      "-- CallbackConvC 				\n" ^
      "--		(Callback fn - for end of quest)\n" ^
      "--\n" ^
      "local function CallbackConvC ()\n" ^
      "	QUEST_COMPLETE(myCode);\n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "--	\n" ^
      "--		DECLARE TABLE	\n" ^
      "--\n" ^
      "\n" ^
      "Q1Q1 = {\n" ^
      "	OnInit				= OnInit,\n" ^
      "	OnBegin				= OnBegin,\n" ^
      "	OnEnd				= OnEnd,\n" ^
      "	OnAbandon			= OnAbandon,\n" ^
      "	OnEnterLocation		= OnEnterLocation,\n" ^
      "	OnExecuteAction		= OnExecuteAction,\n" ^
      "	OnCompleteAction	= OnCompleteAction,\n" ^
      "	OnQueryAction		= OnQueryAction,\n" ^
      "	OnLoad				= OnLoad,\n" ^
      "	OnSave				= OnSave,\n" ^
      "	OnQueryProgress		= OnQueryProgress,\n" ^
      "	OnQueryPercentage	= OnQueryPercentage,\n" ^
      "	OnQueryDifficulty	= OnQueryDifficulty,\n" ^
      "\n" ^
      "	CallbackConvA = CallbackConvA ,\n" ^
      "	CallbackConvB = CallbackConvB ,\n" ^
      "	CallbackConvC = CallbackConvC ,\n" ^
      "};\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n";
    abandonable = false;
    icon = 0;
    important = true;
    avail_location = "CDKO";
    avail_minlevel = 14;
    avail_maxlevel = 1000;
    avail_repeat = 1;
    avail_donequest0 = "Q1Q0";
    avail_donequest1 = "";
    avail_donequest2 = "";
    avail_notdonequest = "";
    avail_notactivequest = "";
    avail_companion0 = "";
    avail_companion1 = "";
    avail_notcompanion = "";
    avail_item = "";
    avail_notitem = "";
    avail_award = "";
    avail_notaward = "";
    battle_monster = "MWLF";
    battle_spells = ["SRND"; "SHAS"];
    battles = [("MWLF", ["SRND"; "SHAS"])];
    battle_actions = [(2, 0, false)];
    battle_stage_advances = [(2, 3)];
    battle_stage_fails = [];
    enter_removes = [];
    reveal_on_begin = ["CGRU"];
    reveal_on_end = [];
    ruin_reveals = ["RWGS"];
    ruin_dones_on_end = [];
    ruin_dones_on_battle = ["RWGS"];
    ruin_dones_on_abandon = [];
    reward_gold = 0;
    reward_xp = 80;
    reward_items = [];
    reward_awards = [];
    reward_companions = [];
  };
  {
    id = "Q1Q2";
    name_text = "[QUEST_Q1Q2_NAME]";
    desc_text = "[QUEST_Q1Q2_DESC]";
    group = "[QG_PRIM_NAME]";
    text_file = "English\\Quests\\Q1Q2_Text.xml";
    texts = [("[QUEST_Q1Q2_ACTION1]", "Battle the Ogres"); ("[QUEST_Q1Q2_ACTION2]", "Battle the Ogres Again"); ("[QUEST_Q1Q2_ACTION3]", "Return to Khrona"); ("[QUEST_Q1Q2_FAILURE1]", "You have not beaten the Ogre, but you may try again."); ("[QUEST_Q1Q2_FAILURE2]", "You have not beaten the second Ogre, but you may try again."); ("[QUEST_Q1Q2_OGRES]", "There are a large number of Ogres here and they appear to be hostile."); ("[QUEST_Q1Q2_PROGRESS1]", "You must travel south to Gork and try to settle down the Ogres."); ("[QUEST_Q1Q2_PROGRESS2]", "The Ogres are still restless, you will need to teach them another lesson."); ("[QUEST_Q1Q2_REWARD]", "Khrona is grateful for your help in driving the Ogres back into the south."); ("[QUEST_Q1Q2_SUCCESS1]", "You have defeated one of the Ogres, but the rest seem to be ignoring you."); ("[QUEST_Q1Q2_SUCCESS2]", "Defeating a second Ogre seems to have quietened them down a little."); ("[QUEST_Q1Q2_QMHELP1]", "This Ogre is wearing a huge Horned Helm and Chain Armor to protect him.")];
    lua_file = "Assets\\Quests\\Q1Q2.lua";
    lua_object = "Q1Q2";
    lua_source = "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--             Ogre Tactics	\n" ^
      "--	\n" ^
      "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--		STATES	\n" ^
      "--\n" ^
      "-- 0 => Inactive\n" ^
      "-- 1 => Quest obtained, nothing done yet\n" ^
      "-- 2 => Killed Monster #1\n" ^
      "-- 3 => Killed Monster #2 - must return\n" ^
      "-- 4 => Finished \n" ^
      "-- \n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Variables\n" ^
      "--\n" ^
      "local questState = 0;\n" ^
      "local hadOgreMessage = 0;\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Constants\n" ^
      "--\n" ^
      "local myCode     = \"Q1Q2\";\n" ^
      "local myLocation = \"WGRK\";\n" ^
      "local myOrigin   = \"CDKO\";\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnInit				\n" ^
      "--		(called for every quest when they are loading\n" ^
      "--		 to set the initial state of all variables)\n" ^
      "--\n" ^
      "local function OnInit()\n" ^
      "	questState = 0;\n" ^
      "	hadOgreMessage = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnBegin				\n" ^
      "--		(called when a quest is first obtained)\n" ^
      "--\n" ^
      "local function OnBegin()\n" ^
      "	questState = 1;\n" ^
      "	hadOgreMessage = 0;\n" ^
      "	QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q1Q2a.xml\",myOrigin);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnd				\n" ^
      "--		(called when a quest has ended)\n" ^
      "--\n" ^
      "local function OnEnd()\n" ^
      "	questState = 3;\n" ^
      "	\n" ^
      "	-- Reward\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q1Q2_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[QUEST_Q1Q2_REWARD]\");\n" ^
      "	QUEST_REWARD_MENU(myTitle,myMessage);\n" ^
      "	QUEST_REWARD_GOLD(400);\n" ^
      "	QUEST_REWARD_XP(90);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnAbandon				\n" ^
      "--		(called when a quest has been abandoned by the player)\n" ^
      "--\n" ^
      "local function OnAbandon()\n" ^
      "	questState = 0;  -- it can be restarted\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnterLocation		\n" ^
      "--		(a hero has arrived at a new location)\n" ^
      "--\n" ^
      "local function OnEnterLocation(idLocation)\n" ^
      "	if (idLocation == myLocation and hadOgreMessage == 0) then\n" ^
      "		hadOgreMessage = 1;\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_Q1Q2_NAME]\");\n" ^
      "		local myMessage = GET_TEXT(\"[QUEST_Q1Q2_OGRES]\");\n" ^
      "		QUEST_MESSAGE(myTitle,myMessage,idLocation);\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryAction\n" ^
      "--		(should anything appear on the popup menu)\n" ^
      "--\n" ^
      "local function OnQueryAction(idLocation)\n" ^
      "	if (idLocation==myLocation and questState==1) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q1Q2_ACTION1]\");\n" ^
      "	elseif (idLocation==myLocation and questState==2) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q1Q2_ACTION2]\");\n" ^
      "	elseif (idLocation==myOrigin and questState==3) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q1Q2_ACTION3]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnExecuteAction				\n" ^
      "--		(do this whenever the player executes the next action)\n" ^
      "--\n" ^
      "local function OnExecuteAction(idLocation)\n" ^
      "	if (questState==1) then\n" ^
      "		QUEST_BATTLE(myCode,0,1);\n" ^
      "	elseif (questState==2) then\n" ^
      "		QUEST_BATTLE(myCode,1,1);\n" ^
      "	elseif (questState==3) then\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q1Q2b.xml\",idLocation);\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnCompleteAction				\n" ^
      "--		(do this whenever the player completes his action)\n" ^
      "--		It is called after the game has returned to the map screen\n" ^
      "--\n" ^
      "local function OnCompleteAction(idLocation, success)\n" ^
      "		\n" ^
      "\n" ^
      "	if (questState==1) then\n" ^
      "	\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_Q1Q2_NAME]\");\n" ^
      "		local myMessage;\n" ^
      "		if (success == 1) then\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_Q1Q2_SUCCESS1]\");\n" ^
      "			questState = 2;\n" ^
      "		else\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_Q1Q2_FAILURE1]\");\n" ^
      "		end\n" ^
      "		QUEST_MESSAGE(myTitle,myMessage,idLocation);\n" ^
      "		QUEST_UPDATE_MAP();\n" ^
      "			\n" ^
      "	elseif (questState==2) then\n" ^
      "	\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_Q1Q2_NAME]\");\n" ^
      "		local myMessage;\n" ^
      "		if (success == 1) then\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_Q1Q2_SUCCESS2]\");\n" ^
      "			questState = 3;\n" ^
      "		else\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_Q1Q2_FAILURE2]\");\n" ^
      "		end\n" ^
      "		QUEST_MESSAGE(myTitle,myMessage,idLocation);\n" ^
      "		QUEST_UPDATE_MAP();\n" ^
      "		\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnLoad				\n" ^
      "--		(a save game is being loaded)\n" ^
      "--\n" ^
      "local function OnLoad()\n" ^
      "	questState = QUEST_LOAD_INT();\n" ^
      "	hadOgreMessage = QUEST_LOAD_INT();\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnSave				\n" ^
      "--		(a save game is being saved)\n" ^
      "--\n" ^
      "local function OnSave()\n" ^
      "	QUEST_SAVE_INT(questState);\n" ^
      "	QUEST_SAVE_INT(hadOgreMessage);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryProgress		\n" ^
      "--		(returns text describing the next step required)\n" ^
      "--\n" ^
      "local function OnQueryProgress()\n" ^
      "	if (questState==1) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q1Q2_PROGRESS1]\");\n" ^
      "	elseif (questState==2) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q1Q2_PROGRESS2]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryPercentage	\n" ^
      "--		(returns a percentage of completion)\n" ^
      "--\n" ^
      "local function OnQueryPercentage()\n" ^
      "	return (questState - 1) * 33;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryDifficulty	\n" ^
      "--		(returns 0-4 for difficulty - v.easy to v.difficult )\n" ^
      "--\n" ^
      "local function OnQueryDifficulty()\n" ^
      "	-- average\n" ^
      "	return 2; \n" ^
      "end\n" ^
      "\n" ^
      "-- CallbackConvA 				\n" ^
      "--		(Callback fn - for end of quest)\n" ^
      "--\n" ^
      "local function CallbackConvA ()\n" ^
      "	QUEST_SET_VISIBILITY(myLocation ,1);\n" ^
      "end\n" ^
      "\n" ^
      "-- CallbackConvB 				\n" ^
      "--		(Callback fn - for end of quest)\n" ^
      "--\n" ^
      "local function CallbackConvB ()\n" ^
      "	QUEST_COMPLETE(myCode);\n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
