  {
    id = "Q1Q3";
    name_text = "[QUEST_Q1Q3_NAME]";
    desc_text = "[QUEST_Q1Q3_DESC]";
    group = "[QG_PRIM_NAME]";
    text_file = "English\\Quests\\Q1Q3_Text.xml";
    texts = [("[QUEST_Q1Q3_ACTION]", "Battle the Ogre Mage"); ("[QUEST_Q1Q3_FAILURE]", "You have failed to defeat the Ogre Mage.  You must try again!"); ("[QUEST_Q1Q3_KILL]", "You have defeated the Ogre Mage.  The remaining Ogres will soon descend into chaos."); ("[QUEST_Q1Q3_RETURN]", "Return to Khrona"); ("[QUEST_Q1Q3_REWARD]", "Khrona is pleased and pays you for your troubles."); ("[QUEST_Q1Q3_STEP1]", "You must first go to the Gluk and battle an Ogre Mage."); ("[QUEST_Q1Q3_STEP2]", "You must now head back to Dhun-Kor."); ("[QUEST_Q1Q3_QMHELP0]", "This Ogre Mage is very powerful and also knows the Rain of Fire spell.")];
    lua_file = "Assets\\Quests\\Q1Q3.lua";
    lua_object = "Q1Q3";
    lua_source = "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--             Ogre Magic	\n" ^
      "--	\n" ^
      "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--		STATES	\n" ^
      "--\n" ^
      "-- 0 => Inactive\n" ^
      "-- 1 => Quest obtained, nothing done yet\n" ^
      "-- 2 => Monster defeated, must return\n" ^
      "-- 3 => Finished\n" ^
      "-- \n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Variables\n" ^
      "--\n" ^
      "local questState = 0;\n" ^
      "local lostToMonster = 0;\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Constants\n" ^
      "--\n" ^
      "local myCode     = \"Q1Q3\";\n" ^
      "local myLocation = \"CGLK\";\n" ^
      "local myOrigin   = \"CDKO\";\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnInit				\n" ^
      "--		(called for every quest when they are loading\n" ^
      "--		 to set the initial state of all variables)\n" ^
      "--\n" ^
      "local function OnInit()\n" ^
      "	questState = 0;\n" ^
      "	lostToMonster = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnBegin				\n" ^
      "--		(called when a quest is first obtained)\n" ^
      "--\n" ^
      "local function OnBegin()\n" ^
      "	questState = 1;\n" ^
      "	QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q1Q3a.xml\",myOrigin);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnd				\n" ^
      "--		(called when a quest has ended)\n" ^
      "--\n" ^
      "local function OnEnd()\n" ^
      "	questState = 3;\n" ^
      "	\n" ^
      "	-- Reward\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q1Q3_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[QUEST_Q1Q3_REWARD]\");\n" ^
      "	QUEST_REWARD_MENU(myTitle,myMessage);\n" ^
      "	QUEST_REWARD_GOLD(200);\n" ^
      "	QUEST_REWARD_XP(90);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnAbandon				\n" ^
      "--		(called when a quest has been abandoned by the player)\n" ^
      "--\n" ^
      "local function OnAbandon()\n" ^
      "	questState = 0;  -- it can be restarted\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnterLocation		\n" ^
      "--		(a hero has arrived at a new location)\n" ^
      "--\n" ^
      "local function OnEnterLocation(idLocation)\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryAction\n" ^
      "--		(should anything appear on the popup menu)\n" ^
      "--\n" ^
      "local function OnQueryAction(idLocation)\n" ^
      "	if (idLocation==myLocation and questState==1) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q1Q3_ACTION]\");\n" ^
      "	elseif (idLocation==myOrigin and questState==2) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q1Q3_RETURN]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnExecuteAction				\n" ^
      "--		(do this whenever the player executes the next action)\n" ^
      "--\n" ^
      "local function OnExecuteAction(idLocation)\n" ^
      "	if (questState==1) then\n" ^
      "		QUEST_BATTLE(myCode,0,1);\n" ^
      "	elseif (questState==2) then\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q1Q3b.xml\",myOrigin);\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnCompleteAction				\n" ^
      "--		(do this whenever the player completes his action)\n" ^
      "--		It is called after the game has returned to the map screen\n" ^
      "--\n" ^
      "local function OnCompleteAction(idLocation, success)\n" ^
      "\n" ^
      "	if (questState==1) then\n" ^
      "	\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_Q1Q3_NAME]\");\n" ^
      "		local myMessage;\n" ^
      "		if (success == 1) then\n" ^
      "	  		questState = 2;\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_Q1Q3_KILL]\");\n" ^
      "		else\n" ^
      "			lostToMonster = 1;\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_Q1Q3_FAILURE]\");\n" ^
      "		end\n" ^
      "		QUEST_MESSAGE(myTitle,myMessage,myLocation);\n" ^
      "		QUEST_UPDATE_MAP();\n" ^
      "		\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnLoad				\n" ^
      "--		(a save game is being loaded)\n" ^
      "--\n" ^
      "local function OnLoad()\n" ^
      "	questState = QUEST_LOAD_INT();\n" ^
      "	lostToMonster = QUEST_LOAD_INT();\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnSave				\n" ^
      "--		(a save game is being saved)\n" ^
      "--\n" ^
      "local function OnSave()\n" ^
      "	QUEST_SAVE_INT(questState);\n" ^
      "	QUEST_SAVE_INT(lostToMonster);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryProgress		\n" ^
      "--		(returns text describing the next step required)\n" ^
      "--\n" ^
      "local function OnQueryProgress()\n" ^
      "	if (questState == 1) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q1Q3_STEP1]\");\n" ^
      "	elseif (questState == 2) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q1Q3_STEP2]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryPercentage	\n" ^
      "--		(returns a percentage of completion)\n" ^
      "--\n" ^
      "local function OnQueryPercentage()\n" ^
      "	if (questState <= 1) then\n" ^
      "		return 0;\n" ^
      "	elseif (questState == 2) then\n" ^
      "		return 50;\n" ^
      "	end\n" ^
      "	return 100;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryDifficulty	\n" ^
      "--		(returns 0-4 for difficulty - v.easy to v.difficult )\n" ^
      "--\n" ^
      "local function OnQueryDifficulty()\n" ^
      "	-- average\n" ^
      "	return 2; \n" ^
      "end\n" ^
      "\n" ^
      "-- CallbackConvA 				\n" ^
      "--		(Callback fn - for end of quest)\n" ^
      "--\n" ^
      "local function CallbackConvA ()\n" ^
      "	QUEST_SET_VISIBILITY(myLocation ,1);\n" ^
      "end\n" ^
      "\n" ^
      "-- CallbackConvB 				\n" ^
      "--		(Callback fn - for end of quest)\n" ^
      "--\n" ^
      "local function CallbackConvB ()\n" ^
      "	QUEST_COMPLETE(myCode);\n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "--	\n" ^
      "--		DECLARE TABLE	\n" ^
      "--\n" ^
      "\n" ^
      "Q1Q3 = {\n" ^
      "	OnInit			= OnInit,\n" ^
      "	OnBegin			= OnBegin,\n" ^
      "	OnEnd				= OnEnd,\n" ^
      "	OnAbandon			= OnAbandon,\n" ^
      "	OnEnterLocation		= OnEnterLocation,\n" ^
      "	OnExecuteAction		= OnExecuteAction,\n" ^
      "	OnCompleteAction		= OnCompleteAction,\n" ^
      "	OnQueryAction		= OnQueryAction,\n" ^
      "	OnLoad			= OnLoad,\n" ^
      "	OnSave			= OnSave,\n" ^
      "	OnQueryProgress		= OnQueryProgress,\n" ^
      "	OnQueryPercentage	= OnQueryPercentage,\n" ^
      "	OnQueryDifficulty	= OnQueryDifficulty,\n" ^
      "\n" ^
      "	CallbackConvA = CallbackConvA ,\n" ^
      "	CallbackConvB = CallbackConvB ,\n" ^
      "};\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n";
    abandonable = false;
    icon = 0;
    important = true;
    avail_location = "CDKO";
    avail_minlevel = 15;
    avail_maxlevel = 1000;
    avail_repeat = 1;
    avail_donequest0 = "Q1Q2";
    avail_donequest1 = "";
    avail_donequest2 = "";
    avail_notdonequest = "";
    avail_notactivequest = "";
    avail_companion0 = "";
    avail_companion1 = "";
    avail_notcompanion = "";
    avail_item = "";
    avail_notitem = "";
    avail_award = "";
    avail_notaward = "";
    battle_monster = "MOGM";
    battle_spells = ["SROF"];
    battles = [("MOGM", ["SROF"])];
    battle_actions = [(1, 0, true)];
    battle_stage_advances = [(1, 2)];
    battle_stage_fails = [];
    enter_removes = [];
    reveal_on_begin = ["CGLK"];
    reveal_on_end = [];
    ruin_reveals = [];
