    reward_gold = 200;
    reward_xp = 90;
    reward_items = [];
    reward_awards = [];
    reward_companions = [];
  };
  {
    id = "Q1Q4";
    name_text = "[QUEST_Q1Q4_NAME]";
    desc_text = "[QUEST_Q1Q4_DESC]";
    group = "[QG_PRIM_NAME]";
    text_file = "English\\Quests\\Q1Q4_Text.xml";
    texts = [("[QUEST_Q1Q4_ACTION0]", "Speak with Gruulkar"); ("[QUEST_Q1Q4_ACTION1]", "Confront an Ogre Mage"); ("[QUEST_Q1Q4_ACTION2]", "Speak with Khrona"); ("[QUEST_Q1Q4_FAILOGRE]", "You failed to defeat the Ogre Mage.  You will need to try again."); ("[QUEST_Q1Q4_FOUGHTGUARD0]", "The Guard chases you away, but it is doubtful Grullkar would talk to you again anyway."); ("[QUEST_Q1Q4_FOUGHTGUARD1]", "You defeat the Guard, but Gruulkar will still not talk with you."); ("[QUEST_Q1Q4_HELP0]", "You must travel to Gruuldok and talk with Gruulkar."); ("[QUEST_Q1Q4_HELP1]", "You must search throughout Kor for another way to stop Gruulkar."); ("[QUEST_Q1Q4_MSGA]", "A Huge Orc Champion blocks your way to Gruulkar.  It doesn't look like you'll be speaking to him any more."); ("[QUEST_Q1Q4_MSGB]", "Perhaps the Ogres here have an idea of how to stop Gruulkar..."); ("[QUEST_Q1Q4_REWARD]", "You have failed to stop Gruulkar from going to war, but you have gathered some useful information."); ("[QUEST_Q1Q4_QMNAME0]", "Orc Champion"); ("[QUEST_Q1Q4_QMHELP0]", "This Champion is extremely well-armored and can Headbutt just like an Orc Lord.")];
    lua_file = "Assets\\Quests\\Q1Q4.lua";
    lua_object = "Q1Q4";
    lua_source = "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--             War Council	\n" ^
      "--	\n" ^
      "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--		STATES	\n" ^
      "--\n" ^
      "-- 0 => Inactive\n" ^
      "-- 1 => Got quest, talked with Khrona\n" ^
      "-- 2 => Talked to Gruulkar\n" ^
      "-- 3 => Complete\n" ^
      "-- \n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Variables\n" ^
      "--\n" ^
      "local questState = 0;\n" ^
      "local foughtGuard = 0;\n" ^
      "local talkedToKhrona = 0;\n" ^
      "local foughtOgre = 0;\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Constants\n" ^
      "--\n" ^
      "local myCode     = \"Q1Q4\";\n" ^
      "local myOrigin   = \"CDKO\";\n" ^
      "local myDestination1   = \"CGRU\";\n" ^
      "local myDestination2   = \"CGLK\";\n" ^
      "local myDestination3   = \"CDKO\";\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnInit				\n" ^
      "--		(called for every quest when they are loading\n" ^
      "--		 to set the initial state of all variables)\n" ^
      "--\n" ^
      "local function OnInit()\n" ^
      "	questState = 0;\n" ^
      "	foughtGuard = 0;\n" ^
      "	talkedToKhrona = 0;\n" ^
      "	foughtOgre = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnBegin				\n" ^
      "--		(called when a quest is first obtained)\n" ^
      "--\n" ^
      "local function OnBegin()\n" ^
      "	questState = 1;\n" ^
      "	foughtGuard = 0;\n" ^
      "	talkedToKhrona = 0;\n" ^
      "	foughtOgre = 0;\n" ^
      "	QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q1Q4a.xml\",myOrigin);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnd				\n" ^
      "--		(called when a quest has ended)\n" ^
      "--\n" ^
      "local function OnEnd()\n" ^
      "	questState = 3;\n" ^
      "	\n" ^
      "	-- Reward\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q1Q4_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[QUEST_Q1Q4_REWARD]\");\n" ^
      "	QUEST_REWARD_MENU(myTitle,myMessage);\n" ^
      "	QUEST_REWARD_XP(50);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnAbandon				\n" ^
      "--		(called when a quest has been abandoned by the player)\n" ^
      "--\n" ^
      "local function OnAbandon()\n" ^
      "	-- cannot abandon\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnterLocation		\n" ^
      "--		(a hero has arrived at a new location)\n" ^
      "--\n" ^
      "local function OnEnterLocation(idLocation)\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryAction\n" ^
      "--		(should anything appear on the popup menu)\n" ^
      "--\n" ^
      "local function OnQueryAction(idLocation)\n" ^
      "	if (questState == 1 and idLocation == myDestination1) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q1Q4_ACTION0]\");\n" ^
      "	elseif (questState == 2 and idLocation == myDestination1 and foughtGuard==0) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q1Q4_ACTION0]\");\n" ^
      "	elseif (questState == 2 and idLocation == myDestination2 and foughtOgre==0) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q1Q4_ACTION1]\");\n" ^
      "	elseif (questState == 2 and idLocation == myDestination3 and talkedToKhrona==0) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q1Q4_ACTION2]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnExecuteAction				\n" ^
      "--		(do this whenever the player executes the next action)\n" ^
      "--\n" ^
      "local function OnExecuteAction(idLocation)\n" ^
      "	if (questState == 1 and idLocation == myDestination1) then\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q1Q4b.xml\",idLocation );\n" ^
      "	elseif (questState == 2 and idLocation == myDestination1 and foughtGuard==0) then\n" ^
      "		QUEST_MESSAGE_CALLBACK(\n" ^
      "				GET_TEXT(\"[QUEST_Q1Q4_NAME]\"),\n" ^
      "				GET_TEXT(\"[QUEST_Q1Q4_MSGA]\"),\n" ^
      "				idLocation, myCode, \"CallbackMsgA\");\n" ^
      "	elseif (questState == 2 and idLocation == myDestination2 and foughtOgre==0) then\n" ^
      "		QUEST_MESSAGE_CALLBACK(\n" ^
      "				GET_TEXT(\"[QUEST_Q1Q4_NAME]\"),\n" ^
      "				GET_TEXT(\"[QUEST_Q1Q4_MSGB]\"),\n" ^
      "				idLocation, myCode, \"CallbackMsgB\");\n" ^
      "	elseif (questState == 2 and idLocation == myDestination3 and talkedToKhrona==0) then\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q1Q4c.xml\",idLocation );\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnCompleteAction				\n" ^
      "--		(do this whenever the player completes his action)\n" ^
      "--		It is called after the game has returned to the map screen\n" ^
      "--\n" ^
      "local function OnCompleteAction(idLocation, success)\n" ^
      "	if (questState==2) then\n" ^
      "\n" ^
      "		if (idLocation == myDestination1) then\n" ^
      "			if (success == 1) then\n" ^
      "				QUEST_MESSAGE(\n" ^
      "					GET_TEXT(\"[QUEST_Q1Q4_NAME]\"),\n" ^
      "					GET_TEXT(\"[QUEST_Q1Q4_FOUGHTGUARD1]\"),\n" ^
      "					idLocation);\n" ^
      "				foughtGuard = 1;\n" ^
      "			else\n" ^
      "				QUEST_MESSAGE(\n" ^
      "					GET_TEXT(\"[QUEST_Q1Q4_NAME]\"),\n" ^
      "					GET_TEXT(\"[QUEST_Q1Q4_FOUGHTGUARD0]\"),\n" ^
      "					idLocation);\n" ^
      "\n" ^
      "			end\n" ^
      "		elseif (idLocation == myDestination2) then\n" ^
      "			if (success == 1) then\n" ^
      "				QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q1Q4d.xml\",idLocation );\n" ^
      "			else\n" ^
      "				QUEST_MESSAGE(\n" ^
      "					GET_TEXT(\"[QUEST_Q1Q4_NAME]\"),\n" ^
      "					GET_TEXT(\"[QUEST_Q1Q4_FAILOGRE]\"),\n" ^
      "					idLocation);\n" ^
      "\n" ^
      "			end\n" ^
      "		end\n" ^
      "\n" ^
      "		if (foughtGuard == 1 and foughtOgre == 1 and talkedToKhrona == 1) then\n" ^
      "			QUEST_COMPLETE(myCode);\n" ^
      "		else\n" ^
      "			QUEST_UPDATE_MAP();\n" ^
      "		end\n" ^
      "		\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnLoad				\n" ^
      "--		(a save game is being loaded)\n" ^
      "--\n" ^
      "local function OnLoad()\n" ^
      "	questState = QUEST_LOAD_INT();\n" ^
      "	foughtGuard = QUEST_LOAD_INT();\n" ^
      "	foughtOgre = QUEST_LOAD_INT();\n" ^
      "	talkedToKhrona = QUEST_LOAD_INT();\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnSave				\n" ^
      "--		(a save game is being saved)\n" ^
      "--\n" ^
      "local function OnSave()\n" ^
      "	QUEST_SAVE_INT(questState );\n" ^
      "	QUEST_SAVE_INT(foughtGuard );\n" ^
      "	QUEST_SAVE_INT(foughtOgre );\n" ^
      "	QUEST_SAVE_INT(talkedToKhrona );\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryProgress		\n" ^
      "--		(returns text describing the next step required)\n" ^
      "--\n" ^
      "local function OnQueryProgress()\n" ^
      "	if (questState == 1) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q1Q4_HELP0]\");\n" ^
      "	elseif (questState == 2) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q1Q4_HELP1]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryPercentage	\n" ^
      "--		(returns a percentage of completion)\n" ^
      "--\n" ^
      "local function OnQueryPercentage()\n" ^
      "	if (questState == 1) then\n" ^
      "		return 0;\n" ^
      "	end\n" ^
      "	return foughtGuard*33 + foughtOgre *33 + talkedToKhrona *33;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryDifficulty	\n" ^
      "--		(returns 0-4 for difficulty - v.easy to v.difficult )\n" ^
      "--\n" ^
      "local function OnQueryDifficulty()\n" ^
      "	-- average\n" ^
      "	return 2; \n" ^
      "end\n" ^
      "\n" ^
      "-- Callbacks				\n" ^
      "--		(Callback fn - for end of quest/message)\n" ^
      "--\n" ^
      "local function CallbackConvA ()\n" ^
      "end\n" ^
      "local function CallbackConvB ()\n" ^
      "	questState = 2;\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "local function CallbackConvC ()\n" ^
      "	talkedToKhrona = 1;\n" ^
      "	if (foughtGuard == 1 and foughtOgre == 1 and talkedToKhrona == 1) then\n" ^
      "		QUEST_COMPLETE(myCode);\n" ^
      "	else\n" ^
      "		QUEST_UPDATE_MAP();\n" ^
      "	end\n" ^
      "end\n" ^
      "local function CallbackConvD ()\n" ^
      "	foughtOgre = 1;\n" ^
      "	if (foughtGuard == 1 and foughtOgre == 1 and talkedToKhrona == 1) then\n" ^
      "		QUEST_COMPLETE(myCode);\n" ^
      "	else\n" ^
      "		QUEST_UPDATE_MAP();\n" ^
      "	end\n" ^
      "end\n" ^
      "local function CallbackMsgA ()\n" ^
      "	QUEST_BATTLE(myCode,0,1);\n" ^
      "end\n" ^
      "local function CallbackMsgB ()\n" ^
      "	QUEST_BATTLE(myCode,1,1);\n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
