    texts = [("[QUEST_Q1Q6_ACTION1]", "Hide in a Scorpion Hole"); ("[QUEST_Q1Q6_ACTION2]", "Ambush Gruulkar"); ("[QUEST_Q1Q6_FAILURE1]", "You have failed to defeat the Scorpion. You must try again."); ("[QUEST_Q1Q6_FAILURE2]", "You have failed to defeat Grullkar. You must try again, quickly!"); ("[QUEST_Q1Q6_MSGA]", "A fine plan, except there is a Scorpion down this hole!"); ("[QUEST_Q1Q6_PROGRESS1]", "Travel to Snake Fang and find a Scorpion Hole to hide in."); ("[QUEST_Q1Q6_PROGRESS2]", "Wait for Gruulkar to pass by and then ambush him."); ("[QUEST_Q1Q6_REWARD]", "You have defeated Gruulkar. As proof of your victory you take Gruulkar's Shield."); ("[QUEST_Q1Q6_SUCCESS1]", "You have defeated the Scorpion. The hole is now all yours."); ("[QUEST_Q1Q6_QMHELP1]", "Gruulkar is the leader of the Orcs of Kor.")];
    lua_file = "Assets\\Quests\\Q1Q6.lua";
    lua_object = "Q1Q6";
    lua_source = "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--             Gruulkar	\n" ^
      "--	\n" ^
      "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--		STATES	\n" ^
      "--\n" ^
      "-- 0 => Inactive\n" ^
      "-- 1 => Quest obtained, nothing done yet\n" ^
      "-- 2 => Killed Monster #1\n" ^
      "-- 3 => Finished (Killed Monster #2)\n" ^
      "-- \n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Variables\n" ^
      "--\n" ^
      "local questState = 0;\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Constants\n" ^
      "--\n" ^
      "local myCode     = \"Q1Q6\";\n" ^
      "local myLocation = \"WSFA\";\n" ^
      "local myOrigin   = \"CDKO\";\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnInit				\n" ^
      "--		(called for every quest when they are loading\n" ^
      "--		 to set the initial state of all variables)\n" ^
      "--\n" ^
      "local function OnInit()\n" ^
      "	questState = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnBegin				\n" ^
      "--		(called when a quest is first obtained)\n" ^
      "--\n" ^
      "local function OnBegin()\n" ^
      "	questState = 1;\n" ^
      "	QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q1Q6a.xml\",myOrigin);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnd				\n" ^
      "--		(called when a quest has ended)\n" ^
      "--\n" ^
      "local function OnEnd()\n" ^
      "	questState = 3;\n" ^
      "	\n" ^
      "	-- Reward\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q1Q6_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[QUEST_Q1Q6_REWARD]\");\n" ^
      "	QUEST_REWARD_MENU(myTitle,myMessage);\n" ^
      "	QUEST_REWARD_ITEM(\"IGSH\");\n" ^
      "	QUEST_REWARD_XP(250);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnAbandon				\n" ^
      "--		(called when a quest has been abandoned by the player)\n" ^
      "--\n" ^
      "local function OnAbandon()\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnterLocation		\n" ^
      "--		(a hero has arrived at a new location)\n" ^
      "--\n" ^
      "local function OnEnterLocation(idLocation)\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryAction\n" ^
      "--		(should anything appear on the popup menu)\n" ^
      "--\n" ^
      "local function OnQueryAction(idLocation)\n" ^
      "	if (idLocation==myLocation and questState==1) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q1Q6_ACTION1]\");\n" ^
      "	elseif (idLocation==myLocation and questState==2) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q1Q6_ACTION2]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnExecuteAction				\n" ^
      "--		(do this whenever the player executes the next action)\n" ^
      "--\n" ^
      "local function OnExecuteAction(idLocation)\n" ^
      "	if (questState==1) then\n" ^
      "		QUEST_MESSAGE_CALLBACK(GET_TEXT(\"[QUEST_Q1Q6_NAME]\"),\n" ^
      "			GET_TEXT(\"[QUEST_Q1Q6_MSGA]\"), idLocation,\n" ^
      "			\"Q1Q6\",\"CallbackMsgA\");\n" ^
      "	elseif (questState==2) then\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q1Q6b.xml\",idLocation);\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnCompleteAction				\n" ^
      "--		(do this whenever the player completes his action)\n" ^
      "--		It is called after the game has returned to the map screen\n" ^
      "--\n" ^
      "local function OnCompleteAction(idLocation, success)\n" ^
      "		\n" ^
      "\n" ^
      "	if (questState==1) then\n" ^
      "	\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_Q1Q6_NAME]\");\n" ^
      "		local myMessage;\n" ^
      "		if (success == 1) then\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_Q1Q6_SUCCESS1]\");\n" ^
      "			questState = 2;\n" ^
      "		else\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_Q1Q6_FAILURE1]\");\n" ^
      "		end\n" ^
      "		QUEST_MESSAGE(myTitle,myMessage,idLocation);\n" ^
      "		QUEST_UPDATE_MAP();\n" ^
      "			\n" ^
      "	elseif (questState==2) then\n" ^
      "	\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_Q1Q6_NAME]\");\n" ^
      "		local myMessage;\n" ^
      "		if (success == 1) then\n" ^
      "			QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q1Q6c.xml\",idLocation);\n" ^
      "		else\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_Q1Q6_FAILURE2]\");\n" ^
