      "--\n" ^
      "local myCode     = \"Q1R3\";\n" ^
      "local myLocation = \"RUML\";\n" ^
      "local myLocation2= \"RCBL\";\n" ^
      "local myLocation3= \"RMOL\";\n" ^
      "local myOrigin   = \"CDRH\";\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnInit				\n" ^
      "--		(called for every quest when they are loading\n" ^
      "--		 to set the initial state of all variables)\n" ^
      "--\n" ^
      "local function OnInit()\n" ^
      "	questState = 0;\n" ^
      "	doneLoc1 = 0;\n" ^
      "	doneLoc2 = 0;\n" ^
      "	doneLoc3 = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnBegin				\n" ^
      "--		(called when a quest is first obtained)\n" ^
      "--\n" ^
      "local function OnBegin()\n" ^
      "	questState = 1;\n" ^
      "	doneLoc1 = 0;\n" ^
      "	doneLoc2 = 0;\n" ^
      "	doneLoc3 = 0;\n" ^
      "	QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q1R3a.xml\",myOrigin);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnd				\n" ^
      "--		(called when a quest has ended)\n" ^
      "--\n" ^
      "local function OnEnd()\n" ^
      "	questState = 3;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnAbandon				\n" ^
      "--		(called when a quest has been abandoned by the player)\n" ^
      "--\n" ^
      "local function OnAbandon()\n" ^
      "	questState = 0;  -- it can be restarted\n" ^
      "	QUEST_SET_RUIN_DONE(myLocation);\n" ^
      "	QUEST_SET_RUIN_DONE(myLocation2);\n" ^
      "	QUEST_SET_RUIN_DONE(myLocation3);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnterLocation		\n" ^
      "--		(a hero has arrived at a new location)\n" ^
      "--\n" ^
      "local function OnEnterLocation(idLocation)\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryAction\n" ^
      "--		(should anything appear on the popup menu)\n" ^
      "--\n" ^
      "local function OnQueryAction(idLocation)\n" ^
      "	if (idLocation==myLocation and questState==1 and doneLoc1==0) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q1R3_ACTION]\");\n" ^
      "	elseif (idLocation==myLocation2 and questState==1 and doneLoc2==0) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q1R3_ACTION]\");\n" ^
      "	elseif (idLocation==myLocation3 and questState==1 and doneLoc3==0) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q1R3_ACTION]\");\n" ^
      "	elseif (idLocation==myOrigin and questState==2) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q1R3_RETURN]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnExecuteAction				\n" ^
      "--		(do this whenever the player executes the next action)\n" ^
      "--\n" ^
      "local function OnExecuteAction(idLocation)\n" ^
      "\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q1R3_NAME]\");\n" ^
      "	local myMessage;\n" ^
      "\n" ^
      "	if (questState==1 and idLocation==myLocation) then\n" ^
      "		myMessage = GET_TEXT(\"[QUEST_Q1R3_MSGA]\");\n" ^
      "		QUEST_MESSAGE_CALLBACK(myTitle ,myMessage ,idLocation, myCode, \"CallbackMsgA\");\n" ^
      "	elseif (questState==1 and idLocation==myLocation2) then\n" ^
      "		myMessage = GET_TEXT(\"[QUEST_Q1R3_MSGB]\");\n" ^
      "		QUEST_MESSAGE_CALLBACK(myTitle ,myMessage ,idLocation, myCode, \"CallbackMsgB\");\n" ^
      "	elseif (questState==1 and idLocation==myLocation3) then\n" ^
      "		myMessage = GET_TEXT(\"[QUEST_Q1R3_MSGC]\");\n" ^
      "		QUEST_MESSAGE_CALLBACK(myTitle ,myMessage ,idLocation, myCode, \"CallbackMsgC\");\n" ^
      "	elseif (questState==2) then\n" ^
      "		myMessage = GET_TEXT(\"[QUEST_Q1R3_MSGE]\");\n" ^
      "		QUEST_MESSAGE_CALLBACK(myTitle ,myMessage ,idLocation, myCode, \"CallbackMsgE\");\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnCompleteAction				\n" ^
      "--		(do this whenever the player completes his action)\n" ^
      "--		It is called after the game has returned to the map screen\n" ^
      "--\n" ^
      "local function OnCompleteAction(idLocation, success)\n" ^
      "\n" ^
      "	if (questState==1 and idLocation==myLocation) then\n" ^
      "	\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_Q1R3_NAME]\");\n" ^
      "		local myMessage;\n" ^
      "		if (success == 1) then\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_Q1R3_MSGD]\");\n" ^
      "			QUEST_MESSAGE_CALLBACK(myTitle,myMessage,idLocation,myCode,\"CallbackMsgD\");\n" ^
      "		else\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_Q1R3_FAILURE]\");\n" ^
      "			QUEST_MESSAGE(myTitle,myMessage,idLocation);\n" ^
      "		end\n" ^
      "\n" ^
      "	elseif (questState==2) then\n" ^
      "\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_Q1R3_NAME]\");\n" ^
      "		local myMessage;\n" ^
      "		if (success == 1) then\n" ^
      "			QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q1R3b.xml\",myOrigin);\n" ^
      "		else\n" ^
      "			local myTitle = GET_TEXT(\"[QUEST_Q1R3_NAME]\");\n" ^
      "			local myMessage = GET_TEXT(\"[QUEST_Q1R3_FAILURE]\");\n" ^
      "			QUEST_MESSAGE(myTitle,myMessage,idLocation);\n" ^
      "		end\n" ^
      "\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnLoad				\n" ^
      "--		(a save game is being loaded)\n" ^
      "--\n" ^
      "local function OnLoad()\n" ^
      "	questState = QUEST_LOAD_INT();\n" ^
      "	doneLoc1 = QUEST_LOAD_INT();\n" ^
      "	doneLoc2 = QUEST_LOAD_INT();\n" ^
      "	doneLoc3 = QUEST_LOAD_INT();\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnSave				\n" ^
      "--		(a save game is being saved)\n" ^
      "--\n" ^
      "local function OnSave()\n" ^
      "	QUEST_SAVE_INT(questState);\n" ^
      "	QUEST_SAVE_INT(doneLoc1);\n" ^
      "	QUEST_SAVE_INT(doneLoc2);\n" ^
      "	QUEST_SAVE_INT(doneLoc3);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryProgress		\n" ^
      "--		(returns text describing the next step required)\n" ^
      "--\n" ^
      "local function OnQueryProgress()\n" ^
      "	if (questState == 1) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q1R3_STEP1]\");\n" ^
      "	elseif (questState == 2) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q1R3_STEP2]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryPercentage	\n" ^
      "--		(returns a percentage of completion)\n" ^
      "--\n" ^
      "local function OnQueryPercentage()\n" ^
      "	if (questState <= 1) then\n" ^
      "		return doneLoc1*25 + doneLoc2*25 + doneLoc3*25 ;\n" ^
      "	elseif (questState == 2) then\n" ^
      "		return 75;\n" ^
      "	end\n" ^
      "	return 100;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryDifficulty	\n" ^
      "--		(returns 0-4 for difficulty - v.easy to v.difficult )\n" ^
      "--\n" ^
      "local function OnQueryDifficulty()\n" ^
      "	-- average\n" ^
      "	return 1; \n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "-- Callbacks				\n" ^
      "--		(Callback fn - for end of quest/message)\n" ^
      "--\n" ^
      "local function CallbackConvA ()\n" ^
      "	QUEST_ADD_RUIN(myLocation);\n" ^
      "	QUEST_ADD_RUIN(myLocation2);\n" ^
      "	QUEST_ADD_RUIN(myLocation3);\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "local function CallbackConvB ()\n" ^
      "	\n" ^
      "	-- Reward\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q1R3_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[QUEST_Q1R3_REWARD]\");\n" ^
      "	QUEST_REWARD_MENU_CALLBACK(myTitle,myMessage, myCode,\"CallbackCompanion\");\n" ^
      "	QUEST_REWARD_XP(200);\n" ^
      "end\n" ^
      "local function CallbackMsgA ()\n" ^
      "	QUEST_BATTLE(myCode,0,1);\n" ^
      "end\n" ^
      "local function CallbackMsgB ()\n" ^
      "	doneLoc2 = 1;\n" ^
      "	QUEST_SET_RUIN_DONE(myLocation2);	\n" ^
      "	if (doneLoc1==1 and doneLoc2==1 and doneLoc3==1) then\n" ^
      "		questState=2;\n" ^
      "	end	\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "local function CallbackMsgC ()\n" ^
      "	doneLoc3 = 1;\n" ^
      "	QUEST_SET_RUIN_DONE(myLocation3);	\n" ^
      "	if (doneLoc1==1 and doneLoc2==1 and doneLoc3==1) then\n" ^
      "		questState=2;\n" ^
      "	end	\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "local function CallbackMsgD ()\n" ^
      "	doneLoc1 = 1;\n" ^
      "	QUEST_SET_RUIN_DONE(myLocation);\n" ^
      "	if (doneLoc1==1 and doneLoc2==1 and doneLoc3==1) then\n" ^
      "		questState=2;\n" ^
      "	end	\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "local function CallbackMsgE ()\n" ^
      "	QUEST_BATTLE(myCode,1,1);\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackCompanion ()\n" ^
      "	QUEST_ADD_COMPANION(\"NFLI\");\n" ^
      "	QUEST_COMPANION_MESSAGE(\"NFLI\");\n" ^
      "	QUEST_COMPLETE(myCode);\n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "--	\n" ^
      "--		DECLARE TABLE	\n" ^
      "--\n" ^
      "\n" ^
      "Q1R3 = {\n" ^
      "	OnInit				= OnInit,\n" ^
      "	OnBegin				= OnBegin,\n" ^
      "	OnEnd				= OnEnd,\n" ^
      "	OnAbandon			= OnAbandon,\n" ^
      "	OnEnterLocation		= OnEnterLocation,\n" ^
      "	OnExecuteAction		= OnExecuteAction,\n" ^
      "	OnCompleteAction	= OnCompleteAction,\n" ^
      "	OnQueryAction		= OnQueryAction,\n" ^
      "	OnLoad				= OnLoad,\n" ^
      "	OnSave				= OnSave,\n" ^
      "	OnQueryProgress		= OnQueryProgress,\n" ^
      "	OnQueryPercentage	= OnQueryPercentage,\n" ^
      "	OnQueryDifficulty	= OnQueryDifficulty,\n" ^
      "\n" ^
      "	CallbackConvA = CallbackConvA,\n" ^
      "	CallbackConvB = CallbackConvB,\n" ^
      "	CallbackMsgA = CallbackMsgA,\n" ^
      "	CallbackMsgB = CallbackMsgB,\n" ^
      "	CallbackMsgC = CallbackMsgC,\n" ^
      "	CallbackMsgD = CallbackMsgD,\n" ^
      "	CallbackMsgE = CallbackMsgE,\n" ^
      "\n" ^
      "	CallbackCompanion = CallbackCompanion,\n" ^
      "};\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n";
    abandonable = true;
    icon = 2;
    important = false;
    avail_location = "CDRH";
    avail_minlevel = 19;
    avail_maxlevel = 1000;
    avail_repeat = 1;
    avail_donequest0 = "Q1R0";
    avail_donequest1 = "Q1R1";
    avail_donequest2 = "Q1R2";
    avail_notdonequest = "";
    avail_notactivequest = "";
    avail_companion0 = "";
    avail_companion1 = "";
    avail_notcompanion = "";
    avail_item = "";
    avail_notitem = "";
    avail_award = "";
    avail_notaward = "";
    battle_monster = "MMIN";
    battle_spells = [];
    battles = [("MMIN", []); ("MMIN", [])];
    battle_actions = [];
    battle_stage_advances = [];
    battle_stage_fails = [];
    enter_removes = [];
    reveal_on_begin = [];
    reveal_on_end = [];
    ruin_reveals = ["RUML"; "RCBL"; "RMOL"];
    ruin_dones_on_end = ["RCBL"; "RMOL"; "RUML"];
    ruin_dones_on_battle = [];
    ruin_dones_on_abandon = ["RUML"; "RCBL"; "RMOL"];
    reward_gold = 0;
    reward_xp = 200;
    reward_items = [];
    reward_awards = [];
    reward_companions = ["NFLI"];
  };
  {
    id = "Q1S0";
    name_text = "[QUEST_Q1S0_NAME]";
    desc_text = "[QUEST_Q1S0_DESC]";
    group = "";
    text_file = "English\\Quests\\Q1S0_Text.xml";
    texts = [("[QUEST_Q1S0_KHALKUSNO]", "Khalkus will not let you keep the key.  But maybe if you ask him to leave..."); ("[QUEST_Q1S0_ACTION]", "Search for the Heirloom"); ("[QUEST_Q1S0_FAILURE]", "The Ogre has chased you away, you will need to try again."); ("[QUEST_Q1S0_KEEP]", "Keep the Heirloom"); ("[QUEST_Q1S0_KILL]", "Having defeated the Ogre, a quick search turns up the heirloom - a fine looking key. Nobody is watching - it would be very easy to keep it!"); ("[QUEST_Q1S0_RETURN]", "Return the Heirloom"); ("[QUEST_Q1S0_REWARD0]", "Khalkus is overjoyed that you have returned the heirloom.  He names you a Dwarf-Friend (and you gain +2 Morale)."); ("[QUEST_Q1S0_REWARD1]", "Khalkus is sad to learn that the heirloom was lost."); ("[QUEST_Q1S0_STEP1]", "You must go to the Ogre's Tower and search for the heirloom."); ("[QUEST_Q1S0_STEP2]", "You must now return the heirloom to Dhun-Kor (or you could keep it and say it was lost).")];
    lua_file = "Assets\\Quests\\Q1S0.lua";
    lua_object = "Q1S0";
    lua_source = "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--             Dwarven Heirloom	\n" ^
      "--	\n" ^
      "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--		STATES	\n" ^
      "--\n" ^
      "-- 0 => Inactive\n" ^
      "-- 1 => Quest obtained, nothing done yet\n" ^
      "-- 2 => Monster defeated, must return\n" ^
      "-- 3 => Finished\n" ^
      "-- \n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Variables\n" ^
      "--\n" ^
      "local questState = 0;\n" ^
      "local lostToMonster = 0;\n" ^
      "local keptHeirloom = 0;\n" ^
      "local triedToKeepKey = 0;\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Constants\n" ^
      "--\n" ^
      "local myCode     = \"Q1S0\";\n" ^
      "local myLocation = \"ROTO\";\n" ^
      "local myOrigin   = \"CDKO\";\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnInit				\n" ^
      "--		(called for every quest when they are loading\n" ^
      "--		 to set the initial state of all variables)\n" ^
      "--\n" ^
      "local function OnInit()\n" ^
      "	questState = 0;\n" ^
      "	lostToMonster = 0;\n" ^
      "	keptHeirloom = 0;\n" ^
      "	triedToKeepKey = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnBegin				\n" ^
      "--		(called when a quest is first obtained)\n" ^
      "--\n" ^
      "local function OnBegin()\n" ^
      "	questState = 1;\n" ^
      "	triedToKeepKey = 0;\n" ^
      "	lostToMonster = 0;\n" ^
      "	keptHeirloom = 0;\n" ^
      "	QUEST_ADD_RUIN(myLocation);\n" ^
      "	QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q1S0a.xml\",myOrigin);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnd				\n" ^
      "--		(called when a quest has ended)\n" ^
      "--\n" ^
      "local function OnEnd()\n" ^
      "	questState = 3;\n" ^
      "\n" ^
      "	QUEST_SET_RUIN_DONE(myLocation);\n" ^
      "	\n" ^
      "	-- Reward\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q1S0_NAME]\");\n" ^
      "	if (keptHeirloom == 1) then\n" ^
      "		local myMessage = GET_TEXT(\"[QUEST_Q1S0_REWARD1]\");\n" ^
      "		QUEST_REWARD_MENU(myTitle,myMessage);\n" ^
      "		QUEST_REWARD_ITEM(\"IKKE\");\n" ^
      "		QUEST_REWARD_XP(50);\n" ^
      "	else\n" ^
      "		local myMessage = GET_TEXT(\"[QUEST_Q1S0_REWARD0]\");\n" ^
      "		QUEST_REWARD_MENU(myTitle,myMessage);\n" ^
      "		QUEST_REWARD_GOLD(200);\n" ^
      "		QUEST_REWARD_XP(50);\n" ^
      "		QUEST_ADD_AWARD(\"ADFR\");\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnAbandon				\n" ^
      "--		(called when a quest has been abandoned by the player)\n" ^
      "--\n" ^
      "local function OnAbandon()\n" ^
      "	questState = 0;  -- it can be restarted\n" ^
      "	QUEST_SET_RUIN_DONE(myLocation);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnterLocation		\n" ^
      "--		(a hero has arrived at a new location)\n" ^
      "--\n" ^
      "local function OnEnterLocation(idLocation)\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryAction\n" ^
      "--		(should anything appear on the popup menu)\n" ^
      "--\n" ^
      "local function OnQueryAction(idLocation)\n" ^
      "	if (idLocation==myLocation and questState==1) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q1S0_ACTION]\");\n" ^
      "	elseif (idLocation==myOrigin and questState==2) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q1S0_RETURN]\");\n" ^
      "	elseif (idLocation==myLocation and questState==2) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q1S0_KEEP]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnExecuteAction				\n" ^
      "--		(do this whenever the player executes the next action)\n" ^
      "--\n" ^
      "local function OnExecuteAction(idLocation)\n" ^
      "	if (questState==1) then\n" ^
      "		QUEST_BATTLE(myCode,0,1);\n" ^
      "\n" ^
      "	elseif (questState==2 and idLocation == myOrigin ) then\n" ^
      "		keptHeirloom = 0;\n" ^
      "		QUEST_COMPLETE(myCode);\n" ^
      "\n" ^
      "	elseif (questState==2) then\n" ^
      "\n" ^
      "		if (QUEST_HERO_HAS_COMPANION_SELECTED(\"NKHA\")==1 and triedToKeepKey==0) then\n" ^
      "			triedToKeepKey = 1;\n" ^
      "			QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q1S0b.xml\",idLocation);\n" ^
      "\n" ^
      "		elseif (QUEST_HERO_HAS_COMPANION_SELECTED(\"NKHA\")==1 and triedToKeepKey==1) then\n" ^
      "			local myTitle = GET_TEXT(\"[QUEST_Q1S0_NAME]\");\n" ^
      "			local myMessage = GET_TEXT(\"[QUEST_Q1S0_KHALKUSNO]\");\n" ^
      "			QUEST_MESSAGE(myTitle,myMessage,idLocation);\n" ^
      "\n" ^
      "		else\n" ^
      "			keptHeirloom = 1;\n" ^
      "			QUEST_COMPLETE(myCode);\n" ^
      "		end\n" ^
      "\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnCompleteAction				\n" ^
      "--		(do this whenever the player completes his action)\n" ^
      "--		It is called after the game has returned to the map screen\n" ^
      "--\n" ^
      "local function OnCompleteAction(idLocation, success)\n" ^
      "\n" ^
      "	if (questState==1) then\n" ^
      "	\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_Q1S0_NAME]\");\n" ^
      "		local myMessage;\n" ^
      "		if (success == 1) then\n" ^
      "	  		questState = 2;\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_Q1S0_KILL]\");\n" ^
      "		else\n" ^
      "			lostToMonster = 1;\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_Q1S0_FAILURE]\");\n" ^
      "		end\n" ^
      "		QUEST_MESSAGE(myTitle,myMessage,myLocation);\n" ^
      "		QUEST_UPDATE_MAP();\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnLoad				\n" ^
      "--		(a save game is being loaded)\n" ^
      "--\n" ^
      "local function OnLoad()\n" ^
      "	questState     = QUEST_LOAD_INT();\n" ^
      "	lostToMonster  = QUEST_LOAD_INT();\n" ^
      "	keptHeirloom   = QUEST_LOAD_INT();\n" ^
      "	triedToKeepKey = QUEST_LOAD_INT();\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnSave				\n" ^
      "--		(a save game is being saved)\n" ^
      "--\n" ^
      "local function OnSave()\n" ^
