    battle_actions = [(1, 0, true)];
    battle_stage_advances = [];
    battle_stage_fails = [];
    enter_removes = [];
    reveal_on_begin = ["WNKR"];
    reveal_on_end = [];
    ruin_reveals = [];
    ruin_dones_on_end = [];
    ruin_dones_on_battle = [];
    ruin_dones_on_abandon = ["WNKR"];
    reward_gold = 100;
    reward_xp = 65;
