  {
    id = "Q1S4";
    name_text = "[QUEST_Q1S4_NAME]";
    desc_text = "[QUEST_Q1S4_DESC]";
    group = "";
    text_file = "English\\Quests\\Q1S4_Text.xml";
    texts = [("[QUEST_Q1S4_REWARDKEEP]", "You decide to keep the Relic.  You had better not let the Orcish Priests find out though!"); ("[QUEST_Q1S4_KEEP]", "Keep the Relic"); ("[QUEST_Q1S4_ACTION]", "Search for the Goblin"); ("[QUEST_Q1S4_FAILURE]", "The Goblin has slipped away, he is still somewhere in Kor. You must pursue him!"); ("[QUEST_Q1S4_RETURN]", "Return the Relic"); ("[QUEST_Q1S4_REWARD]", "You return the Relic and the Orcish Priests of Ymorgia reward you with Gold."); ("[QUEST_Q1S4_STEP1]", "You must find the Goblin, somewhere in Kor, and reclaim the relic."); ("[QUEST_Q1S4_STEP2]", "You must return the relic to the Temple in Gruuldok to receive your reward, or if you are at Drong's Tower you could keep the relic instead."); ("[QUEST_Q1S4_SUCCESS]", "You never caught the Goblin, but you have the relic to return to Gruuldok.  Of course, you could always decide to keep the relic instead...")];
    lua_file = "Assets\\Quests\\Q1S4.lua";
    lua_object = "Q1S4";
    lua_source = "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--             Crazy Goblin	\n" ^
      "--	\n" ^
      "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--		STATES	\n" ^
      "--\n" ^
      "-- 0 => Inactive\n" ^
      "-- 1 => Goblin in White Skull (WWSK)\n" ^
      "-- 2 => Goblin in Snake Fang (WSFA)\n" ^
      "-- 3 => Goblin in Northern Kor (WNKR)\n" ^
      "-- 4 => Goblin in Bone Head (WBHE)\n" ^
      "-- 5 => Goblin in Blood Moon (WRMO)\n" ^
      "-- 6 => Goblin in Gork (WGRK)\n" ^
      "-- 7 => Goblin in Drong's Tower (WDRT)\n" ^
      "-- 8 => Got relic - can return to Gruuldok (CGRU)\n" ^
      "-- 9 => Finished\n" ^
      "-- \n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Variables\n" ^
      "--\n" ^
      "local questState = 0;\n" ^
      "local keptItem = 0;\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Constants\n" ^
      "--\n" ^
      "local myCode     = \"Q1S4\";\n" ^
      "local myOrigin   = \"CGRU\";\n" ^
      "local myLocation1 = \"WWSK\";\n" ^
      "local myLocation2 = \"WSFA\";\n" ^
      "local myLocation3 = \"WNKR\";\n" ^
      "local myLocation4 = \"WBHE\";\n" ^
      "local myLocation5 = \"WRMO\";\n" ^
      "local myLocation6 = \"WGRK\";\n" ^
      "local myLocation7 = \"WDRT\";\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnInit				\n" ^
      "--		(called for every quest when they are loading\n" ^
      "--		 to set the initial state of all variables)\n" ^
      "--\n" ^
      "local function OnInit()\n" ^
      "	questState = 0;\n" ^
      "	keptItem = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnBegin				\n" ^
      "--		(called when a quest is first obtained)\n" ^
      "--\n" ^
      "local function OnBegin()\n" ^
      "	questState = 1;\n" ^
      "	keptItem = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnd				\n" ^
      "--		(called when a quest has ended)\n" ^
      "--\n" ^
      "local function OnEnd()\n" ^
      "	questState = 9;\n" ^
      "	\n" ^
      "	-- Reward\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q1S4_NAME]\");\n" ^
      "	local myMessage;\n" ^
      "	if (keptItem == 0) then\n" ^
      "		 myMessage = GET_TEXT(\"[QUEST_Q1S4_REWARD]\");\n" ^
      "	else\n" ^
      "		 myMessage = GET_TEXT(\"[QUEST_Q1S4_REWARDKEEP]\");\n" ^
      "	end\n" ^
      "\n" ^
      "	QUEST_REWARD_MENU(myTitle,myMessage);\n" ^
      "\n" ^
      "	if (keptItem == 0) then\n" ^
      "		QUEST_REWARD_GOLD(250);\n" ^
      "		QUEST_REWARD_XP(100);\n" ^
      "	else\n" ^
      "		QUEST_REWARD_ITEM(\"IROY\");\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnAbandon				\n" ^
      "--		(called when a quest has been abandoned by the player)\n" ^
      "--\n" ^
      "local function OnAbandon()\n" ^
      "	questState = 0;  -- it can be restarted\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnterLocation		\n" ^
      "--		(a hero has arrived at a new location)\n" ^
      "--\n" ^
      "local function OnEnterLocation(idLocation)\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryAction\n" ^
      "--		(should anything appear on the popup menu)\n" ^
      "--\n" ^
      "local function OnQueryAction(idLocation)\n" ^
      "	if (idLocation==myLocation1 and questState==1) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q1S4_ACTION]\");\n" ^
      "	elseif (idLocation==myLocation2 and questState==2) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q1S4_ACTION]\");\n" ^
      "	elseif (idLocation==myLocation3 and questState==3) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q1S4_ACTION]\");\n" ^
      "	elseif (idLocation==myLocation4 and questState==4) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q1S4_ACTION]\");\n" ^
      "	elseif (idLocation==myLocation5 and questState==5) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q1S4_ACTION]\");\n" ^
      "	elseif (idLocation==myLocation6 and questState==6) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q1S4_ACTION]\");\n" ^
      "	elseif (idLocation==myLocation7 and questState==7) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q1S4_ACTION]\");\n" ^
      "	elseif (idLocation==myOrigin and questState==8) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q1S4_RETURN]\");\n" ^
      "	elseif (idLocation==myLocation7 and questState==8) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q1S4_KEEP]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnExecuteAction				\n" ^
      "--		(do this whenever the player executes the next action)\n" ^
      "--\n" ^
      "local function OnExecuteAction(idLocation)\n" ^
      "	if (questState<7) then\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_Q1S4_NAME]\");\n" ^
      "		local myMessage = GET_TEXT(\"[QUEST_Q1S4_FAILURE]\");\n" ^
      "		QUEST_MESSAGE(myTitle ,myMessage ,idLocation);\n" ^
      "		questState = questState + 1;\n" ^
      "		QUEST_UPDATE_MAP();\n" ^
      "	elseif (questState==7) then\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q1S4a.xml\",idLocation);\n" ^
      "		questState = questState + 1;\n" ^
      "		QUEST_UPDATE_MAP();\n" ^
      "	elseif (questState==8 and idLocation==myOrigin) then\n" ^
      "		keptItem = 0;\n" ^
      "		QUEST_COMPLETE(myCode);\n" ^
      "	elseif (questState==8 and idLocation==myLocation7) then\n" ^
      "		keptItem = 1;\n" ^
      "		QUEST_COMPLETE(myCode);\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnCompleteAction				\n" ^
      "--		(do this whenever the player completes his action)\n" ^
      "--		It is called after the game has returned to the map screen\n" ^
      "--\n" ^
      "local function OnCompleteAction(idLocation, success)\n" ^
      "\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnLoad				\n" ^
      "--		(a save game is being loaded)\n" ^
      "--\n" ^
      "local function OnLoad()\n" ^
      "	questState = QUEST_LOAD_INT();\n" ^
      "	keptItem  = QUEST_LOAD_INT();\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnSave				\n" ^
      "--		(a save game is being saved)\n" ^
      "--\n" ^
      "local function OnSave()\n" ^
      "	QUEST_SAVE_INT(questState);\n" ^
      "	QUEST_SAVE_INT(keptItem);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryProgress		\n" ^
      "--		(returns text describing the next step required)\n" ^
      "--\n" ^
      "local function OnQueryProgress()\n" ^
      "	if (questState < 8) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q1S4_STEP1]\");\n" ^
      "	elseif (questState == 8) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q1S4_STEP2]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryPercentage	\n" ^
      "--		(returns a percentage of completion)\n" ^
      "--\n" ^
      "local function OnQueryPercentage()\n" ^
      "	return (questState-1) * 12;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryDifficulty	\n" ^
      "--		(returns 0-4 for difficulty - v.easy to v.difficult )\n" ^
      "--\n" ^
      "local function OnQueryDifficulty()\n" ^
      "	-- average\n" ^
      "	return 1; \n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- CallbackConvA 	\n" ^
      "--		Callback for a conversation\n" ^
      "--\n" ^
      "local function CallbackConvA()\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q1S4_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[QUEST_Q1S4_SUCCESS]\");\n" ^
      "	QUEST_MESSAGE(myTitle ,myMessage ,myLocation7 );\n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "--	\n" ^
      "--		DECLARE TABLE	\n" ^
      "--\n" ^
      "\n" ^
      "Q1S4 = {\n" ^
      "	OnInit				= OnInit,\n" ^
      "	OnBegin				= OnBegin,\n" ^
      "	OnEnd				= OnEnd,\n" ^
      "	OnAbandon			= OnAbandon,\n" ^
      "	OnEnterLocation		= OnEnterLocation,\n" ^
      "	OnExecuteAction		= OnExecuteAction,\n" ^
      "	OnCompleteAction	= OnCompleteAction,\n" ^
      "	OnQueryAction		= OnQueryAction,\n" ^
      "	OnLoad				= OnLoad,\n" ^
      "	OnSave				= OnSave,\n" ^
      "	OnQueryProgress		= OnQueryProgress,\n" ^
      "	OnQueryPercentage	= OnQueryPercentage,\n" ^
      "	OnQueryDifficulty	= OnQueryDifficulty,\n" ^
      "\n" ^
      "	CallbackConvA = CallbackConvA ,\n" ^
      "};\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n";
    abandonable = true;
    icon = 2;
    important = false;
    avail_location = "CGRU";
    avail_minlevel = 12;
    avail_maxlevel = 1000;
    avail_repeat = 1;
