    texts = [("[QUEST_Q2G0_ACTION]", "Fight the Stranger"); ("[QUEST_Q2G0_FAILURE]", "You have failed to defeat the stranger. You must try again."); ("[QUEST_Q2G0_KILL]", "You have defeated the stranger.  You should return to the Gnoll in Hyaan."); ("[QUEST_Q2G0_RETURN]", "Return to the Gnoll"); ("[QUEST_Q2G0_REWARD]", "The Gnoll rewards you with an unusual amount of Gold."); ("[QUEST_Q2G0_STEP1]", "You must locate the strange man at The Pike and chase him away."); ("[QUEST_Q2G0_STEP2]", "You must return to the Gnoll at Hyaan for your reward."); ("[QUEST_Q2G0_QMNAME0]", "Assassin")];
    lua_file = "Assets\\Quests\\Q2G0.lua";
    lua_object = "Q2G0";
    lua_source = "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--             Gnoll in a Hole	\n" ^
      "--	\n" ^
      "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--		STATES	\n" ^
      "--\n" ^
      "-- 0 => Inactive\n" ^
      "-- 1 => Quest obtained, nothing done yet\n" ^
      "-- 2 => Monster defeated, must return\n" ^
      "-- 3 => Finished\n" ^
      "-- \n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Variables\n" ^
      "--\n" ^
      "local questState = 0;\n" ^
      "local doneSerephine = 0;\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Constants\n" ^
      "--\n" ^
      "local myCode        = \"Q2G0\";\n" ^
      "local myLocation    = \"WPIK\";\n" ^
      "local myOrigin      = \"CHYA\";\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnInit				\n" ^
      "--		(called for every quest when they are loading\n" ^
      "--		 to set the initial state of all variables)\n" ^
      "--\n" ^
      "local function OnInit()\n" ^
      "	questState = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnBegin				\n" ^
      "--		(called when a quest is first obtained)\n" ^
      "--\n" ^
      "local function OnBegin()\n" ^
      "	questState = 1;\n" ^
      "	QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q2G0a.xml\",myOrigin);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnd				\n" ^
      "--		(called when a quest has ended)\n" ^
      "--\n" ^
      "local function OnEnd()\n" ^
      "	questState = 3;\n" ^
      "	\n" ^
      "	-- Reward\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q2G0_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[QUEST_Q2G0_REWARD]\");\n" ^
      "	QUEST_REWARD_MENU(myTitle,myMessage);\n" ^
      "	QUEST_REWARD_GOLD(1000);\n" ^
      "	QUEST_REWARD_XP(100);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnAbandon				\n" ^
      "--		(called when a quest has been abandoned by the player)\n" ^
      "--\n" ^
      "local function OnAbandon()\n" ^
      "	questState = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnterLocation		\n" ^
      "--		(a hero has arrived at a new location)\n" ^
      "--\n" ^
      "local function OnEnterLocation(idLocation)\n" ^
      "	if (idLocation == myLocation and\n" ^
      "		QUEST_HERO_HAS_COMPANION_SELECTED(\"NSER\")==1 and\n" ^
      "		doneSerephine == 0) then\n" ^
      "			QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q2G0b.xml\",idLocation);\n" ^
      "			QUEST_STOP_MOVEMENT();\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryAction\n" ^
      "--		(should anything appear on the popup menu)\n" ^
      "--\n" ^
      "local function OnQueryAction(idLocation)\n" ^
      "	if (idLocation==myLocation and questState==1) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q2G0_ACTION]\");\n" ^
      "	elseif (idLocation==myOrigin and questState==2) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q2G0_RETURN]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnExecuteAction				\n" ^
      "--		(do this whenever the player executes the next action)\n" ^
      "--\n" ^
      "local function OnExecuteAction(idLocation)\n" ^
      "	if (questState==1) then\n" ^
      "		QUEST_BATTLE(myCode,0,1);\n" ^
      "	elseif (questState==2) then\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q2G0c.xml\",idLocation);\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnCompleteAction				\n" ^
      "--		(do this whenever the player completes his action)\n" ^
      "--		It is called after the game has returned to the map screen\n" ^
      "--\n" ^
      "local function OnCompleteAction(idLocation, success)\n" ^
      "\n" ^
      "	if (questState==1) then\n" ^
      "	\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_Q2G0_NAME]\");\n" ^
      "		local myMessage;\n" ^
      "		if (success == 1) then\n" ^
      "	  		questState = 2;\n" ^
      "			QUEST_SET_RUIN_DONE(myLocation);\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_Q2G0_KILL]\");\n" ^
      "		else\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_Q2G0_FAILURE]\");\n" ^
      "		end\n" ^
      "		QUEST_MESSAGE(myTitle,myMessage,myLocation);\n" ^
      "		QUEST_UPDATE_MAP();\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnLoad				\n" ^
      "--		(a save game is being loaded)\n" ^
      "--\n" ^
      "local function OnLoad()\n" ^
      "	questState = QUEST_LOAD_INT();\n" ^
      "	doneSerephine = QUEST_LOAD_INT();\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnSave				\n" ^
      "--		(a save game is being saved)\n" ^
      "--\n" ^
      "local function OnSave()\n" ^
      "	QUEST_SAVE_INT(questState);\n" ^
      "	QUEST_SAVE_INT(doneSerephine);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryProgress		\n" ^
      "--		(returns text describing the next step required)\n" ^
      "--\n" ^
      "local function OnQueryProgress()\n" ^
      "	if (questState == 1) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q2G0_STEP1]\");\n" ^
      "	elseif (questState == 2) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q2G0_STEP2]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryPercentage	\n" ^
      "--		(returns a percentage of completion)\n" ^
      "--\n" ^
      "local function OnQueryPercentage()\n" ^
      "	if (questState <= 1) then\n" ^
      "		return 0;\n" ^
      "	elseif (questState == 2) then\n" ^
      "		return 50;\n" ^
      "	end\n" ^
      "	return 100;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryDifficulty	\n" ^
      "--		(returns 0-4 for difficulty - v.easy to v.difficult )\n" ^
      "--\n" ^
      "local function OnQueryDifficulty()\n" ^
      "	-- average\n" ^
      "	return 2; \n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "\n" ^
      "local function CallbackConvA ()\n" ^
      "	questState = 1;\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackConvB ()\n" ^
      "	doneSerephine = 1;\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackConvC ()\n" ^
      "	QUEST_COMPLETE(myCode);\n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "--	\n" ^
      "--		DECLARE TABLE	\n" ^
      "--\n" ^
      "\n" ^
      "Q2G0 = {\n" ^
      "	OnInit				= OnInit,\n" ^
      "	OnBegin				= OnBegin,\n" ^
      "	OnEnd				= OnEnd,\n" ^
      "	OnAbandon			= OnAbandon,\n" ^
      "	OnEnterLocation		= OnEnterLocation,\n" ^
      "	OnExecuteAction		= OnExecuteAction,\n" ^
      "	OnCompleteAction	= OnCompleteAction,\n" ^
      "	OnQueryAction		= OnQueryAction,\n" ^
      "	OnLoad				= OnLoad,\n" ^
      "	OnSave				= OnSave,\n" ^
      "	OnQueryProgress		= OnQueryProgress,\n" ^
      "	OnQueryPercentage	= OnQueryPercentage,\n" ^
      "	OnQueryDifficulty	= OnQueryDifficulty,\n" ^
      "	\n" ^
      "	CallbackConvA = CallbackConvA ,\n" ^
      "	CallbackConvB = CallbackConvB ,\n" ^
      "	CallbackConvC = CallbackConvC ,\n" ^
      "};\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n";
