    lua_source = "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--             Gnoll Hunters	\n" ^
      "--	\n" ^
      "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--		STATES	\n" ^
      "--\n" ^
      "-- 0 => Inactive\n" ^
      "-- 1 => Quest obtained, nothing done yet\n" ^
      "-- 2 => Monster defeated, must return\n" ^
      "-- 3 => Finished\n" ^
      "-- \n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Variables\n" ^
      "--\n" ^
      "local questState = 0;\n" ^
      "local doneTusk = 0;\n" ^
      "local doneAlfland = 0;\n" ^
      "local doneDhunKor = 0;\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Constants\n" ^
      "--\n" ^
      "local myCode        = \"Q2G1\";\n" ^
      "local myLocation1    = \"CTSK\";\n" ^
      "local myLocation2    = \"WALF\";\n" ^
      "local myLocation3    = \"CDKO\";\n" ^
      "local myOrigin      = \"CHYA\";\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnInit				\n" ^
      "--		(called for every quest when they are loading\n" ^
      "--		 to set the initial state of all variables)\n" ^
      "--\n" ^
      "local function OnInit()\n" ^
      "	questState = 0;\n" ^
      "	doneTusk = 0;\n" ^
      "	doneAlfland = 0;\n" ^
      "	doneDhunKor = 0;\n" ^
      "\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnBegin				\n" ^
      "--		(called when a quest is first obtained)\n" ^
      "--\n" ^
      "local function OnBegin()\n" ^
      "	questState = 1;\n" ^
      "	QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q2G1a.xml\",myOrigin);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnd				\n" ^
      "--		(called when a quest has ended)\n" ^
      "--\n" ^
      "local function OnEnd()\n" ^
      "	questState = 3;\n" ^
      "	\n" ^
      "	-- Reward\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q2G1_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[QUEST_Q2G1_REWARD]\");\n" ^
      "	QUEST_REWARD_MENU(myTitle,myMessage);\n" ^
      "	QUEST_REWARD_GOLD(1000);\n" ^
      "	QUEST_REWARD_XP(100);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnAbandon				\n" ^
      "--		(called when a quest has been abandoned by the player)\n" ^
      "--\n" ^
      "local function OnAbandon()\n" ^
      "	questState = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnterLocation		\n" ^
      "--		(a hero has arrived at a new location)\n" ^
      "--\n" ^
      "local function OnEnterLocation(idLocation)\n" ^
      "	if (idLocation == myLocation1 and doneTusk == 0) then\n" ^
      "		QUEST_MESSAGE(GET_TEXT(\"[QUEST_Q2G1_NAME]\"),\n" ^
      "				  GET_TEXT(\"[QUEST_Q2G1_MSG]\"),\n" ^
      "				  idLocation);\n" ^
      "\n" ^
      "	elseif (idLocation == myLocation2 and doneAlfland == 0) then\n" ^
      "		QUEST_MESSAGE(GET_TEXT(\"[QUEST_Q2G1_NAME]\"),\n" ^
      "				  GET_TEXT(\"[QUEST_Q2G1_MSG]\"),\n" ^
      "				  idLocation);\n" ^
      "\n" ^
      "	elseif (idLocation == myLocation3 and doneDhunKor == 0) then\n" ^
      "		QUEST_MESSAGE(GET_TEXT(\"[QUEST_Q2G1_NAME]\"),\n" ^
      "				  GET_TEXT(\"[QUEST_Q2G1_MSG]\"),\n" ^
      "				  idLocation);\n" ^
      "\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryAction\n" ^
      "--		(should anything appear on the popup menu)\n" ^
      "--\n" ^
      "local function OnQueryAction(idLocation)\n" ^
      "	if (idLocation==myLocation1 and questState==1 and doneTusk==0) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q2G1_ACTION]\");\n" ^
      "	elseif (idLocation==myLocation2 and questState==1 and doneAlfland==0) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q2G1_ACTION]\");\n" ^
      "	elseif (idLocation==myLocation3 and questState==1 and doneDhunKor==0) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q2G1_ACTION]\");\n" ^
      "	elseif (idLocation==myOrigin and questState==2) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q2G1_RETURN]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnExecuteAction				\n" ^
      "--		(do this whenever the player executes the next action)\n" ^
      "--\n" ^
      "local function OnExecuteAction(idLocation)\n" ^
      "	if (questState==1) then\n" ^
      "		QUEST_BATTLE(myCode,0,1);\n" ^
      "	elseif (questState==2) then\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q2G1b.xml\",idLocation);\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnCompleteAction				\n" ^
      "--		(do this whenever the player completes his action)\n" ^
      "--		It is called after the game has returned to the map screen\n" ^
      "--\n" ^
      "local function OnCompleteAction(idLocation, success)\n" ^
      "\n" ^
      "	if (questState==1) then\n" ^
      "	\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_Q2G1_NAME]\");\n" ^
      "		local myMessage;\n" ^
      "		if (success == 1) then\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_Q2G1_KILL]\");\n" ^
      "			if (idLocation == myLocation1) then\n" ^
      "				doneTusk = 1;\n" ^
      "			elseif (idLocation == myLocation2) then\n" ^
      "				doneAlfland = 1;\n" ^
      "			elseif (idLocation == myLocation3) then\n" ^
      "				doneDhunKor = 1;\n" ^
      "			end\n" ^
      "			if (doneTusk ==1 and doneAlfland ==1 and doneDhunKor ==1) then\n" ^
      "	  			questState = 2;\n" ^
      "			end\n" ^
      "		else\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_Q2G1_FAILURE]\");\n" ^
      "		end\n" ^
      "		QUEST_MESSAGE(myTitle,myMessage,idLocation);\n" ^
      "		QUEST_UPDATE_MAP();\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnLoad				\n" ^
      "--		(a save game is being loaded)\n" ^
      "--\n" ^
      "local function OnLoad()\n" ^
      "	questState = QUEST_LOAD_INT();\n" ^
      "	doneTusk = QUEST_LOAD_INT();\n" ^
      "	doneAlfland = QUEST_LOAD_INT();\n" ^
      "	doneDhunKor = QUEST_LOAD_INT();\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnSave				\n" ^
      "--		(a save game is being saved)\n" ^
      "--\n" ^
      "local function OnSave()\n" ^
      "	QUEST_SAVE_INT(questState);\n" ^
      "	QUEST_SAVE_INT(doneTusk );\n" ^
      "	QUEST_SAVE_INT(doneAlfland );\n" ^
      "	QUEST_SAVE_INT(doneDhunKor );\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryProgress		\n" ^
      "--		(returns text describing the next step required)\n" ^
      "--\n" ^
      "local function OnQueryProgress()\n" ^
      "	if (questState == 1) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q2G1_STEP1]\");\n" ^
      "	elseif (questState == 2) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q2G1_STEP2]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryPercentage	\n" ^
      "--		(returns a percentage of completion)\n" ^
      "--\n" ^
      "local function OnQueryPercentage()\n" ^
      "	if (questState <= 1) then\n" ^
      "		return doneTusk*25 + doneAlfland*25 + doneDhunKor*25;\n" ^
      "	elseif (questState == 2) then\n" ^
      "		return 75;\n" ^
      "	end\n" ^
      "	return 100;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryDifficulty	\n" ^
      "--		(returns 0-4 for difficulty - v.easy to v.difficult )\n" ^
      "--\n" ^
      "local function OnQueryDifficulty()\n" ^
      "	-- average\n" ^
      "	return 2; \n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "\n" ^
      "local function CallbackConvA ()\n" ^
      "	questState = 1;\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackConvB ()\n" ^
      "	QUEST_COMPLETE(myCode);\n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
