  {
    id = "Q2I5";
    name_text = "[QUEST_Q2I5_NAME]";
    desc_text = "[QUEST_Q2I5_DESC]";
    group = "";
    text_file = "English\\Quests\\Q2I5_Text.xml";
    texts = [("[QUEST_Q2I5_ACTION1]", "Deliver Jarl's Invitation"); ("[QUEST_Q2I5_ACTION2]", "Deliver Jotun's Invitation"); ("[QUEST_Q2I5_KILL1]", "You have successfully delivered Jarl's invitation. You still need to deliver Jotun's."); ("[QUEST_Q2I5_KILL2]", "You have successfully delivered Jotun's invititation. You still need to deliver Jarl's."); ("[QUEST_Q2I5_KILL3]", "You have successfully delivered the invitations. Return to the City of Tusk for your reward."); ("[QUEST_Q2I5_RETURN]", "Recieve your delivery fee"); ("[QUEST_Q2I5_REWARD]", "You are rewarded well for your services."); ("[QUEST_Q2I5_STEP0]", "You must deliver both invitations to Jarl and Jotun."); ("[QUEST_Q2I5_STEP1]", "You have delivered Jarl's invitation. You must now deliver Jotun's."); ("[QUEST_Q2I5_STEP2]", "You have delivered Jotun's invitation. You must now deliver Jarl's."); ("[QUEST_Q2I5_STEP3]", "You have delivered both invitations. You must now return to the City of Tusk to collect your delivery fee.")];
    lua_file = "Assets\\Quests\\Q2I5.lua";
    lua_object = "Q2I5";
    lua_source = "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--             The Invitation	\n" ^
      "--	\n" ^
      "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--		STATES	\n" ^
      "--\n" ^
      "-- 0 => Inactive\n" ^
      "-- 1 => Quest obtained, nothing done yet\n" ^
      "-- 2 => Jarl's invitation delivered.\n" ^
      "-- 3 => Jotus's invitation delivered.\n" ^
      "-- 4 => both delivered\n" ^
      "-- \n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Variables\n" ^
      "--\n" ^
      "local questState = 0;\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Constants\n" ^
      "--\n" ^
      "local myCode     = \"Q2I5\";\n" ^
      "local myLocation1 = \"CJAK\";\n" ^
      "local myLocation2 = \"CJOK\";\n" ^
      "local giantsWalk  = \"WGWK\";\n" ^
      "local blackHoof   = \"WSHD\";\n" ^
      "local myOrigin   = \"CTSK\";\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnInit				\n" ^
      "--		(called for every quest when they are loading\n" ^
      "--		 to set the initial state of all variables)\n" ^
      "--\n" ^
      "local function OnInit()\n" ^
      "	questState = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnBegin				\n" ^
      "--		(called when a quest is first obtained)\n" ^
      "--\n" ^
      "local function OnBegin()\n" ^
      "	questState = 1;\n" ^
      "	QUEST_SET_VISIBILITY(blackHoof,1);\n" ^
      "	QUEST_SET_VISIBILITY(giantsWalk,1);\n" ^
      "	QUEST_SET_VISIBILITY(myLocation1,1);\n" ^
      "	QUEST_SET_VISIBILITY(myLocation2,1);\n" ^
      "	Std_AddEncounter(giantsWalk,myLocation1,\"EFGI\");\n" ^
      "	Std_AddEncounter(giantsWalk,myLocation2,\"EVGI\");\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnd				\n" ^
      "--		(called when a quest has ended)\n" ^
      "--\n" ^
      "local function OnEnd()\n" ^
      "	questState = 5;\n" ^
      "	\n" ^
      "	-- Reward\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q2I5_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[QUEST_Q2I5_REWARD]\");\n" ^
      "	QUEST_REWARD_MENU(myTitle,myMessage);\n" ^
      "	QUEST_REWARD_GOLD(200);\n" ^
      "	QUEST_REWARD_XP(200);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnAbandon				\n" ^
      "--		(called when a quest has been abandoned by the player)\n" ^
      "--\n" ^
      "local function OnAbandon()\n" ^
      "	questState = 0;  -- it can be restarted\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnterLocation		\n" ^
      "--		(a hero has arrived at a new location)\n" ^
      "--\n" ^
      "local function OnEnterLocation(idLocation)\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryAction\n" ^
      "--		(should anything appear on the popup menu)\n" ^
      "--\n" ^
      "local function OnQueryAction(idLocation)\n" ^
      "	if (idLocation == myLocation1 and questState~=2 and questState<4) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q2I5_ACTION1]\");\n" ^
      "	elseif (idLocation == myLocation2 and questState <3) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q2I5_ACTION2]\");\n" ^
      "	elseif (idLocation==myOrigin and questState==4) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q2I5_RETURN]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnExecuteAction				\n" ^
      "--		(do this whenever the player executes the next action)\n" ^
      "--\n" ^
      "local function OnExecuteAction(idLocation)\n" ^
      "	if (questState==1) then\n" ^
      "		if (idLocation == myLocation1) then\n" ^
      "			questState = 2;\n" ^
      "		elseif (idLocation == myLocation2) then\n" ^
      "			questState = 3;\n" ^
      "		end\n" ^
      "\n" ^
      "		QUEST_COMPLETE_PART(myCode,idLocation,1);\n" ^
      "		\n" ^
      "	\n" ^
      "	elseif (questState==4) then\n" ^
      "		QUEST_COMPLETE(myCode);\n" ^
      "	elseif (questState >1) then\n" ^
      "		questState = 4;\n" ^
      "		QUEST_COMPLETE_PART(myCode,idLocation,1);\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnCompleteAction				\n" ^
      "--		(do this whenever the player completes his action)\n" ^
      "--		It is called after the game has returned to the map screen\n" ^
      "--\n" ^
      "local function OnCompleteAction(idLocation, success)\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q2I5_NAME]\");\n" ^
      "	local myMessage;\n" ^
      "	\n" ^
      "	if (questState==2) then\n" ^
      "		--if still one delivery to go\n" ^
      "		myMessage = GET_TEXT(\"[QUEST_Q2I5_KILL1]\");\n" ^
      "	elseif(questState==3) then\n" ^
      "		--display midway progress message.\n" ^
      "		myMessage = GET_TEXT(\"[QUEST_Q2I5_KILL2]\");\n" ^
      "	else\n" ^
      "		--display quest complete messsage.\n" ^
      "		myMessage = GET_TEXT(\"[QUEST_Q2I5_KILL3]\");\n" ^
      "	end\n" ^
      "	QUEST_MESSAGE(myTitle,myMessage,idLocation);\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "		\n" ^
      "	\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnLoad				\n" ^
      "--		(a save game is being loaded)\n" ^
      "--\n" ^
      "local function OnLoad()\n" ^
      "	questState = QUEST_LOAD_INT();\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnSave				\n" ^
      "--		(a save game is being saved)\n" ^
      "--\n" ^
      "local function OnSave()\n" ^
      "	QUEST_SAVE_INT(questState);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryProgress		\n" ^
      "--		(returns text describing the next step required)\n" ^
      "--\n" ^
      "local function OnQueryProgress()\n" ^
      "	if (questState == 1) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q2I5_STEP0]\");\n" ^
      "	elseif(questState == 2) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q2I5_STEP1]\");\n" ^
      "	elseif(questState == 3) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q2I5_STEP2]\");\n" ^
      "	elseif(questState ==4) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q2I5_STEP3]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryPercentage	\n" ^
      "--		(returns a percentage of completion)\n" ^
      "--\n" ^
      "local function OnQueryPercentage()\n" ^
      "	if (questState ==1) then\n" ^
      "		return 0;\n" ^
      "	elseif(questState < 4) then\n" ^
      "		return 33;		\n" ^
      "	elseif (questState == 4) then\n" ^
      "		return 66;\n" ^
      "	end\n" ^
      "	return 100;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryDifficulty	\n" ^
      "--		(returns 0-4 for difficulty - v.easy to v.difficult )\n" ^
      "--\n" ^
      "local function OnQueryDifficulty()\n" ^
      "	-- average\n" ^
      "	return 2; \n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "--	\n" ^
      "--		DECLARE TABLE	\n" ^
      "--\n" ^
      "\n" ^
      "Q2I5 = {\n" ^
      "	OnInit				= OnInit,\n" ^
      "	OnBegin				= OnBegin,\n" ^
      "	OnEnd				= OnEnd,\n" ^
      "	OnAbandon			= OnAbandon,\n" ^
      "	OnEnterLocation		= OnEnterLocation,\n" ^
