    texts = [("[QUEST_Q2I6_ACTION]", "Search for an Eye"); ("[QUEST_Q2I6_FAILURE]", "You have failed to defeat the Dragon Spider. You must try again if you want that eye."); ("[QUEST_Q2I6_KILL]", "You have defeated the Dragon Spider.  The Eye is all yours."); ("[QUEST_Q2I6_RETURN]", "Deliver the Eye"); ("[QUEST_Q2I6_REWARD]", "You have eased your conscience."); ("[QUEST_Q2I6_STEP1]", "You must go to the Dragons' Graveyard and get a Dragon's Eye."); ("[QUEST_Q2I6_STEP2]", "You must now take the Dragon's Eye to Silvermyr.")];
    lua_file = "Assets\\Quests\\Q2I6.lua";
    lua_object = "Q2I6";
    lua_source = "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--             Fresh Eyes	\n" ^
      "--	\n" ^
      "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--		STATES	\n" ^
      "--\n" ^
      "-- 0 => Inactive\n" ^
      "-- 1 => Quest obtained, nothing done yet\n" ^
      "-- 2 => Monster defeated, must return\n" ^
      "-- 3 => Finished\n" ^
      "-- \n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Variables\n" ^
      "--\n" ^
      "local questState = 0;\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Constants\n" ^
      "--\n" ^
      "local myCode        = \"Q2I6\";\n" ^
      "local myLocation    = \"RDGV\";\n" ^
      "local myDestination = \"CSIL\";\n" ^
      "local myOrigin      = \"CHTP\";\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnInit				\n" ^
      "--		(called for every quest when they are loading\n" ^
      "--		 to set the initial state of all variables)\n" ^
      "--\n" ^
      "local function OnInit()\n" ^
      "	questState = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnBegin				\n" ^
      "--		(called when a quest is first obtained)\n" ^
      "--\n" ^
      "local function OnBegin()\n" ^
      "	questState = 1;\n" ^
      "	QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q2I6a.xml\",myOrigin);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnd				\n" ^
      "--		(called when a quest has ended)\n" ^
      "--\n" ^
      "local function OnEnd()\n" ^
      "	questState = 3;\n" ^
      "	\n" ^
      "	-- Reward\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q2I6_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[QUEST_Q2I6_REWARD]\");\n" ^
      "	QUEST_REWARD_MENU(myTitle,myMessage);\n" ^
      "	QUEST_REWARD_XP(260);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnAbandon				\n" ^
      "--		(called when a quest has been abandoned by the player)\n" ^
      "--\n" ^
      "local function OnAbandon()\n" ^
      "	questState = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnterLocation		\n" ^
      "--		(a hero has arrived at a new location)\n" ^
      "--\n" ^
      "local function OnEnterLocation(idLocation)\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryAction\n" ^
      "--		(should anything appear on the popup menu)\n" ^
      "--\n" ^
      "local function OnQueryAction(idLocation)\n" ^
      "	if (idLocation==myLocation and questState==1) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q2I6_ACTION]\");\n" ^
      "	elseif (idLocation==myDestination and questState==2) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q2I6_RETURN]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnExecuteAction				\n" ^
      "--		(do this whenever the player executes the next action)\n" ^
      "--\n" ^
      "local function OnExecuteAction(idLocation)\n" ^
      "	if (questState==1) then\n" ^
      "		QUEST_BATTLE(myCode,0,1);\n" ^
      "	elseif (questState==2) then\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q2I6b.xml\",idLocation);\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnCompleteAction				\n" ^
      "--		(do this whenever the player completes his action)\n" ^
      "--		It is called after the game has returned to the map screen\n" ^
      "--\n" ^
      "local function OnCompleteAction(idLocation, success)\n" ^
      "\n" ^
      "	if (questState==1) then\n" ^
      "	\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_Q2I6_NAME]\");\n" ^
      "		local myMessage;\n" ^
      "		if (success == 1) then\n" ^
      "	  		questState = 2;\n" ^
      "			QUEST_SET_RUIN_DONE(myLocation);\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_Q2I6_KILL]\");\n" ^
      "		else\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_Q2I6_FAILURE]\");\n" ^
      "		end\n" ^
      "		QUEST_MESSAGE(myTitle,myMessage,myLocation);\n" ^
      "		QUEST_UPDATE_MAP();\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnLoad				\n" ^
      "--		(a save game is being loaded)\n" ^
      "--\n" ^
      "local function OnLoad()\n" ^
      "	questState = QUEST_LOAD_INT();\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnSave				\n" ^
      "--		(a save game is being saved)\n" ^
      "--\n" ^
      "local function OnSave()\n" ^
      "	QUEST_SAVE_INT(questState);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryProgress		\n" ^
      "--		(returns text describing the next step required)\n" ^
      "--\n" ^
      "local function OnQueryProgress()\n" ^
      "	if (questState == 1) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q2I6_STEP1]\");\n" ^
      "	elseif (questState == 2) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q2I6_STEP2]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryPercentage	\n" ^
      "--		(returns a percentage of completion)\n" ^
      "--\n" ^
      "local function OnQueryPercentage()\n" ^
      "	if (questState <= 1) then\n" ^
      "		return 0;\n" ^
      "	elseif (questState == 2) then\n" ^
      "		return 50;\n" ^
      "	end\n" ^
      "	return 100;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryDifficulty	\n" ^
      "--		(returns 0-4 for difficulty - v.easy to v.difficult )\n" ^
      "--\n" ^
      "local function OnQueryDifficulty()\n" ^
      "	-- average\n" ^
      "	return 2; \n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "\n" ^
      "local function CallbackConvA ()\n" ^
      "	questState = 1;\n" ^
      "	QUEST_ADD_RUIN(myLocation);\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackConvB ()\n" ^
      "	QUEST_COMPLETE(myCode);\n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "--	\n" ^
      "--		DECLARE TABLE	\n" ^
      "--\n" ^
      "\n" ^
      "Q2I6 = {\n" ^
      "	OnInit				= OnInit,\n" ^
      "	OnBegin				= OnBegin,\n" ^
      "	OnEnd				= OnEnd,\n" ^
      "	OnAbandon			= OnAbandon,\n" ^
      "	OnEnterLocation		= OnEnterLocation,\n" ^
      "	OnExecuteAction		= OnExecuteAction,\n" ^
      "	OnCompleteAction	= OnCompleteAction,\n" ^
      "	OnQueryAction	= OnQueryAction,\n" ^
      "	OnLoad				= OnLoad,\n" ^
      "	OnSave				= OnSave,\n" ^
      "	OnQueryProgress		= OnQueryProgress,\n" ^
      "	OnQueryPercentage	= OnQueryPercentage,\n" ^
      "	OnQueryDifficulty	= OnQueryDifficulty,\n" ^
      "	\n" ^
      "	CallbackConvA = CallbackConvA ,\n" ^
      "	CallbackConvB = CallbackConvB ,\n" ^
      "};\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n";
