  {
    id = "Q2J4";
    name_text = "[QUEST_Q2J4_NAME]";
    desc_text = "[QUEST_Q2J4_DESC]";
    group = "[QG_JAJO_NAME]";
    text_file = "English\\Quests\\Q2J4_Text.xml";
    texts = [("[QUEST_Q2J4_ACTION1]", "Battle the Medusa"); ("[QUEST_Q2J4_ACTION2]", "Shop for Griffonskin"); ("[QUEST_Q2J4_FAILURE]", "You have failed to defeat the Medusa. You must try again."); ("[QUEST_Q2J4_KILL]", "You have defeated the Medusa.  You retrieve some blood with which to sign the documents."); ("[QUEST_Q2J4_R0]", "Jarl's Hammer and Cloak"); ("[QUEST_Q2J4_R1]", "Jotun's Helm and Boots"); ("[QUEST_Q2J4_RETURN]", "Talk to the Giants"); ("[QUEST_Q2J4_REWARD]", "You have succeeded!  Jarl and Jotun give you all the items they no longer want."); ("[QUEST_Q2J4_STEP1]", "You must approach Jarl and Jotun and see if they can reach a truce."); ("[QUEST_Q2J4_STEP2]", "You must travel to Werret to find a Medusa and to Gruuldok to get some Griffonskin."); ("[QUEST_Q2J4_STEP3]", "You must return to the Giants' Walk to meet with Jarl and Jotun."); ("[QUEST_Q2J4_TALK1]", "Talk to Jarl"); ("[QUEST_Q2J4_TALK2]", "Talk to Jotun")];
    lua_file = "Assets\\Quests\\Q2J4.lua";
    lua_object = "Q2J4";
    lua_source = "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--             Brotherly Love	\n" ^
      "--	\n" ^
      "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--		STATES	\n" ^
      "--\n" ^
      "-- 0 => Inactive\n" ^
      "-- 1 => Quest obtained, nothing done yet\n" ^
      "-- 2 => Giants agree, must get items\n" ^
      "-- 3 => Monster defeated, & items obtained must return\n" ^
      "-- 4 => Finished\n" ^
      "-- \n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Variables\n" ^
      "--\n" ^
      "local questState = 0;\n" ^
      "local gotBlood = 0;\n" ^
      "local gotParchment = 0;\n" ^
      "local gotJarl = 0;\n" ^
      "local gotJotun = 0;\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Constants\n" ^
      "--\n" ^
      "local myCode        = \"Q2J4\";\n" ^
      "local myLocation1   = \"WWRT\";\n" ^
      "local myLocation2   = \"CGRU\";\n" ^
      "local myOrigin1     = \"CJAK\";\n" ^
      "local myOrigin2     = \"CJOK\";\n" ^
      "local myDestination = \"WGWK\";\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnInit				\n" ^
      "--		(called for every quest when they are loading\n" ^
      "--		 to set the initial state of all variables)\n" ^
      "--\n" ^
      "local function OnInit()\n" ^
      "	questState = 0;\n" ^
      "	gotBlood = 0;\n" ^
      "	gotParchment = 0;\n" ^
      "	gotJarl = 0;\n" ^
      "	gotJotun = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnBegin				\n" ^
      "--		(called when a quest is first obtained)\n" ^
      "--\n" ^
      "local function OnBegin()\n" ^
      "	questState = 1;\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnd				\n" ^
      "--		(called when a quest has ended)\n" ^
      "--\n" ^
      "local function OnEnd()\n" ^
      "	questState = 4;\n" ^
      "	\n" ^
      "	-- Reward\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q2J4_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[QUEST_Q2J4_REWARD]\");\n" ^
      "	QUEST_REWARD_MENU(myTitle,myMessage);\n" ^
      "	QUEST_REWARD_ITEM_WITH_TEXT(\"IJAH\",GET_TEXT(\"[QUEST_Q2J4_R0]\"));\n" ^
      "	QUEST_REWARD_ITEM_WITH_TEXT(\"IJOH\",GET_TEXT(\"[QUEST_Q2J4_R1]\"));\n" ^
      "	\n" ^
      "	QUEST_ADD_ITEM(\"IJAC\");\n" ^
      "	QUEST_ADD_ITEM(\"IJOB\");\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnAbandon				\n" ^
      "--		(called when a quest has been abandoned by the player)\n" ^
      "--\n" ^
      "local function OnAbandon()\n" ^
      "	questState = 0;\n" ^
      "	gotBlood = 0;\n" ^
      "	gotParchment = 0;\n" ^
      "	gotJarl = 0;\n" ^
      "	gotJotun = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnterLocation		\n" ^
      "--		(a hero has arrived at a new location)\n" ^
      "--\n" ^
      "local function OnEnterLocation(idLocation)\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryAction\n" ^
      "--		(should anything appear on the popup menu)\n" ^
      "--\n" ^
      "local function OnQueryAction(idLocation)\n" ^
      "	if (idLocation==myOrigin1 and questState==1 and gotJarl==0) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q2J4_TALK1]\");\n" ^
      "	elseif (idLocation==myOrigin2 and questState==1 and gotJotun==0) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q2J4_TALK2]\");\n" ^
      "	elseif (idLocation==myLocation1 and questState==2 and gotBlood==0) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q2J4_ACTION1]\");\n" ^
      "	elseif (idLocation==myLocation2 and questState==2 and gotParchment==0) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q2J4_ACTION2]\");\n" ^
      "	elseif (idLocation==myDestination and questState==3) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q2J4_RETURN]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnExecuteAction				\n" ^
      "--		(do this whenever the player executes the next action)\n" ^
      "--\n" ^
      "local function OnExecuteAction(idLocation)\n" ^
      "	if (idLocation==myOrigin1 and questState==1 and gotJarl==0) then\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q2J4a.xml\",idLocation);\n" ^
      "	elseif (idLocation==myOrigin2 and questState==1 and gotJotun==0) then\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q2J4b.xml\",idLocation);\n" ^
      "	elseif (idLocation==myLocation1 and questState==2 and gotBlood==0) then\n" ^
      "		QUEST_BATTLE(myCode,0,1);\n" ^
      "	elseif (idLocation==myLocation2 and questState==2 and gotParchment==0 and QUEST_GET_GOLD()<100) then\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q2J4cc.xml\",idLocation);\n" ^
      "	elseif (idLocation==myLocation2 and questState==2 and gotParchment==0) then\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q2J4c.xml\",idLocation);\n" ^
      "	elseif (idLocation==myDestination and questState==3) then\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q2J4d.xml\",idLocation);\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnCompleteAction				\n" ^
      "--		(do this whenever the player completes his action)\n" ^
      "--		It is called after the game has returned to the map screen\n" ^
      "--\n" ^
      "local function OnCompleteAction(idLocation, success)\n" ^
      "\n" ^
      "	if (questState==2) then\n" ^
      "	\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_Q2J4_NAME]\");\n" ^
      "		local myMessage;\n" ^
      "		if (success == 1) then\n" ^
      "			gotBlood = 1;\n" ^
      "	  		if (gotParchment==1) then\n" ^
      "				questState = 3;\n" ^
      "			end\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_Q2J4_KILL]\");\n" ^
      "		else\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_Q2J4_FAILURE]\");\n" ^
      "		end\n" ^
      "		QUEST_MESSAGE(myTitle,myMessage,idLocation);\n" ^
      "		QUEST_UPDATE_MAP();\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnLoad				\n" ^
      "--		(a save game is being loaded)\n" ^
      "--\n" ^
      "local function OnLoad()\n" ^
      "	questState = QUEST_LOAD_INT();\n" ^
      "	gotBlood = QUEST_LOAD_INT();\n" ^
      "	gotParchment = QUEST_LOAD_INT();\n" ^
      "	gotJarl = QUEST_LOAD_INT();\n" ^
      "	gotJotun = QUEST_LOAD_INT();\n" ^
      "\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnSave				\n" ^
      "--		(a save game is being saved)\n" ^
      "--\n" ^
      "local function OnSave()\n" ^
      "	QUEST_SAVE_INT(questState);\n" ^
      "	QUEST_SAVE_INT(gotBlood );\n" ^
      "	QUEST_SAVE_INT(gotParchment );\n" ^
      "	QUEST_SAVE_INT(gotJarl );\n" ^
      "	QUEST_SAVE_INT(gotJotun );\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryProgress		\n" ^
      "--		(returns text describing the next step required)\n" ^
      "--\n" ^
      "local function OnQueryProgress()\n" ^
      "	if (questState == 1) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q2J4_STEP1]\");\n" ^
      "	elseif (questState == 2) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q2J4_STEP2]\");\n" ^
      "	elseif (questState == 3) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q2J4_STEP3]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryPercentage	\n" ^
      "--		(returns a percentage of completion)\n" ^
      "--\n" ^
      "local function OnQueryPercentage()\n" ^
      "	if (questState <= 1) then\n" ^
      "		return gotJarl*20 + gotJotun*20;\n" ^
      "	elseif (questState == 2) then\n" ^
      "		return 40 + gotBlood*20 + gotParchment*20;\n" ^
      "	elseif (questState == 3) then\n" ^
      "		return 80;\n" ^
      "	end\n" ^
      "	return 100;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryDifficulty	\n" ^
      "--		(returns 0-4 for difficulty - v.easy to v.difficult )\n" ^
      "--\n" ^
      "local function OnQueryDifficulty()\n" ^
      "	-- average\n" ^
      "	return 2; \n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "\n" ^
      "local function CallbackConvA ()\n" ^
