    texts = [("[QUEST_Q2M1_ACTION]", "Fight the Wyvern"); ("[QUEST_Q2M1_FAILURE]", "You have failed to defeat the Wyvern. You must try again."); ("[QUEST_Q2M1_KILL]", "You have defeated the Wyvern. You must return to Red-Axe in the city of Tusk."); ("[QUEST_Q2M1_RETURN]", "Return to Red-Axe"); ("[QUEST_Q2M1_REWARD]", "The Trial is complete. Red-Axe is pleased with your progress."); ("[QUEST_Q2M1_STEP1]", "You must travel to the Wyverns' Roost and battle a Wyvern."); ("[QUEST_Q2M1_STEP2]", "You must return to Red-Axe in Tusk for your reward."); ("[QUEST_Q2M1_QMHELP0]", "This Wyvern is particularly large and has a Battle Skill higher than most.")];
    lua_file = "Assets\\Quests\\Q2M1.lua";
