    texts = [("[QUEST_Q2Q0_ACTION]", "Approach the Temple"); ("[QUEST_Q2Q0_ACTION4]", "Battle a Firewalker"); ("[QUEST_Q2Q0_FAILURE]", "You have been defeated by the Firewalker, but Tauron allows you to try again."); ("[QUEST_Q2Q0_MSG1]", "You see a huge pike. Impaled upon it are the heads of many creatures: Humans, Elves and Dwarves to name but a few..."); ("[QUEST_Q2Q0_MSG2]", "Tauron Flamebite is waiting for you on the steps of the Horned Temple."); ("[QUEST_Q2Q0_PROG1]", "You must enter the Horned Temple."); ("[QUEST_Q2Q0_PROG2]", "You must travel north to see the Pike."); ("[QUEST_Q2Q0_PROG3]", "You must try to enter the Horned Temple once again."); ("[QUEST_Q2Q0_PROG4]", "You must defeat a Minotaur Firewalker at the Horned Temple to prove your worth to Tauron Flamebite."); ("[QUEST_Q2Q0_REWARD]", "Tauron seems to have warmed to you - just a little."); ("[QUEST_Q2Q0_QMNAME0]", "Firewalker"); ("[QUEST_Q2Q0_QMHELP0]", "Firewalkers are similar to regular Minotaurs, but they have a stock of fire-related spells.")];
    lua_file = "Assets\\Quests\\Q2Q0.lua";
    lua_object = "Q2Q0";
    lua_source = "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--             Slave Trail	\n" ^
      "--	\n" ^
      "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--		STATES	\n" ^
      "--\n" ^
      "-- 0 => Inactive\n" ^
      "-- 1 => Quest obtained, nothing done yet\n" ^
      "-- 2 => Met Tauron\n" ^
      "-- 3 => Visited The Pike\n" ^
      "-- 4 => Tried to enter, but now must fight a Firewalker\n" ^
      "-- 5 => Finished\n" ^
      "-- \n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Variables\n" ^
      "--\n" ^
      "local questState = 0;\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Constants\n" ^
      "--\n" ^
      "local myCode     = \"Q2Q0\";\n" ^
      "local myDestination = \"WPIK\";\n" ^
      "local myLocation = \"CHTP\";\n" ^
      "local myOrigin   = \"CHTP\";\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnInit				\n" ^
      "--		(called for every quest when they are loading\n" ^
      "--		 to set the initial state of all variables)\n" ^
      "--\n" ^
      "local function OnInit()\n" ^
      "	questState = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnBegin				\n" ^
      "--		(called when a quest is first obtained)\n" ^
      "--\n" ^
      "local function OnBegin()\n" ^
      "	questState = 1;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnd				\n" ^
      "--		(called when a quest has ended)\n" ^
      "--\n" ^
      "local function OnEnd()\n" ^
      "	questState = 5;\n" ^
      "	\n" ^
      "	-- Reward\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q2Q0_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[QUEST_Q2Q0_REWARD]\");\n" ^
      "	QUEST_REWARD_MENU(myTitle,myMessage);\n" ^
      "	QUEST_REWARD_XP(100);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnAbandon				\n" ^
      "--		(called when a quest has been abandoned by the player)\n" ^
      "--\n" ^
      "local function OnAbandon()\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnterLocation		\n" ^
      "--		(a hero has arrived at a new location)\n" ^
      "--\n" ^
      "local function OnEnterLocation(idLocation)\n" ^
      "\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q2Q0_NAME]\");\n" ^
      "	local myMessage;\n" ^
      "\n" ^
      "	if (questState==2 and idLocation==myDestination) then\n" ^
      "		local myMessage = GET_TEXT(\"[QUEST_Q2Q0_MSG1]\");\n" ^
      "		QUEST_MESSAGE(myTitle,myMessage,idLocation);\n" ^
      "		questState = 3;\n" ^
      "		QUEST_UPDATE_MAP();\n" ^
      "	elseif (questState==3 and idLocation==myLocation) then\n" ^
      "		local myMessage = GET_TEXT(\"[QUEST_Q2Q0_MSG2]\");\n" ^
      "		QUEST_MESSAGE(myTitle,myMessage,idLocation);\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryAction\n" ^
      "--		(should anything appear on the popup menu)\n" ^
      "--\n" ^
      "local function OnQueryAction(idLocation)\n" ^
      "	if (idLocation==myLocation and questState==1) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q2Q0_ACTION]\");\n" ^
      "	elseif (idLocation==myDestination and questState==2) then\n" ^
      "		return GET_TEXT(\"[ON]\");\n" ^
      "	elseif (idLocation==myLocation and questState==3) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q2Q0_ACTION]\");\n" ^
      "	elseif (idLocation==myLocation and questState==4) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q2Q0_ACTION4]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnExecuteAction				\n" ^
      "--		(do this whenever the player executes the next action)\n" ^
      "--\n" ^
      "local function OnExecuteAction(idLocation)\n" ^
      "	if (questState==1) then\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q2Q0a.xml\",idLocation);\n" ^
      "	elseif (questState==3) then\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q2Q0b.xml\",idLocation);\n" ^
      "		questState=4;\n" ^
      "		QUEST_UPDATE_MAP();\n" ^
      "	elseif (questState==4) then\n" ^
      "		QUEST_BATTLE_NOCAPTURE(myCode,0,1);\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnCompleteAction				\n" ^
      "--		(do this whenever the player completes his action)\n" ^
      "--		It is called after the game has returned to the map screen\n" ^
      "--\n" ^
      "local function OnCompleteAction(idLocation, success)\n" ^
      "\n" ^
      "	if (questState==4) then\n" ^
      "	\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_Q2Q0_NAME]\");\n" ^
      "		local myMessage;\n" ^
      "		if (success == 1) then\n" ^
      "			QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q2Q0c.xml\",idLocation);\n" ^
      "		else\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_Q2Q0_FAILURE]\");\n" ^
      "			QUEST_MESSAGE(myTitle,myMessage,myLocation);\n" ^
      "		end\n" ^
      "		\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnLoad				\n" ^
      "--		(a save game is being loaded)\n" ^
      "--\n" ^
      "local function OnLoad()\n" ^
      "	questState = QUEST_LOAD_INT();\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnSave				\n" ^
      "--		(a save game is being saved)\n" ^
      "--\n" ^
      "local function OnSave()\n" ^
      "	QUEST_SAVE_INT(questState);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryProgress		\n" ^
      "--		(returns text describing the next step required)\n" ^
      "--\n" ^
      "local function OnQueryProgress()\n" ^
      "	if (questState == 1) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q2Q0_PROG1]\");\n" ^
      "	elseif (questState == 2) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q2Q0_PROG2]\");\n" ^
      "	elseif (questState == 3) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q2Q0_PROG3]\");\n" ^
      "	elseif (questState == 4) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q2Q0_PROG4]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryPercentage	\n" ^
      "--		(returns a percentage of completion)\n" ^
      "--\n" ^
      "local function OnQueryPercentage()\n" ^
      "	return (questState-1)*25;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryDifficulty	\n" ^
      "--		(returns 0-4 for difficulty - v.easy to v.difficult )\n" ^
      "--\n" ^
      "local function OnQueryDifficulty()\n" ^
      "	-- average\n" ^
      "	return 2; \n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackConvA ()\n" ^
      "	questState = 2;\n" ^
      "	QUEST_SET_VISIBILITY(myDestination ,1);\n" ^
      "	Std_AddEncounter(myLocation ,myDestination,\"EHP0\")\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackConvC ()\n" ^
      "	QUEST_COMPLETE(myCode);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "--	\n" ^
      "--		DECLARE TABLE	\n" ^
      "--\n" ^
      "\n" ^
      "Q2Q0 = {\n" ^
      "	OnInit				= OnInit,\n" ^
      "	OnBegin				= OnBegin,\n" ^
      "	OnEnd				= OnEnd,\n" ^
      "	OnAbandon			= OnAbandon,\n" ^
      "	OnEnterLocation		= OnEnterLocation,\n" ^
      "	OnExecuteAction		= OnExecuteAction,\n" ^
      "	OnCompleteAction	= OnCompleteAction,\n" ^
      "	OnQueryAction		= OnQueryAction,\n" ^
      "	OnLoad				= OnLoad,\n" ^
      "	OnSave				= OnSave,\n" ^
      "	OnQueryProgress		= OnQueryProgress,\n" ^
      "	OnQueryPercentage	= OnQueryPercentage,\n" ^
      "	OnQueryDifficulty	= OnQueryDifficulty,\n" ^
      "\n" ^
      "	CallbackConvA = CallbackConvA ,\n" ^
      "	CallbackConvC = CallbackConvC ,\n" ^
      "};\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
