    lua_file = "Assets\\Quests\\Q2Q2.lua";
    lua_object = "Q2Q2";
    lua_source = "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--             Horns of Sartek	\n" ^
      "--	\n" ^
      "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--		STATES	\n" ^
      "--\n" ^
      "-- 0 => Inactive\n" ^
      "-- 1 => Quest obtained, nothing done yet\n" ^
      "-- 2 => Killed Monster #1\n" ^
      "-- 3 => Killed Monster #2\n" ^
      "-- 4 => Finished (returned)\n" ^
      "-- \n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Variables\n" ^
      "--\n" ^
      "local questState = 0;\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Constants\n" ^
      "--\n" ^
      "local myCode     = \"Q2Q2\";\n" ^
      "local myLocation = \"CTSK\";\n" ^
      "local myOrigin   = \"CHTP\";\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnInit				\n" ^
      "--		(called for every quest when they are loading\n" ^
      "--		 to set the initial state of all variables)\n" ^
      "--\n" ^
      "local function OnInit()\n" ^
      "	questState = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnBegin				\n" ^
      "--		(called when a quest is first obtained)\n" ^
      "--\n" ^
      "local function OnBegin()\n" ^
      "	questState = 1;\n" ^
      "	QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q2Q2a.xml\",myOrigin);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnd				\n" ^
      "--		(called when a quest has ended)\n" ^
      "--\n" ^
      "local function OnEnd()\n" ^
      "	questState = 4;\n" ^
      "	\n" ^
      "	-- Reward\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q2Q2_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[QUEST_Q2Q2_REWARD]\");\n" ^
      "	QUEST_REWARD_MENU(myTitle,myMessage);\n" ^
      "	QUEST_REWARD_GOLD(100);\n" ^
      "	QUEST_REWARD_XP(100);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnAbandon				\n" ^
      "--		(called when a quest has been abandoned by the player)\n" ^
      "--\n" ^
      "local function OnAbandon()\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnterLocation		\n" ^
      "--		(a hero has arrived at a new location)\n" ^
      "--\n" ^
      "local function OnEnterLocation(idLocation)\n" ^
      "   	if (idLocation == myLocation and questState == 1 and\n" ^
      "		QUEST_HERO_HAS_COMPANION_SELECTED(\"NSUN\") == 1) then\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q2Q2c.xml\",idLocation);\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryAction\n" ^
      "--		(should anything appear on the popup menu)\n" ^
      "--\n" ^
      "local function OnQueryAction(idLocation)\n" ^
      "	if (idLocation==myLocation and questState==1) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q2Q2_ACTION1]\");\n" ^
      "	elseif (idLocation==myLocation and questState==2) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q2Q2_ACTION2]\");\n" ^
      "	elseif (idLocation==myOrigin and questState==3) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q2Q2_ACTION3]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnExecuteAction				\n" ^
      "--		(do this whenever the player executes the next action)\n" ^
      "--\n" ^
      "local function OnExecuteAction(idLocation)\n" ^
      "	if (questState==1) then\n" ^
      "		QUEST_BATTLE(myCode,0,1);\n" ^
      "	elseif (questState==2) then\n" ^
      "		QUEST_BATTLE(myCode,1,1);\n" ^
      "	elseif (questState==3) then\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q2Q2b.xml\",idLocation);\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnCompleteAction				\n" ^
      "--		(do this whenever the player completes his action)\n" ^
      "--		It is called after the game has returned to the map screen\n" ^
      "--\n" ^
      "local function OnCompleteAction(idLocation, success)\n" ^
      "		\n" ^
      "\n" ^
      "	if (questState==1) then\n" ^
      "	\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_Q2Q2_NAME]\");\n" ^
      "		local myMessage;\n" ^
      "		if (success == 1) then\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_Q2Q2_SUCCESS1]\");\n" ^
      "			questState = 2;\n" ^
      "		else\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_Q2Q2_FAILURE1]\");\n" ^
      "		end\n" ^
      "		QUEST_MESSAGE(myTitle,myMessage,idLocation);\n" ^
      "		QUEST_UPDATE_MAP();\n" ^
      "			\n" ^
      "	elseif (questState==2) then\n" ^
      "	\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_Q2Q2_NAME]\");\n" ^
      "		local myMessage;\n" ^
      "		if (success == 1) then\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_Q2Q2_SUCCESS2]\");\n" ^
      "			questState = 3;\n" ^
      "		else\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_Q2Q2_FAILURE2]\");\n" ^
      "		end\n" ^
      "		QUEST_MESSAGE(myTitle,myMessage,myLocation);\n" ^
      "		QUEST_UPDATE_MAP();\n" ^
      "		\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnLoad				\n" ^
      "--		(a save game is being loaded)\n" ^
      "--\n" ^
      "local function OnLoad()\n" ^
      "	questState = QUEST_LOAD_INT();\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnSave				\n" ^
      "--		(a save game is being saved)\n" ^
      "--\n" ^
      "local function OnSave()\n" ^
      "	QUEST_SAVE_INT(questState);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryProgress		\n" ^
      "--		(returns text describing the next step required)\n" ^
      "--\n" ^
      "local function OnQueryProgress()\n" ^
      "	if (questState==1) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q2Q2_PROGRESS1]\");\n" ^
      "	elseif (questState==2) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q2Q2_PROGRESS2]\");\n" ^
      "	elseif (questState==3) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q2Q2_PROGRESS3]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryPercentage	\n" ^
      "--		(returns a percentage of completion)\n" ^
      "--\n" ^
      "local function OnQueryPercentage()\n" ^
      "	return (questState - 1) * 33;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryDifficulty	\n" ^
      "--		(returns 0-4 for difficulty - v.easy to v.difficult )\n" ^
      "--\n" ^
      "local function OnQueryDifficulty()\n" ^
      "	-- average\n" ^
      "	return 2; \n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "\n" ^
      "local function CallbackConvA ()\n" ^
      "	questState = 1;\n" ^
      "	QUEST_SET_VISIBILITY(myLocation ,1);\n" ^
      "\n" ^
      "	QUEST_ADD_COMPANION(\"NSUN\");\n" ^
      "	QUEST_COMPANION_MESSAGE(\"NSUN\");\n" ^
      "\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackConvB ()\n" ^
      "	QUEST_COMPLETE(myCode);\n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "--	\n" ^
      "--		DECLARE TABLE	\n" ^
      "--\n" ^
      "\n" ^
      "Q2Q2 = {\n" ^
      "	OnInit				= OnInit,\n" ^
      "	OnBegin				= OnBegin,\n" ^
      "	OnEnd				= OnEnd,\n" ^
      "	OnAbandon			= OnAbandon,\n" ^
      "	OnEnterLocation		= OnEnterLocation,\n" ^
      "	OnExecuteAction		= OnExecuteAction,\n" ^
      "	OnCompleteAction	= OnCompleteAction,\n" ^
