    ruin_reveals = [];
    ruin_dones_on_end = [];
    ruin_dones_on_battle = [];
    ruin_dones_on_abandon = [];
    reward_gold = 0;
    reward_xp = 250;
    reward_items = [];
    reward_awards = [];
    reward_companions = [];
  };
  {
    id = "Q2Q7";
    name_text = "[QUEST_Q2Q7_NAME]";
    desc_text = "[QUEST_Q2Q7_DESC]";
    group = "[QG_PRIM_NAME]";
    text_file = "English\\Quests\\Q2Q7_Text.xml";
    texts = [("[QUEST_Q2Q7_ACTION]", "Search for the Ribs"); ("[QUEST_Q2Q7_FAILURE]", "The Minotaur King is too well protected by the Ribs of Sartek. You must fight him again."); ("[QUEST_Q2Q7_KILL]", "Having defeated the Minotaur King, you take the ribs that he had fashioned into some crude armor."); ("[QUEST_Q2Q7_NOTFOUND]", "The Ribs of Sartek are not here."); ("[QUEST_Q2Q7_RETURN]", "Return the Ribs"); ("[QUEST_Q2Q7_REWARD]", "With the ribs now in place, Sartek's body is beginning to take shape."); ("[QUEST_Q2Q7_STEP1]", "You must seek out the Ribs of Sartek, hidden somewhere within the Realms of War."); ("[QUEST_Q2Q7_STEP2]", "You must return the Ribs of Sartek to Tauron at the Horned Temple."); ("[QUEST_Q2Q7_QMHELP0]", "This Minotaur King is wearing armor made from the Ribs of Sartek. These provide much protection when he takes large amounts of damage.")];
    lua_file = "Assets\\Quests\\Q2Q7.lua";
    lua_object = "Q2Q7";
    lua_source = "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--             Ribs of Sartek	\n" ^
      "--	\n" ^
      "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--		STATES	\n" ^
      "--\n" ^
      "-- 0 => Inactive\n" ^
      "-- 1 => Quest obtained, nothing done yet\n" ^
      "-- 2 => Monster defeated, must return\n" ^
      "-- 3 => Finished\n" ^
      "-- \n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Variables\n" ^
      "--\n" ^
      "local questState = 0;\n" ^
      "local done1 = 0;\n" ^
      "local done2 = 0;\n" ^
      "local done3 = 0;\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Constants\n" ^
      "--\n" ^
      "local myCode        = \"Q2Q7\";\n" ^
      "local myLocation    = \"WGWK\";\n" ^
      "local myLocation1    = \"WWRT\";\n" ^
      "local myLocation2    = \"WSHD\";\n" ^
      "local myLocation3    = \"WPIK\";\n" ^
      "local myOrigin      = \"CHTP\";\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnInit				\n" ^
      "--		(called for every quest when they are loading\n" ^
      "--		 to set the initial state of all variables)\n" ^
      "--\n" ^
      "local function OnInit()\n" ^
      "	questState = 0;\n" ^
      "	done1 = 0;\n" ^
      "	done2 = 0;\n" ^
      "	done3 = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnBegin				\n" ^
      "--		(called when a quest is first obtained)\n" ^
      "--\n" ^
      "local function OnBegin()\n" ^
      "	questState = 1;\n" ^
      "	done1 = 0;\n" ^
      "	done2 = 0;\n" ^
      "	done3 = 0;\n" ^
      "	QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q2Q7a.xml\",myOrigin);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnd				\n" ^
      "--		(called when a quest has ended)\n" ^
      "--\n" ^
      "local function OnEnd()\n" ^
      "	questState = 3;\n" ^
      "	\n" ^
      "	-- Reward\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q2Q7_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[QUEST_Q2Q7_REWARD]\");\n" ^
      "	QUEST_REWARD_MENU(myTitle,myMessage);\n" ^
      "	QUEST_REWARD_XP(300);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnAbandon				\n" ^
      "--		(called when a quest has been abandoned by the player)\n" ^
      "--\n" ^
      "local function OnAbandon()\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnterLocation		\n" ^
      "--		(a hero has arrived at a new location)\n" ^
      "--\n" ^
      "local function OnEnterLocation(idLocation)\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryAction\n" ^
      "--		(should anything appear on the popup menu)\n" ^
      "--\n" ^
      "local function OnQueryAction(idLocation)\n" ^
      "	if (idLocation==myLocation and questState==1) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q2Q7_ACTION]\");\n" ^
      "	elseif (idLocation==myLocation1 and questState==1 and done1==0) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q2Q7_ACTION]\");\n" ^
      "	elseif (idLocation==myLocation2 and questState==1 and done2==0) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q2Q7_ACTION]\");\n" ^
      "	elseif (idLocation==myLocation3 and questState==1 and done3==0) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q2Q7_ACTION]\");\n" ^
      "	elseif (idLocation==myOrigin and questState==2) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q2Q7_RETURN]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnExecuteAction				\n" ^
      "--		(do this whenever the player executes the next action)\n" ^
      "--\n" ^
      "local function OnExecuteAction(idLocation)\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q2Q7_NAME]\");\n" ^
      "	if (questState==1 and idLocation==myLocation) then\n" ^
      "		QUEST_BATTLE(myCode,0,1);\n" ^
      "	elseif (questState==1 and idLocation==myLocation1) then\n" ^
      "		local myMessage = GET_TEXT(\"[QUEST_Q2Q7_NOTFOUND]\");\n" ^
      "		QUEST_MESSAGE(myTitle,myMessage,idLocation);\n" ^
      "		done1 = 1;\n" ^
      "		QUEST_UPDATE_MAP();\n" ^
      "	elseif (questState==1 and idLocation==myLocation2) then\n" ^
      "		local myMessage = GET_TEXT(\"[QUEST_Q2Q7_NOTFOUND]\");\n" ^
      "		QUEST_MESSAGE(myTitle,myMessage,idLocation);\n" ^
      "		done2 = 1;\n" ^
      "		QUEST_UPDATE_MAP();\n" ^
      "	elseif (questState==1 and idLocation==myLocation3) then\n" ^
      "		local myMessage = GET_TEXT(\"[QUEST_Q2Q7_NOTFOUND]\");\n" ^
      "		QUEST_MESSAGE(myTitle,myMessage,idLocation);\n" ^
      "		done3 = 1;\n" ^
      "		QUEST_UPDATE_MAP();\n" ^
      "	elseif (questState==2) then\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q2Q7c.xml\",idLocation);\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnCompleteAction				\n" ^
      "--		(do this whenever the player completes his action)\n" ^
      "--		It is called after the game has returned to the map screen\n" ^
      "--\n" ^
      "local function OnCompleteAction(idLocation, success)\n" ^
      "\n" ^
      "	if (questState==1) then\n" ^
      "	\n" ^
      "		if (success == 1 and QUEST_HERO_HAS_COMPANION_SELECTED(\"NDRO\")==1) then\n" ^
      "			QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q2Q7b.xml\",idLocation);\n" ^
      "			return;\n" ^
      "		end\n" ^
      "\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_Q2Q7_NAME]\");\n" ^
      "		local myMessage;\n" ^
      "		if (success == 1) then\n" ^
      "	  		questState = 2;\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_Q2Q7_KILL]\");\n" ^
      "		else\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_Q2Q7_FAILURE]\");\n" ^
      "		end\n" ^
      "		QUEST_MESSAGE(myTitle,myMessage,myLocation);\n" ^
      "		QUEST_UPDATE_MAP();\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnLoad				\n" ^
      "--		(a save game is being loaded)\n" ^
      "--\n" ^
      "local function OnLoad()\n" ^
      "	questState = QUEST_LOAD_INT();\n" ^
      "	done1 = QUEST_LOAD_INT();\n" ^
      "	done2 = QUEST_LOAD_INT();\n" ^
      "	done3 = QUEST_LOAD_INT();\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnSave				\n" ^
      "--		(a save game is being saved)\n" ^
      "--\n" ^
      "local function OnSave()\n" ^
      "	QUEST_SAVE_INT(questState);\n" ^
      "	QUEST_SAVE_INT(done1);\n" ^
      "	QUEST_SAVE_INT(done2);\n" ^
      "	QUEST_SAVE_INT(done3);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryProgress		\n" ^
      "--		(returns text describing the next step required)\n" ^
      "--\n" ^
      "local function OnQueryProgress()\n" ^
      "	if (questState == 1) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q2Q7_STEP1]\");\n" ^
      "	elseif (questState == 2) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q2Q7_STEP2]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryPercentage	\n" ^
      "--		(returns a percentage of completion)\n" ^
      "--\n" ^
      "local function OnQueryPercentage()\n" ^
      "	if (questState <= 1) then\n" ^
      "		return done1*10 + done2*10 + done3*10;\n" ^
      "	elseif (questState == 2) then\n" ^
      "		return 50;\n" ^
      "	end\n" ^
      "	return 100;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryDifficulty	\n" ^
      "--		(returns 0-4 for difficulty - v.easy to v.difficult )\n" ^
      "--\n" ^
      "local function OnQueryDifficulty()\n" ^
      "	-- average\n" ^
      "	return 3; \n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "\n" ^
      "local function CallbackConvA ()\n" ^
      "	questState = 1;\n" ^
      "	QUEST_SET_VISIBILITY(\"WWRT\" ,1);\n" ^
      "	QUEST_SET_VISIBILITY(\"WGWK\" ,1);\n" ^
      "	Std_AddEncounter(\"WWRT\",\"CTSK\",\"EWGN\");\n" ^
      "	Std_AddEncounter(\"WGWK\",\"WSHD\",\"EGHG\");\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackConvB ()\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q2Q7_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[QUEST_Q2Q7_KILL]\");\n" ^
      "	questState = 2;\n" ^
      "	QUEST_MESSAGE(myTitle,myMessage,myLocation);\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackConvC ()\n" ^
      "	QUEST_COMPLETE(myCode);\n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "--	\n" ^
      "--		DECLARE TABLE	\n" ^
      "--\n" ^
      "\n" ^
      "Q2Q7 = {\n" ^
      "	OnInit				= OnInit,\n" ^
      "	OnBegin				= OnBegin,\n" ^
      "	OnEnd				= OnEnd,\n" ^
      "	OnAbandon			= OnAbandon,\n" ^
      "	OnEnterLocation		= OnEnterLocation,\n" ^
      "	OnExecuteAction		= OnExecuteAction,\n" ^
      "	OnCompleteAction	= OnCompleteAction,\n" ^
      "	OnQueryAction		= OnQueryAction,\n" ^
      "	OnLoad				= OnLoad,\n" ^
      "	OnSave				= OnSave,\n" ^
      "	OnQueryProgress		= OnQueryProgress,\n" ^
      "	OnQueryPercentage	= OnQueryPercentage,\n" ^
      "	OnQueryDifficulty	= OnQueryDifficulty,\n" ^
      "	\n" ^
      "	CallbackConvA = CallbackConvA ,\n" ^
      "	CallbackConvB = CallbackConvB ,\n" ^
      "	CallbackConvC = CallbackConvC ,\n" ^
      "};\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n";
    abandonable = false;
    icon = 0;
    important = true;
    avail_location = "CHTP";
    avail_minlevel = 23;
    avail_maxlevel = 1000;
    avail_repeat = 1;
    avail_donequest0 = "Q2Q6";
    avail_donequest1 = "";
    avail_donequest2 = "";
