    avail_notactivequest = "";
    avail_companion0 = "";
    avail_companion1 = "";
    avail_notcompanion = "";
    avail_item = "";
    avail_notitem = "";
    avail_award = "";
    avail_notaward = "";
    battle_monster = "MMIK";
    battle_spells = [];
    battles = [("MMIK", [])];
    battle_actions = [(1, 0, true)];
    battle_stage_advances = [(1, 2)];
    battle_stage_fails = [];
    enter_removes = [];
    reveal_on_begin = ["WWRT"; "WGWK"];
    reveal_on_end = [];
    ruin_reveals = [];
    ruin_dones_on_end = [];
    ruin_dones_on_battle = [];
    ruin_dones_on_abandon = [];
    reward_gold = 0;
    reward_xp = 300;
    reward_items = [];
    reward_awards = [];
    reward_companions = [];
  };
  {
    id = "Q2Q8";
    name_text = "[QUEST_Q2Q8_NAME]";
    desc_text = "[QUEST_Q2Q8_DESC]";
    group = "[QG_PRIM_NAME]";
    text_file = "English\\Quests\\Q2Q8_Text.xml";
    texts = [("[QUEST_Q2Q8_ACTION1]", "Visit the Red Tower"); ("[QUEST_Q2Q8_ACTION2]", "Challenge Sir Borik"); ("[QUEST_Q2Q8_FAILURE]", "You have failed to defeat Sir Borik. You must try again."); ("[QUEST_Q2Q8_KILL]", "You have defeated Sir Borik, and you take his helm as your prize."); ("[QUEST_Q2Q8_RETURN]", "Return the Crest"); ("[QUEST_Q2Q8_REWARD]", "Tauron is now awaiting one final piece of his God."); ("[QUEST_Q2Q8_STEP1]", "You must travel to Maethelburg in the Borderlands to see if you can find the Knight with the Crest."); ("[QUEST_Q2Q8_STEP2]", "You must travel to Drakenburg and challenge Sir Borik to a duel for his helmet."); ("[QUEST_Q2Q8_STEP3]", "You must return the Crest to Tauron at the Horned Temple."); ("[QUEST_Q2Q8_QMNAME0]", "Sir Borik"); ("[QUEST_Q2Q8_QMHELP0]", "Sir Borik is particularly powerful.  His skills are high, he is well armored, and he has extra spells.")];
    lua_file = "Assets\\Quests\\Q2Q8.lua";
    lua_object = "Q2Q8";
    lua_source = "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--             Crest of Sartek	\n" ^
      "--	\n" ^
      "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--		STATES	\n" ^
      "--\n" ^
      "-- 0 => Inactive\n" ^
      "-- 1 => Quest obtained, nothing done yet\n" ^
      "-- 2 => Talked to Lord Greythane\n" ^
      "-- 3 => Defeated Lord Borik & got Crest\n" ^
      "-- 4 => Finished\n" ^
      "-- \n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Variables\n" ^
      "--\n" ^
      "local questState = 0;\n" ^
      "local doneDarkhunterWarning = 0;\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Constants\n" ^
      "--\n" ^
      "local myCode        = \"Q2Q8\";\n" ^
      "local myDHConvLoc   = \"CGAL\";\n" ^
      "local myLocation    = \"WMAE\";\n" ^
      "local myLocation2   = \"CDRA\";\n" ^
      "local myOrigin      = \"CHTP\";\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnInit				\n" ^
      "--		(called for every quest when they are loading\n" ^
      "--		 to set the initial state of all variables)\n" ^
      "--\n" ^
      "local function OnInit()\n" ^
      "	questState = 0;\n" ^
      "	doneDarkhunterWarning = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnBegin				\n" ^
      "--		(called when a quest is first obtained)\n" ^
      "--\n" ^
      "local function OnBegin()\n" ^
      "	questState = 1;\n" ^
      "	QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q2Q8a.xml\",myOrigin);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnd				\n" ^
      "--		(called when a quest has ended)\n" ^
      "--\n" ^
      "local function OnEnd()\n" ^
      "	questState = 3;\n" ^
      "	\n" ^
      "	-- Reward\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q2Q8_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[QUEST_Q2Q8_REWARD]\");\n" ^
      "	QUEST_REWARD_MENU(myTitle,myMessage);\n" ^
      "	QUEST_REWARD_XP(400);\n" ^
      "\n" ^
      "\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnAbandon				\n" ^
      "--		(called when a quest has been abandoned by the player)\n" ^
      "--\n" ^
      "local function OnAbandon()\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnterLocation		\n" ^
      "--		(a hero has arrived at a new location)\n" ^
      "--\n" ^
      "local function OnEnterLocation(idLocation)\n" ^
      "	if (idLocation == myDHConvLoc  and doneDarkhunterWarning == 0 and\n" ^
      "	    QUEST_HERO_HAS_COMPANION_SELECTED(\"NDKH\")==1) then\n" ^
      "\n" ^
      "			QUEST_STOP_MOVEMENT();\n" ^
      "			doneDarkhunterWarning = 1\n" ^
      "			QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q2Q8b.xml\",idLocation);\n" ^
      "\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryAction\n" ^
      "--		(should anything appear on the popup menu)\n" ^
      "--\n" ^
      "local function OnQueryAction(idLocation)\n" ^
      "	if (idLocation==myLocation and questState==1) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q2Q8_ACTION1]\");\n" ^
      "	elseif (idLocation==myLocation2 and questState==2) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q2Q8_ACTION2]\");\n" ^
      "	elseif (idLocation==myOrigin and questState==3) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q2Q8_RETURN]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnExecuteAction				\n" ^
      "--		(do this whenever the player executes the next action)\n" ^
      "--\n" ^
      "local function OnExecuteAction(idLocation)\n" ^
      "	if (questState==1) then\n" ^
      "		if (QUEST_HERO_HAS_COMPANION_SELECTED(\"NDKH\")==1) then\n" ^
      "			QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q2Q8c.xml\",idLocation);\n" ^
      "		else\n" ^
      "			QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q2Q8d.xml\",idLocation);\n" ^
      "		end\n" ^
      "	elseif (questState==2) then\n" ^
      "		QUEST_BATTLE_NOCAPTURE(myCode,0,1);\n" ^
      "	elseif (questState==3) then\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q2Q8e.xml\",idLocation);\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnCompleteAction				\n" ^
      "--		(do this whenever the player completes his action)\n" ^
      "--		It is called after the game has returned to the map screen\n" ^
      "--\n" ^
      "local function OnCompleteAction(idLocation, success)\n" ^
      "\n" ^
      "	if (questState==2) then\n" ^
      "	\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_Q2Q8_NAME]\");\n" ^
      "		local myMessage;\n" ^
      "		if (success == 1) then\n" ^
      "	  		questState = 3;\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_Q2Q8_KILL]\");\n" ^
      "\n" ^
      "			Std_AddEncounter(\"CDRA\",\"WSKE\",\"EDKN\");--Knight Encounter outside Drakenburg\n" ^
      "		else\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_Q2Q8_FAILURE]\");\n" ^
      "		end\n" ^
      "		QUEST_MESSAGE(myTitle,myMessage,idLocation);\n" ^
      "\n" ^
      "\n" ^
      "		QUEST_UPDATE_MAP();\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnLoad				\n" ^
      "--		(a save game is being loaded)\n" ^
      "--\n" ^
      "local function OnLoad()\n" ^
      "	questState = QUEST_LOAD_INT();\n" ^
      "	doneDarkhunterWarning = QUEST_LOAD_INT();\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnSave				\n" ^
      "--		(a save game is being saved)\n" ^
      "--\n" ^
      "local function OnSave()\n" ^
      "	QUEST_SAVE_INT(questState);\n" ^
      "	QUEST_SAVE_INT(doneDarkhunterWarning );\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryProgress		\n" ^
      "--		(returns text describing the next step required)\n" ^
      "--\n" ^
      "local function OnQueryProgress()\n" ^
      "	if (questState == 1) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q2Q8_STEP1]\");\n" ^
      "	elseif (questState == 2) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q2Q8_STEP2]\");\n" ^
      "	elseif (questState == 3) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q2Q8_STEP3]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryPercentage	\n" ^
      "--		(returns a percentage of completion)\n" ^
      "--\n" ^
      "local function OnQueryPercentage()\n" ^
      "	return (questState-1)*33;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryDifficulty	\n" ^
      "--		(returns 0-4 for difficulty - v.easy to v.difficult )\n" ^
      "--\n" ^
      "local function OnQueryDifficulty()\n" ^
      "	-- average\n" ^
      "	return 3; \n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "\n" ^
      "local function CallbackConvA ()\n" ^
      "	questState = 1;\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackConvB ()\n" ^
      "	doneDarkhunterWarning = 1;\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackConvC ()\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackConvD ()\n" ^
      "	questState = 2;\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackConvE ()\n" ^
      "	QUEST_COMPLETE(myCode);\n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
