    id = "Q2Q9";
    name_text = "[QUEST_Q2Q9_NAME]";
    desc_text = "[QUEST_Q2Q9_DESC]";
    group = "[QG_PRIM_NAME]";
    text_file = "English\\Quests\\Q2Q9_Text.xml";
    texts = [("[QUEST_Q2Q9_ACTION]", "Enter the Horned Citadel"); ("[QUEST_Q2Q9_FAILURE]", "You have failed to defeat Minogoth. You must try again."); ("[QUEST_Q2Q9_KILL]", "You quickly take the Skull of Sartek before Minogoth can return to full power. You also take Minogoth's armor."); ("[QUEST_Q2Q9_RETURN]", "Return the Skull"); ("[QUEST_Q2Q9_REWARD]", "Tauron takes the final piece of Sartek.  The task is complete."); ("[QUEST_Q2Q9_STEP1]", "You must travel to Ohtar and steal the Skull of Sartek from Minogoth."); ("[QUEST_Q2Q9_STEP2]", "You must return the Skull of Sartek to Tauron at the Horned Temple.")];
    lua_file = "Assets\\Quests\\Q2Q9.lua";
    lua_object = "Q2Q9";
    lua_source = "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--             Skull of Sartek	\n" ^
      "--	\n" ^
      "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--		STATES	\n" ^
      "--\n" ^
      "-- 0 => Inactive\n" ^
      "-- 1 => Quest obtained, nothing done yet\n" ^
      "-- 2 => Monster defeated, must return\n" ^
      "-- 3 => Finished\n" ^
      "-- \n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Variables\n" ^
      "--\n" ^
      "local questState = 0;\n" ^
      "local doneFlickerConv = 0;\n" ^
      "local doneMinogothConv = 0;\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Constants\n" ^
      "--\n" ^
      "local myCode        = \"Q2Q9\";\n" ^
      "local myLocation    = \"COHT\";\n" ^
      "local myOrigin      = \"CHTP\";\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnInit				\n" ^
      "--		(called for every quest when they are loading\n" ^
      "--		 to set the initial state of all variables)\n" ^
      "--\n" ^
      "local function OnInit()\n" ^
      "	questState = 0;\n" ^
      "	doneFlickerConv = 0;\n" ^
      "	doneMinogothConv = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnBegin				\n" ^
      "--		(called when a quest is first obtained)\n" ^
      "--\n" ^
      "local function OnBegin()\n" ^
      "	questState = 1;\n" ^
      "	doneFlickerConv = 0;\n" ^
      "	doneMinogothConv = 0;\n" ^
      "	QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q2Q9a.xml\",myOrigin);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnd				\n" ^
      "--		(called when a quest has ended)\n" ^
      "--\n" ^
      "local function OnEnd()\n" ^
      "	questState = 3;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnAbandon				\n" ^
      "--		(called when a quest has been abandoned by the player)\n" ^
      "--\n" ^
      "local function OnAbandon()\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnterLocation		\n" ^
      "--		(a hero has arrived at a new location)\n" ^
      "--\n" ^
      "local function OnEnterLocation(idLocation)\n" ^
      "	if (idLocation == myLocation and doneFlickerConv == 0 and\n" ^
      "		QUEST_HERO_HAS_COMPANION_SELECTED(\"NFLI\")==1) then\n" ^
      "\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q2Q9b.xml\",idLocation);\n" ^
      "		\n" ^
      "	end\n" ^
      "		\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryAction\n" ^
      "--		(should anything appear on the popup menu)\n" ^
      "--\n" ^
      "local function OnQueryAction(idLocation)\n" ^
      "	if (idLocation==myLocation and questState==1) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q2Q9_ACTION]\");\n" ^
      "	elseif (idLocation==myOrigin and questState==2) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q2Q9_RETURN]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnExecuteAction				\n" ^
      "--		(do this whenever the player executes the next action)\n" ^
      "--\n" ^
      "local function OnExecuteAction(idLocation)\n" ^
      "	if (questState==1) then\n" ^
      "		if (doneMinogothConv == 0) then\n" ^
      "			QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q2Q9c.xml\",idLocation);\n" ^
      "		else\n" ^
      "			QUEST_BATTLE(myCode,0,1);\n" ^
      "		end\n" ^
      "	elseif (questState==2) then\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q2Q9e.xml\",idLocation);\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnCompleteAction				\n" ^
      "--		(do this whenever the player completes his action)\n" ^
      "--		It is called after the game has returned to the map screen\n" ^
      "--\n" ^
      "local function OnCompleteAction(idLocation, success)\n" ^
      "\n" ^
      "	if (questState==1) then\n" ^
      "	\n" ^
      "		if (success == 1) then\n" ^
      "			QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q2Q9d.xml\",idLocation);\n" ^
      "		else\n" ^
      "			local myTitle = GET_TEXT(\"[QUEST_Q2Q9_NAME]\");\n" ^
      "			local myMessage = GET_TEXT(\"[QUEST_Q2Q9_FAILURE]\");\n" ^
      "			QUEST_MESSAGE(myTitle,myMessage,myLocation);\n" ^
      "		end\n" ^
      "		\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnLoad				\n" ^
      "--		(a save game is being loaded)\n" ^
      "--\n" ^
      "local function OnLoad()\n" ^
      "	questState = QUEST_LOAD_INT();\n" ^
      "	doneFlickerConv = QUEST_LOAD_INT();\n" ^
      "	doneMinogothConv = QUEST_LOAD_INT(); \n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnSave				\n" ^
      "--		(a save game is being saved)\n" ^
      "--\n" ^
      "local function OnSave()\n" ^
      "	QUEST_SAVE_INT(questState);\n" ^
      "	QUEST_SAVE_INT(doneFlickerConv);\n" ^
      "	QUEST_SAVE_INT(doneMinogothConv);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryProgress		\n" ^
      "--		(returns text describing the next step required)\n" ^
      "--\n" ^
      "local function OnQueryProgress()\n" ^
      "	if (questState == 1) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q2Q9_STEP1]\");\n" ^
      "	elseif (questState == 2) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q2Q9_STEP2]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryPercentage	\n" ^
      "--		(returns a percentage of completion)\n" ^
      "--\n" ^
      "local function OnQueryPercentage()\n" ^
      "	if (questState <= 1) then\n" ^
      "		return 0;\n" ^
      "	elseif (questState == 2) then\n" ^
      "		return 50;\n" ^
      "	end\n" ^
      "	return 100;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryDifficulty	\n" ^
      "--		(returns 0-4 for difficulty - v.easy to v.difficult )\n" ^
      "--\n" ^
      "local function OnQueryDifficulty()\n" ^
      "	-- average\n" ^
      "	return 3; \n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "\n" ^
      "local function CallbackConvA ()\n" ^
      "	questState = 1;\n" ^
      "	QUEST_SET_VISIBILITY(myLocation ,1);\n" ^
      "	QUEST_SET_CITY_STATUS(myLocation ,3);\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackConvB ()\n" ^
      "	doneFlickerConv = 1;\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackConvC ()\n" ^
      "	doneMinogothConv = 1;\n" ^
      "	QUEST_BATTLE_NOCAPTURE(myCode,0,1);\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackConvD ()\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q2Q9_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[QUEST_Q2Q9_KILL]\");\n" ^
      "	QUEST_MESSAGE(myTitle,myMessage,myLocation);\n" ^
      "	questState = 2;\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackConvE ()\n" ^
      "	\n" ^
      "	-- Reward\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q2Q9_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[QUEST_Q2Q9_REWARD]\");\n" ^
      "	QUEST_REWARD_MENU_CALLBACK(myTitle,myMessage,myCode,\"CallbackReward\");\n" ^
      "	QUEST_REWARD_XP(600);\n" ^
      "	QUEST_REWARD_ITEM(\"IAOM\");\n" ^
      "\n" ^
      "	QUEST_SET_CITY_STATUS(myLocation ,0);\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackReward ()\n" ^
      "	QUEST_CUTSCENE(\"CutScenes\\\\Chap4_Intro.xml\");\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "	QUEST_COMPLETE(myCode);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "--	\n" ^
      "--		DECLARE TABLE	\n" ^
      "--\n" ^
      "\n" ^
      "Q2Q9 = {\n" ^
      "	OnInit				= OnInit,\n" ^
      "	OnBegin				= OnBegin,\n" ^
      "	OnEnd				= OnEnd,\n" ^
      "	OnAbandon			= OnAbandon,\n" ^
      "	OnEnterLocation		= OnEnterLocation,\n" ^
      "	OnExecuteAction		= OnExecuteAction,\n" ^
      "	OnCompleteAction	= OnCompleteAction,\n" ^
      "	OnQueryAction		= OnQueryAction,\n" ^
      "	OnLoad				= OnLoad,\n" ^
      "	OnSave				= OnSave,\n" ^
      "	OnQueryProgress		= OnQueryProgress,\n" ^
      "	OnQueryPercentage	= OnQueryPercentage,\n" ^
      "	OnQueryDifficulty	= OnQueryDifficulty,\n" ^
      "	\n" ^
      "	CallbackConvA = CallbackConvA ,\n" ^
      "	CallbackConvB = CallbackConvB ,\n" ^
      "	CallbackConvC = CallbackConvC ,\n" ^
      "	CallbackConvD = CallbackConvD ,\n" ^
      "	CallbackConvE = CallbackConvE ,\n" ^
      "	CallbackReward = CallbackReward ,\n" ^
      "};\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n";
