  {
    id = "Q3D1";
    name_text = "[QUEST_Q3D1_NAME]";
    desc_text = "[QUEST_Q3D1_DESC]";
    group = "[QG_LODR_NAME]";
    text_file = "English\\Quests\\Q3D1_Text.xml";
    texts = [("[QUEST_Q3D1_ACTION]", "Search for the Dragon"); ("[QUEST_Q3D1_ACTION2]", "Battle the Dragon"); ("[QUEST_Q3D1_FAILURE]", "You have failed to defeat the Undead Dragon. You can try to fight it again or simply return to Elistara."); ("[QUEST_Q3D1_KILL]", "You have defeated the Undead Dragon. You must return to Elistara with the news."); ("[QUEST_Q3D1_NOSIGN]", "There is no sign of Elistara's Dragon here."); ("[QUEST_Q3D1_RETURN]", "Return to Elistara"); ("[QUEST_Q3D1_REWARD]", "Elistara is devastated by the news."); ("[QUEST_Q3D1_STEP1]", "You must search for Elistara's Dragon in the Realms of Death."); ("[QUEST_Q3D1_STEP2]", "You may continue to try and fight the Dragon, or return to Elistara."); ("[QUEST_Q3D1_STEP3]", "You must return to Elistara in Ylarie."); ("[QUEST_Q3D1_TRACKS]", "You do not find the Dragon, but there appear to be some Dragon tracks leading towards Lord Bane's Citadel.")];
    lua_file = "Assets\\Quests\\Q3D1.lua";
    lua_object = "Q3D1";
    lua_source = "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--             Dragontracks	\n" ^
      "--	\n" ^
      "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--		STATES	\n" ^
      "--\n" ^
      "-- 0 => Inactive\n" ^
      "-- 1 => Quest obtained, nothing done yet\n" ^
      "-- 2 => Visited Skullguard Keep\n" ^
      "-- 3 => Visited BoneBridge\n" ^
      "-- 4 => Visited Bane's Citadel\n" ^
      "-- 5 => Monster not defeated, but may return\n" ^
      "-- 6 => Monster defeated, must return\n" ^
      "-- 7 => Finished\n" ^
      "-- \n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Variables\n" ^
      "--\n" ^
      "local questState = 0;\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Constants\n" ^
      "--\n" ^
      "local myCode        = \"Q3D1\";\n" ^
      "local myLocation    = \"CLBC\";\n" ^
      "local myWaypoint1   = \"WSGK\";\n" ^
      "local myWaypoint2   = \"WBBR\";\n" ^
      "local myOrigin      = \"CYLA\";\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnInit				\n" ^
      "--		(called for every quest when they are loading\n" ^
      "--		 to set the initial state of all variables)\n" ^
      "--\n" ^
      "local function OnInit()\n" ^
      "	questState = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnBegin				\n" ^
      "--		(called when a quest is first obtained)\n" ^
      "--\n" ^
      "local function OnBegin()\n" ^
      "	questState = 1;\n" ^
      "	QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q3D1a.xml\",myOrigin);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnd				\n" ^
      "--		(called when a quest has ended)\n" ^
      "--\n" ^
      "local function OnEnd()\n" ^
      "	questState = 4;\n" ^
      "	\n" ^
      "	-- Reward\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q3D1_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[QUEST_Q3D1_REWARD]\");\n" ^
      "	QUEST_REWARD_MENU(myTitle,myMessage);\n" ^
      "	QUEST_REWARD_XP(200);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnAbandon				\n" ^
      "--		(called when a quest has been abandoned by the player)\n" ^
      "--\n" ^
      "local function OnAbandon()\n" ^
      "	questState = 0;\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnterLocation		\n" ^
      "--		(a hero has arrived at a new location)\n" ^
      "--\n" ^
      "local function OnEnterLocation(idLocation)\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryAction\n" ^
      "--		(should anything appear on the popup menu)\n" ^
      "--\n" ^
      "local function OnQueryAction(idLocation)\n" ^
      "	if (idLocation==myLocation and questState==3) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q3D1_ACTION]\");\n" ^
      "	elseif (idLocation==myLocation and questState==4) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q3D1_ACTION]\");\n" ^
      "	elseif (idLocation==myLocation and questState==5) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q3D1_ACTION2]\");\n" ^
      "	elseif (idLocation==myOrigin and questState > 4) then --state 5or6 allow to return\n" ^
      "			return GET_TEXT(\"[QUEST_Q3D1_RETURN]\");\n" ^
      "	elseif (idLocation==myWaypoint1 and questState==1) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q3D1_ACTION]\");\n" ^
      "	elseif (idLocation==myWaypoint2 and questState==2) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q3D1_ACTION]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnExecuteAction				\n" ^
      "--		(do this whenever the player executes the next action)\n" ^
      "--\n" ^
      "local function OnExecuteAction(idLocation)\n" ^
      "	if (questState==1 and idLocation==myWaypoint1) then\n" ^
      "		questState = 2;\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_Q3D1_NAME]\");\n" ^
      "		local myMessage = GET_TEXT(\"[QUEST_Q3D1_NOSIGN]\");\n" ^
      "		QUEST_MESSAGE(myTitle,myMessage,idLocation);\n" ^
      "		QUEST_UPDATE_MAP();\n" ^
      "	\n" ^
      "	elseif (questState==2 and idLocation==myWaypoint2) then\n" ^
      "		questState = 3;\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_Q3D1_NAME]\");\n" ^
      "		local myMessage = GET_TEXT(\"[QUEST_Q3D1_TRACKS]\");\n" ^
      "		if (QUEST_IS_VISIBLE(myLocation)==0) then\n" ^
      "			QUEST_SET_VISIBILITY(myLocation,1);\n" ^
      "			QUEST_SET_CITY_STATUS(myLocation,CITYSTATUS_CLOSED);\n" ^
      "		end\n" ^
      "		QUEST_MESSAGE(myTitle,myMessage,idLocation);\n" ^
      "		QUEST_UPDATE_MAP();\n" ^
      "	\n" ^
      "	elseif (questState==3 and idLocation==myLocation) then\n" ^
      "		questState = 4;\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q3D1b.xml\",idLocation);\n" ^
      "	\n" ^
      "	elseif (questState==5 and idLocation==myLocation) then\n" ^
      "\n" ^
      "		QUEST_BATTLE(myCode,0,1);\n" ^
      "\n" ^
      "	elseif (questState >4 and idLocation==myOrigin) then\n" ^
      "\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q3D1c.xml\",idLocation);\n" ^
      "	\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnCompleteAction				\n" ^
      "--		(do this whenever the player completes his action)\n" ^
      "--		It is called after the game has returned to the map screen\n" ^
      "--\n" ^
      "local function OnCompleteAction(idLocation, success)\n" ^
      "\n" ^
      "	if (questState > 3) then\n" ^
      "	\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_Q3D1_NAME]\");\n" ^
      "		local myMessage;\n" ^
      "		if (success == 1) then\n" ^
      "	  		questState = 6;\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_Q3D1_KILL]\");\n" ^
      "		else\n" ^
      "			questState = 5;\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_Q3D1_FAILURE]\");\n" ^
      "		end\n" ^
      "		QUEST_MESSAGE(myTitle,myMessage,myLocation);\n" ^
      "		QUEST_UPDATE_MAP();\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnLoad				\n" ^
      "--		(a save game is being loaded)\n" ^
      "--\n" ^
      "local function OnLoad()\n" ^
      "	questState = QUEST_LOAD_INT();\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnSave				\n" ^
      "--		(a save game is being saved)\n" ^
      "--\n" ^
      "local function OnSave()\n" ^
      "	QUEST_SAVE_INT(questState);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryProgress		\n" ^
      "--		(returns text describing the next step required)\n" ^
      "--\n" ^
      "local function OnQueryProgress()\n" ^
      "	if (questState == 1) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q3D1_STEP1]\");\n" ^
      "	elseif (questState == 5) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q3D1_STEP2]\");\n" ^
      "	elseif (questState == 6) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q3D1_STEP3]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryPercentage	\n" ^
      "--		(returns a percentage of completion)\n" ^
      "--\n" ^
      "local function OnQueryPercentage()\n" ^
      "	return (questState-1)*16;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryDifficulty	\n" ^
      "--		(returns 0-4 for difficulty - v.easy to v.difficult )\n" ^
      "--\n" ^
      "local function OnQueryDifficulty()\n" ^
      "	-- average\n" ^
      "	return 3; \n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "\n" ^
      "local function CallbackConvA ()\n" ^
      "	questState = 1;\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackConvB ()\n" ^
      "	QUEST_BATTLE(myCode,0,1);\n" ^
      "	questState = 5; -- better set it here in case they cancel\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackConvC ()\n" ^
      "	QUEST_COMPLETE(myCode);\n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "--	\n" ^
      "--		DECLARE TABLE	\n" ^
      "--\n" ^
      "\n" ^
      "Q3D1 = {\n" ^
      "	OnInit				= OnInit,\n" ^
      "	OnBegin				= OnBegin,\n" ^
      "	OnEnd				= OnEnd,\n" ^
      "	OnAbandon			= OnAbandon,\n" ^
      "	OnEnterLocation		= OnEnterLocation,\n" ^
      "	OnExecuteAction		= OnExecuteAction,\n" ^
      "	OnCompleteAction	= OnCompleteAction,\n" ^
      "	OnQueryAction		= OnQueryAction,\n" ^
      "	OnLoad				= OnLoad,\n" ^
      "	OnSave				= OnSave,\n" ^
      "	OnQueryProgress		= OnQueryProgress,\n" ^
      "	OnQueryPercentage	= OnQueryPercentage,\n" ^
      "	OnQueryDifficulty	= OnQueryDifficulty,\n" ^
      "	\n" ^
      "	CallbackConvA = CallbackConvA ,\n" ^
      "	CallbackConvB = CallbackConvB ,\n" ^
      "	CallbackConvC = CallbackConvC ,\n" ^
      "};\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n";
