  {
    id = "Q3D2";
    name_text = "[QUEST_Q3D2_NAME]";
    desc_text = "[QUEST_Q3D2_DESC]";
    group = "[QG_LODR_NAME]";
    text_file = "English\\Quests\\Q3D2_Text.xml";
    texts = [("[QUEST_Q3D2_ACTION]", "Enter Kelthurax's Lair"); ("[QUEST_Q3D2_ARRIVE]", "There are still no signs of any Dragons, and a huge Iron Golem blocks the way into Kelthurax's Lair."); ("[QUEST_Q3D2_FAILURE]", "You have failed to gain entry to the lair. You must try again."); ("[QUEST_Q3D2_NOELISTARA]", "You shouldn't enter without Elistara in your party!"); ("[QUEST_Q3D2_REWARD]", "You have helped Elistara fulfil her oath and deliver the message."); ("[QUEST_Q3D2_STEP1]", "You must travel to the Dragonrealm and gain entry to Kelthurax's Lair.")];
    lua_file = "Assets\\Quests\\Q3D2.lua";
    lua_object = "Q3D2";
    lua_source = "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--             Condolences	\n" ^
      "--	\n" ^
      "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--		STATES	\n" ^
      "--\n" ^
      "-- 0 => Inactive\n" ^
      "-- 1 => Quest obtained, nothing done yet\n" ^
      "-- 2 => Finished\n" ^
      "-- \n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Variables\n" ^
      "--\n" ^
      "local questState = 0;\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Constants\n" ^
      "--\n" ^
      "local myCode        = \"Q3D2\";\n" ^
      "local myLocation    = \"CDRH\";\n" ^
      "local myOrigin      = \"CYLA\";\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnInit				\n" ^
      "--		(called for every quest when they are loading\n" ^
      "--		 to set the initial state of all variables)\n" ^
      "--\n" ^
      "local function OnInit()\n" ^
      "	questState = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnBegin				\n" ^
      "--		(called when a quest is first obtained)\n" ^
      "--\n" ^
      "local function OnBegin()\n" ^
      "	questState = 1;\n" ^
      "	QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q3D2a.xml\",myOrigin);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnd				\n" ^
      "--		(called when a quest has ended)\n" ^
      "--\n" ^
      "local function OnEnd()\n" ^
      "	questState = 2;\n" ^
      "	\n" ^
      "	-- Reward\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q3D2_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[QUEST_Q3D2_REWARD]\");\n" ^
      "	QUEST_REWARD_MENU(myTitle,myMessage);\n" ^
      "	QUEST_REWARD_XP(200);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnAbandon				\n" ^
      "--		(called when a quest has been abandoned by the player)\n" ^
      "--\n" ^
      "local function OnAbandon()\n" ^
      "	questState = 0;\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnterLocation		\n" ^
      "--		(a hero has arrived at a new location)\n" ^
      "--\n" ^
      "local function OnEnterLocation(idLocation)\n" ^
      "	if (idLocation == myLocation) then\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_Q3D2_NAME]\");\n" ^
      "		local myMessage = GET_TEXT(\"[QUEST_Q3D2_ARRIVE]\");\n" ^
      "		QUEST_MESSAGE(myTitle,myMessage,idLocation);\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryAction\n" ^
      "--		(should anything appear on the popup menu)\n" ^
      "--\n" ^
      "local function OnQueryAction(idLocation)\n" ^
      "	if (idLocation==myLocation and questState==1) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q3D2_ACTION]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnExecuteAction				\n" ^
      "--		(do this whenever the player executes the next action)\n" ^
      "--\n" ^
      "local function OnExecuteAction(idLocation)\n" ^
      "	if (questState==1) then\n" ^
      "			QUEST_BATTLE(myCode,0,1);\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnCompleteAction				\n" ^
      "--		(do this whenever the player completes his action)\n" ^
      "--		It is called after the game has returned to the map screen\n" ^
      "--\n" ^
      "local function OnCompleteAction(idLocation, success)\n" ^
      "\n" ^
      "	if (questState==1) then\n" ^
      "	\n" ^
      "		local myMessage;\n" ^
      "		if (success == 1) then\n" ^
