    lua_source = "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--             Sign of Dragons	\n" ^
      "--	\n" ^
      "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--		STATES	\n" ^
      "--\n" ^
      "-- 0 => Inactive\n" ^
      "-- 1 => Quest obtained, nothing done yet\n" ^
      "-- 2 => Finished\n" ^
      "-- \n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Variables\n" ^
      "--\n" ^
      "local questState = 0;\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
