      "local function OnQueryAction(idLocation)\n" ^
      "	if (idLocation==myLocation and questState==1) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q3D3_ACTION]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnExecuteAction				\n" ^
      "--		(do this whenever the player executes the next action)\n" ^
      "--\n" ^
      "local function OnExecuteAction(idLocation)\n" ^
      "	if (questState==1) then\n" ^
      "		if (QUEST_HERO_HAS_COMPANION_SELECTED(\"NELI\")==1 and\n" ^
      "		    QUEST_HERO_HAS_COMPANION_SELECTED(\"NFLI\")==1) then\n" ^
      "			QUEST_BATTLE(myCode,0,1);\n" ^
