    texts = [("[QUEST_Q3I3_ACTION1]", "Battle the Undead"); ("[QUEST_Q3I3_ACTION2]", "Battle the Baneguard"); ("[QUEST_Q3I3_ACTION3]", "Report to Queen"); ("[QUEST_Q3I3_FAILURE1]", "You have failed to defeat the Undead. You will not be able to find the Elven captives until they are out of your way."); ("[QUEST_Q3I3_FAILURE2]", "You have failed to defeat the Baneguard."); ("[QUEST_Q3I3_MESSAGE1]", "You have walked into a trap. You are surrounded by the Undead."); ("[QUEST_Q3I3_PROGRESS1]", "Travel to the Iceguard Keep to pick up the trail left by the Undead."); ("[QUEST_Q3I3_PROGRESS2]", "The tracks left by the Undead lead you to the Lake of Blood. Travel there to find the Elven captives."); ("[QUEST_Q3I3_PROGRESS3]", "Return to Ehlariel and report the grim fate of the Elven captives."); ("[QUEST_Q3I3_REWARD]", "You have been rewarded for your effort on this dangerous mission. You are awarded the Iceguard."); ("[QUEST_Q3I3_SUCCESS1]", "You have defeated the Undead and uncovered a trail leading to the Lake of Blood. You need to follow this trail if you want to rescue the Elven captives."); ("[QUEST_Q3I3_SUCCESS2]", "You must return to Ehlariel and report the grim fate of the Elven captives."); ("[QUEST_Q3I3_QMNAME1]", "Baneguard"); ("[QUEST_Q3I3_QMHELP1]", "The Baneguard have more spells than a regular Doomknight.  They can cast Cleave and Bone Strike. They also have more Life Points and Battle skill.")];
    lua_file = "Assets\\Quests\\Q3I3.lua";
    lua_object = "Q3I3";
    lua_source = "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--             The Baneguard	\n" ^
      "--	\n" ^
      "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--		STATES	\n" ^
      "--\n" ^
      "-- 0 => Inactive\n" ^
      "-- 1 => Quest obtained, nothing done yet\n" ^
      "-- 2 => Killed Undead Arkliche\n" ^
      "-- 3 => Killed baneguard\n" ^
      "-- 4 => Finished (returned)\n" ^
      "-- \n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Variables\n" ^
      "--\n" ^
      "local questState = 0;\n" ^
      "local baneIntro  = 0;\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Constants\n" ^
      "--\n" ^
      "local myCode      = \"Q3I3\";\n" ^
      "local myLocation1 = \"WIGK\";\n" ^
      "local myLocation2 = \"WLOB\";\n" ^
      "local myOrigin    = \"CEHL\";\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnInit				\n" ^
      "--		(called for every quest when they are loading\n" ^
      "--		 to set the initial state of all variables)\n" ^
      "--\n" ^
      "local function OnInit()\n" ^
      "	questState = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnBegin				\n" ^
      "--		(called when a quest is first obtained)\n" ^
      "--\n" ^
      "local function OnBegin()\n" ^
      "	questState = 1;\n" ^
      "	QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q3I3a.xml\",myOrigin);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnd				\n" ^
      "--		(called when a quest has ended)\n" ^
      "--\n" ^
      "local function OnEnd()\n" ^
      "	questState = 4;\n" ^
      "	\n" ^
      "	-- Reward\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q3I3_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[QUEST_Q3I3_REWARD]\");\n" ^
      "	QUEST_REWARD_MENU(myTitle,myMessage);\n" ^
      "	QUEST_REWARD_GOLD(200);\n" ^
      "	QUEST_REWARD_XP(200);\n" ^
      "	QUEST_ADD_AWARD(\"AICE\");\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnAbandon				\n" ^
      "--		(called when a quest has been abandoned by the player)\n" ^
      "--\n" ^
      "local function OnAbandon()\n" ^
      "	questState=0;\n" ^
      "	baneIntro=0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnterLocation		\n" ^
      "--		(a hero has arrived at a new location)\n" ^
      "--\n" ^
      "local function OnEnterLocation(idLocation)\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q3I3_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[QUEST_Q3I3_MESSAGE1]\");\n" ^
      "	\n" ^
      "	if (idLocation==myLocation1 and questState==1) then\n" ^
      "		QUEST_MESSAGE(myTitle,myMessage,idLocation);\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryAction\n" ^
      "--		(should anything appear on the popup menu)\n" ^
      "--\n" ^
      "local function OnQueryAction(idLocation)\n" ^
      "	if (idLocation==myLocation1 and questState==1) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q3I3_ACTION1]\");\n" ^
      "	elseif (idLocation==myLocation2 and questState==2) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q3I3_ACTION2]\");\n" ^
      "	elseif (idLocation==myOrigin and questState==3) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q3I3_ACTION3]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnExecuteAction				\n" ^
      "--		(do this whenever the player executes the next action)\n" ^
      "--\n" ^
      "local function OnExecuteAction(idLocation)\n" ^
      "	if (questState==1) then\n" ^
      "		QUEST_BATTLE(myCode,0,1);\n" ^
      "	elseif (questState==2) then\n" ^
      "		if(baneIntro==0) then\n" ^
      "			QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q3I3b.xml\",idLocation);\n" ^
      "			--only plays conversation once.\n" ^
      "		else\n" ^
      "			QUEST_BATTLE(myCode,1,1);	\n" ^
      "		end\n" ^
      "	elseif (questState==3) then\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q3I3c.xml\",idLocation);\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnCompleteAction				\n" ^
      "--		(do this whenever the player completes his action)\n" ^
      "--		It is called after the game has returned to the map screen\n" ^
      "--\n" ^
      "local function OnCompleteAction(idLocation, success)\n" ^
      "		\n" ^
      "\n" ^
      "	if (questState==1) then\n" ^
      "	\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_Q3I3_NAME]\");\n" ^
      "		local myMessage;\n" ^
      "		if (success == 1) then\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_Q3I3_SUCCESS1]\");\n" ^
      "			questState = 2;\n" ^
      "			QUEST_COMPLETE_PART(myLocation1,1);\n" ^
      "			QUEST_SET_VISIBILITY(myLocation2,1);\n" ^
      "			QUEST_UPDATE_MAP();\n" ^
      "\n" ^
      "		else\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_Q3I3_FAILURE1]\");\n" ^
      "		end\n" ^
      "		QUEST_MESSAGE(myTitle,myMessage,idLocation);\n" ^
      "			\n" ^
      "	elseif (questState==2) then\n" ^
      "	\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_Q3I3_NAME]\");\n" ^
      "		local myMessage;\n" ^
      "		if (success == 1) then\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_Q3I3_SUCCESS2]\");\n" ^
      "			questState = 3;\n" ^
      "			QUEST_COMPLETE_PART(myLocation2,1);\n" ^
      "			QUEST_UPDATE_MAP();\n" ^
      "		else\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_Q3I3_FAILURE2]\");\n" ^
      "		end\n" ^
      "		baneIntro = 1;\n" ^
      "		QUEST_MESSAGE(myTitle,myMessage,idLocation);\n" ^
      "		\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnLoad				\n" ^
      "--		(a save game is being loaded)\n" ^
      "--\n" ^
      "local function OnLoad()\n" ^
      "	questState = QUEST_LOAD_INT();\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnSave				\n" ^
      "--		(a save game is being saved)\n" ^
      "--\n" ^
      "local function OnSave()\n" ^
      "	QUEST_SAVE_INT(questState);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryProgress		\n" ^
      "--		(returns text describing the next step required)\n" ^
      "--\n" ^
      "local function OnQueryProgress()\n" ^
      "	if (questState==1) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q3I3_PROGRESS1]\");\n" ^
      "	elseif (questState==2) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q3I3_PROGRESS2]\");\n" ^
      "	elseif (questState==3) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q3I3_PROGRESS3]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryPercentage	\n" ^
      "--		(returns a percentage of completion)\n" ^
      "--\n" ^
      "local function OnQueryPercentage()\n" ^
      "	return (questState - 1) * 33;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryDifficulty	\n" ^
      "--		(returns 0-4 for difficulty - v.easy to v.difficult )\n" ^
      "--\n" ^
      "local function OnQueryDifficulty()\n" ^
      "	-- average\n" ^
      "	return 2; \n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "\n" ^
      "local function CallbackConvA ()\n" ^
      "	questState = 1;\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackConvB ()\n" ^
      "	QUEST_BATTLE(myCode,1,1);\n" ^
      "\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackConvC ()\n" ^
      "	QUEST_COMPLETE(myCode);\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "--	\n" ^
      "--		DECLARE TABLE	\n" ^
      "--\n" ^
      "\n" ^
      "Q3I3 = {\n" ^
      "	OnInit				= OnInit,\n" ^
      "	OnBegin				= OnBegin,\n" ^
      "	OnEnd				= OnEnd,\n" ^
      "	OnAbandon			= OnAbandon,\n" ^
      "	OnEnterLocation		= OnEnterLocation,\n" ^
      "	OnExecuteAction		= OnExecuteAction,\n" ^
      "	OnCompleteAction	= OnCompleteAction,\n" ^
      "	OnQueryAction		= OnQueryAction,\n" ^
      "	OnLoad				= OnLoad,\n" ^
      "	OnSave				= OnSave,\n" ^
      "	OnQueryProgress		= OnQueryProgress,\n" ^
      "	OnQueryPercentage	= OnQueryPercentage,\n" ^
      "	OnQueryDifficulty	= OnQueryDifficulty,\n" ^
      "	\n" ^
      "	CallbackConvA = CallbackConvA,\n" ^
      "	CallbackConvB = CallbackConvB,\n" ^
      "	CallbackConvC = CallbackConvC,\n" ^
      "};\n" ^
      "\n" ^
