  {
    id = "Q3Q0";
    name_text = "[QUEST_Q3Q0_NAME]";
    desc_text = "[QUEST_Q3Q0_DESC]";
    group = "[QG_PRIM_NAME]";
    text_file = "English\\Quests\\Q3Q0_Text.xml";
    texts = [("[QUEST_Q3Q0_ACTION0]", "Fight the Doomknight"); ("[QUEST_Q3Q0_ACTION1]", "Cross the Pass"); ("[QUEST_Q3Q0_BANEMSG]", "A huge blizzard is blocking the way through the path, as is one of Lord Bane's Doomknights."); ("[QUEST_Q3Q0_FAILURE0]", "You have failed to defeat the Doomknight. You must try again."); ("[QUEST_Q3Q0_FAILURE1]", "The blizzard is too strong - you cannot cross the mountains."); ("[QUEST_Q3Q0_KILL]", "You have defeated the Doomknight, but a huge blizzard is blocking the pass."); ("[QUEST_Q3Q0_RETURN]", "Return to Tauron"); ("[QUEST_Q3Q0_REWARD]", "You have tried to cross Gornak's Gap and failed. There must be another way through."); ("[QUEST_Q3Q0_STEP1]", "You must cross the mountains through Gornak's Gap and travel to Lord Bane's citadel."); ("[QUEST_Q3Q0_STEP2]", "You must defeat one of Lord Bane's minions - a Doomknight - to try and cross the pass."); ("[QUEST_Q3Q0_STEP3]", "Gornak's Gap is blocked by a huge blizzard.  You must travel back to Tauron in Ohtar.")];
    lua_file = "Assets\\Quests\\Q3Q0.lua";
    lua_object = "Q3Q0";
    lua_source = "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--             Gornak&apos;s Gap	\n" ^
      "--	\n" ^
      "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--		STATES	\n" ^
      "--\n" ^
      "-- 0 => Inactive\n" ^
      "-- 1 => Quest obtained, nothing done yet\n" ^
      "-- 2 => Had Bane conv\n" ^
      "-- 3 => Monster defeated, must return\n" ^
      "-- 4 => Finished\n" ^
      "-- \n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Variables\n" ^
      "--\n" ^
      "local questState = 0;\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Constants\n" ^
      "--\n" ^
      "local myCode        = \"Q3Q0\";\n" ^
      "local myLocation    = \"WGGP\";\n" ^
      "local myOrigin      = \"COHT\";\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnInit				\n" ^
      "--		(called for every quest when they are loading\n" ^
      "--		 to set the initial state of all variables)\n" ^
      "--\n" ^
      "local function OnInit()\n" ^
      "	questState = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnBegin				\n" ^
      "--		(called when a quest is first obtained)\n" ^
      "--\n" ^
      "local function OnBegin()\n" ^
      "	questState = 1;\n" ^
      "	QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q3Q0a.xml\",myOrigin);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnd				\n" ^
      "--		(called when a quest has ended)\n" ^
      "--\n" ^
      "local function OnEnd()\n" ^
      "	questState = 3;\n" ^
      "	\n" ^
      "	-- Reward\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q3Q0_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[QUEST_Q3Q0_REWARD]\");\n" ^
      "	QUEST_REWARD_MENU(myTitle,myMessage);\n" ^
      "	QUEST_REWARD_XP(325);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnAbandon				\n" ^
      "--		(called when a quest has been abandoned by the player)\n" ^
      "--\n" ^
      "local function OnAbandon()\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnterLocation		\n" ^
      "--		(a hero has arrived at a new location)\n" ^
      "--\n" ^
      "local function OnEnterLocation(idLocation)\n" ^
      "	if (questState == 1 and idLocation == myLocation) then\n" ^
      "		QUEST_STOP_MOVEMENT();\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q3Q0b.xml\",idLocation);\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryAction\n" ^
      "--		(should anything appear on the popup menu)\n" ^
      "--\n" ^
      "local function OnQueryAction(idLocation)\n" ^
      "	if (idLocation==myLocation and questState==2) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q3Q0_ACTION0]\");\n" ^
      "	elseif (idLocation==myLocation and questState==3) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q3Q0_ACTION1]\");\n" ^
      "	elseif (idLocation==myOrigin and questState==3) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q3Q0_RETURN]\");\n" ^
      "	elseif (idLocation==\"CLBC\" and questState==1) then\n" ^
      "			return GET_TEXT(\"[ON]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnExecuteAction				\n" ^
      "--		(do this whenever the player executes the next action)\n" ^
      "--\n" ^
      "local function OnExecuteAction(idLocation)\n" ^
      "	if (questState==2) then\n" ^
      "		QUEST_BATTLE(myCode,0,1);\n" ^
      "	elseif (questState==3 and idLocation == myLocation) then\n" ^
      "		QUEST_MESSAGE(GET_TEXT(\"[QUEST_Q3Q0_NAME]\"),GET_TEXT(\"[QUEST_Q3Q0_FAILURE1]\"),idLocation);\n" ^
      "	elseif (questState==3 and idLocation == myOrigin) then\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q3Q0d.xml\",idLocation);\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnCompleteAction				\n" ^
      "--		(do this whenever the player completes his action)\n" ^
      "--		It is called after the game has returned to the map screen\n" ^
      "--\n" ^
      "local function OnCompleteAction(idLocation, success)\n" ^
      "\n" ^
      "	if (questState==2) then\n" ^
      "	\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_Q3Q0_NAME]\");\n" ^
      "		local myMessage;\n" ^
      "		if (success == 1) then\n" ^
      "			if (QUEST_HERO_HAS_COMPANION_SELECTED(\"NSUN\")==1) then\n" ^
      "				QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q3Q0c.xml\",idLocation);\n" ^
      "			else\n" ^
      "				QUEST_MESSAGE_CALLBACK(myTitle,GET_TEXT(\"[QUEST_Q3Q0_KILL]\"),idLocation,myCode,\"CallbackConvC\");\n" ^
      "			end\n" ^
      "		else\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_Q3Q0_FAILURE0]\");\n" ^
      "			QUEST_MESSAGE(myTitle,myMessage,myLocation);\n" ^
      "			QUEST_UPDATE_MAP();\n" ^
      "		end\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnLoad				\n" ^
      "--		(a save game is being loaded)\n" ^
      "--\n" ^
      "local function OnLoad()\n" ^
      "	questState = QUEST_LOAD_INT();\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnSave				\n" ^
      "--		(a save game is being saved)\n" ^
      "--\n" ^
      "local function OnSave()\n" ^
      "	QUEST_SAVE_INT(questState);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryProgress		\n" ^
      "--		(returns text describing the next step required)\n" ^
      "--\n" ^
      "local function OnQueryProgress()\n" ^
      "	if (questState == 1) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q3Q0_STEP1]\");\n" ^
      "	elseif (questState == 2) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q3Q0_STEP2]\");\n" ^
      "	elseif (questState == 3) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q3Q0_STEP3]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryPercentage	\n" ^
      "--		(returns a percentage of completion)\n" ^
      "--\n" ^
      "local function OnQueryPercentage()\n" ^
      "	return (questState-1)*33;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryDifficulty	\n" ^
      "--		(returns 0-4 for difficulty - v.easy to v.difficult )\n" ^
      "--\n" ^
      "local function OnQueryDifficulty()\n" ^
      "	-- average\n" ^
      "	return 2; \n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "\n" ^
      "local function CallbackConvA ()\n" ^
      "	questState = 1;\n" ^
      "\n" ^
      "	QUEST_SET_VISIBILITY(\"WSMZ\",1);\n" ^
      "	QUEST_SET_VISIBILITY(myLocation,1); -- Gornaks Gap\n" ^
      "	QUEST_SET_VISIBILITY(\"WGRW\",1);\n" ^
      "	QUEST_SET_VISIBILITY(\"WSOI\",1);\n" ^
      "	QUEST_SET_VISIBILITY(\"CLBC\",1);\n" ^
      "	QUEST_SET_CITY_STATUS(\"CLBC\",CITYSTATUS_CLOSED);\n" ^
      "\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackConvB ()\n" ^
      "	questState = 2;\n" ^
      "\n" ^
      "	QUEST_MESSAGE(GET_TEXT(\"[QUEST_Q3Q0_NAME]\"),GET_TEXT(\"[QUEST_Q3Q0_BANEMSG]\"),myLocation);\n" ^
      "	QUEST_SET_VISIBILITY(\"WGRW\",0);\n" ^
      "	QUEST_SET_VISIBILITY(\"WSOI\",0);\n" ^
      "	QUEST_SET_VISIBILITY(\"CLBC\",0);\n" ^
      "	QUEST_ENCOUNTER_REMOVE_AT(\"WGRW\",myLocation);\n" ^
      "	QUEST_ENCOUNTER_REMOVE_AT(\"CLBC\",\"WSOI\");\n" ^
      "\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackConvC ()\n" ^
      "	questState = 3;\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackConvD ()\n" ^
      "	QUEST_COMPLETE(myCode);\n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "--	\n" ^
      "--		DECLARE TABLE	\n" ^
      "--\n" ^
      "\n" ^
      "Q3Q0 = {\n" ^
      "	OnInit				= OnInit,\n" ^
      "	OnBegin				= OnBegin,\n" ^
      "	OnEnd				= OnEnd,\n" ^
      "	OnAbandon			= OnAbandon,\n" ^
      "	OnEnterLocation		= OnEnterLocation,\n" ^
      "	OnExecuteAction		= OnExecuteAction,\n" ^
      "	OnCompleteAction	= OnCompleteAction,\n" ^
      "	OnQueryAction		= OnQueryAction,\n" ^
      "	OnLoad				= OnLoad,\n" ^
      "	OnSave				= OnSave,\n" ^
      "	OnQueryProgress		= OnQueryProgress,\n" ^
      "	OnQueryPercentage	= OnQueryPercentage,\n" ^
      "	OnQueryDifficulty	= OnQueryDifficulty,\n" ^
      "	\n" ^
      "	CallbackConvA = CallbackConvA ,\n" ^
      "	CallbackConvB = CallbackConvB ,\n" ^
      "	CallbackConvC = CallbackConvC ,\n" ^
      "	CallbackConvD = CallbackConvD ,\n" ^
      "};\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n";
