    lua_source = "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--             Ylarie Defence	\n" ^
      "--	\n" ^
      "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--		STATES	\n" ^
      "--\n" ^
      "-- 0 => Inactive\n" ^
      "-- 1 => Quest obtained, nothing done yet\n" ^
      "-- 2 => Killed Monster #1\n" ^
      "-- 3 => Killed Monster #2\n" ^
      "-- 4 => Killed Monster #3\n" ^
      "-- 5 => Killed Monster #4 (finished)\n" ^
      "-- \n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Variables\n" ^
      "--\n" ^
      "local questState = 0;\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Constants\n" ^
      "--\n" ^
      "local myCode     = \"Q3Q2\";\n" ^
      "local myOrigin   = \"CYLA\";\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnInit				\n" ^
      "--		(called for every quest when they are loading\n" ^
      "--		 to set the initial state of all variables)\n" ^
      "--\n" ^
      "local function OnInit()\n" ^
      "	questState = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnBegin				\n" ^
      "--		(called when a quest is first obtained)\n" ^
      "--\n" ^
      "local function OnBegin()\n" ^
      "	questState = 1;\n" ^
      "	QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q3Q2a.xml\",myOrigin);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnd				\n" ^
      "--		(called when a quest has ended)\n" ^
      "--\n" ^
      "local function OnEnd()\n" ^
      "	questState = 5;\n" ^
      "	\n" ^
      "	-- Reward\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q3Q2_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[QUEST_Q3Q2_REWARD]\");\n" ^
      "	QUEST_REWARD_MENU(myTitle,myMessage);\n" ^
      "	QUEST_REWARD_GOLD(250);\n" ^
      "	QUEST_REWARD_XP(350);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnAbandon				\n" ^
      "--		(called when a quest has been abandoned by the player)\n" ^
      "--\n" ^
      "local function OnAbandon()\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnterLocation		\n" ^
      "--		(a hero has arrived at a new location)\n" ^
      "--\n" ^
      "local function OnEnterLocation(idLocation)\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryAction\n" ^
      "--		(should anything appear on the popup menu)\n" ^
      "--\n" ^
      "local function OnQueryAction(idLocation)\n" ^
      "	if (idLocation==myOrigin) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q3Q2_ACTION]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnExecuteAction				\n" ^
      "--		(do this whenever the player executes the next action)\n" ^
      "--\n" ^
      "local function OnExecuteAction(idLocation)\n" ^
      "	if (questState==1) then\n" ^
      "		QUEST_BATTLE(myCode,0,1);\n" ^
      "	elseif (questState==2) then\n" ^
      "		QUEST_BATTLE(myCode,1,1);\n" ^
      "	elseif (questState==3) then\n" ^
      "		QUEST_BATTLE(myCode,2,1);\n" ^
      "	elseif (questState==4) then\n" ^
      "		QUEST_BATTLE(myCode,3,1);\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnCompleteAction				\n" ^
      "--		(do this whenever the player completes his action)\n" ^
      "--		It is called after the game has returned to the map screen\n" ^
      "--\n" ^
      "local function OnCompleteAction(idLocation, success)\n" ^
      "	\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q3Q2_NAME]\");\n" ^
      "\n" ^
      "	if (success	== 0) then\n" ^
      "\n" ^
      "		local myMessage = GET_TEXT(\"[QUEST_Q3Q2_FAILURE]\");\n" ^
      "		QUEST_MESSAGE(myTitle,myMessage,idLocation);\n" ^
      "\n" ^
      "	elseif (questState==1) then\n" ^
      "	\n" ^
      "		local myMessage = GET_TEXT(\"[QUEST_Q3Q2_SUCCESS1]\");\n" ^
      "		QUEST_MESSAGE(myTitle,myMessage,idLocation);\n" ^
      "		questState = 2;\n" ^
      "		QUEST_UPDATE_MAP();\n" ^
      "			\n" ^
      "	elseif (questState==2) then\n" ^
      "	\n" ^
      "		local myMessage = GET_TEXT(\"[QUEST_Q3Q2_SUCCESS2]\");\n" ^
      "		QUEST_MESSAGE_CALLBACK(myTitle,myMessage,idLocation,myCode,\"CallbackMsg2\");\n" ^
      "		QUEST_UPDATE_MAP();\n" ^
      "		\n" ^
      "	elseif (questState==3) then\n" ^
      "	\n" ^
      "		local myMessage = GET_TEXT(\"[QUEST_Q3Q2_SUCCESS3]\");\n" ^
      "		QUEST_MESSAGE_CALLBACK(myTitle,myMessage,idLocation,myCode,\"CallbackMsg3\");\n" ^
      "		QUEST_UPDATE_MAP();\n" ^
      "		\n" ^
      "	elseif (questState==4) then\n" ^
      "	\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q3Q2d.xml\",myOrigin);\n" ^
      "		\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnLoad				\n" ^
      "--		(a save game is being loaded)\n" ^
      "--\n" ^
      "local function OnLoad()\n" ^
      "	questState = QUEST_LOAD_INT();\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnSave				\n" ^
      "--		(a save game is being saved)\n" ^
      "--\n" ^
      "local function OnSave()\n" ^
      "	QUEST_SAVE_INT(questState);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryProgress		\n" ^
      "--		(returns text describing the next step required)\n" ^
      "--\n" ^
      "local function OnQueryProgress()\n" ^
      "	return GET_TEXT(\"[QUEST_Q3Q2_PROGRESS1]\");\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryPercentage	\n" ^
      "--		(returns a percentage of completion)\n" ^
      "--\n" ^
      "local function OnQueryPercentage()\n" ^
      "	return (questState - 1) * 25;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryDifficulty	\n" ^
      "--		(returns 0-4 for difficulty - v.easy to v.difficult )\n" ^
      "--\n" ^
      "local function OnQueryDifficulty()\n" ^
      "	-- average\n" ^
      "	return 2; \n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "\n" ^
      "local function CallbackConvA ()\n" ^
      "\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q3Q2_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[QUEST_Q3Q2_PROGRESS1]\");\n" ^
      "	QUEST_MESSAGE(myTitle,myMessage,myOrigin);\n" ^
      "\n" ^
      "	questState = 1;\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackConvB ()\n" ^
      "	questState = 3;\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "local function CallbackConvC ()\n" ^
      "	questState = 4;\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "local function CallbackConvD ()\n" ^
      "	QUEST_COMPLETE(myCode);\n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "local function CallbackMsg2 ()\n" ^
      "	QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q3Q2b.xml\",myOrigin);\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackMsg3 ()\n" ^
      "	if (QUEST_HERO_HAS_COMPANION_SELECTED(\"NDKH\")==1) then\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q3Q2c.xml\",myOrigin);\n" ^
      "	else\n" ^
      "		questState = 4;\n" ^
      "		QUEST_UPDATE_MAP();\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "--	\n" ^
      "--		DECLARE TABLE	\n" ^
      "--\n" ^
      "\n" ^
      "Q3Q2 = {\n" ^
      "	OnInit				= OnInit,\n" ^
      "	OnBegin				= OnBegin,\n" ^
      "	OnEnd				= OnEnd,\n" ^
      "	OnAbandon			= OnAbandon,\n" ^
      "	OnEnterLocation		= OnEnterLocation,\n" ^
      "	OnExecuteAction		= OnExecuteAction,\n" ^
      "	OnCompleteAction	= OnCompleteAction,\n" ^
      "	OnQueryAction		= OnQueryAction,\n" ^
      "	OnLoad				= OnLoad,\n" ^
      "	OnSave				= OnSave,\n" ^
      "	OnQueryProgress		= OnQueryProgress,\n" ^
      "	OnQueryPercentage	= OnQueryPercentage,\n" ^
      "	OnQueryDifficulty	= OnQueryDifficulty,\n" ^
      "	\n" ^
      "	CallbackConvA = CallbackConvA,\n" ^
      "	CallbackConvB = CallbackConvB,\n" ^
      "	CallbackConvC = CallbackConvC,\n" ^
      "	CallbackConvD = CallbackConvD,\n" ^
      "\n" ^
      "	CallbackMsg2 = CallbackMsg2,\n" ^
      "	CallbackMsg3 = CallbackMsg3,\n" ^
      "};\n" ^
      "\n" ^
      "\n" ^
