    texts = [("[QUEST_Q3Q5_ACTION]", "Battle a Necromancer"); ("[QUEST_Q3Q5_DHLEAVE]", "Darkhunter has left your party."); ("[QUEST_Q3Q5_FAILURE]", "You have failed to defeat the Necromancer. You must try again."); ("[QUEST_Q3Q5_KILL]", "You have defeated one of Lord Bane's Generals.  When all three are done, the way to Lord Bane's citadel will be clear."); ("[QUEST_Q3Q5_RETURN]", "N/A"); ("[QUEST_Q3Q5_REWARD]", "You have cleared the way to Lord Bane's citadel."); ("[QUEST_Q3Q5_STEP1]", "You must travel into the Realms of Death, find Lord Bane's three Generals, and defeat them."); ("[QUEST_Q3Q5_STEP2]", "You must continue battling Lord Bane's Generals - the three Necromancers, until they have all been defeated.")];
    lua_file = "Assets\\Quests\\Q3Q5.lua";
    lua_object = "Q3Q5";
    lua_source = "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--             Three Skulls	\n" ^
      "--	\n" ^
      "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--		STATES	\n" ^
      "--\n" ^
      "-- 0 => Inactive\n" ^
      "-- 1 => Quest obtained, nothing done yet\n" ^
      "-- 2 => Some necros slain\n" ^
      "-- 3 => Finished\n" ^
      "-- \n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Variables\n" ^
      "--\n" ^
      "local questState = 0;\n" ^
      "local doneNecro1 = 0;\n" ^
      "local doneNecro2 = 0;\n" ^
      "local doneNecro3 = 0;\n" ^
      "local triedNecro1 = 0;\n" ^
      "local triedNecro2 = 0;\n" ^
      "local triedNecro3 = 0;\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Constants\n" ^
      "--\n" ^
      "local myCode        = \"Q3Q5\";\n" ^
      "local myLocation1   = \"WBBR\";\n" ^
      "local myLocation2   = \"WLOB\";\n" ^
      "local myLocation3   = \"WSOI\";\n" ^
      "local myOrigin      = \"CYLA\";\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnInit				\n" ^
      "--		(called for every quest when they are loading\n" ^
      "--		 to set the initial state of all variables)\n" ^
      "--\n" ^
      "local function OnInit()\n" ^
      "	questState = 0;\n" ^
      "	doneNecro1 = 0;\n" ^
      "	doneNecro2 = 0;\n" ^
      "	doneNecro3 = 0;\n" ^
      "	triedNecro1 = 0;\n" ^
      "	triedNecro2 = 0;\n" ^
      "	triedNecro3 = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnBegin				\n" ^
      "--		(called when a quest is first obtained)\n" ^
      "--\n" ^
      "local function OnBegin()\n" ^
      "	questState = 1;\n" ^
      "	doneNecro1 = 0;\n" ^
      "	doneNecro2 = 0;\n" ^
      "	doneNecro3 = 0;\n" ^
      "	triedNecro1 = 0;\n" ^
      "	triedNecro2 = 0;\n" ^
      "	triedNecro3 = 0;\n" ^
      "	QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q3Q5a.xml\",myOrigin);\n" ^
      "	\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnd				\n" ^
      "--		(called when a quest has ended)\n" ^
      "--\n" ^
      "local function OnEnd()\n" ^
      "	questState = 3;\n" ^
      "	\n" ^
      "	-- Reward\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q3Q5_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[QUEST_Q3Q5_REWARD]\");\n" ^
      "	QUEST_REWARD_MENU(myTitle,myMessage);\n" ^
      "	QUEST_REWARD_GOLD(200);\n" ^
      "	QUEST_REWARD_XP(450);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnAbandon				\n" ^
      "--		(called when a quest has been abandoned by the player)\n" ^
      "--\n" ^
      "local function OnAbandon()\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnterLocation		\n" ^
      "--		(a hero has arrived at a new location)\n" ^
      "--\n" ^
      "local function OnEnterLocation(idLocation)\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryAction\n" ^
      "--		(should anything appear on the popup menu)\n" ^
      "--\n" ^
      "local function OnQueryAction(idLocation)\n" ^
      "	if (idLocation==myLocation1 and doneNecro1==0) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q3Q5_ACTION]\");\n" ^
      "	elseif (idLocation==myLocation2 and doneNecro2==0) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q3Q5_ACTION]\");\n" ^
      "	elseif (idLocation==myLocation3 and doneNecro3==0) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q3Q5_ACTION]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnExecuteAction				\n" ^
      "--		(do this whenever the player executes the next action)\n" ^
      "--\n" ^
      "local function OnExecuteAction(idLocation)\n" ^
      "	if (idLocation==myLocation1 and doneNecro1==0) then\n" ^
      "		if (triedNecro1 == 1) then\n" ^
      "			QUEST_BATTLE(myCode,0,1);\n" ^
      "		elseif (QUEST_HERO_HAS_ITEM(\"ISES\")==0) then\n" ^
      "			QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q3Q5b.xml\",idLocation);\n" ^
      "		else\n" ^
      "			QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q3Q5bb.xml\",idLocation);\n" ^
      "		end\n" ^
      "	elseif (idLocation==myLocation2 and doneNecro2==0) then\n" ^
      "		if (triedNecro2 == 1) then\n" ^
      "			QUEST_BATTLE(myCode,0,1);\n" ^
      "		elseif (QUEST_HERO_HAS_ITEM(\"ISES\")==0) then\n" ^
      "			QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q3Q5c.xml\",idLocation);\n" ^
      "		else\n" ^
      "			QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q3Q5cc.xml\",idLocation);\n" ^
      "		end\n" ^
      "	elseif (idLocation==myLocation3 and doneNecro3==0) then\n" ^
      "		if (triedNecro3 == 1) then\n" ^
      "			QUEST_BATTLE(myCode,0,1);\n" ^
      "		elseif (QUEST_HERO_HAS_ITEM(\"ISES\")==0) then\n" ^
      "			QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q3Q5d.xml\",idLocation);\n" ^
      "		else\n" ^
      "			QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q3Q5dd.xml\",idLocation);\n" ^
      "		end\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnCompleteAction				\n" ^
      "--		(do this whenever the player completes his action)\n" ^
      "--		It is called after the game has returned to the map screen\n" ^
      "--\n" ^
      "local function OnCompleteAction(idLocation, success)\n" ^
      "\n" ^
      "\n" ^
      "	if (questState==1 or questState==2) then\n" ^
      "	\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_Q3Q5_NAME]\");\n" ^
      "		local myMessage;\n" ^
      "\n" ^
      "		if (success == 0) then\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_Q3Q5_FAILURE]\");\n" ^
      "			QUEST_MESSAGE(myTitle,myMessage,idLocation);\n" ^
      "			QUEST_UPDATE_MAP();\n" ^
      "		else --  I  WON\n" ^
      "			if (idLocation == myLocation1) then\n" ^
      "				doneNecro1 = 1;\n" ^
      "			elseif (idLocation == myLocation2) then\n" ^
      "				doneNecro2 = 1;\n" ^
      "			elseif (idLocation == myLocation3) then\n" ^
      "				doneNecro3 = 1;\n" ^
      "			end\n" ^
      "\n" ^
      "			if (doneNecro1==1 and doneNecro2==1 and doneNecro3==1) then\n" ^
      "				-- Finish\n" ^
      "				if (QUEST_HERO_HAS_ITEM(\"ISES\")==1 and\n" ^
      "				    QUEST_HERO_HAS_COMPANION_SELECTED(\"NDKH\")==1) then\n" ^
      "					QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q3Q5e.xml\",idLocation);\n" ^
      "				elseif (QUEST_HERO_HAS_ITEM(\"ISES\")==1) then\n" ^
      "					QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q3Q5ff.xml\",idLocation);\n" ^
      "				else\n" ^
      "					QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q3Q5f.xml\",idLocation);\n" ^
      "				end\n" ^
      "			else\n" ^
      "				-- Continue\n" ^
      "				questState = 2;\n" ^
      "				myMessage = GET_TEXT(\"[QUEST_Q3Q5_KILL]\");\n" ^
      "				QUEST_MESSAGE(myTitle,myMessage,idLocation);\n" ^
      "				QUEST_UPDATE_MAP();\n" ^
      "			end\n" ^
      "		end\n" ^
      "	\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnLoad				\n" ^
      "--		(a save game is being loaded)\n" ^
      "--\n" ^
      "local function OnLoad()\n" ^
      "	questState = QUEST_LOAD_INT();\n" ^
      "	doneNecro1 = QUEST_LOAD_INT();\n" ^
      "	doneNecro2 = QUEST_LOAD_INT();\n" ^
      "	doneNecro3 = QUEST_LOAD_INT();\n" ^
      "	triedNecro1 = QUEST_LOAD_INT();\n" ^
      "	triedNecro2 = QUEST_LOAD_INT();\n" ^
      "	triedNecro3 = QUEST_LOAD_INT();\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnSave				\n" ^
      "--		(a save game is being saved)\n" ^
      "--\n" ^
      "local function OnSave()\n" ^
      "	QUEST_SAVE_INT(questState);\n" ^
      "	QUEST_SAVE_INT(doneNecro1);\n" ^
      "	QUEST_SAVE_INT(doneNecro2);\n" ^
      "	QUEST_SAVE_INT(doneNecro3);\n" ^
      "	QUEST_SAVE_INT(triedNecro1);\n" ^
      "	QUEST_SAVE_INT(triedNecro2);\n" ^
      "	QUEST_SAVE_INT(triedNecro3);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryProgress		\n" ^
      "--		(returns text describing the next step required)\n" ^
      "--\n" ^
      "local function OnQueryProgress()\n" ^
      "	if (questState == 1) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q3Q5_STEP1]\");\n" ^
      "	elseif (questState == 2) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q3Q5_STEP2]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryPercentage	\n" ^
      "--		(returns a percentage of completion)\n" ^
      "--\n" ^
      "local function OnQueryPercentage()\n" ^
      "	if (questState <= 2) then\n" ^
      "		return doneNecro1*33 + doneNecro2*33 + doneNecro3*33;\n" ^
      "	end\n" ^
      "	return 100;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryDifficulty	\n" ^
      "--		(returns 0-4 for difficulty - v.easy to v.difficult )\n" ^
      "--\n" ^
      "local function OnQueryDifficulty()\n" ^
      "	-- average\n" ^
      "	return 3; \n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "\n" ^
      "local function CallbackConvA ()\n" ^
      "	questState = 1;\n" ^
      "	QUEST_SET_VISIBILITY(\"WTIR\",1);\n" ^
      "	QUEST_SET_VISIBILITY(\"WIGK\",1);\n" ^
      "	QUEST_SET_VISIBILITY(\"WLOB\",1);\n" ^
      "	QUEST_SET_VISIBILITY(\"CLBC\",1);\n" ^
      "	QUEST_SET_VISIBILITY(\"WSOI\",1);\n" ^
      "	QUEST_SET_VISIBILITY(\"WGRW\",1);\n" ^
      "	QUEST_SET_CITY_STATUS(\"CLBC\",CITYSTATUS_CLOSED);\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackConvB ()\n" ^
      "	triedNecro1 = 1;\n" ^
      "	QUEST_BATTLE(myCode,0,1);\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackConvC ()\n" ^
      "	triedNecro2 = 1;\n" ^
      "	QUEST_BATTLE(myCode,0,1);\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackConvD ()\n" ^
      "	triedNecro3 = 1;\n" ^
      "	QUEST_BATTLE(myCode,0,1);\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackConvE ()\n" ^
      "	QUEST_REMOVE_COMPANION(\"NDKH\");\n" ^
      "\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q3Q5_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[QUEST_Q3Q5_DHLEAVE]\");\n" ^
      "	QUEST_MESSAGE_CALLBACK(myTitle,myMessage,\"CLBC\",myCode,\"CallbackMsgE\");\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackConvF ()\n" ^
      "	QUEST_SET_CITY_STATUS(\"CLBC\",CITYSTATUS_CLOSEDWITHQUESTS);\n" ^
      "	QUEST_COMPLETE(myCode);\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackMsgE ()\n" ^
      "	QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q3Q5ff.xml\",\"CLBC\");\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "--	\n" ^
      "--		DECLARE TABLE	\n" ^
      "--\n" ^
      "\n" ^
      "Q3Q5 = {\n" ^
      "	OnInit				= OnInit,\n" ^
      "	OnBegin				= OnBegin,\n" ^
      "	OnEnd				= OnEnd,\n" ^
      "	OnAbandon			= OnAbandon,\n" ^
      "	OnEnterLocation		= OnEnterLocation,\n" ^
      "	OnExecuteAction		= OnExecuteAction,\n" ^
      "	OnCompleteAction	= OnCompleteAction,\n" ^
      "	OnQueryAction		= OnQueryAction,\n" ^
      "	OnLoad				= OnLoad,\n" ^
      "	OnSave				= OnSave,\n" ^
      "	OnQueryProgress		= OnQueryProgress,\n" ^
      "	OnQueryPercentage	= OnQueryPercentage,\n" ^
      "	OnQueryDifficulty	= OnQueryDifficulty,\n" ^
      "	\n" ^
      "	CallbackConvA = CallbackConvA ,\n" ^
      "	CallbackConvB = CallbackConvB ,\n" ^
      "	CallbackConvC = CallbackConvC ,\n" ^
      "	CallbackConvD = CallbackConvD ,\n" ^
      "	CallbackConvE = CallbackConvE ,\n" ^
      "	CallbackConvF = CallbackConvF ,\n" ^
      "	CallbackMsgE = CallbackMsgE ,\n" ^
      "};\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
