  {
    id = "Q3S0";
    name_text = "[QUEST_Q3S0_NAME]";
    desc_text = "[QUEST_Q3S0_DESC]";
    group = "[QG_PRIM_NAME]";
    text_file = "English\\Quests\\Q3S0_Text.xml";
    texts = [("[QUEST_Q3S0_ABANDON]", "Put the Sword Away"); ("[QUEST_Q3S0_ACTION]", "Point the Sword"); ("[QUEST_Q3S0_DRINK]", "Drink from the Bloodspring"); ("[QUEST_Q3S0_IMMORTAL]", "You feel a surge of power pass through your body. You feel like a God!"); ("[QUEST_Q3S0_LEAVE0]", "Serephine has left the party."); ("[QUEST_Q3S0_LEAVE1]", "Winter has left the party."); ("[QUEST_Q3S0_LEAVE2]", "Khalkus has left the party."); ("[QUEST_Q3S0_LEAVE3]", "Flicker has left the party."); ("[QUEST_Q3S0_LEAVE4]", "Elistara has left the party."); ("[QUEST_Q3S0_REWARD]", "You have tasted the Bloodspring. You receive the Award: Immortality."); ("[QUEST_Q3S0_STEP0]", "Use your sword at Bane's Citadel to see where it points."); ("[QUEST_Q3S0_STEP1]", "Use your sword at the Lake of Blood to see where it points."); ("[QUEST_Q3S0_STEP2]", "Use your sword at Kal-Ungar to see where it points."); ("[QUEST_Q3S0_STEP3]", "Use your sword at the Wasteland to see where it points."); ("[QUEST_Q3S0_STEP4]", "Use your sword in the Hidden Valley to see where it points."); ("[QUEST_Q3S0_STEP5]", "Drink from the Bloodspring to gain this mysterious power."); ("[QUEST_Q3S0_SWORD0]", "Your Sword is pointing towards the Lake of Blood."); ("[QUEST_Q3S0_SWORD1]", "Your Sword is pointing towards the Dark Dwarven citadel of Kal-Ungar."); ("[QUEST_Q3S0_SWORD2]", "Your Sword is pointing towards the Wasteland."); ("[QUEST_Q3S0_SWORD3]", "Your Sword is pointing towards a Hidden Valley."); ("[QUEST_Q3S0_SWORD4]", "Your Sword is pointing towards the Bloodspring - the source of the Lake of Blood.")];
    lua_file = "Assets\\Quests\\Q3S0.lua";
    lua_object = "Q3S0";
    lua_source = "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--            Follow The Sword	\n" ^
      "--	\n" ^
      "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--		STATES	\n" ^
      "--\n" ^
      "-- 0 => Inactive\n" ^
      "-- 1 => Quest obtained, nothing done yet\n" ^
      "-- 2 => 'Pointed Sword' at Bane's Citadel\n" ^
      "-- 3 => 'Pointed Sword' at the Lake of Blood\n" ^
      "-- 4 => 'Pointed Sword' at Kal-Ungar\n" ^
      "-- 5 => 'Pointed Sword' at the Wasteland\n" ^
      "-- 6 => 'Pointed Sword' at the Hidden Valley\n" ^
      "-- 7 => 'Had a drink' at the Bloodspring\n" ^
      "-- 8 => Finished (had a drink)\n" ^
      "-- \n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Variables\n" ^
      "--\n" ^
      "local questState = 0;\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Constants\n" ^
      "--\n" ^
      "local myCode        = \"Q3S0\";\n" ^
      "local myOrigin      = \"CLBC\";\n" ^
      "local myLocation1   = \"WLOB\";\n" ^
      "local myLocation2   = \"CKUN\";\n" ^
      "local myLocation3   = \"WWAS\";\n" ^
      "local myLocation4   = \"WHVA\";\n" ^
      "local myLocation5   = \"WBSP\";\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnInit				\n" ^
      "--		(called for every quest when they are loading\n" ^
      "--		 to set the initial state of all variables)\n" ^
      "--\n" ^
      "local function OnInit()\n" ^
      "	questState = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnBegin				\n" ^
      "--		(called when a quest is first obtained)\n" ^
      "--\n" ^
      "local function OnBegin()\n" ^
      "\n" ^
      "	questState = 1;\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnd				\n" ^
      "--		(called when a quest has ended)\n" ^
      "--\n" ^
      "local function OnEnd()\n" ^
      "	questState = 8;\n" ^
      "	\n" ^
      "	-- Reward\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q3S0_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[QUEST_Q3S0_REWARD]\");\n" ^
      "	QUEST_REWARD_MENU(myTitle,myMessage);\n" ^
      "	QUEST_REWARD_XP(1000);\n" ^
      "\n" ^
      "	QUEST_ADD_AWARD(\"AIMM\");\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnAbandon				\n" ^
      "--		(called when a quest has been abandoned by the player)\n" ^
      "--\n" ^
      "local function OnAbandon()\n" ^
      "	questState = 0;\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnterLocation		\n" ^
      "--		(a hero has arrived at a new location)\n" ^
      "--\n" ^
      "local function OnEnterLocation(idLocation)\n" ^
      "	if (questState == 2 and idLocation == myLocation1) then	\n" ^
      "\n" ^
      "		if (QUEST_HERO_HAS_COMPANION_SELECTED(\"NSER\")==1) then\n" ^
      "			local myTitle = GET_TEXT(\"[QUEST_Q3S0_NAME]\");\n" ^
      "			local myMessage = GET_TEXT(\"[QUEST_Q3S0_LEAVE0]\");\n" ^
      "			QUEST_MESSAGE(myTitle, myMessage, myLocation1);\n" ^
      "			QUEST_REMOVE_COMPANION(\"NSER\");\n" ^
      "		end\n" ^
      "\n" ^
      "	elseif (questState == 3 and idLocation == myLocation2) then\n" ^
      "		\n" ^
      "\n" ^
      "		if (QUEST_HERO_HAS_COMPANION_SELECTED(\"NWIN\")==1) then\n" ^
      "			local myTitle = GET_TEXT(\"[QUEST_Q3S0_NAME]\");\n" ^
      "			local myMessage = GET_TEXT(\"[QUEST_Q3S0_LEAVE1]\");\n" ^
      "			QUEST_MESSAGE(myTitle, myMessage, myLocation2);\n" ^
      "			QUEST_REMOVE_COMPANION(\"NWIN\");\n" ^
      "		end\n" ^
      "\n" ^
      "	elseif (questState == 4 and idLocation == myLocation3) then\n" ^
      "		\n" ^
      "\n" ^
      "		if (QUEST_HERO_HAS_COMPANION_SELECTED(\"NKHA\")==1) then\n" ^
      "			local myTitle = GET_TEXT(\"[QUEST_Q3S0_NAME]\");\n" ^
      "			local myMessage = GET_TEXT(\"[QUEST_Q3S0_LEAVE2]\");\n" ^
      "			QUEST_MESSAGE(myTitle, myMessage, myLocation3);\n" ^
      "			QUEST_REMOVE_COMPANION(\"NKHA\");\n" ^
      "		end\n" ^
      "\n" ^
      "	elseif (questState == 5 and idLocation == myLocation4) then\n" ^
      "		\n" ^
      "\n" ^
      "		if (QUEST_HERO_HAS_COMPANION_SELECTED(\"NFLI\")==1) then\n" ^
      "			local myTitle = GET_TEXT(\"[QUEST_Q3S0_NAME]\");\n" ^
      "			local myMessage = GET_TEXT(\"[QUEST_Q3S0_LEAVE3]\");\n" ^
      "			QUEST_MESSAGE(myTitle, myMessage, myLocation4);\n" ^
      "			QUEST_REMOVE_COMPANION(\"NFLI\");\n" ^
      "		end\n" ^
      "\n" ^
      "	elseif (questState == 6 and idLocation == myLocation5) then\n" ^
      "		\n" ^
      "\n" ^
      "		if (QUEST_HERO_HAS_COMPANION_SELECTED(\"NELI\")==1) then\n" ^
      "			local myTitle = GET_TEXT(\"[QUEST_Q3S0_NAME]\");\n" ^
      "			local myMessage = GET_TEXT(\"[QUEST_Q3S0_LEAVE4]\");\n" ^
      "			QUEST_MESSAGE(myTitle, myMessage, myLocation5);\n" ^
      "			QUEST_REMOVE_COMPANION(\"NELI\");\n" ^
      "		end\n" ^
      "\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryAction\n" ^
      "--		(should anything appear on the popup menu)\n" ^
      "--\n" ^
      "local function OnQueryAction(idLocation)\n" ^
      "	if (idLocation==myOrigin and questState==1) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q3S0_ACTION]\");\n" ^
      "	elseif (idLocation==myLocation1 and questState==2) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q3S0_ACTION]\");\n" ^
      "	elseif (idLocation==myLocation2 and questState==3) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q3S0_ACTION]\");\n" ^
      "	elseif (idLocation==myLocation3 and questState==4) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q3S0_ACTION]\");\n" ^
      "	elseif (idLocation==myLocation4 and questState==5) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q3S0_ACTION]\");\n" ^
      "	elseif (idLocation==myLocation5 and questState==6) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q3S0_DRINK]\");\n" ^
      "	elseif (idLocation==myOrigin and questState>1) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q3S0_ABANDON]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnExecuteAction				\n" ^
      "--		(do this whenever the player executes the next action)\n" ^
      "--\n" ^
      "local function OnExecuteAction(idLocation)\n" ^
      "\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q3S0_NAME]\");\n" ^
      "\n" ^
      "	if (idLocation==myOrigin and questState==1) then\n" ^
      "		questState = 2;\n" ^
      "		local myMessage = GET_TEXT(\"[QUEST_Q3S0_SWORD0]\");\n" ^
      "		QUEST_MESSAGE_CALLBACK(myTitle, myMessage, idLocation, myCode, \"CallbackMsgA\");\n" ^
      "		QUEST_SET_VISIBILITY(myLocation1,1);\n" ^
      "	elseif (idLocation==myLocation1 and questState==2) then\n" ^
      "		questState = 3;\n" ^
      "		local myMessage = GET_TEXT(\"[QUEST_Q3S0_SWORD1]\");\n" ^
      "		QUEST_MESSAGE_CALLBACK(myTitle, myMessage, idLocation, myCode, \"CallbackMsgB\");\n" ^
      "		QUEST_SET_VISIBILITY(myLocation2,1);\n" ^
      "	elseif (idLocation==myLocation2 and questState==3) then\n" ^
      "		questState = 4;\n" ^
      "		local myMessage = GET_TEXT(\"[QUEST_Q3S0_SWORD2]\");\n" ^
      "		QUEST_MESSAGE_CALLBACK(myTitle, myMessage, idLocation, myCode, \"CallbackMsgC\");\n" ^
      "		QUEST_SET_VISIBILITY(myLocation3,1);\n" ^
      "	elseif (idLocation==myLocation3 and questState==4) then\n" ^
      "		questState = 5;\n" ^
      "		local myMessage = GET_TEXT(\"[QUEST_Q3S0_SWORD3]\");\n" ^
      "		QUEST_MESSAGE_CALLBACK(myTitle, myMessage, idLocation, myCode, \"CallbackMsgD\");\n" ^
      "		QUEST_SET_VISIBILITY(myLocation4,1);\n" ^
      "	elseif (idLocation==myLocation4 and questState==5) then\n" ^
      "		questState = 6;\n" ^
      "		local myMessage = GET_TEXT(\"[QUEST_Q3S0_SWORD4]\");\n" ^
      "		QUEST_MESSAGE_CALLBACK(myTitle, myMessage, idLocation, myCode, \"CallbackMsgE\");\n" ^
      "		QUEST_SET_VISIBILITY(myLocation5,1);\n" ^
      "	elseif (idLocation==myLocation5 and questState==6) then\n" ^
      "		questState = 7;\n" ^
      "		local myMessage = GET_TEXT(\"[QUEST_Q3S0_IMMORTAL]\");\n" ^
      "		QUEST_MESSAGE_CALLBACK(myTitle, myMessage, idLocation, myCode, \"CallbackMsg\");\n" ^
      "	elseif (idLocation==myOrigin and questState>1) then\n" ^
      "		QUEST_ABANDON(myCode);\n" ^
      "	end\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnCompleteAction				\n" ^
      "--		(do this whenever the player completes his action)\n" ^
      "--		It is called after the game has returned to the map screen\n" ^
      "--\n" ^
      "local function OnCompleteAction(idLocation, success)\n" ^
      "\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnLoad				\n" ^
      "--		(a save game is being loaded)\n" ^
      "--\n" ^
      "local function OnLoad()\n" ^
      "	questState = QUEST_LOAD_INT();\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnSave				\n" ^
      "--		(a save game is being saved)\n" ^
      "--\n" ^
      "local function OnSave()\n" ^
      "	QUEST_SAVE_INT(questState);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryProgress		\n" ^
      "--		(returns text describing the next step required)\n" ^
      "--\n" ^
      "local function OnQueryProgress()\n" ^
      "	if (questState == 1) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q3S0_STEP0]\");\n" ^
      "	elseif (questState == 2) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q3S0_STEP1]\");\n" ^
      "	elseif (questState == 3) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q3S0_STEP2]\");\n" ^
      "	elseif (questState == 4) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q3S0_STEP3]\");\n" ^
      "	elseif (questState == 5) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q3S0_STEP4]\");\n" ^
      "	elseif (questState == 6) then\n" ^
      "		return GET_TEXT(\"[QUEST_Q3S0_STEP5]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryPercentage	\n" ^
      "--		(returns a percentage of completion)\n" ^
      "--\n" ^
      "local function OnQueryPercentage()\n" ^
      "	return (questState-1)*16;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryDifficulty	\n" ^
      "--		(returns 0-4 for difficulty - v.easy to v.difficult )\n" ^
      "--\n" ^
      "local function OnQueryDifficulty()\n" ^
      "	-- average\n" ^
      "	return 2; \n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "\n" ^
      "local function CallbackMsg ()\n" ^
      "	QUEST_COMPLETE(myCode);\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackMsgA ()\n" ^
      "	if (QUEST_HERO_HAS_COMPANION_SELECTED(\"NSER\")==1) then\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q3S0a.xml\",myOrigin);	\n" ^
      "		\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackMsgB ()\n" ^
      "	if (QUEST_HERO_HAS_COMPANION_SELECTED(\"NWIN\")==1) then\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q3S0b.xml\",myLocation1);	\n" ^
      "		\n" ^
      "	end\n" ^
      "\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackMsgC ()\n" ^
      "	if (QUEST_HERO_HAS_COMPANION_SELECTED(\"NKHA\")==1) then\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q3S0c.xml\",myLocation2);	\n" ^
      "		\n" ^
      "	end\n" ^
      "\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackMsgD ()\n" ^
      "	if (QUEST_HERO_HAS_COMPANION_SELECTED(\"NFLI\")==1) then\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q3S0d.xml\",myLocation3);	\n" ^
      "		\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackMsgE ()\n" ^
      "	if (QUEST_HERO_HAS_COMPANION_SELECTED(\"NELI\")==1) then\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q3S0e.xml\",myLocation4);	\n" ^
      "		\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "--	\n" ^
      "--		DECLARE TABLE	\n" ^
      "--\n" ^
      "\n" ^
      "Q3S0 = {\n" ^
      "	OnInit				= OnInit,\n" ^
      "	OnBegin				= OnBegin,\n" ^
      "	OnEnd				= OnEnd,\n" ^
      "	OnAbandon			= OnAbandon,\n" ^
      "	OnEnterLocation		= OnEnterLocation,\n" ^
      "	OnExecuteAction		= OnExecuteAction,\n" ^
      "	OnCompleteAction	= OnCompleteAction,\n" ^
      "	OnQueryAction		= OnQueryAction,\n" ^
      "	OnLoad				= OnLoad,\n" ^
      "	OnSave				= OnSave,\n" ^
      "	OnQueryProgress		= OnQueryProgress,\n" ^
      "	OnQueryPercentage	= OnQueryPercentage,\n" ^
      "	OnQueryDifficulty	= OnQueryDifficulty,\n" ^
      "	\n" ^
      "	CallbackMsg = CallbackMsg ,\n" ^
      "	CallbackMsgA = CallbackMsgA ,\n" ^
      "	CallbackMsgB = CallbackMsgB ,\n" ^
      "	CallbackMsgC = CallbackMsgC ,\n" ^
      "	CallbackMsgD = CallbackMsgD ,\n" ^
      "	CallbackMsgE = CallbackMsgE ,\n" ^
      "};\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
