      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n";
    abandonable = true;
    icon = 2;
    important = true;
    avail_location = "CLBC";
    avail_minlevel = 26;
    avail_maxlevel = 1000;
    avail_repeat = 1;
    avail_donequest0 = "Q3Q5";
    avail_donequest1 = "";
    avail_donequest2 = "";
    avail_notdonequest = "Q3Q6";
    avail_notactivequest = "Q3Q6";
    avail_companion0 = "";
