    avail_notaward = "";
    battle_monster = "";
    battle_spells = [];
    battles = [];
    battle_actions = [];
    battle_stage_advances = [];
    battle_stage_fails = [];
    enter_removes = [(2, "WLOB", "NSER"); (3, "CKUN", "NWIN"); (4, "WWAS", "NKHA"); (5, "WHVA", "NFLI"); (6, "WBSP", "NELI")];
    reveal_on_begin = [];
    reveal_on_end = ["WLOB"; "CKUN"; "WWAS"; "WHVA"; "WBSP"];
    ruin_reveals = [];
    ruin_dones_on_end = [];
    ruin_dones_on_battle = [];
    ruin_dones_on_abandon = [];
