  };
  {
    id = "Q3W0";
    name_text = "[QUEST_Q3W0_NAME]";
    desc_text = "[QUEST_Q3W0_DESC]";
    group = "[QG_WWLF_NAME]";
    text_file = "English\\Quests\\Q3W0_Text.xml";
    texts = [("[QUEST_Q3W0_ACTION1]", "Fight the Wolf"); ("[QUEST_Q3W0_ACTION2]", "Chase away the Wolf Pack"); ("[QUEST_Q3W0_ACTION3]", "Fight the Doomknight"); ("[QUEST_Q3W0_FAILURE1]", "You have failed to defeat the Wolf."); ("[QUEST_Q3W0_FAILURE2]", "You have failed to defeat the Doomknight."); ("[QUEST_Q3W0_MESSAGE]", "You can either continue to chase the wolf pack or help them reclaim their homeland from the Undead."); ("[QUEST_Q3W0_PROGRESS1]", "Chase away the wolf pack that's been terrorizing the Elves at Tirianin."); ("[QUEST_Q3W0_PROGRESS2]", "Chase away the wolf pack or help the wolf pack reclaim their homeland."); ("[QUEST_Q3W0_REWARD1]", "You have successfully chased away the wolf pack. You receive the Wolfbane Cloak."); ("[QUEST_Q3W0_REWARD2]", "You have defeated the Doomknight. The Wolves can return to their home.")];
    lua_file = "Assets\\Quests\\Q3W0.lua";
    lua_object = "Q3W0";
    lua_source = "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--             Wolf Pack	\n" ^
      "--	\n" ^
      "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--		STATES	\n" ^
      "--\n" ^
      "-- 0 => Inactive\n" ^
      "-- 1 => Quest obtained, nothing done yet\n" ^
      "-- 2 => Have fought the Wolf - choice to help or fight.\n" ^
      "-- 3 => Have won second fight.\n" ^
      "-- 4 => end\n" ^
      "-- \n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Variables\n" ^
      "--\n" ^
      "local questState = 0;\n" ^
      "local fightWolf  = 0; -- When set to true - cannot be changed back.\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Constants\n" ^
      "--\n" ^
      "local myCode     = \"Q3W0\";\n" ^
      "local myLocation1 = \"WTIR\";\n" ^
      "local myLocation2 = \"WIGK\";\n" ^
      "local myOrigin   = \"CYLA\";\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnInit				\n" ^
      "--		(called for every quest when they are loading\n" ^
      "--		 to set the initial state of all variables)\n" ^
      "--\n" ^
      "local function OnInit()\n" ^
      "	questState = 0;\n" ^
      "	fightWolf  = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnBegin				\n" ^
      "--		(called when a quest is first obtained)\n" ^
      "--\n" ^
      "local function OnBegin()\n" ^
      "	questState = 1;\n" ^
      "	QUEST_SET_VISIBILITY(myLocation1, 1);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnd				\n" ^
      "--		(called when a quest has ended)\n" ^
      "--\n" ^
      "local function OnEnd()\n" ^
      "	local myMessage;\n" ^
      "	questState = 4;\n" ^
      "	\n" ^
      "\n" ^
      "	-- Reward\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q3W0_NAME]\");\n" ^
      "	if(fightWolf==1) then\n" ^
      "		myMessage = GET_TEXT(\"[QUEST_Q3W0_REWARD1]\");\n" ^
      "	else\n" ^
      "		myMessage = GET_TEXT(\"[QUEST_Q3W0_REWARD2]\");\n" ^
      "	end\n" ^
      "	QUEST_REWARD_MENU(myTitle,myMessage);\n" ^
      "	QUEST_REWARD_XP(200);\n" ^
      "	if (fightWolf==1 and QUEST_HERO_HAS_ITEM(\"IWBC\")==0) then\n" ^
      "		QUEST_REWARD_ITEM(\"IWBC\");\n" ^
      "	else\n" ^
      "		QUEST_REWARD_GOLD(200);\n" ^
      "	end\n" ^
      "	\n" ^
      "\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnAbandon				\n" ^
      "--		(called when a quest has been abandoned by the player)\n" ^
      "--\n" ^
      "local function OnAbandon()\n" ^
      "	questState = 0;  -- it can be restarted\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnterLocation		\n" ^
      "--		(a hero has arrived at a new location)\n" ^
      "--\n" ^
      "local function OnEnterLocation(idLocation)\n" ^
      "end\n" ^
      "\n" ^
      "--------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryAction\n" ^
      "--		(should anything appear on the popup menu)\n" ^
      "--\n" ^
      "local function OnQueryAction(idLocation)\n" ^
      "	if (idLocation==myLocation1 and questState==1) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q3W0_ACTION1]\");\n" ^
      "	elseif (idLocation==myLocation1 and questState==2) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q3W0_ACTION2]\");\n" ^
      "	elseif (idLocation==myLocation2 and questState==2 and fightWolf==0) then\n" ^
      "			return GET_TEXT(\"[QUEST_Q3W0_ACTION3]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnExecuteAction				\n" ^
      "--		(do this whenever the player executes the next action)\n" ^
      "--\n" ^
      "local function OnExecuteAction(idLocation)\n" ^
      "	if (questState==1) then\n" ^
      "		QUEST_BATTLE(myCode,0,1);\n" ^
      "	elseif (questState==2 and idLocation==myLocation1) then\n" ^
      "		QUEST_BATTLE(myCode,1,1);\n" ^
      "	elseif (questState==2 and idLocation==myLocation2) then\n" ^
      "		QUEST_BATTLE(myCode,2,1);\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnCompleteAction				\n" ^
      "--		(do this whenever the player completes his action)\n" ^
      "--		It is called after the game has returned to the map screen\n" ^
      "--\n" ^
      "local function OnCompleteAction(idLocation, success)\n" ^
      "\n" ^
      "	if (questState==1) then\n" ^
      "	\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_Q3W0_NAME]\");\n" ^
      "		local myMessage;\n" ^
      "\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q3W0a.xml\",myLocation1);\n" ^
      "	\n" ^
      "	\n" ^
      "	elseif (questState==2) then	\n" ^
      "		if (idLocation==myLocation1) then\n" ^
      "			fightWolf = 1; --once choosing to fight - lose option to help.\n" ^
      "			if(success==1) then\n" ^
      "				questState = 3;\n" ^
      "				QUEST_COMPLETE(myCode);\n" ^
      "			else\n" ^
      "				myMessage = GET_TEXT(\"[QUEST_Q3W0_FAILURE1]\");\n" ^
      "			end\n" ^
      "\n" ^
      "		elseif (idLocation==myLocation2) then\n" ^
      "			if(success==1) then\n" ^
      "				QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_Q3W0b.xml\",myLocation2);\n" ^
