      "	QUEST_MESSAGE(myTitle,myMessage,myLocation);\n" ^
      "	Std_AddEncounter(tirianin,myLocation,\"ENDK\");\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackConvC ()\n" ^
      "	-- Reward\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_Q3W2_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[QUEST_Q3W2_REWARD]\");\n" ^
      "	QUEST_REWARD_MENU_CALLBACK(myTitle,myMessage, myCode,\"CallbackCompanion\");\n" ^
      "	QUEST_REWARD_GOLD(200);\n" ^
      "	QUEST_REWARD_XP(200);\n" ^
      "end\n" ^
      "\n" ^
