    texts = [("[QUEST_QP01_ACTION1]", "Track the thief"); ("[QUEST_QP01_ACTION2]", "Battle the thief"); ("[QUEST_QP01_FAILURE]", "You have failed to defeat the thief and reclaim Patches treasure."); ("[QUEST_QP01_REWARD]", "Patch rewards you for helping to reclaim his treasure."); ("[QUEST_QP01_STEP1]", "You must follow the tracks to the Pike to track down the thief who stole Patch's treasure."); ("[QUEST_QP01_STEP2]", "You must follow the tracks to Tusk to track down the thief who stole Patch's treasure."); ("[QUEST_QP01_STEP3]", "You must follow the tracks to Weret to track down the thief who stole Patch's treasure.")];
    lua_file = "Assets\\Quests\\QP01.lua";
    lua_object = "QP01";
    lua_source = "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--             Ill gotten gains	\n" ^
      "--	\n" ^
      "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--		STATES	\n" ^
      "--\n" ^
      "-- 0 => Inactive\n" ^
      "-- 1 => Quest obtained, Found tracks leading to the Pike\n" ^
      "-- 2 => Found tracks leading to Tusk\n" ^
      "-- 3 => Found tracks leading to Weret\n" ^
      "-- 4 => Finished\n" ^
      "-- \n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Variables\n" ^
      "--\n" ^
      "local questState = 0;\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Constants\n" ^
      "--\n" ^
      "local myCode        = \"QP01\";\n" ^
      "local myLocation1    = \"WPIK\";\n" ^
      "local myLocation2    = \"CTSK\";\n" ^
      "local myLocation3    = \"WWRT\";\n" ^
      "local myOrigin      = \"CHYA\";\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnInit				\n" ^
      "--		(called for every quest when they are loading\n" ^
      "--		 to set the initial state of all variables)\n" ^
      "--\n" ^
      "local function OnInit()\n" ^
      "	questState = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnBegin				\n" ^
      "--		(called when a quest is first obtained)\n" ^
      "--\n" ^
      "local function OnBegin()\n" ^
      "	questState = 1;\n" ^
      "	QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_QP01a.xml\",myOrigin);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnd				\n" ^
      "--		(called when a quest has ended)\n" ^
      "--\n" ^
      "local function OnEnd()\n" ^
      "	questState = 4;\n" ^
      "	\n" ^
      "	-- Reward\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_QP01_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[QUEST_QP01_REWARD]\");\n" ^
      "	QUEST_REWARD_MENU(myTitle,myMessage);\n" ^
      "	QUEST_REWARD_GOLD(300);\n" ^
      "	QUEST_REWARD_XP(200);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnAbandon				\n" ^
      "--		(called when a quest has been abandoned by the player)\n" ^
      "--\n" ^
      "local function OnAbandon()\n" ^
      "	questState=0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnterLocation		\n" ^
      "--		(a hero has arrived at a new location)\n" ^
      "--\n" ^
      "local function OnEnterLocation(idLocation)\n" ^
      "	\n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryAction\n" ^
      "--		(should anything appear on the popup menu)\n" ^
      "--\n" ^
      "local function OnQueryAction(idLocation)\n" ^
      "	if(questState==1 and idLocation==myLocation1 and \n" ^
      "		QUEST_HERO_HAS_COMPANION_SELECTED(\"NPAT\")==1) then\n" ^
      "\n" ^
      "		return GET_TEXT(\"[QUEST_QP01_ACTION1]\");\n" ^
      "\n" ^
      "	elseif(questState==2 and idLocation==myLocation2 and \n" ^
      "		QUEST_HERO_HAS_COMPANION_SELECTED(\"NPAT\")==1) then\n" ^
      "\n" ^
      "		return GET_TEXT(\"[QUEST_QP01_ACTION1]\");\n" ^
      "\n" ^
      "	elseif(questState==3 and idLocation==myLocation3 and \n" ^
      "		QUEST_HERO_HAS_COMPANION_SELECTED(\"NPAT\")==1) then\n" ^
      "\n" ^
      "		return GET_TEXT(\"[QUEST_QP01_ACTION2]\");\n" ^
      "\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnExecuteAction				\n" ^
      "--		(do this whenever the player executes the next action)\n" ^
      "--\n" ^
      "local function OnExecuteAction(idLocation)\n" ^
      "	if (questState==1) then\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_QP01b.xml\",myLocation1);\n" ^
      "\n" ^
      "	elseif(questState==2) then\n" ^
      "		QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_QP01c.xml\",myLocation2);\n" ^
      "\n" ^
      "	elseif(questState==3) then\n" ^
      "		QUEST_BATTLE(myCode,0,1);\n" ^
      "	end\n" ^
      "\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnCompleteAction				\n" ^
      "--		(do this whenever the player completes his action)\n" ^
      "--		It is called after the game has returned to the map screen\n" ^
      "--\n" ^
      "local function OnCompleteAction(idLocation, success)\n" ^
      "\n" ^
      "	if (questState==3) then\n" ^
      "	\n" ^
      "		local myMessage;\n" ^
      "		if (success == 1) then\n" ^
      "			QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_QP01d.xml\",myLocation3);\n" ^
      "		else\n" ^
      "			local myTitle = GET_TEXT(\"[QUEST_QP01_NAME]\");\n" ^
      "			local myMessage = GET_TEXT(\"[QUEST_QP01_FAILURE]\");\n" ^
      "			QUEST_MESSAGE(myTitle,myMessage,myLocation);\n" ^
      "			QUEST_UPDATE_MAP();\n" ^
      "		end\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnLoad				\n" ^
      "--		(a save game is being loaded)\n" ^
      "--\n" ^
      "local function OnLoad()\n" ^
      "	questState = QUEST_LOAD_INT();\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnSave				\n" ^
      "--		(a save game is being saved)\n" ^
      "--\n" ^
      "local function OnSave()\n" ^
      "	QUEST_SAVE_INT(questState);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryProgress		\n" ^
      "--		(returns text describing the next step required)\n" ^
      "--\n" ^
      "local function OnQueryProgress()\n" ^
      "	if (questState == 1) then\n" ^
      "		return GET_TEXT(\"[QUEST_QP01_STEP1]\");\n" ^
      "	elseif (questState == 2) then\n" ^
      "		return GET_TEXT(\"[QUEST_QP01_STEP2]\");\n" ^
      "	elseif (questState == 3) then\n" ^
      "		return GET_TEXT(\"[QUEST_QP01_STEP3]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryPercentage	\n" ^
      "--		(returns a percentage of completion)\n" ^
      "--\n" ^
      "local function OnQueryPercentage()\n" ^
      "	if (questState <= 1) then\n" ^
      "		return 0;\n" ^
      "	elseif (questState <= 2) then\n" ^
      "		return 33;\n" ^
      "	elseif (questState <= 3) then\n" ^
      "		return 66;\n" ^
      "	end\n" ^
      "	return 100;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryDifficulty	\n" ^
      "--		(returns 0-4 for difficulty - v.easy to v.difficult )\n" ^
      "--\n" ^
      "local function OnQueryDifficulty()\n" ^
      "	-- average\n" ^
      "	return 2; \n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "\n" ^
      "local function CallbackConvA ()\n" ^
      "	questState = 1;\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackConvB ()\n" ^
      "	questState = 2;\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackConvC ()\n" ^
      "	questState = 3;\n" ^
      "	QUEST_SET_VISIBILITY(myLocation3,1);\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackConvD ()\n" ^
      "	QUEST_COMPLETE(myCode);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "--	\n" ^
      "--		DECLARE TABLE	\n" ^
      "--\n" ^
      "\n" ^
      "QP01 = {\n" ^
      "	OnInit				= OnInit,\n" ^
      "	OnBegin				= OnBegin,\n" ^
      "	OnEnd				= OnEnd,\n" ^
      "	OnAbandon			= OnAbandon,\n" ^
      "	OnEnterLocation		= OnEnterLocation,\n" ^
      "	OnExecuteAction		= OnExecuteAction,\n" ^
      "	OnCompleteAction	= OnCompleteAction,\n" ^
      "	OnQueryAction		= OnQueryAction,\n" ^
      "	OnLoad				= OnLoad,\n" ^
      "	OnSave				= OnSave,\n" ^
      "	OnQueryProgress		= OnQueryProgress,\n" ^
      "	OnQueryPercentage	= OnQueryPercentage,\n" ^
      "	OnQueryDifficulty	= OnQueryDifficulty,\n" ^
      "	\n" ^
      "	CallbackConvA = CallbackConvA ,\n" ^
      "	CallbackConvB = CallbackConvB ,\n" ^
      "	CallbackConvC = CallbackConvC ,\n" ^
      "	CallbackConvD = CallbackConvD ,\n" ^
      "};\n" ^
