  {
    id = "QS00";
    name_text = "[QUEST_QS00_NAME]";
    desc_text = "[QUEST_QS00_DESC]";
    group = "";
    text_file = "English\\Quests\\QS00_Text.xml";
    texts = [("[QUEST_QS00_RETCOMP]", "Return with Serephine"); ("[QUEST_QS00_ACTION]", "Try to Save Serephine"); ("[QUEST_QS00_FAILURE]", "You escape the guards but not in time to save Serephine.  She has been taken away; you are uncertain exactly where."); ("[QUEST_QS00_NOCOMP]", "You will need Serephine with you to complete the quest in Enmouth."); ("[QUEST_QS00_PRELUDE]", "As you enter Enmouth, you are ambushed by guards.  They seem intent on capturing Princess Serephine."); ("[QUEST_QS00_REENTER]", "This is where Serephine was taken from your party by Imperial Guards. Perhaps you can rescue her..."); ("[QUEST_QS00_REMOVECOMP]", "Princess Serephine has been removed from your party.  You must try to get her back."); ("[QUEST_QS00_REWARD]", "By the time you defeat the Imperial Guards, they have taken Serephine away; you are uncertain exactly where."); ("[QUEST_QS00_STEP1]", "You must travel to Enmouth to help Princess Serephine's friend."); ("[QUEST_QS00_STEP2]", "You must try to save Serephine from the Imperial Guards in Enmouth.")];
    lua_file = "Assets\\Quests\\QS00.lua";
    lua_object = "QS00";
    lua_source = "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--             Secret Message	\n" ^
      "--	\n" ^
      "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--		STATES	\n" ^
      "--\n" ^
      "-- 0 => Inactive\n" ^
      "-- 1 => Quest obtained, nothing done yet\n" ^
      "-- 2 => Had conversation with Selentius, but not fight\n" ^
      "-- 3 => Finished\n" ^
      "-- \n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Variables\n" ^
      "--\n" ^
      "local questState = 0;\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Constants\n" ^
      "--\n" ^
      "local myCode        = \"QS00\";\n" ^
      "local myLocation    = \"CENM\";\n" ^
      "local myOrigin      = \"CHTP\";\n" ^
      "\n" ^
      "\n" ^
      "--calls Conv_QS00b\n" ^
      "local function ConvB()\n" ^
      "	QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_QS00b.xml\",myLocation);	\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnInit				\n" ^
      "--		(called for every quest when they are loading\n" ^
      "--		 to set the initial state of all variables)\n" ^
      "--\n" ^
      "local function OnInit()\n" ^
      "	questState = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnBegin				\n" ^
      "--		(called when a quest is first obtained)\n" ^
      "--\n" ^
      "local function OnBegin()\n" ^
      "	questState = 1;\n" ^
      "	QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_QS00a.xml\",myOrigin);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnd				\n" ^
      "--		(called when a quest has ended)\n" ^
      "--\n" ^
      "local function OnEnd()\n" ^
      "	questState = 3;\n" ^
      "	\n" ^
      "	-- Reward\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_QS00_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[QUEST_QS00_REMOVECOMP]\");\n" ^
      "	QUEST_REWARD_MENU(myTitle,myMessage);\n" ^
      "	QUEST_REWARD_XP(10);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnAbandon				\n" ^
      "--		(called when a quest has been abandoned by the player)\n" ^
      "--\n" ^
      "local function OnAbandon()\n" ^
      "	questState = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnterLocation		\n" ^
      "--		(a hero has arrived at a new location)\n" ^
      "--\n" ^
      "local function OnEnterLocation(idLocation)\n" ^
      "	if(questState==1 and idLocation==myLocation) then\n" ^
      "\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_QS00_NAME]\");\n" ^
      "		if (QUEST_HERO_HAS_COMPANION_SELECTED(\"NSER\")==0) then\n" ^
      "\n" ^
      "			local myMessage = GET_TEXT(\"[QUEST_QS00_NOCOMP]\");\n" ^
      "			QUEST_MESSAGE_CALLBACK(myTitle,myMessage,myLocation);\n" ^
      "		else\n" ^
      "			QUEST_REMOVE_COMPANION(\"NSER\");\n" ^
      "			local myMessage = GET_TEXT(\"[QUEST_QS00_PRELUDE]\");\n" ^
      "			QUEST_MESSAGE_CALLBACK(myTitle,myMessage,myLocation,myCode,\"ConvB\");\n" ^
      "		end\n" ^
      "			\n" ^
      "	elseif (questState==2 and idLocation==myLocation) then\n" ^
      "\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_QS00_NAME]\");\n" ^
      "		local myMessage = GET_TEXT(\"[QUEST_QS00_REENTER]\");\n" ^
      "		QUEST_MESSAGE(myTitle,myMessage,myLocation);\n" ^
      "			\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryAction\n" ^
      "--		(should anything appear on the popup menu)\n" ^
      "--\n" ^
      "local function OnQueryAction(idLocation)\n" ^
      "	if (idLocation==myLocation and questState==1) then\n" ^
      "			return GET_TEXT(\"[QUEST_QS00_RETCOMP]\");\n" ^
      "	elseif (idLocation==myLocation and questState==2) then\n" ^
      "			return GET_TEXT(\"[QUEST_QS00_ACTION]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnExecuteAction				\n" ^
      "--		(do this whenever the player executes the next action)\n" ^
      "--\n" ^
      "local function OnExecuteAction(idLocation)\n" ^
      "	if (idLocation == myLocation and questState==1) then\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_QS00_NAME]\");\n" ^
      "		local myMessage = GET_TEXT(\"[QUEST_QS00_NOCOMP]\");\n" ^
      "		QUEST_MESSAGE_CALLBACK(myTitle,myMessage,idLocation);\n" ^
      "	elseif (idLocation == myLocation and questState==2) then\n" ^
      "		QUEST_BATTLE(myCode,0,1);\n" ^
      "	end	\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnCompleteAction				\n" ^
      "--		(do this whenever the player completes his action)\n" ^
      "--		It is called after the game has returned to the map screen\n" ^
      "--\n" ^
      "local function OnCompleteAction(idLocation, success)\n" ^
      "\n" ^
      "	if (questState==1 or questState==2) then\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_QS00_NAME]\");	\n" ^
      "		local myMessage;	\n" ^
      "		--Whether succeed of fail - display Kidnapped message.\n" ^
      "		if(success==1) then\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_QS00_REWARD]\");\n" ^
      "			\n" ^
      "		else\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_QS00_FAILURE]\");\n" ^
      "			\n" ^
      "		end\n" ^
      "		QUEST_MESSAGE_CALLBACK(myTitle,myMessage,myLocation,myCode,\"CompleteQ\");\n" ^
      "		\n" ^
      "		\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnLoad				\n" ^
      "--		(a save game is being loaded)\n" ^
      "--\n" ^
      "local function OnLoad()\n" ^
      "	questState = QUEST_LOAD_INT();\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnSave				\n" ^
      "--		(a save game is being saved)\n" ^
      "--\n" ^
      "local function OnSave()\n" ^
      "	QUEST_SAVE_INT(questState);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryProgress		\n" ^
      "--		(returns text describing the next step required)\n" ^
      "--\n" ^
      "local function OnQueryProgress()\n" ^
      "	if (questState == 1) then\n" ^
      "		return GET_TEXT(\"[QUEST_QS00_STEP1]\");\n" ^
      "	elseif (questState == 2) then\n" ^
      "		return GET_TEXT(\"[QUEST_QS00_STEP2]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryPercentage	\n" ^
      "--		(returns a percentage of completion)\n" ^
      "--\n" ^
      "local function OnQueryPercentage()\n" ^
      "	return (questState-1)*50;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryDifficulty	\n" ^
      "--		(returns 0-4 for difficulty - v.easy to v.difficult )\n" ^
      "--\n" ^
      "local function OnQueryDifficulty()\n" ^
      "	-- average\n" ^
      "	return 2; \n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "\n" ^
      "local function CallbackConvA ()\n" ^
      "	questState = 1;\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackConvB ()\n" ^
      "	questState = 2;\n" ^
      "	QUEST_BATTLE(myCode,0,1);\n" ^
      "end\n" ^
      "\n" ^
      "local function CompleteQ()\n" ^
      "	QUEST_COMPLETE(myCode);\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "--	\n" ^
      "--		DECLARE TABLE	\n" ^
      "--\n" ^
      "\n" ^
      "QS00 = {\n" ^
      "	OnInit				= OnInit,\n" ^
      "	OnBegin				= OnBegin,\n" ^
      "	OnEnd				= OnEnd,\n" ^
      "	OnAbandon			= OnAbandon,\n" ^
      "	OnEnterLocation		= OnEnterLocation,\n" ^
      "	OnExecuteAction		= OnExecuteAction,\n" ^
      "	OnCompleteAction	= OnCompleteAction,\n" ^
      "	OnQueryAvailable	= OnQueryAvailable,\n" ^
      "	OnQueryAction		= OnQueryAction,\n" ^
      "	OnLoad				= OnLoad,\n" ^
      "	OnSave				= OnSave,\n" ^
      "	OnQueryProgress		= OnQueryProgress,\n" ^
      "	OnQueryPercentage	= OnQueryPercentage,\n" ^
      "	OnQueryDifficulty	= OnQueryDifficulty,\n" ^
      "	\n" ^
      "	CallbackConvA = CallbackConvA ,\n" ^
      "	CallbackConvB = CallbackConvB ,\n" ^
      "	ConvB	= ConvB,\n" ^
      "	CompleteQ = CompleteQ,\n" ^
      "};\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
