  {
    id = "QS02";
    name_text = "[QUEST_QS02_NAME]";
    desc_text = "[QUEST_QS02_DESC]";
    group = "";
    text_file = "English\\Quests\\QS02_Text.xml";
    texts = [("[QUEST_QS02_BATTLE]", "You have been attacked by Imperial Guards who are trying to take Princess Serephine back home."); ("[QUEST_QS02_CANX]", "You have manage to flee from the Imperial Guards. But they will never be too far behind you."); ("[QUEST_QS02_FAILURE1]", "You have failed to defeat the Imperial Guards. You flee, but they are close behind."); ("[QUEST_QS02_PROGRESS1]", "Imperial Guards are searching the area looking for you. You should be cautious."); ("[QUEST_QS02_PROGRESS2]", "You may have defeated some of the Imperial Guards, but the rest will not give up this easily. You should remain cautious."); ("[QUEST_QS02_REWARD]", "You have been rewarded by Princess Serephine for your bravery."); ("[QUEST_QS02_SUCCESS1]", "You have defeated most of the Imperial Guards. You must continue to be cautious, as they will not give up so easily."); ("[QUEST_QS02_SUCCESS2]", "You have defeated the remaining Imperial Guards.")];
    lua_file = "Assets\\Quests\\QS02.lua";
    lua_object = "QS02";
    lua_source = "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--             Imperial Legion	\n" ^
      "--	\n" ^
      "---------------------------------------------------------\n" ^
      "--	\n" ^
      "--		STATES	\n" ^
      "--\n" ^
      "-- 0 => Inactive\n" ^
      "-- 1 => Quest started - Imperial guard searching for you.\n" ^
      "-- 2 => Killed first lot of imperial guard -  second lot still out there\n" ^
      "-- 3 => Killed second lot of imperial guard\n" ^
      "-- 4 => Finished (returned)\n" ^
      "-- \n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Variables\n" ^
      "--\n" ^
      "local questState = 0;\n" ^
      "local myLocation 	= \"CYLA\";\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- Local Constants\n" ^
      "--\n" ^
      "local myCode     	= \"QS02\";\n" ^
      "local myOrigin   	= \"CYLA\";\n" ^
      "local maxRandom 	= 4;\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "local function ConvB()\n" ^
      "	QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_QS02b.xml\",myLocation);\n" ^
      "end\n" ^
      "\n" ^
      "local function ConvC()\n" ^
      "	QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_QS02c.xml\",myLocation);\n" ^
      "end\n" ^
      "\n" ^
      "local function Battle()\n" ^
      "	local currBattle = questState - 1;\n" ^
      "	QUEST_BATTLE(myCode,currBattle,1);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnInit				\n" ^
      "--		(called for every quest when they are loading\n" ^
      "--		 to set the initial state of all variables)\n" ^
      "--\n" ^
      "local function OnInit()\n" ^
      "	questState = 0;\n" ^
      "	math.randomseed(os.time()); --new randomseed\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnBegin				\n" ^
      "--		(called when a quest is first obtained)\n" ^
      "--\n" ^
      "local function OnBegin()\n" ^
      "	questState = 1;\n" ^
      "	QUEST_CONVERSATION(\"Assets\\\\Conversations\\\\Conv_QS02a.xml\",myOrigin);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnd				\n" ^
      "--		(called when a quest has ended)\n" ^
      "--\n" ^
      "local function OnEnd()\n" ^
      "	questState = 4;\n" ^
      "	\n" ^
      "	-- Reward\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_QS02_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[QUEST_QS02_REWARD]\");\n" ^
      "	QUEST_REWARD_MENU(myTitle,myMessage);	\n" ^
      "	QUEST_REWARD_GOLD(200);\n" ^
      "	QUEST_REWARD_XP(150);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnAbandon				\n" ^
      "--		(called when a quest has been abandoned by the player)\n" ^
      "--\n" ^
      "local function OnAbandon()\n" ^
      "	questState = 0;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnEnterLocation		\n" ^
      "--		(a hero has arrived at a new location)\n" ^
      "--\n" ^
      "local function OnEnterLocation(idLocation)\n" ^
      "	--randomly pop up battle with imperial guards.\n" ^
      "	local random = math.random(1,maxRandom);\n" ^
      "	local myTitle;\n" ^
      "	local myMessage;\n" ^
      "	myLocation = idLocation;\n" ^
      "	if(random==1 and QUEST_HERO_HAS_COMPANION_SELECTED(\"NSER\")==1) then	\n" ^
      "		QUEST_STOP_MOVEMENT();\n" ^
      "		myTitle = GET_TEXT(\"[QUEST_QS02_NAME]\");\n" ^
      "		myMessage = GET_TEXT(\"[QUEST_QS02_BATTLE]\");\n" ^
      "		QUEST_MESSAGE_CALLBACK(myTitle,myMessage,myLocation,myCode,\"Battle\");\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryAction\n" ^
      "--		(should anything appear on the popup menu)\n" ^
      "--\n" ^
      "local function OnQueryAction(idLocation)\n" ^
      "\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnExecuteAction				\n" ^
      "--		(do this whenever the player executes the next action)\n" ^
      "--\n" ^
      "local function OnExecuteAction(idLocation)\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnCompleteAction				\n" ^
      "--		(do this whenever the player completes his action)\n" ^
      "--		It is called after the game has returned to the map screen\n" ^
      "--\n" ^
      "local function OnCompleteAction(idLocation, success)\n" ^
      "		\n" ^
      "\n" ^
      "	if (questState==1) then\n" ^
      "	\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_QS02_NAME]\");\n" ^
      "		local myMessage;\n" ^
      "		if (success == 1) then\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_QS02_SUCCESS1]\");\n" ^
      "			QUEST_MESSAGE_CALLBACK(myTitle,myMessage,idLocation,myCode,\"ConvB\");\n" ^
      "		else\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_QS02_FAILURE1]\");\n" ^
      "			QUEST_MESSAGE(myTitle,myMessage,idLocation);\n" ^
      "		end\n" ^
      "\n" ^
      "			\n" ^
      "	elseif (questState==2) then\n" ^
      "	\n" ^
      "		local myTitle = GET_TEXT(\"[QUEST_QS02_NAME]\");\n" ^
      "		local myMessage;\n" ^
      "		if (success == 1) then\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_QS02_SUCCESS2]\");\n" ^
      "			QUEST_MESSAGE_CALLBACK(myTitle,myMessage,myLocation,myCode,\"ConvC\");\n" ^
      "		else\n" ^
      "			myMessage = GET_TEXT(\"[QUEST_QS02_FAILURE1]\");\n" ^
      "			QUEST_MESSAGE(myTitle,myMessage,idLocation);\n" ^
      "		end\n" ^
      "\n" ^
      "\n" ^
      "		\n" ^
      "	end\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnLoad				\n" ^
      "--		(a save game is being loaded)\n" ^
      "--\n" ^
      "local function OnLoad()\n" ^
      "	questState = QUEST_LOAD_INT();\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnSave				\n" ^
      "--		(a save game is being saved)\n" ^
      "--\n" ^
      "local function OnSave()\n" ^
      "	QUEST_SAVE_INT(questState);\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryProgress		\n" ^
      "--		(returns text describing the next step required)\n" ^
      "--\n" ^
      "local function OnQueryProgress()\n" ^
      "	if (questState==1) then\n" ^
      "		return GET_TEXT(\"[QUEST_QS02_PROGRESS1]\");\n" ^
      "	elseif (questState==2) then\n" ^
      "		return GET_TEXT(\"[QUEST_QS02_PROGRESS2]\");\n" ^
      "	end\n" ^
      "	return \"\";\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryPercentage	\n" ^
      "--		(returns a percentage of completion)\n" ^
      "--\n" ^
      "local function OnQueryPercentage()\n" ^
      "	return (questState - 1) * 50;\n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "-- OnQueryDifficulty	\n" ^
      "--		(returns 0-4 for difficulty - v.easy to v.difficult )\n" ^
      "--\n" ^
      "local function OnQueryDifficulty()\n" ^
      "	-- average\n" ^
      "	return 2; \n" ^
      "end\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "\n" ^
      "local function CallbackConvA ()\n" ^
      "	questState = 1;\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackConvB ()	\n" ^
      "	questState = 2;\n" ^
      "	QUEST_UPDATE_MAP();\n" ^
      "end\n" ^
      "\n" ^
      "local function CallbackConvC ()\n" ^
      "	questState = 3;\n" ^
      "	QUEST_COMPLETE(myCode);\n" ^
      "end\n" ^
      "\n" ^
      "------------------------------------------------\n" ^
      "--\n" ^
      "-- OnCancelAction\n" ^
      "--\n" ^
      "--    Called whenever a battle is cancelled\n" ^
      "--\n" ^
      "local function OnCancelAction(idLocation)\n" ^
      "	local myTitle = GET_TEXT(\"[QUEST_QS02_NAME]\");\n" ^
      "	local myMessage = GET_TEXT(\"[QUEST_QS02_CANX]\");\n" ^
      "	QUEST_MESSAGE(myTitle,myMessage,idLocation);\n" ^
      "end\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "---------------------------------------------------------\n" ^
      "--\n" ^
      "--	\n" ^
      "--		DECLARE TABLE	\n" ^
      "--\n" ^
      "\n" ^
      "QS02 = {\n" ^
      "	OnCancelAction = OnCancelAction,\n" ^
      "	OnInit				= OnInit,\n" ^
      "	OnBegin				= OnBegin,\n" ^
      "	OnEnd				= OnEnd,\n" ^
      "	OnAbandon			= OnAbandon,\n" ^
      "	OnEnterLocation		= OnEnterLocation,\n" ^
      "	OnExecuteAction		= OnExecuteAction,\n" ^
      "	OnCompleteAction	= OnCompleteAction,\n" ^
      "	OnQueryAction		= OnQueryAction,\n" ^
      "	OnLoad				= OnLoad,\n" ^
      "	OnSave				= OnSave,\n" ^
      "	OnQueryProgress		= OnQueryProgress,\n" ^
      "	OnQueryPercentage	= OnQueryPercentage,\n" ^
      "	OnQueryDifficulty	= OnQueryDifficulty,\n" ^
      "	\n" ^
      "	CallbackConvA = CallbackConvA,\n" ^
      "	CallbackConvB = CallbackConvB,\n" ^
      "	CallbackConvC = CallbackConvC,\n" ^
      "	ConvB = ConvB,\n" ^
      "	ConvC = ConvC,\n" ^
      "	Battle = Battle,\n" ^
      "};\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
      "\n" ^
